def american_to_implied_prob(price):

    """Convert American odds to implied probability as a decimal."""

    x = safe_float(str(price).replace("+", ""), None)

    if x is None or x == 0:

        return None

    if x > 0:

        return 100.0 / (x + 100.0)

    return abs(x) / (abs(x) + 100.0)



def no_vig_two_way(over_price, under_price):

    """Return no-vig over/under probabilities for a paired two-way market."""

    o = american_to_implied_prob(over_price)

    u = american_to_implied_prob(under_price)

    if o is None or u is None or (o + u) <= 0:

        return {"over": None, "under": None, "vig": None}

    total = o + u

    return {"over": o / total, "under": u / total, "vig": total - 1.0}



def _pct_display(v):

    x = safe_float(v, None)

    if x is None:

        return "—"

    if abs(x) <= 1:

        x *= 100.0

    return f"{x:.1f}%"



def _manual_saved_key(row):

    """Stable key for saved manual odds. Uses pitcher + line so old slates do not fight new lines."""

    return (

        normalize_name((row or {}).get("Pitcher") or (row or {}).get("pitcher") or ""),

        None if safe_float((row or {}).get("Line"), None) is None else round(float(safe_float((row or {}).get("Line"), None)), 2),

    )



def _manual_saved_name_key(row):

    return normalize_name((row or {}).get("Pitcher") or (row or {}).get("pitcher") or "")



def _clean_manual_odds_row(r, keep_blank=False):

    """Clean one manual odds row. Blank odds are ignored unless keep_blank is explicitly True."""

    if not isinstance(r, dict):

        return None

    name = str(r.get("Pitcher") or r.get("pitcher") or "").strip()

    line = safe_float(r.get("Line") if r.get("Line") is not None else r.get("line"), None)

    if not name or line is None:

        return None

    over = _fmt_manual_price(r.get("Over Odds") if r.get("Over Odds") is not None else r.get("over_odds"))

    under = _fmt_manual_price(r.get("Under Odds") if r.get("Under Odds") is not None else r.get("under_odds"))

    if not keep_blank and not over and not under:

        return None

    return {

        "Pitcher": name,

        "Matchup": str(r.get("Matchup") or r.get("matchup") or ""),

        "Line": round(float(line), 1),

        "Over Odds": over,

        "Under Odds": under,

        "Book": str(r.get("Book") or r.get("book") or "Manual"),

        "Saved At": california_now().strftime("%Y-%m-%d %H:%M:%S PT") if "california_now" in globals() else datetime.now().strftime("%Y-%m-%d %H:%M:%S"),

    }



def load_saved_manual_odds_rows():

    """Load saved manual odds from primary, backup, or local fallback."""

    for path in [SAVED_ODDS_FILE, SAVED_ODDS_BACKUP_FILE, SAVED_ODDS_LOCAL_FILE]:

        rows = load_json(path, [])

        if isinstance(rows, list) and rows:

            cleaned = []

            seen = set()

            for r in rows:

                cr = _clean_manual_odds_row(r, keep_blank=False)

                if not cr:

                    continue

                k = _manual_saved_key(cr)

                if k in seen:

                    continue

                seen.add(k)

                cleaned.append(cr)

            if cleaned:

                return cleaned

    return []



def save_manual_odds_rows(rows):

    """Merge-save manual odds without letting blank rows erase previously saved prices."""

    existing = load_saved_manual_odds_rows()

    merged = {}

    order = []

    for r in existing:

        cr = _clean_manual_odds_row(r, keep_blank=False)

        if not cr:

            continue

        k = _manual_saved_key(cr)

        merged[k] = cr

        order.append(k)



    for r in rows or []:

        cr = _clean_manual_odds_row(r, keep_blank=False)

        if not cr:

            continue

        k = _manual_saved_key(cr)

        prev = merged.get(k, {})

        if not cr.get("Over Odds") and prev.get("Over Odds"):

            cr["Over Odds"] = prev.get("Over Odds")

        if not cr.get("Under Odds") and prev.get("Under Odds"):

            cr["Under Odds"] = prev.get("Under Odds")

        merged[k] = cr

        if k not in order:

            order.append(k)



    cleaned = [merged[k] for k in order if k in merged]

    for path in [SAVED_ODDS_FILE, SAVED_ODDS_BACKUP_FILE, SAVED_ODDS_LOCAL_FILE]:

        save_json(path, cleaned)

    return cleaned



def log_source_request(source, status, message=""):

    rows = load_json(REQUEST_LOG_FILE, [])

    rows.append({

        "time": now_iso(),

        "source": str(source)[:180],

        "status": str(status)[:80],

        "message": str(message)[:350]

    })

    save_json(REQUEST_LOG_FILE, rows[-500:])



def strip_accents(text):

    """Normalize accents so Underdog names like Sánchez match MLB names like Sanchez."""

    try:

        return "".join(

            ch for ch in unicodedata.normalize("NFKD", str(text or ""))

            if not unicodedata.combining(ch)

        )

    except Exception:

        return str(text or "")



def normalize_name(name):

    s = strip_accents(name).lower().strip()

    for ch in [".", ",", "'", "-", "_", " jr", " sr", " ii", " iii", " iv"]:

        s = s.replace(ch, " ")

    return " ".join(s.split())



def name_score(a, b):

    """Robust player-name match.



    Handles full names, abbreviations, and Underdog initial + last-name display:

    - Cristopher Sanchez vs C. Sánchez

    - Gavin Williams vs G. Williams

    - Jacob deGrom vs J. deGrom

    """

    a_norm, b_norm = normalize_name(a), normalize_name(b)

    if not a_norm or not b_norm:

        return 0.0

    if a_norm == b_norm:

        return 1.0

    if a_norm in b_norm or b_norm in a_norm:

        return 0.94



    a_parts, b_parts = a_norm.split(), b_norm.split()

    if a_parts and b_parts:

        a_first, b_first = a_parts[0], b_parts[0]

        a_last, b_last = a_parts[-1], b_parts[-1]



        # Exact last-name + first-initial match, e.g. "Cristopher Sanchez" vs "C Sanchez".

        if a_last == b_last and a_first[:1] == b_first[:1]:

            return 0.93



        # Multi-word last names / particles still get strong credit if the last token and initial match.

        if a_last == b_last:

            return max(0.82, difflib.SequenceMatcher(None, a_norm, b_norm).ratio())



    return difflib.SequenceMatcher(None, a_norm, b_norm).ratio()



def is_pitcher_k_text(text):

    t = str(text or "").lower()

    return (

        "strikeout" in t

        or "strike out" in t

        or "pitcher k" in t

        or t in ["ks", "k", "pitcher strikeouts"]

    ) and not any(bad in t for bad in ["batter", "hitter"])



def is_bad_sport_text(text):

    """Hard block non-MLB/basketball contamination from prop feeds."""

    t = f" {str(text or '').lower()} "

    bad_terms = [

        " nba", " nba_", "basketball", "wnba", "nfl", "football", "nhl",

        "soccer", "tennis", "golf", "college basketball", "ncaab"

    ]

    return any(x in t for x in bad_terms)



def is_bad_k_market_text(text):

    """Reject non-pitcher-K or alternate/novelty markets that can carry misleading values."""

    t = str(text or "").lower()

    bad_terms = [

        "batter", "hitter", "team strikeouts", "fantasy points", "fantasy score",

        "runs+rbi", "hits+runs+rbi", "total bases", "stolen base", "walks allowed",

        "earned runs", "outs recorded", "pitching outs", "hits allowed", "runs allowed",

        "single", "double", "home run", "rbi", "runs scored", "combo", "rival",

        "special", "discount", "alternative", "alt "

    ]

    return any(x in t for x in bad_terms)



@st.cache_data(ttl=300, show_spinner=False)

def safe_get_json(url, params=None, timeout=14, headers=None):

    try:

        h = {

            "User-Agent": "Mozilla/5.0 MLBKPropEngine/refresh-save-build",

            "Accept": "application/json,text/plain,*/*",

        }

        if headers:

            h.update(headers)

        r = requests.get(url, params=params, timeout=timeout, headers=h)

        if r.status_code != 200:

            log_source_request(url, f"HTTP {r.status_code}", r.text[:250])

            return None

        try:

            return r.json()

        except Exception as e:

            log_source_request(url, "BAD_JSON", str(e))

            return None

    except Exception as e:

        log_source_request(url, "REQUEST_ERROR", str(e))

        return None



def baseball_ip_to_float(ip):

    if ip is None:

        return None

    try:

        s = str(ip)

        if "." not in s:

            return float(s)

        whole, frac = s.split(".", 1)

        outs = int(frac[:1]) if frac else 0

        if outs not in [0, 1, 2]:

            return float(s)

        return int(whole) + outs / 3

    except Exception:

        return None



def get_first_stat_split(data):

    if not isinstance(data, dict):

        return None

    stats = data.get("stats") or []

    if not stats or not isinstance(stats[0], dict):

        return None

    splits = stats[0].get("splits") or []

    if not splits or not isinstance(splits[0], dict):

        return None

    return splits[0]



def flatten_json(obj):

    items = []

    if isinstance(obj, dict):

        items.append(obj)

        for v in obj.values():

            items.extend(flatten_json(v))

    elif isinstance(obj, list):

        for x in obj:

            items.extend(flatten_json(x))

    return items



def first_value(d, keys):

    for k in keys:

        if isinstance(d, dict) and k in d and d[k] not in [None, ""]:

            return d[k]

    return None



# =========================

# BETTING MATH

# =========================

def poisson_over_probability(lam, line):

    lam = safe_float(lam, 0)

    line = safe_float(line)

    if line is None or lam <= 0:

        return None

    k = int(math.floor(line))

    prob_under_or_equal = sum((lam ** i) * exp(-lam) / factorial(i) for i in range(k + 1))

    return float(clamp(1 - prob_under_or_equal, 0.001, 0.999))



def american_to_implied(price):

    price = safe_float(price)

    if price is None:

        return None

    if price > 0:

        return 100 / (price + 100)

    return abs(price) / (abs(price) + 100)



def decimal_odds(odds):

    odds = safe_float(odds)

    if odds is None:

        return None

    if odds > 0:

        return 1 + odds / 100

    return 1 + 100 / abs(odds)



def expected_value(prob, odds):

    dec = decimal_odds(odds)

    if prob is None or dec is None:

        return None

    return (prob * (dec - 1)) - (1 - prob)



def kelly_fraction(prob, odds):

    dec = decimal_odds(odds)

    if prob is None or dec is None:

        return 0.0

    b = dec - 1

    q = 1 - prob

    if b <= 0:

        return 0.0

    return float(clamp(((b * prob) - q) / b, 0, 0.25))



def paired_no_vig_probability(rows, target_row):

    price = safe_float(target_row.get("Price"))

    listed = american_to_implied(price)

    if listed is None:

        return None

    provider = str(target_row.get("Provider", target_row.get("Source", ""))).lower()

    line = safe_float(target_row.get("Line"))

    side = str(target_row.get("Side", "")).lower()

    if line is None or not side:

        return listed

    want = "under" if "over" in side else "over" if "under" in side else None

    if not want:

        return listed

    opposite = None

    for r in rows or []:

        if safe_float(r.get("Line")) != line:

            continue

        if str(r.get("Provider", r.get("Source", ""))).lower() != provider:

            continue

        if want in str(r.get("Side", "")).lower():

            opposite = american_to_implied(r.get("Price"))

            break

    if opposite is None:

        return listed

    denom = listed + opposite

    return listed / denom if denom > 0 else listed



