# v10.9 TRUE EDGE MERGE HELPERS

# =========================

def elite_pitcher_boost_factor(k_rate):

    """Small K-skill boost for elite strikeout arms.



    Kept conservative because Statcast, recent form, and Log5 already capture a lot

    of pitcher skill. This should never turn a weak edge into an automatic play.

    """

    k_rate = safe_float(k_rate, LEAGUE_AVG_K) or LEAGUE_AVG_K

    if k_rate >= 0.30:

        return 1.035, "Elite pitcher K boost x1.035"

    if k_rate >= 0.27:

        return 1.025, "High-K pitcher boost x1.025"

    if k_rate >= 0.24:

        return 1.015, "Above-average pitcher K boost x1.015"

    return 1.000, "No elite pitcher boost"



def opponent_k_context_factor(lineup_k):

    """Extra lineup strikeout-context nudge after Log5.



    The main opponent-K signal is still the posted-lineup/hitter blend. This small

    factor only recognizes extreme high-K or low-K lineups without double-counting.

    """

    lk = safe_float(lineup_k, LEAGUE_AVG_K) or LEAGUE_AVG_K

    diff = lk - LEAGUE_AVG_K

    if diff >= 0.040:

        return 1.045, "Extreme high-K opponent context x1.045"

    if diff >= 0.030:

        return 1.035, "High-K opponent context x1.035"

    if diff >= 0.020:

        return 1.020, "Above-average opponent K context x1.020"

    if diff <= -0.035:

        return 0.955, "Extreme contact opponent context x0.955"

    if diff <= -0.025:

        return 0.970, "Low-K opponent context x0.970"

    return 1.000, "Neutral opponent K context"





def build_csw_trend_score(statcast_profile, enabled=True):

    """CSW Trend Score: recent CSW direction vs season Statcast baseline.



    This is intentionally conservative. It only uses real Statcast pitch-level

    aggregates already pulled by get_statcast_pitch_profile. Missing or thin data

    returns neutral so the core projection is not hurt.

    """

    if not enabled or not isinstance(statcast_profile, dict) or not statcast_profile.get("available"):

        return {"available": False, "score": 50, "label": "CSW_TREND_NEUTRAL", "k_factor": 1.0, "confidence_nudge": 0.0, "note": "CSW trend unavailable; neutral"}



    season = safe_float(statcast_profile.get("csw"), None)

    recent = safe_float(statcast_profile.get("csw_recent_30"), None)

    if recent is None:

        recent = safe_float(statcast_profile.get("csw_recent_45"), None)

    base = season

    recent_pitches = safe_int(statcast_profile.get("csw_recent_30_pitches"), 0) or safe_int(statcast_profile.get("csw_recent_45_pitches"), 0) or 0

    total_pitches = safe_int(statcast_profile.get("rows"), 0) or 0



    if season is None or recent is None or recent_pitches < 40 or total_pitches < 120:

        return {"available": False, "score": 50, "label": "CSW_TREND_THIN", "k_factor": 1.0, "confidence_nudge": 0.0, "recent_csw": None if recent is None else round(recent*100,1), "season_csw": None if season is None else round(season*100,1), "note": "CSW trend thin; neutral"}



    delta = float(recent - base)

    score = 50.0 + clamp(delta * 625.0, -18.0, 18.0)



    if recent >= 0.315 and delta >= 0.025:

        label, k_factor, conf = "CSW_TREND_SURGING", 1.018, 3.0

    elif delta >= 0.018:

        label, k_factor, conf = "CSW_TREND_UP", 1.012, 2.0

    elif delta <= -0.025 and recent <= 0.275:

        label, k_factor, conf = "CSW_TREND_FADING", 0.982, -3.0

    elif delta <= -0.018:

        label, k_factor, conf = "CSW_TREND_DOWN", 0.988, -2.0

    else:

        label, k_factor, conf = "CSW_TREND_STABLE", 1.000, 0.0



    return {

        "available": True,

        "score": round(float(clamp(score, 30, 70)), 1),

        "label": label,

        "k_factor": round(float(k_factor), 3),

        "confidence_nudge": round(float(conf), 2),

        "recent_csw": round(recent * 100, 1),

        "season_csw": round(base * 100, 1),

        "delta": round(delta * 100, 1),

        "recent_pitches": int(recent_pitches),

        "note": f"{label}: recent CSW {recent*100:.1f}% vs season {base*100:.1f}% ({delta*100:+.1f} pts); K factor x{k_factor:.3f}",

    }





def apply_csw_trend_adjustment(k_rate, csw_trend_profile, enabled=True):

    kr = safe_float(k_rate, None)

    if kr is None or not enabled or not isinstance(csw_trend_profile, dict):

        return k_rate, "CSW trend adjustment skipped"

    factor = safe_float(csw_trend_profile.get("k_factor"), 1.0) or 1.0

    factor = float(clamp(factor, 0.975, 1.025))

    return float(clamp(kr * factor, 0.08, 0.50)), csw_trend_profile.get("note", "CSW trend neutral")





def build_opponent_k_trend_score(lineup_rows, lineup_k=None, enabled=True):

    """Opponent K Trend Score from confirmed/projected lineup rolling K rates.



    Compares current/rolling batter K pressure to season batter K pressure. This is

    a small matchup-context layer, not a replacement for Log5 or the existing

    opponent K context.

    """

    if not enabled:

        return {"available": False, "score": 50, "label": "OPP_K_TREND_OFF", "k_factor": 1.0, "confidence_nudge": 0.0, "note": "Opponent K trend off"}



    rows = [r for r in (lineup_rows or []) if isinstance(r, dict)]

    recent_vals, season_vals = [], []

    for r in rows[:9]:

        # Stored as percentages on lineup rows.

        r14 = safe_float(r.get("Rolling 14d K%"), None)

        r30 = safe_float(r.get("Rolling 30d K%"), None)

        seas = safe_float(r.get("Season K%"), None)

        used = safe_float(r.get("Used K%"), None)

        recent_pct = r14 if r14 is not None else r30

        if recent_pct is None and used is not None:

            recent_pct = used

        if recent_pct is not None and 0 <= recent_pct <= 60:

            recent_vals.append(recent_pct / 100.0)

        if seas is not None and 0 <= seas <= 60:

            season_vals.append(seas / 100.0)



    if len(recent_vals) < 5 or len(season_vals) < 5:

        lk = safe_float(lineup_k, None)

        if lk is None:

            return {"available": False, "score": 50, "label": "OPP_K_TREND_THIN", "k_factor": 1.0, "confidence_nudge": 0.0, "note": "Opponent K trend thin; neutral"}

        # Fallback: use level only, not direction.

        if lk >= LEAGUE_AVG_K + 0.025:

            return {"available": False, "score": 56, "label": "OPP_K_LEVEL_HIGH", "k_factor": 1.006, "confidence_nudge": 0.5, "recent_k": round(lk*100,1), "season_k": None, "delta": None, "note": f"Opponent K level high ({lk*100:.1f}%); tiny K factor x1.006"}

        if lk <= LEAGUE_AVG_K - 0.025:

            return {"available": False, "score": 44, "label": "OPP_K_LEVEL_LOW", "k_factor": 0.994, "confidence_nudge": -0.5, "recent_k": round(lk*100,1), "season_k": None, "delta": None, "note": f"Opponent K level low ({lk*100:.1f}%); tiny K factor x0.994"}

        return {"available": False, "score": 50, "label": "OPP_K_TREND_THIN", "k_factor": 1.0, "confidence_nudge": 0.0, "note": "Opponent K trend thin; neutral"}



    recent = float(np.mean(recent_vals))

    season = float(np.mean(season_vals))

    delta = recent - season

    score = 50.0 + clamp(delta * 525.0, -16.0, 16.0)



    if delta >= 0.025:

        label, k_factor, conf = "OPP_K_TREND_RISING", 1.014, 2.0

    elif delta >= 0.015:

        label, k_factor, conf = "OPP_K_TREND_SLIGHT_UP", 1.008, 1.0

    elif delta <= -0.025:

        label, k_factor, conf = "OPP_K_TREND_FALLING", 0.986, -2.0

    elif delta <= -0.015:

        label, k_factor, conf = "OPP_K_TREND_SLIGHT_DOWN", 0.992, -1.0

    else:

        label, k_factor, conf = "OPP_K_TREND_STABLE", 1.000, 0.0



    return {

        "available": True,

        "score": round(float(clamp(score, 34, 66)), 1),

        "label": label,

        "k_factor": round(float(k_factor), 3),

        "confidence_nudge": round(float(conf), 2),

        "recent_k": round(recent * 100, 1),

        "season_k": round(season * 100, 1),

        "delta": round(delta * 100, 1),

        "sample": min(len(recent_vals), len(season_vals)),

        "note": f"{label}: opponent recent K {recent*100:.1f}% vs season {season*100:.1f}% ({delta*100:+.1f} pts); K factor x{k_factor:.3f}",

    }





def apply_opponent_k_trend_adjustment(matchup_k, opponent_k_trend_profile, enabled=True):

    mk = safe_float(matchup_k, None)

    if mk is None or not enabled or not isinstance(opponent_k_trend_profile, dict):

        return matchup_k, "Opponent K trend adjustment skipped"

    factor = safe_float(opponent_k_trend_profile.get("k_factor"), 1.0) or 1.0

    factor = float(clamp(factor, 0.982, 1.018))

    return float(clamp(mk * factor, 0.03, 0.60)), opponent_k_trend_profile.get("note", "Opponent K trend neutral")



def pitch_count_trend_bf_factor(recent_rows):

    """Recent pitch-count trend factor for starter BF/leash.



    Uses only real recent game-log pitch counts. Missing data remains neutral.

    """

    vals = []

    for r in (recent_rows or [])[:3]:

        p = safe_float(r.get("Pitches"))

        if p is not None and p > 0:

            vals.append(p)

    if not vals:

        return 1.0, "Pitch-count trend unavailable; neutral"

    avg = float(np.mean(vals))

    if avg >= 100:

        return 1.040, f"Recent pitch-count leash boost x1.040 (L3 avg {avg:.0f})"

    if avg >= 92:

        return 1.020, f"Recent pitch-count leash boost x1.020 (L3 avg {avg:.0f})"

    if avg <= 82:

        return 0.940, f"Recent low pitch-count leash cut x0.940 (L3 avg {avg:.0f})"

    return 1.000, f"Neutral pitch-count trend (L3 avg {avg:.0f})"





def bf_trend_bf_adjustment_v11_19(workload_rows):

    """Last-3 BF trend: small, capped BF adjustment for K opportunity.



    Uses only real recent game-log batters faced. This supports the existing leash

    model without overriding K skill or creating fake volume.

    """

    vals = []

    for r in (workload_rows or [])[:10]:

        bf = safe_float(r.get("BF"), None)

        if bf is not None and bf > 0:

            vals.append(float(bf))

    if len(vals) < 3:

        return 0.0, "BF trend unavailable; neutral", None, None, 0.0

    l3 = float(np.mean(vals[:3]))

    l10 = float(np.mean(vals[:10])) if len(vals) >= 5 else float(np.mean(vals))

    trend = l3 - l10

    adj = 0.0

    if trend >= 3.0:

        adj = 0.45

        note = f"Last-3 BF trend rising: +{adj:.2f} BF (L3 {l3:.1f} vs base {l10:.1f})"

    elif trend >= 1.5:

        adj = 0.25

        note = f"Last-3 BF trend slightly rising: +{adj:.2f} BF (L3 {l3:.1f} vs base {l10:.1f})"

    elif trend <= -3.0:

        adj = -0.45

        note = f"Last-3 BF trend falling: {adj:.2f} BF (L3 {l3:.1f} vs base {l10:.1f})"

    elif trend <= -1.5:

        adj = -0.25

        note = f"Last-3 BF trend slightly falling: {adj:.2f} BF (L3 {l3:.1f} vs base {l10:.1f})"

    else:

        note = f"Last-3 BF trend neutral (L3 {l3:.1f} vs base {l10:.1f})"

    return float(adj), note, round(l3, 1), round(l10, 1), round(trend, 1)





def build_pitch_count_module(workload_rows):

    """Pitch Count 2.0: converts recent real pitch-count workload into a volume score.



    This is intentionally tied to the existing BF/leash engine. It does not create

    fake data; missing pitch counts stay neutral. The module returns a 0-100 score,

    a label, a BF adjustment, and a small volatility tax used by decision filters.

    """

    rows = list(workload_rows or [])

    pitch_vals = []

    bf_vals = []

    ip_vals = []

    for r in rows[:10]:

        pc = safe_float(r.get("Pitches"), None)

        bf = safe_float(r.get("BF"), None)

        ip = safe_float(r.get("IP_float"), None)

        if pc is not None and pc > 0:

            pitch_vals.append(float(pc))

        if bf is not None and bf > 0:

            bf_vals.append(float(bf))

        if ip is not None and ip > 0:

            ip_vals.append(float(ip))



    if not pitch_vals:

        return {

            "score": 72,

            "label": "PITCH_COUNT_UNKNOWN",

            "bf_adj": 0.0,

            "bf_factor": 1.0,

            "volatility_tax": 0.02,

            "avg_l3": None,

            "avg_l5": None,

            "avg_l10": None,

            "trend": 0.0,

            "note": "Pitch Count 2.0 neutral: no recent pitch-count data",

        }



    if len(pitch_vals) < 3:

        avg_l3 = float(np.mean(pitch_vals))

        avg_l5 = avg_l3

        avg_l10 = avg_l3

        return {

            "score": 70,

            "label": "PITCH_COUNT_THIN_SAMPLE",

            "bf_adj": 0.0,

            "bf_factor": 1.0,

            "volatility_tax": 0.03,

            "avg_l3": round(avg_l3, 1),

            "avg_l5": round(avg_l5, 1),

            "avg_l10": round(avg_l10, 1),

            "trend": 0.0,

            "sample_n": len(pitch_vals),

            "note": f"Pitch Count 2.0 neutral: only {len(pitch_vals)} usable pitch-count samples",

        }



    avg_l3 = float(np.mean(pitch_vals[:3])) if len(pitch_vals) >= 1 else None

    avg_l5 = float(np.mean(pitch_vals[:5])) if len(pitch_vals) >= 1 else avg_l3

    avg_l10 = float(np.mean(pitch_vals[:10])) if len(pitch_vals) >= 1 else avg_l5

    ip_l3 = float(np.mean(ip_vals[:3])) if ip_vals else None

    bf_l3 = float(np.mean(bf_vals[:3])) if bf_vals else None

    trend = 0.0

    if avg_l3 is not None and avg_l10 is not None:

        trend = avg_l3 - avg_l10



    score = 70.0

    # Recent pitch ceiling / leash.

    if avg_l3 >= 98:

        score += 18

    elif avg_l3 >= 92:

        score += 10

    elif avg_l3 >= 86:

        score += 3

    elif avg_l3 >= 80:

        score -= 8

    else:

        score -= 18



    # Longer-term volume support.

    if avg_l5 >= 95:

        score += 8

    elif avg_l5 >= 88:

        score += 3

    elif avg_l5 < 82:

        score -= 8



    # Innings and BF confirmation.

    if ip_l3 is not None:

        if ip_l3 >= 6.0:

            score += 7

        elif ip_l3 < 5.0:

            score -= 12

    if bf_l3 is not None:

        if bf_l3 >= 24:

            score += 5

        elif bf_l3 < 20:

            score -= 8



    # Direction of pitch-count trend.

    if trend >= 5:

        score += 5

    elif trend <= -7:

        score -= 7



    score = int(round(clamp(score, 35, 100)))



    if score >= 92:

        label = "ELITE_VOLUME"

        bf_adj, bf_factor, vol_tax = 0.70, 1.025, 0.00

    elif score >= 84:

        label = "FULL_LEASH"

        bf_adj, bf_factor, vol_tax = 0.35, 1.012, 0.00

    elif score >= 72:

        label = "NORMAL"

        bf_adj, bf_factor, vol_tax = 0.00, 1.000, 0.01

    elif score >= 60:

        label = "MONITOR"

        bf_adj, bf_factor, vol_tax = -0.55, 0.982, 0.025

    else:

        label = "SHORT_LEASH"

        bf_adj, bf_factor, vol_tax = -1.20, 0.958, 0.045



    note = f"Pitch Count 2.0 {label}: score {score}/100; L3 {avg_l3:.0f}, L5 {avg_l5:.0f}, trend {trend:+.1f}; BF adj {bf_adj:+.2f}"

    return {

        "score": score,

        "label": label,

        "bf_adj": round(float(bf_adj), 2),

        "bf_factor": round(float(bf_factor), 3),

        "volatility_tax": round(float(vol_tax), 3),

        "avg_l3": round(float(avg_l3), 1) if avg_l3 is not None else None,

        "avg_l5": round(float(avg_l5), 1) if avg_l5 is not None else None,

        "avg_l10": round(float(avg_l10), 1) if avg_l10 is not None else None,

        "trend": round(float(trend), 1),

        "note": note,

    }







def build_innings_outcome_module(recent_rows, expected_bf, ppb=None, pitch_count_profile=None, manager_hook_status=None, game_script_risk=None, workload_context=None):

    """Project starter innings outcome and early-pull risk from real recent IP/BF/pitch-count data."""

    rows = list(recent_rows or [])

    ip_vals, bf_vals, bf_per_ip_vals = [], [], []

    for r in rows[:10]:

        ip = safe_float(r.get("IP_float"), None)

        bf0 = safe_float(r.get("BF"), None)

        if ip is not None and ip > 0:

            ip_vals.append(float(ip))

        if bf0 is not None and bf0 > 0:

            bf_vals.append(float(bf0))

        if ip is not None and ip > 0 and bf0 is not None and bf0 > 0:

            bf_per_ip_vals.append(float(bf0) / float(ip))

    exp_bf = safe_float(expected_bf, DEFAULT_BF) or DEFAULT_BF

    bf_per_ip = float(clamp(np.mean(bf_per_ip_vals), 3.65, 5.15)) if bf_per_ip_vals else 4.25

    ip_from_bf = exp_bf / bf_per_ip

    recent_l3_ip = float(np.mean(ip_vals[:3])) if ip_vals else None

    recent_l5_ip = float(np.mean(ip_vals[:5])) if ip_vals else recent_l3_ip

    recent_l10_ip = float(np.mean(ip_vals[:10])) if ip_vals else recent_l5_ip

    projected_ip = (ip_from_bf * 0.68 + recent_l5_ip * 0.32) if recent_l5_ip is not None else ip_from_bf



    # V2.3 BF/IP consistency: a normal scheduled starter cannot quietly show a

    # full-start BF projection with an opener-level IP projection. The correction

    # is capped by the BF-implied innings and the role-aware workload floor.

    workload_ctx = workload_context if isinstance(workload_context, dict) else {}

    consistency_adjustment = 0.0

    if workload_ctx.get("starter_like") and not workload_ctx.get("explicit_short_role"):

        role_floor = safe_float(workload_ctx.get("base_ip_floor"), 4.25) or 4.25

        consistency_floor = max(4.0, min(role_floor, ip_from_bf + 0.20))

        bf_alignment_floor = max(3.8, ip_from_bf - 0.30)

        target_floor = max(consistency_floor, bf_alignment_floor)

        if projected_ip < target_floor:

            consistency_adjustment = target_floor - projected_ip

            projected_ip = target_floor



    pc_label = str((pitch_count_profile or {}).get("label") or "").upper()

    hook = str(manager_hook_status or "").upper()

    gs_label = str((game_script_risk or {}).get("label") or "").upper() if isinstance(game_script_risk, dict) else ""

    risk_points, reasons = 0, []

    if recent_l3_ip is not None and recent_l3_ip < 5.0:

        risk_points += 22; reasons.append("L3 IP below 5.0")

    elif recent_l3_ip is not None and recent_l3_ip >= 6.0:

        risk_points -= 8; reasons.append("L3 IP supports 6+ innings")

    if exp_bf < 20:

        risk_points += 18; reasons.append("expected BF under 20")

    elif exp_bf >= 24:

        risk_points -= 8; reasons.append("expected BF supports normal leash")

    if pc_label in ["SHORT_LEASH", "MONITOR"]:

        risk_points += 18; reasons.append(f"pitch count {pc_label}")

    elif pc_label in ["FULL_LEASH", "ELITE_VOLUME"]:

        risk_points -= 8; reasons.append(f"pitch count {pc_label}")

    if hook == "STRICT_HOOK":

        risk_points += 20; reasons.append("manager hook strict")

    if gs_label in ["HIGH", "EXTREME"]:

        risk_points += 12; reasons.append(f"game script {gs_label}")

    risk_score = int(clamp(50 + risk_points, 5, 95))

    if risk_score >= 78:

        label = "EARLY_PULL_HIGH"

    elif risk_score >= 62:

        label = "EARLY_PULL_MONITOR"

    elif risk_score <= 35:

        label = "FULL_INNINGS_PROFILE"

    else:

        label = "NORMAL_INNINGS"

    projected_ip = float(clamp(projected_ip, 3.0, 7.6))

    low_ip = float(clamp(projected_ip - (0.75 if risk_score < 62 else 1.05), 2.0, 8.0))

    high_ip = float(clamp(projected_ip + (0.70 if risk_score < 62 else 0.45), 2.0, 8.2))

    projected_pitches = None

    if ppb is not None:

        projected_pitches = float(clamp(exp_bf * (safe_float(ppb, 3.9) or 3.9), 45, 115))

    note_bits = reasons[:4] if reasons else ["normal innings/leash profile"]

    return {

        "projected_ip": round(projected_ip, 2),

        "ip_floor": round(low_ip, 2),

        "ip_ceiling": round(high_ip, 2),

        "recent_ip_l3": round(float(recent_l3_ip), 2) if recent_l3_ip is not None else None,

        "recent_ip_l5": round(float(recent_l5_ip), 2) if recent_l5_ip is not None else None,

        "recent_ip_l10": round(float(recent_l10_ip), 2) if recent_l10_ip is not None else None,

        "bf_per_ip": round(float(bf_per_ip), 2),

        "projected_pitches": round(projected_pitches, 0) if projected_pitches is not None else None,

        "early_pull_risk_score": risk_score,

        "early_pull_label": label,

        "workload_consistency_adjustment_ip": round(float(consistency_adjustment), 2),

        "workload_role_label": workload_ctx.get("role_label"),

        "workload_confidence": workload_ctx.get("confidence"),

        "note": f"Innings outcome {label}: IP {projected_ip:.1f} range {low_ip:.1f}-{high_ip:.1f}; " + "; ".join(note_bits) + (f"; BF/IP consistency +{consistency_adjustment:.2f} IP" if consistency_adjustment > 0 else ""),

    }



def tto_decay_factor(pa_index):

    """Third-time-through-order decay for PA-by-PA K probabilities."""

    i = int(pa_index)

    if i < 18:

        return 1.000

    if i < 27:

        return 0.925

    return 0.860



