ROTOWIRE_READER_FALLBACK_ENABLED = True

ROTOWIRE_READER_URL = "https://r.jina.ai/http://www.rotowire.com/baseball/daily-lineups.php"

ROTOWIRE_READER_URL_HTTPS = "https://r.jina.ai/http://r.jina.ai/http://https://www.rotowire.com/baseball/daily-lineups.php"

ROTOGRINDERS_READER_URL = "https://r.jina.ai/http://r.jina.ai/http://https://rotogrinders.com/lineups/mlb"



ROTOWIRE_TEAM_ALIASES = {

    "AZ": "ARI", "ARZ": "ARI",

    "ATH": "ATH", "OAK": "ATH",

    "CWS": "CHW", "CHW": "CHW",

    "KC": "KC", "KCR": "KC",

    "LAA": "LAA", "ANA": "LAA",

    "LAD": "LAD", "LA": "LAD",

    "MIA": "MIA", "FLA": "MIA",

    "NYM": "NYM", "NYY": "NYY",

    "SD": "SD", "SDP": "SD",

    "SF": "SF", "SFG": "SF",

    "TB": "TB", "TBR": "TB",

    "WSH": "WSH", "WAS": "WSH",

}



ROTOGRINDERS_TEAM_NAME_TO_ABBR = {

    "Arizona Diamondbacks": "ARI", "Atlanta Braves": "ATL", "Baltimore Orioles": "BAL",

    "Boston Red Sox": "BOS", "Chicago Cubs": "CHC", "Chicago White Sox": "CHW",

    "Cincinnati Reds": "CIN", "Cleveland Guardians": "CLE", "Colorado Rockies": "COL",

    "Detroit Tigers": "DET", "Houston Astros": "HOU", "Kansas City Royals": "KC",

    "Los Angeles Angels": "LAA", "Los Angeles Dodgers": "LAD", "Miami Marlins": "MIA",

    "Milwaukee Brewers": "MIL", "Minnesota Twins": "MIN", "New York Mets": "NYM",

    "New York Yankees": "NYY", "Athletics": "ATH", "Oakland Athletics": "ATH",

    "Philadelphia Phillies": "PHI", "Pittsburgh Pirates": "PIT", "San Diego Padres": "SD",

    "Seattle Mariners": "SEA", "San Francisco Giants": "SF", "St. Louis Cardinals": "STL",

    "Tampa Bay Rays": "TB", "Texas Rangers": "TEX", "Toronto Blue Jays": "TOR",

    "Washington Nationals": "WSH",

}



def _rw_norm_team_abbr(abbr):

    a = str(abbr or "").upper().strip()

    return ROTOWIRE_TEAM_ALIASES.get(a, a)



def _rw_clean_name(name):

    name = html.unescape(str(name or ""))

    name = name.replace("\xa0", " ")

    name = " ".join(name.split())

    # Rotowire sometimes appends injury/status markers in the visible text.

    for token in [" IL", " DTD", " OUT", " Q", " SUSP"]:

        if name.endswith(token):

            name = name[: -len(token)].strip()

    return name



def _rotowire_manual_status_to_source(status):

    s = str(status or "").upper()

    if "CONFIRMED" in s or "LOCKED" in s or "OFFICIAL" in s:

        return "ROTOWIRE_CONFIRMED_LINEUP"

    return "ROTOWIRE_EXPECTED_LINEUP"



def _rotowire_load_manual_lineups():

    try:

        if os.path.exists(ROTOWIRE_MANUAL_LINEUPS_FILE):

            df = pd.read_csv(ROTOWIRE_MANUAL_LINEUPS_FILE)

            return df if isinstance(df, pd.DataFrame) else pd.DataFrame()

    except Exception:

        pass

    return pd.DataFrame()



def _rotowire_save_manual_lineups(df):

    try:

        if df is None or not isinstance(df, pd.DataFrame) or df.empty:

            return {"saved": 0, "path": ROTOWIRE_MANUAL_LINEUPS_FILE, "reason": "empty"}

        out = df.copy()

        # Flexible headers: accept Team/TEAM, Batter/Player/Name, Hand/Bats, Position/Pos.

        rename = {}

        for c in list(out.columns):

            low = str(c).strip().lower()

            if low in {"team", "team_abbr", "abbr"}:

                rename[c] = "Team"

            elif low in {"order", "#", "batting_order", "battingorder"}:

                rename[c] = "Order"

            elif low in {"batter", "player", "name", "hitter"}:

                rename[c] = "Batter"

            elif low in {"hand", "bats", "bat_side", "batside"}:

                rename[c] = "Hand"

            elif low in {"position", "pos"}:

                rename[c] = "Position"

            elif low in {"status", "lineup_status", "source"}:

                rename[c] = "Status"

        out = out.rename(columns=rename)

        if "Team" not in out.columns or "Batter" not in out.columns:

            return {"saved": 0, "path": ROTOWIRE_MANUAL_LINEUPS_FILE, "error": "Need Team and Batter columns"}

        if "Order" not in out.columns:

            out["Order"] = out.groupby(out["Team"].astype(str).map(_rw_norm_team_abbr)).cumcount() + 1

        if "Hand" not in out.columns:

            out["Hand"] = ""

        if "Position" not in out.columns:

            out["Position"] = ""

        if "Status" not in out.columns:

            out["Status"] = "Expected Lineup"

        out["Team"] = out["Team"].astype(str).map(_rw_norm_team_abbr)

        out["Batter"] = out["Batter"].astype(str).map(_rw_clean_name)

        out["Order"] = pd.to_numeric(out["Order"], errors="coerce")

        out = out[out["Team"].astype(str).str.len().between(2, 4)]

        out = out[out["Batter"].astype(str).str.len() >= 3]

        out = out.sort_values(["Team", "Order"], na_position="last")

        out = out.drop_duplicates(["Team", "Batter"], keep="first")

        out.to_csv(ROTOWIRE_MANUAL_LINEUPS_FILE, index=False)

        teams = int(out["Team"].nunique()) if "Team" in out.columns else 0

        return {"saved": len(out), "teams": teams, "path": ROTOWIRE_MANUAL_LINEUPS_FILE}

    except Exception as e:

        return {"saved": 0, "path": ROTOWIRE_MANUAL_LINEUPS_FILE, "error": str(e)[:160]}



def _rotowire_manual_lineups_dict():

    df = _rotowire_load_manual_lineups()

    if df is None or not isinstance(df, pd.DataFrame) or df.empty:

        return {}

    rows_by_team = {}

    try:

        d = df.copy()

        d["Team"] = d["Team"].astype(str).map(_rw_norm_team_abbr)

        d["Order"] = pd.to_numeric(d.get("Order"), errors="coerce")

        d = d.sort_values(["Team", "Order"], na_position="last")

        for team, group in d.groupby("Team", sort=False):

            rows = []

            for i, (_, rr) in enumerate(group.head(9).iterrows(), start=1):

                hand = str(rr.get("Hand") or "").upper().strip()

                rows.append({

                    "Order": int(rr.get("Order")) if pd.notna(rr.get("Order")) else i,

                    "Batter": _rw_clean_name(rr.get("Batter")),

                    "Position": str(rr.get("Position") or "").upper().strip() or None,

                    "Hand": hand if hand in {"L", "R", "S"} else None,

                    "Lineup Source": _rotowire_manual_status_to_source(rr.get("Status")),

                    "Manual RotoWire Override": "YES",

                })

            if len(rows) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

                rows_by_team[_rw_norm_team_abbr(team)] = rows[:9]

    except Exception:

        return {}

    return rows_by_team



def _rotowire_payload_signal(txt):

    try:

        raw = str(txt or "")

        low = raw.lower()

        marker_count = low.count("expected lineup") + low.count("confirmed lineup")

        if marker_count >= 2:

            return True, marker_count, "lineup markers"

        team_count = len(set(re.findall(r"\b(ARI|ATL|BAL|BOS|CHC|CHW|CIN|CLE|COL|DET|HOU|KC|LAA|LAD|MIA|MIL|MIN|NYM|NYY|ATH|OAK|PHI|PIT|SD|SEA|SF|STL|TB|TEX|TOR|WSH|WAS)\b", raw.upper())))

        pos_count = len(re.findall(r"\b(C|1B|2B|3B|SS|LF|CF|RF|DH)\b", raw.upper()))

        name_like = len(re.findall(r"\b[A-Z][a-z]+\s+[A-Z][a-zA-Z.'-]+\b", raw))

        ok = len(raw) >= 4500 and team_count >= 4 and pos_count >= 24 and name_like >= 35

        return ok, marker_count, f"teams={team_count}; positions={pos_count}; names={name_like}"

    except Exception as e:

        return False, 0, f"signal error: {e}"



def _rotowire_curl_fetch(url, headers=None, timeout=24):

    try:

        import subprocess

        h = headers or {}

        cmd = [

            "curl", "-L", "--compressed", "--http1.1", "--tlsv1.2",

            "--max-time", str(int(timeout)),

            "-A", str(h.get("User-Agent") or "Mozilla/5.0"),

            "-H", "Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",

            "-H", "Accept-Language: en-US,en;q=0.9",

            str(url),

        ]

        res = subprocess.run(cmd, capture_output=True, text=True, timeout=int(timeout) + 4)

        txt = res.stdout or ""

        return {

            "ok": res.returncode == 0 and bool(txt),

            "text": txt,

            "status_code": res.returncode,

            "url": url,

            "error": (res.stderr or "")[:240],

        }

    except Exception as e:

        return {"ok": False, "text": "", "status_code": None, "url": url, "error": str(e)[:240]}



@st.cache_data(ttl=300, show_spinner=False)

def _rotowire_fetch_daily_lineups_payload():

    """Fetch RotoWire lineups with redundant same-source transports.



    Reliability order:

      1) widgets.rotowire.com (server-rendered and usually easiest to parse)

      2) canonical www.rotowire.com page

      3) Reader mirror of canonical RotoWire page



    All three are the same RotoWire daily-lineups product. Diagnostics preserve

    which transport actually succeeded so Railway failures are visible.

    """

    payload = {

        "text": "", "transport": "NONE", "status": "DISABLED", "http_status": None,

        "bytes": 0, "error": "", "url": ROTOWIRE_DAILY_LINEUPS_URL,

    }

    if not ROTOWIRE_EXPECTED_LINEUPS_ENABLED:

        return payload



    headers_pool = [

        {

            "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1",

            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",

            "Accept-Language": "en-US,en;q=0.9", "Cache-Control": "no-cache",

        },

        {

            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36",

            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",

            "Accept-Language": "en-US,en;q=0.9",

        },

    ]

    errors = []

    targets = [

        (ROTOWIRE_WIDGETS_LINEUPS_URL, "ROTOWIRE_WIDGETS"),

        (ROTOWIRE_DAILY_LINEUPS_URL, "DIRECT_ROTOWIRE"),

        (ROTOWIRE_DAILY_LINEUPS_URL + "?view=lineups", "DIRECT_ROTOWIRE_VIEW_LINEUPS"),

    ]

    for url, transport in targets:

        for headers in headers_pool:

            try:

                r = requests.get(url, timeout=18, headers=headers, allow_redirects=True)

                txt = r.text or ""

                signal_ok, marker_count, signal_note = _rotowire_payload_signal(txt)

                if r.status_code < 400 and signal_ok:

                    payload.update({

                        "text": txt, "transport": transport, "status": "SUCCESS",

                        "http_status": r.status_code, "bytes": len(txt), "error": "; ".join(errors)[:700],

                        "auto_pull_signal": signal_note,

                        "auto_pull_version": ROTOWIRE_AUTO_PULL_VERSION,

                        "url": str(r.url),

                    })

                    return payload

                errors.append(f"{transport} HTTP {r.status_code}; bytes={len(txt)}; lineup_markers={marker_count}; {signal_note}")

            except Exception as exc:

                errors.append(f"{transport} error: {type(exc).__name__}: {exc}")

            curl = _rotowire_curl_fetch(url, headers=headers, timeout=24)

            txt = curl.get("text") or ""

            signal_ok, marker_count, signal_note = _rotowire_payload_signal(txt)

            if curl.get("ok") and signal_ok:

                payload.update({

                    "text": txt, "transport": transport + "_CURL", "status": "SUCCESS",

                    "http_status": curl.get("status_code"), "bytes": len(txt), "error": "; ".join(errors)[:700],

                    "auto_pull_signal": signal_note,

                    "auto_pull_version": ROTOWIRE_AUTO_PULL_VERSION,

                    "url": str(curl.get("url") or url),

                })

                return payload

            if txt or curl.get("error"):

                errors.append(f"{transport}_CURL rc={curl.get('status_code')}; bytes={len(txt)}; lineup_markers={marker_count}; {signal_note}; {curl.get('error')}")



    if ROTOWIRE_READER_FALLBACK_ENABLED:

        for reader_url in [ROTOWIRE_READER_URL, ROTOWIRE_READER_URL_HTTPS]:

            try:

                r = requests.get(reader_url, timeout=22, headers={"User-Agent": "Mozilla/5.0", "Accept": "text/plain,text/markdown,*/*"})

                txt = r.text or ""

                signal_ok, marker_count, signal_note = _rotowire_payload_signal(txt)

                if r.status_code < 400 and signal_ok:

                    payload.update({

                        "text": txt, "transport": "ROTOWIRE_VIA_READER", "status": "SUCCESS",

                        "http_status": r.status_code, "bytes": len(txt), "error": "; ".join(errors)[:700],

                        "auto_pull_signal": signal_note,

                        "auto_pull_version": ROTOWIRE_AUTO_PULL_VERSION,

                        "url": reader_url,

                    })

                    return payload

                errors.append(f"reader HTTP {r.status_code}; bytes={len(txt)}; lineup_markers={marker_count}; {signal_note}")

            except Exception as exc:

                errors.append(f"reader error: {type(exc).__name__}: {exc}")



    payload.update({"status": "FAILED", "error": "; ".join(errors)[:1200], "auto_pull_version": ROTOWIRE_AUTO_PULL_VERSION})

    return payload



def _rotowire_fetch_daily_lineups_html():

    # Backward-compatible helper used by older code paths.

    return (_rotowire_fetch_daily_lineups_payload() or {}).get("text", "")





@st.cache_data(ttl=300, show_spinner=False)

def _rotogrinders_fetch_lineups_payload():

    payload = {

        "text": "", "transport": "NONE", "status": "DISABLED", "http_status": None,

        "bytes": 0, "error": "", "url": ROTOGRINDERS_LINEUPS_URL,

        "auto_pull_version": ROTOWIRE_AUTO_PULL_VERSION,

    }

    headers = {

        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36",

        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",

        "Accept-Language": "en-US,en;q=0.9",

    }

    errors = []

    for url, transport in [(ROTOGRINDERS_LINEUPS_URL, "DIRECT_ROTOGRINDERS"), (ROTOGRINDERS_READER_URL, "ROTOGRINDERS_VIA_READER")]:

        try:

            r = requests.get(url, timeout=22, headers=headers, allow_redirects=True)

            txt = r.text or ""

            team_hits = sum(1 for name in ROTOGRINDERS_TEAM_NAME_TO_ABBR if name in txt)

            player_like = len(re.findall(r"\b[A-Z][a-zA-Z.'-]+\s+[A-Z][a-zA-Z.'-]+\s+\([LRS]\)", txt))

            if r.status_code < 400 and len(txt) >= 4500 and team_hits >= 4 and player_like >= 30:

                payload.update({

                    "text": txt,

                    "transport": transport,

                    "status": "SUCCESS",

                    "http_status": r.status_code,

                    "bytes": len(txt),

                    "error": "; ".join(errors)[:700],

                    "url": str(r.url),

                    "auto_pull_signal": f"teams={team_hits}; players={player_like}",

                })

                return payload

            errors.append(f"{transport} HTTP {r.status_code}; bytes={len(txt)}; teams={team_hits}; players={player_like}")

        except Exception as exc:

            errors.append(f"{transport} error: {type(exc).__name__}: {exc}")

    payload.update({"status": "FAILED", "error": "; ".join(errors)[:1200]})

    return payload





def _rotogrinders_extract_lineups_from_html(raw_html):

    """Parse public Rotogrinders MLB lineup text as a fallback source."""

    if not raw_html:

        return {}

    try:

        from bs4 import BeautifulSoup

        soup = BeautifulSoup(raw_html, "html.parser")

        for bad in soup(["script", "style", "noscript"]):

            bad.decompose()

        lines = [_rw_clean_name(x) for x in soup.get_text("\n", strip=True).split("\n")]

        lines = [x for x in lines if x]

    except Exception:

        lines = [_rw_clean_name(x) for x in str(raw_html).splitlines() if _rw_clean_name(x)]



    team_names = list(ROTOGRINDERS_TEAM_NAME_TO_ABBR.keys())



    def is_team_name(txt):

        return txt in ROTOGRINDERS_TEAM_NAME_TO_ABBR



    def parse_player_line(txt):

        # Examples: Steven Kwan (L) 7 6%, Pete Crow-Armstrong (L) 10 6%.

        m = re.match(r"^([A-Z][A-Za-z.'’\-]+(?:\s+[A-Z][A-Za-z.'’\-]+)+)\s+\(([LRS])\)(?:\s+.*)?$", txt)

        if not m:

            return None, None

        name = _rw_clean_name(m.group(1).replace("’", "'"))

        if any(bad in name.lower() for bad in ["lineup", "weather", "forecast", "optimizer"]):

            return None, None

        return name, m.group(2).upper()



    out = {}

    i = 0

    n = len(lines)

    while i < n:

        if not is_team_name(lines[i]):

            i += 1

            continue

        team_a = ROTOGRINDERS_TEAM_NAME_TO_ABBR.get(lines[i])

        j = i + 1

        while j < min(i + 25, n) and not is_team_name(lines[j]):

            j += 1

        if j >= n or not is_team_name(lines[j]):

            i += 1

            continue

        team_b = ROTOGRINDERS_TEAM_NAME_TO_ABBR.get(lines[j])

        if not team_a or not team_b or team_a == team_b:

            i += 1

            continue



        # End before next game-team pair.

        end = n

        k = j + 1

        while k < n - 1:

            if is_team_name(lines[k]):

                kk = k + 1

                while kk < min(k + 25, n) and not is_team_name(lines[kk]):

                    kk += 1

                if kk < n and is_team_name(lines[kk]):

                    end = k

                    break

            k += 1

        block = lines[j + 1:end]



        lineup_markers = [idx for idx, txt in enumerate(block) if "lineup" in txt.lower() and ("released" in txt.lower() or "confirmed" in txt.lower() or "not released" in txt.lower())]

        if len(lineup_markers) < 2:

            i = end if end < n else i + 1

            continue



        def collect(marker_idx, source):

            rows = []

            pos = 1

            idx = marker_idx + 1

            while idx < len(block) and len(rows) < 9:

                cur = block[idx]

                if "lineup" in cur.lower() and rows:

                    break

                if re.fullmatch(r"\d+", cur):

                    pos = int(cur)

                    idx += 1

                    continue

                name, hand = parse_player_line(cur)

                if name:

                    rows.append({

                        "Order": len(rows) + 1 if not pos else pos,

                        "Batter": name,

                        "Position": None,

                        "Hand": hand,

                        "Lineup Source": source,

                        "Lineup Provider": "ROTOGRINDERS",

                    })

                    pos = len(rows) + 1

                idx += 1

            # Normalize orders if duplicate/missing.

            for order, row in enumerate(rows, start=1):

                row["Order"] = order

            return rows[:9]



        for team, marker_idx in [(team_a, lineup_markers[0]), (team_b, lineup_markers[1])]:

            marker_txt = block[marker_idx].lower()

            source = "ROTOGRINDERS_CONFIRMED_LINEUP" if "confirmed" in marker_txt and "not" not in marker_txt else "ROTOGRINDERS_PROJECTED_LINEUP"

            rows = collect(marker_idx, source)

            if len(rows) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

                out[_rw_norm_team_abbr(team)] = rows[:9]



        i = end if end < n else i + 1

    return out



def _rotowire_extract_lineups_from_html(raw_html):

    """Best-effort Rotowire parser. Returns {TEAM_ABBR: [lineup rows]}.



    The parser is intentionally defensive because public page markup can change.

    If it cannot parse cleanly it returns {} and the app falls back to MLB projected lineups.

    """

    if not raw_html:

        return {}

    lineups = {}



    # Primary parser: Rotowire historically uses lineup__box / lineup__team / lineup__list classes.

    try:

        from bs4 import BeautifulSoup

        soup = BeautifulSoup(raw_html, "html.parser")

        game_blocks = []

        for sel in ["div.lineup__box", "div.lineup", "div[class*='lineup']"]:

            game_blocks = soup.select(sel)

            if game_blocks:

                break



        for block in game_blocks:

            txt = block.get_text(" ", strip=True)

            if len(txt) < 40:

                continue



            abbr_elems = block.select(".lineup__abbr, [class*='abbr'], [class*='team-abbr']")

            abbrs = []

            for e in abbr_elems:

                t = _rw_norm_team_abbr(e.get_text(" ", strip=True))

                if 2 <= len(t) <= 4 and t not in abbrs:

                    abbrs.append(t)

            if len(abbrs) < 2:

                # Fallback: search for standalone uppercase team tokens inside the game block.

                import re

                tokens = re.findall(r"\b(ARI|ATL|BAL|BOS|CHC|CHW|CIN|CLE|COL|DET|HOU|KC|LAA|LAD|MIA|MIL|MIN|NYM|NYY|ATH|OAK|PHI|PIT|SD|SEA|SF|STL|TB|TEX|TOR|WSH)\b", txt)

                for t in tokens:

                    nt = _rw_norm_team_abbr(t)

                    if nt not in abbrs:

                        abbrs.append(nt)

                abbrs = abbrs[:2]

            if len(abbrs) < 2:

                continue



            list_elems = block.select("ul.lineup__list, ol.lineup__list, [class*='lineup__list'], [class*='players']")

            if len(list_elems) < 2:

                # Try splitting team columns.

                list_elems = block.select(".lineup__team, [class*='lineup__team']")

            if len(list_elems) < 2:

                continue



            for team_abbr, list_el in zip(abbrs[:2], list_elems[:2]):

                rows = []

                player_nodes = list_el.select("li, div[class*='player'], span[class*='player']")

                seen = set()

                for node in player_nodes:

                    line = node.get_text(" ", strip=True)

                    if not line or len(line) < 3:

                        continue

                    # Prefer anchor text, usually the clean player name.

                    a = node.find("a")

                    name = _rw_clean_name(a.get_text(" ", strip=True) if a else line)

                    import re

                    # Remove leading lineup order/position tokens from fallback text.

                    name = re.sub(r"^(\d+\s+)?(P|C|1B|2B|3B|SS|LF|CF|RF|DH)\s+", "", name, flags=re.I).strip()

                    # Stop if node is clearly a pitcher row or status text.

                    if name.upper() in {"LINEUP", "EXPECTED LINEUP", "CONFIRMED LINEUP", "UNKNOWN", "PITCHER"}:

                        continue

                    # Keep likely human names only.

                    if len(name.split()) < 2 or len(name) > 34:

                        continue

                    key = normalize_name(name)

                    if key in seen:

                        continue

                    seen.add(key)

                    pos_match = re.search(r"\b(C|1B|2B|3B|SS|LF|CF|RF|DH)\b", line)

                    hand_match = re.search(r"\b([LRS])\b", line)

                    rows.append({

                        "Order": len(rows) + 1,

                        "Batter": name,

                        "Position": pos_match.group(1).upper() if pos_match else None,

                        "Hand": hand_match.group(1).upper() if hand_match else None,

                        "Lineup Source": "ROTOWIRE_EXPECTED_LINEUP",

                    })

                    if len(rows) >= 9:

                        break

                if len(rows) >= 5:

                    lineups[_rw_norm_team_abbr(team_abbr)] = rows[:9]

    except Exception:

        pass



    # Marker/DOM parser for RotoWire's current responsive daily-lineups layout.

    try:

        marker_lineups = _rotowire_extract_lineups_from_marker_dom(raw_html)

        for t_abbr, t_rows in (marker_lineups or {}).items():

            if len(t_rows or []) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS and len(lineups.get(t_abbr, [])) < len(t_rows):

                lineups[t_abbr] = t_rows[:9]

    except Exception:

        pass



    # Text fallback parser: works when Rotowire's visible page text is available but CSS classes changed.

    try:

        text_lineups = _rotowire_extract_lineups_from_visible_text(raw_html)

        for t_abbr, t_rows in (text_lineups or {}).items():

            if len(t_rows or []) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS and len(lineups.get(t_abbr, [])) < len(t_rows):

                lineups[t_abbr] = t_rows[:9]

    except Exception:

        pass



    return lineups





def _rotowire_extract_lineups_from_marker_dom(raw_html):

    """Parse the current RotoWire daily-lineups DOM around lineup status markers.



    RotoWire's markup changes often, but the page consistently exposes two lineup

    status labels per game and 9 position/player rows per team. This parser finds

    each Expected/Confirmed Lineup marker, identifies its game card and team side,

    then reads that side's position/player rows. It does not depend on one brittle

    CSS class name.

    """

    if not raw_html:

        return {}

    try:

        import re

        from bs4 import BeautifulSoup

        soup = BeautifulSoup(raw_html, "html.parser")

    except Exception:

        return {}



    valid_teams = set("ARI ATL BAL BOS CHC CHW CIN CLE COL DET HOU KC LAA LAD MIA MIL MIN NYM NYY ATH OAK PHI PIT SD SEA SF STL TB TEX TOR WSH WAS".split())

    pos_tokens = {"C", "1B", "2B", "3B", "SS", "LF", "CF", "RF", "DH"}



    def _team_tokens(node):

        vals = []

        # Images on the page have team abbreviation alts and/or filenames.

        for img in node.find_all("img"):

            for raw in (img.get("alt"), img.get("title"), img.get("src")):

                txt = str(raw or "")

                for tok in re.findall(r"(?:^|[/_\-])([A-Z]{2,3})(?:[._/\-]|$)", txt.upper()):

                    nt = _rw_norm_team_abbr(tok)

                    if tok in valid_teams or nt in {_rw_norm_team_abbr(x) for x in valid_teams}:

                        if nt not in vals:

                            vals.append(nt)

        # Explicit abbreviation/data attributes are preferred when available.

        for el in node.find_all(True):

            attrs = " ".join(str(el.get(k, "")) for k in ("data-team", "data-abbr", "data-team-abbr", "aria-label"))

            txt = " ".join([attrs, el.get_text(" ", strip=True) if any(x in " ".join(el.get("class", [])) for x in ("abbr", "team") ) else ""])

            for tok in re.findall(r"\b[A-Z]{2,3}\b", txt.upper()):

                nt = _rw_norm_team_abbr(tok)

                if tok in valid_teams or nt in {_rw_norm_team_abbr(x) for x in valid_teams}:

                    if nt not in vals:

                        vals.append(nt)

        if len(vals) < 2:

            txt = node.get_text("\n", strip=True)

            for tok in re.findall(r"(?m)^\s*(ARI|ATL|BAL|BOS|CHC|CHW|CIN|CLE|COL|DET|HOU|KC|LAA|LAD|MIA|MIL|MIN|NYM|NYY|ATH|OAK|PHI|PIT|SD|SEA|SF|STL|TB|TEX|TOR|WSH|WAS)\s*$", txt):

                nt = _rw_norm_team_abbr(tok)

                if nt not in vals:

                    vals.append(nt)

        return vals[:2]



    def _plausible_name(text):

        t = _rw_clean_name(text)

        t = re.sub(r"^[\s*•+\-]+", "", t).strip()

        t = re.sub(r"^\d+\s+", "", t).strip()

        m = re.match(r"^(.+?)\s+([LRS])$", t)

        hand = None

        if m:

            t, hand = m.group(1).strip(), m.group(2).upper()

        if not (3 <= len(t) <= 38) or len(t.split()) < 2:

            return None, None

        low = t.lower()

        if any(x in low for x in ("expected lineup", "confirmed lineup", "starting pitcher", "home run odds", "not announced", "watch now", "tickets")):

            return None, None

        if re.search(r"\bERA\b|\b\d+-\d+\b", t, re.I):

            return None, None

        return t, hand



    def _parse_team_scope(scope, source):

        rows = []

        seen = set()

        # First try semantic row containers (li/tr), which preserve position-name pairing.

        candidates = scope.find_all(["li", "tr"])

        for node in candidates:

            txt = node.get_text(" ", strip=True)

            pm = re.search(r"(?:^|\s)(C|1B|2B|3B|SS|LF|CF|RF|DH)(?:\s|$)", txt)

            if not pm:

                continue

            pos = pm.group(1).upper()

            a = node.find("a")

            name, hand = _plausible_name(a.get_text(" ", strip=True) if a else re.sub(r"^.*?\b" + re.escape(pos) + r"\b", "", txt, count=1))

            if not name:

                continue

            key = normalize_name(name)

            if key in seen:

                continue

            seen.add(key)

            if not hand:

                hm = re.search(r"\b([LRS])\s*$", txt)

                hand = hm.group(1).upper() if hm else None

            rows.append({"Order": len(rows)+1, "Batter": name, "Position": pos, "Hand": hand, "Lineup Source": source})

            if len(rows) == 9:

                return rows



        # Generic descendant-order fallback for div/span based layouts.

        tokens = []

        for el in scope.find_all(["div", "span", "a", "strong"]):

            t = _rw_clean_name(el.get_text(" ", strip=True))

            if t and len(t) <= 60 and (not tokens or t != tokens[-1]):

                tokens.append(t)

        i = 0

        while i < len(tokens) and len(rows) < 9:

            cur = tokens[i].upper().strip()

            if cur in pos_tokens:

                for j in range(i+1, min(i+6, len(tokens))):

                    if tokens[j].upper().strip() in pos_tokens:

                        break

                    name, hand = _plausible_name(tokens[j])

                    if name:

                        key = normalize_name(name)

                        if key not in seen:

                            seen.add(key)

                            rows.append({"Order": len(rows)+1, "Batter": name, "Position": cur, "Hand": hand, "Lineup Source": source})

                        i = j

                        break

            i += 1

        return rows[:9]



    out = {}

    marker_nodes = []

    for text in soup.find_all(string=re.compile(r"^\s*(Expected|Confirmed) Lineup\s*$", re.I)):

        marker_nodes.append(text.parent)



    for marker in marker_nodes:

        label = marker.get_text(" ", strip=True)

        source = "ROTOWIRE_CONFIRMED_LINEUP" if "confirmed" in label.lower() else "ROTOWIRE_EXPECTED_LINEUP"

        # Find the smallest ancestor containing both team lineup markers: the game card.

        game = None

        anc = marker

        for _ in range(9):

            anc = getattr(anc, "parent", None)

            if anc is None:

                break

            count = len(anc.find_all(string=re.compile(r"^\s*(Expected|Confirmed) Lineup\s*$", re.I)))

            teams = _team_tokens(anc)

            if count >= 2 and len(teams) >= 2:

                game = anc

                break

        if game is None:

            continue

        teams = _team_tokens(game)

        if len(teams) < 2:

            continue

        game_markers = [x.parent for x in game.find_all(string=re.compile(r"^\s*(Expected|Confirmed) Lineup\s*$", re.I))]

        try:

            side_idx = game_markers.index(marker)

        except ValueError:

            side_idx = 0

        if side_idx > 1:

            continue

        team = teams[side_idx]



        # Find the smallest ancestor representing only this team side and containing >=5 positions.

        scope = marker.parent

        best = None

        for _ in range(8):

            scope = getattr(scope, "parent", None)

            if scope is None or scope == game.parent:

                break

            txt = scope.get_text(" ", strip=True)

            pos_count = len(re.findall(r"(?:^|\s)(?:C|1B|2B|3B|SS|LF|CF|RF|DH)(?:\s|$)", txt))

            marker_count = len(scope.find_all(string=re.compile(r"^\s*(Expected|Confirmed) Lineup\s*$", re.I)))

            if pos_count >= 5 and marker_count <= 1:

                best = scope

                break

        if best is None:

            # Fallback: use the game card but isolate content from this marker to the next marker.

            best = marker.parent

            while getattr(best, "parent", None) is not None and best.parent != game:

                best = best.parent

        rows = _parse_team_scope(best, source)

        if len(rows) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

            out[team] = rows[:9]

    return out



def _rotowire_extract_lineups_from_visible_text(raw_html):

    """Fallback Rotowire parser using visible text order.



    Rotowire's page can render lineups without stable lineup__ CSS classes.

    This parser only reads the lineup text and returns team batting orders.

    It never touches Underdog/PrizePicks/sportsbook line pulls.

    """

    if not raw_html:

        return {}

    try:

        from bs4 import BeautifulSoup

        soup = BeautifulSoup(raw_html, "html.parser")

        for bad in soup(["script", "style", "noscript"]):

            bad.decompose()

        lines = []

        import re

        for x in soup.get_text("\n", strip=True).split("\n"):

            t = _rw_clean_name(x)

            # Reader/markdown fallbacks may preserve bullets and markdown links.

            t = re.sub(r"^[\s*•+-]+", "", t).strip()

            t = re.sub(r"!?(?:\[([^\]]+)\])\([^)]*\)", r"\1", t).strip()

            if t:

                lines.append(t)

    except Exception:

        return {}



    import re

    team_tokens = set("ARI ATL BAL BOS CHC CHW CIN CLE COL DET HOU KC LAA LAD MIA MIL MIN NYM NYY ATH OAK PHI PIT SD SEA SF STL TB TEX TOR WSH WAS".split())

    pos_tokens = {"C", "1B", "2B", "3B", "SS", "LF", "CF", "RF", "DH"}

    stop_tokens = {

        "Home Run Odds", "Starting Pitcher Intel", "Umpire:", "LINE", "O/U", "Watch Now", "Tickets", "Alerts",

        "Sportsbook Odds", "Display Preference", "Show DFS Salaries", "View Slates", "Classic", "Showdown", "Tiers"

    }



    def is_team_token(t):

        return _rw_norm_team_abbr(t) in {_rw_norm_team_abbr(x) for x in team_tokens}



    def is_pos(t):

        return str(t or "").upper().strip() in pos_tokens



    def clean_player_line(t):

        t = _rw_clean_name(t)

        if not t or t.startswith("$"):

            return None, None

        if t in stop_tokens or t.upper() in {x.upper() for x in stop_tokens}:

            return None, None

        if re.search(r"\b\d+-\d+\b", t) or " ERA" in t or re.match(r"^\d+(\.\d+)?\s", t):

            return None, None

        m = re.match(r"^(.+?)\s+([LRS])$", t)

        hand = None

        if m:

            t = m.group(1).strip()

            hand = m.group(2).strip().upper()

        # skip headings/status lines

        bad_words = {"Confirmed Lineup", "Expected Lineup", "Unknown Lineup", "PRIM", "Lineup", "Subscribe", "Log In"}

        if t in bad_words:

            return None, None

        if len(t) < 3 or len(t) > 34:

            return None, None

        # Must look like a name: either two words, or abbreviated first initial + surname.

        if len(t.split()) < 2:

            return None, None

        if not re.search(r"[A-Za-z]", t):

            return None, None

        return t, hand



    def collect_lineup(block, start_idx, source_label):

        rows = []

        i = start_idx + 1

        safety = 0

        while i < len(block) and len(rows) < 9 and safety < 90:

            safety += 1

            cur = block[i]

            if cur in ("Confirmed Lineup", "Expected Lineup", "Unknown Lineup") and rows:

                break

            if cur.startswith("Umpire") or cur in {"LINE", "O/U", "Home Run Odds", "Starting Pitcher Intel"}:

                if rows:

                    break

            if is_pos(cur):

                pos = cur.upper().strip()

                # Find the next plausible player name before the next position/status line.

                j = i + 1

                while j < len(block) and j < i + 8:

                    nxt = block[j]

                    if is_pos(nxt) or nxt in ("Confirmed Lineup", "Expected Lineup", "Unknown Lineup"):

                        break

                    name, hand = clean_player_line(nxt)

                    if name:

                        rows.append({

                            "Order": len(rows) + 1,

                            "Batter": name,

                            "Position": pos,

                            "Hand": hand,

                            "Lineup Source": source_label,

                        })

                        i = j

                        break

                    j += 1

            i += 1

        return rows



    out = {}

    n = len(lines)

    # Find pairs of MLB team abbreviations that mark each game card.

    i = 0

    while i < n:

        cur = _rw_norm_team_abbr(lines[i])

        if not is_team_token(cur):

            i += 1

            continue

        pair_j = None

        for j in range(i + 1, min(i + 40, n)):

            nxt = _rw_norm_team_abbr(lines[j])

            if is_team_token(nxt) and nxt != cur:

                pair_j = j

                break

        if pair_j is None:

            i += 1

            continue

        abbrs = [cur, _rw_norm_team_abbr(lines[pair_j])]

        # Limit this game card to before the next likely game card.

        end = min(pair_j + 360, n)

        for k in range(pair_j + 1, min(pair_j + 360, n - 1)):

            if k > pair_j + 40 and is_team_token(lines[k]):

                for kk in range(k + 1, min(k + 40, n)):

                    if is_team_token(lines[kk]) and _rw_norm_team_abbr(lines[kk]) != _rw_norm_team_abbr(lines[k]):

                        end = k

                        break

                if end == k:

                    break

        block = lines[pair_j + 1:end]

        markers = []

        for idx, t in enumerate(block):

            if t in ("Confirmed Lineup", "Expected Lineup"):

                src = "ROTOWIRE_CONFIRMED_LINEUP" if t == "Confirmed Lineup" else "ROTOWIRE_EXPECTED_LINEUP"

                markers.append((idx, src))

        if len(markers) >= 2:

            for team_abbr, (midx, src) in zip(abbrs[:2], markers[:2]):

                rows = collect_lineup(block, midx, src)

                if len(rows) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

                    out[_rw_norm_team_abbr(team_abbr)] = rows[:9]

            i = end

        else:

            i += 1

    return out



@st.cache_data(ttl=600, show_spinner=False)

def get_rotowire_expected_lineups_bundle():

    payload = _rotowire_fetch_daily_lineups_payload() or {}

    raw = payload.get("text", "") or ""

    lineups = _rotowire_extract_lineups_from_html(raw) if raw else {}

    provider_counts = {"ROTOWIRE": len(lineups or {}), "ROTOGRINDERS": 0, "MANUAL": 0}

    rg_payload = {}

    rg_lineups = {}

    if ROTOWIRE_EXPECTED_LINEUPS_ENABLED and sum(1 for v in (lineups or {}).values() if len(v or []) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS) < 10:

        try:

            rg_payload = _rotogrinders_fetch_lineups_payload() or {}

            rg_raw = rg_payload.get("text", "") or ""

            rg_lineups = _rotogrinders_extract_lineups_from_html(rg_raw) if rg_raw else {}

            provider_counts["ROTOGRINDERS"] = len(rg_lineups or {})

            if rg_lineups:

                lineups = dict(lineups or {})

                for team, rows in rg_lineups.items():

                    team = _rw_norm_team_abbr(team)

                    if len(lineups.get(team, []) or []) < ROTOWIRE_LINEUP_MIN_VALID_HITTERS and len(rows or []) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

                        lineups[team] = rows[:9]

        except Exception as _rg_e:

            rg_payload = {"status": "FAILED", "error": str(_rg_e)[:240], "transport": "ROTOGRINDERS_ERROR"}

    manual_lineups = _rotowire_manual_lineups_dict()

    if manual_lineups:

        # Auto RotoWire has priority. Manual RotoWire rows only fill teams the

        # live fetch/parser did not produce. Rotogrinders fallback is tried

        # before manual rows.

        lineups = dict(lineups or {})

        provider_counts["MANUAL"] = len(manual_lineups or {})

        for team, rows in manual_lineups.items():

            team = _rw_norm_team_abbr(team)

            if len(lineups.get(team, []) or []) < ROTOWIRE_LINEUP_MIN_VALID_HITTERS and len(rows or []) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

                lineups[_rw_norm_team_abbr(team)] = rows[:9]

    team_counts = {str(k): len(v or []) for k, v in (lineups or {}).items()}

    parsed_teams = sum(1 for v in team_counts.values() if v >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS)

    status = dict(payload)

    status.pop("text", None)

    status["manual_override_file"] = ROTOWIRE_MANUAL_LINEUPS_FILE

    status["manual_override_teams"] = len(manual_lineups or {})

    status["rotogrinders_status"] = rg_payload.get("status", "SKIPPED") if isinstance(rg_payload, dict) else "SKIPPED"

    status["rotogrinders_transport"] = rg_payload.get("transport", "NONE") if isinstance(rg_payload, dict) else "NONE"

    status["rotogrinders_error"] = rg_payload.get("error", "") if isinstance(rg_payload, dict) else ""

    status["provider_counts"] = provider_counts

    status["parsed_teams"] = parsed_teams

    status["team_counts"] = team_counts

    if rg_lineups and payload.get("status") != "SUCCESS" and parsed_teams >= 1:

        status["status"] = "SUCCESS"

        status["transport"] = "ROTOGRINDERS_BACKUP+" + str(status.get("transport") or "FETCH")

    if manual_lineups and payload.get("status") != "SUCCESS" and parsed_teams >= 1:

        status["status"] = "SUCCESS"

        status["transport"] = "MANUAL_ROTOWIRE_BACKUP+" + str(status.get("transport") or "FETCH")

    if payload.get("status") == "SUCCESS" and parsed_teams < 2:

        status["status"] = "PARSE_FAILED"

        status["error"] = ((status.get("error") or "") + "; RotoWire page fetched but lineup parser found too few teams").strip("; ")

    return {"lineups": lineups, "diagnostics": status}





def get_rotowire_expected_lineups():

    return (get_rotowire_expected_lineups_bundle() or {}).get("lineups", {})





def get_rotowire_lineup_diagnostics(team_abbr=None):

    bundle = get_rotowire_expected_lineups_bundle() or {}

    diag = dict(bundle.get("diagnostics") or {})

    if team_abbr:

        ta = _rw_norm_team_abbr(team_abbr)

        rows = ((bundle.get("lineups") or {}).get(ta) or [])

        diag["team"] = ta

        diag["team_batter_count"] = len(rows)

        if len(rows) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS and diag.get("status") in {"SUCCESS", "PARSE_FAILED"}:

            diag["team_status"] = "SUCCESS"

        else:

            diag["team_status"] = "UNAVAILABLE"

    return diag



def _game_team_abbr_from_box_or_live(game_pk, opp_side):

    try:

        live = safe_get_json(f"{MLB_LIVE}/game/{game_pk}/feed/live", timeout=12) or {}

        team = (((live.get("gameData") or {}).get("teams") or {}).get(opp_side) or {})

        abbr = team.get("abbreviation") or team.get("fileCode") or team.get("teamCode")

        if abbr:

            return _rw_norm_team_abbr(abbr)

        box_team = ((((live.get("liveData") or {}).get("boxscore") or {}).get("teams") or {}).get(opp_side) or {}).get("team") or {}

        return _rw_norm_team_abbr(box_team.get("abbreviation") or box_team.get("fileCode") or box_team.get("teamCode"))

    except Exception:

        return None



@st.cache_data(ttl=86400, show_spinner=False)

def _mlb_search_player_id_by_name(name):

    try:

        nm = _rw_clean_name(name)

        if not nm:

            return None

        data = safe_get_json(f"{MLB_BASE}/people/search", params={"names": nm, "sportIds": 1}, timeout=10) or {}

        people = data.get("people") or []

        if not people:

            return None

        target = normalize_name(nm)

        best = None

        best_ratio = 0.0

        for person in people:

            full = person.get("fullName") or ""

            ratio = difflib.SequenceMatcher(None, target, normalize_name(full)).ratio()

            if ratio > best_ratio:

                best_ratio = ratio

                best = person

        if best and best_ratio >= 0.78:

            return best.get("id")

    except Exception:

        return None

    return None



@st.cache_data(ttl=21600, show_spinner=False)

def _mlb_active_team_roster_by_abbr(team_abbr):

    """Active MLB roster used to resolve RotoWire abbreviated names (e.g. C. Jensen)."""

    ta = _rw_norm_team_abbr(team_abbr)

    if not ta:

        return []

    try:

        teams = safe_get_json(f"{MLB_BASE}/teams", params={"sportId": 1}, timeout=12) or {}

        team_id = None

        for t in teams.get("teams") or []:

            aliases = {

                _rw_norm_team_abbr(t.get("abbreviation")), _rw_norm_team_abbr(t.get("teamCode")),

                _rw_norm_team_abbr(t.get("fileCode")),

            }

            if ta in aliases:

                team_id = t.get("id"); break

        if not team_id:

            return []

        data = safe_get_json(f"{MLB_BASE}/teams/{team_id}/roster", params={"rosterType": "active"}, timeout=12) or {}

        out = []

        for rr in data.get("roster") or []:

            person = rr.get("person") or {}

            if person.get("id") and person.get("fullName"):

                out.append({"id": person.get("id"), "name": person.get("fullName")})

        return out

    except Exception:

        return []





def _mlb_resolve_lineup_player_id(name, team_abbr=None):

    """Resolve full or abbreviated lineup names, preferring the expected player's own team roster."""

    nm = _rw_clean_name(name)

    if not nm:

        return None

    # Exact/global MLB search works best for full names.

    if not (len(nm.split()) == 2 and nm.split()[0].rstrip('.').isalpha() and len(nm.split()[0].rstrip('.')) <= 2):

        pid = _mlb_search_player_id_by_name(nm)

        if pid:

            return pid

    roster = _mlb_active_team_roster_by_abbr(team_abbr) if team_abbr else []

    target = normalize_name(nm)

    parts = nm.replace('.', '').split()

    first_initial = parts[0][0].lower() if parts else ''

    surname = normalize_name(parts[-1]) if parts else ''

    best_id, best_score = None, 0.0

    for player in roster:

        full = str(player.get("name") or "")

        fp = full.replace('.', '').split()

        if not fp:

            continue

        full_norm = normalize_name(full)

        score = difflib.SequenceMatcher(None, target, full_norm).ratio()

        full_surname = normalize_name(fp[-1])

        if surname and full_surname == surname:

            score += 0.45

            if first_initial and fp[0] and fp[0][0].lower() == first_initial:

                score += 0.35

        if score > best_score:

            best_score, best_id = score, player.get("id")

    if best_id and best_score >= 0.82:

        return best_id

    return _mlb_search_player_id_by_name(nm)





@st.cache_data(ttl=86400, show_spinner=False)

def _mlb_batter_hand(player_id):

    """Resolve official MLB L/R/S batting side.



    MLB's /people/{id} payload already contains batSide for active players on most

    responses. Some environments ignore/alter hydrate, so use the raw endpoint first,

    then retry with hydrate. Never let a RotoWire/FantasyPros parser failure erase hand.

    """

    if not player_id:

        return None

    for params in ({}, {"hydrate": "currentTeam,batSide"}):

        try:

            data = safe_get_json(f"{MLB_BASE}/people/{player_id}", params=params, timeout=10) or {}

            people = data.get("people") or []

            person = people[0] if people else {}

            code = ((person.get("batSide") or {}).get("code"))

            code = str(code or "").upper().strip()

            if code in {"L", "R", "S"}:

                return code

        except Exception:

            continue

    return None





@st.cache_data(ttl=86400, show_spinner=False)

def _mlb_pitcher_throw_hand(player_id=None, name=""):

    """Resolve official MLB pitcher throwing hand.



    Returns LHP/RHP from MLB people payload. Missing hand stays UNKNOWN; never

    default to RHP, because that silently pulls the wrong opponent split.

    """

    pid = None

    try:

        if player_id not in (None, "", "—"):

            pid = int(float(player_id))

    except Exception:

        pid = None

    if not pid and name and "_mlb_search_player_id_by_name" in globals():

        try:

            pid = _mlb_search_player_id_by_name(str(name))

        except Exception:

            pid = None

    if not pid:

        return None

    for params in ({}, {"hydrate": "currentTeam,pitchHand"}):

        try:

            data = safe_get_json(f"{MLB_BASE}/people/{pid}", params=params, timeout=10) or {}

            people = data.get("people") or []

            person = people[0] if people else {}

            ph = person.get("pitchHand") or {}

            code = str(ph.get("code") or ph.get("description") or "").upper().strip()

            if code in {"L", "LH", "LHP"} or "LEFT" in code:

                return "LHP"

            if code in {"R", "RH", "RHP"} or "RIGHT" in code:

                return "RHP"

        except Exception:

            continue

    return None





def _enrich_lineup_row_identity(row, team_abbr=None):

    """Guarantee a lineup row has MLB player id + L/R/S hand whenever MLB can resolve it."""

    rr = dict(row or {})

    name = _rw_clean_name(rr.get("Batter"))

    pid = rr.get("Player ID") or _mlb_resolve_lineup_player_id(name, team_abbr)

    hand = str(rr.get("Hand") or "").upper().strip()

    if hand not in {"L", "R", "S"}:

        hand = _mlb_batter_hand(pid)

    rr["Player ID"] = pid

    rr["Hand"] = hand if hand in {"L", "R", "S"} else None

    return rr



def build_rotowire_expected_lineup_rows(team_abbr, pitcher_hand=None):

    """Convert Rotowire expected lineup names into the same row schema the K engine already uses."""

    team_abbr = _rw_norm_team_abbr(team_abbr)

    if not ROTOWIRE_EXPECTED_LINEUPS_ENABLED or not team_abbr:

        return []

    rw = get_rotowire_expected_lineups() or {}

    base_rows = rw.get(team_abbr) or []

    if len(base_rows) < 5:

        return []



    rows = []

    for idx, base in enumerate(base_rows[:9], start=1):

        name = _rw_clean_name(base.get("Batter"))

        player_id = _mlb_resolve_lineup_player_id(name, team_abbr)

        season_k, season_so, season_pa = get_batter_season_k_rate(player_id) if player_id else (None, None, None)

        split_k, split_so, split_pa, split_source = get_batter_k_rate_vs_pitcher_hand(player_id, pitcher_hand) if (player_id and pitcher_hand) else (None, None, None, "No split")

        rolling = get_batter_rolling_k_rates(player_id, days_list=(14, 30)) if player_id else {}

        rolling14 = rolling.get(14)

        rolling30 = rolling.get(30)

        used_k, used_source = blend_batter_k_inputs(

            season_k,

            split_k=split_k,

            season_pa=season_pa,

            split_pa=split_pa,

            rolling14=rolling14,

            rolling30=rolling30,

        )

        if used_k is None:

            used_k = split_k if split_k is not None else season_k

            used_source = split_source if split_k is not None else "Season batter K%"

        rows.append({

            "Order": idx,

            "Batter": name,

            "Player ID": player_id,

            "Position": base.get("Position"),

            "Hand": base.get("Hand") or _mlb_batter_hand(player_id),

            "Season K%": None if season_k is None else round(season_k * 100, 1),

            "Split K%": None if split_k is None else round(split_k * 100, 1),

            "Rolling 14d K%": None if rolling14 is None else round(rolling14 * 100, 1),

            "Rolling 30d K%": None if rolling30 is None else round(rolling30 * 100, 1),

            "Split PA/AB": split_pa,

            "Used K%": None if used_k is None else round(used_k * 100, 1),

            "K Source": f"{base.get('Lineup Source', 'ROTOWIRE_EXPECTED_LINEUP').replace('_', ' ').title()} + {used_source}",

            "SO": season_so,

            "PA/AB": season_pa,

            "Raw_K_Rate": used_k,

            "Lineup Source": base.get("Lineup Source") or "ROTOWIRE_EXPECTED_LINEUP",

            "RotoWire Transport": (get_rotowire_lineup_diagnostics(team_abbr) or {}).get("transport"),

            "RotoWire Status": (get_rotowire_lineup_diagnostics(team_abbr) or {}).get("team_status"),

        })

    valid = [r.get("Raw_K_Rate") for r in rows if r.get("Raw_K_Rate") is not None]

    if len(valid) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

        return rows[:9]

    return []



def _try_rotowire_expected_lineup(game_pk, opp_side, pitcher_hand=None):

    team_abbr = _game_team_abbr_from_box_or_live(game_pk, opp_side)

    rw_rows = build_rotowire_expected_lineup_rows(team_abbr, pitcher_hand) if team_abbr else []

    valid_rw = [r.get("Raw_K_Rate") for r in rw_rows[:9] if r.get("Raw_K_Rate") is not None]

    if len(valid_rw) >= ROTOWIRE_LINEUP_MIN_VALID_HITTERS:

        src = "Rotowire confirmed lineup K%" if any(str(r.get("Lineup Source", "")).upper() == "ROTOWIRE_CONFIRMED_LINEUP" for r in rw_rows[:9]) else "Rotowire expected lineup K%"

        return float(np.mean(valid_rw)), rw_rows[:9], f"{src} ({team_abbr})", False

    return None, [], "Rotowire expected lineup unavailable", False







# =========================

# FANTASYPROS DAILY PROJECTED LINEUP LAYER (LINEUP ONLY)

# =========================

# Independent pre-lineup backup. FantasyPros publishes Projected/Confirmed MLB

# lineups with batting order and Bats. MLB official lineups still override it.

FANTASYPROS_LINEUPS_ENABLED = True

FANTASYPROS_LINEUPS_URL = "https://www.fantasypros.com/mlb/lineups/"

FANTASYPROS_LINEUP_MIN_VALID_HITTERS = 5



FANTASYPROS_TEAM_NAMES = {

    "Arizona Diamondbacks":"ARI", "Atlanta Braves":"ATL", "Baltimore Orioles":"BAL", "Boston Red Sox":"BOS",

    "Chicago Cubs":"CHC", "Chicago White Sox":"CHW", "Cincinnati Reds":"CIN", "Cleveland Guardians":"CLE",

    "Colorado Rockies":"COL", "Detroit Tigers":"DET", "Houston Astros":"HOU", "Kansas City Royals":"KC",

    "Los Angeles Angels":"LAA", "Los Angeles Dodgers":"LAD", "Miami Marlins":"MIA", "Milwaukee Brewers":"MIL",

    "Minnesota Twins":"MIN", "New York Mets":"NYM", "New York Yankees":"NYY", "Athletics":"ATH",

    "Philadelphia Phillies":"PHI", "Pittsburgh Pirates":"PIT", "San Diego Padres":"SD", "San Francisco Giants":"SF",

    "Seattle Mariners":"SEA", "St. Louis Cardinals":"STL", "Tampa Bay Rays":"TB", "Texas Rangers":"TEX",

    "Toronto Blue Jays":"TOR", "Washington Nationals":"WSH",

}



@st.cache_data(ttl=300, show_spinner=False)

def get_fantasypros_projected_lineups_bundle():

    diag = {"status":"DISABLED", "http_status":None, "bytes":0, "error":"", "parsed_teams":0, "team_counts":{}}

    if not FANTASYPROS_LINEUPS_ENABLED:

        return {"lineups":{}, "diagnostics":diag}

    try:

        r = requests.get(FANTASYPROS_LINEUPS_URL, timeout=18, headers={

            "User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36",

            "Accept":"text/html,application/xhtml+xml,*/*", "Accept-Language":"en-US,en;q=0.9",

        })

        raw = r.text or ""

        diag.update({"http_status":r.status_code, "bytes":len(raw)})

        if r.status_code >= 400 or len(raw) < 5000:

            diag.update({"status":"FAILED", "error":f"HTTP {r.status_code}; bytes={len(raw)}"})

            return {"lineups":{}, "diagnostics":diag}

        out = _fantasypros_parse_lineups(raw)

        counts = {k:len(v or []) for k,v in out.items()}

        diag.update({"status":"SUCCESS" if sum(v>=5 for v in counts.values())>=2 else "PARSE_FAILED",

                     "parsed_teams":sum(v>=5 for v in counts.values()), "team_counts":counts})

        if diag["status"] != "SUCCESS":

            diag["error"] = "FantasyPros page fetched but parser found too few teams"

        return {"lineups":out, "diagnostics":diag}

    except Exception as exc:

        diag.update({"status":"FAILED", "error":f"{type(exc).__name__}: {exc}"[:700]})

        return {"lineups":{}, "diagnostics":diag}





def _fantasypros_parse_lineups(raw_html):

    """Defensive parser for FantasyPros MLB lineups page.



    Uses tables first, then visible text. The page labels each team block as

    'Team Name Lineup' followed by 'Team Name Projected/Confirmed Lineup'.

    """

    if not raw_html:

        return {}

    import re

    try:

        from bs4 import BeautifulSoup

        soup = BeautifulSoup(raw_html, "html.parser")

    except Exception:

        return {}

    out = {}

    # Table-first: find any table with Player/Bats columns and infer team from nearby heading text.

    for table in soup.find_all("table"):

        headers = [h.get_text(" ", strip=True).lower() for h in table.find_all(["th"])]

        if not any("player" in h for h in headers):

            continue

        prev_text = ""

        node = table

        for _ in range(10):

            node = node.find_previous()

            if not node: break

            t = node.get_text(" ", strip=True)

            if t:

                prev_text = t + " " + prev_text

            if "Lineup" in prev_text and len(prev_text) > 30:

                break

        team = None

        for full, abbr in FANTASYPROS_TEAM_NAMES.items():

            if full.lower() in prev_text.lower():

                team = abbr; break

        if not team:

            continue

        rows=[]

        for tr in table.find_all("tr"):

            cells=[c.get_text(" ", strip=True) for c in tr.find_all(["td","th"])]

            if len(cells)<2 or not str(cells[0]).strip().isdigit():

                continue

            order=int(cells[0]); player_txt=cells[1]

            name=re.sub(r"\s*\([^)]*\)\s*$", "", player_txt).strip()

            hand=None

            for c in cells[2:]:

                cc=str(c).strip().upper()

                if cc in {"L","R","B","S"}:

                    hand="S" if cc=="B" else cc; break

            if name and 1<=order<=9:

                rows.append({"Order":order,"Batter":name,"Hand":hand,"Lineup Source":"FANTASYPROS_PROJECTED_LINEUP"})

        if len(rows)>=5:

            out[_rw_norm_team_abbr(team)] = sorted(rows,key=lambda x:x["Order"])[:9]



    # Text fallback for responsive/mobile markup.

    if len(out) < 2:

        for bad in soup(["script","style","noscript"]):

            bad.decompose()

        text=soup.get_text("\n", strip=True)

        for full, abbr in FANTASYPROS_TEAM_NAMES.items():

            # capture from 'Team Lineup' through next Weather/team heading; numbered rows are stable in visible text.

            pat=re.compile(re.escape(full)+r"\s+Lineup\s+"+re.escape(full)+r"\s+(?:Projected|Confirmed)\s+Lineup(?P<body>.*?)(?=Weather|####|$)", re.I|re.S)

            m=pat.search(text)

            if not m: continue

            body=m.group("body")

            rows=[]

            row_pat=re.compile(r"(?:^|\n)\s*(\d)\s*\|?\s*([^\n|]+?)(?:\([^\n)]*\))?\s*\|?\s*([LRBS])(?:\s|\||$)", re.M)

            for mm in row_pat.finditer(body):

                order=int(mm.group(1)); name=_rw_clean_name(mm.group(2)); hand=mm.group(3).upper(); hand="S" if hand=="B" else hand

                if name and 1<=order<=9:

                    rows.append({"Order":order,"Batter":name,"Hand":hand,"Lineup Source":"FANTASYPROS_PROJECTED_LINEUP"})

            if len(rows)>=5:

                out[_rw_norm_team_abbr(abbr)] = sorted(rows,key=lambda x:x["Order"])[:9]

    return out





def build_fantasypros_lineup_rows(team_abbr, pitcher_hand=None):

    ta=_rw_norm_team_abbr(team_abbr)

    bundle=get_fantasypros_projected_lineups_bundle() or {}

    base=((bundle.get("lineups") or {}).get(ta) or [])

    if len(base)<FANTASYPROS_LINEUP_MIN_VALID_HITTERS:

        return []

    rows=[]

    for idx, b0 in enumerate(base[:9], start=1):

        b=_enrich_lineup_row_identity(b0, ta)

        name=_rw_clean_name(b.get("Batter")); pid=b.get("Player ID")

        season_k, season_so, season_pa = get_batter_season_k_rate(pid) if pid else (None,None,None)

        split_k, split_so, split_pa, split_source = get_batter_k_rate_vs_pitcher_hand(pid,pitcher_hand) if (pid and pitcher_hand) else (None,None,None,"No split")

        rolling=get_batter_rolling_k_rates(pid, days_list=(14,30)) if pid else {}; r14=rolling.get(14); r30=rolling.get(30)

        used_k, used_source=blend_batter_k_inputs(season_k, split_k=split_k, season_pa=season_pa, split_pa=split_pa, rolling14=r14, rolling30=r30)

        if used_k is None:

            used_k=split_k if split_k is not None else season_k; used_source=split_source if split_k is not None else "Season batter K%"

        rows.append({"Order":safe_int(b.get("Order"),idx),"Batter":name,"Player ID":pid,"Hand":b.get("Hand"),"Position":b.get("Position"),

                     "Season K%":None if season_k is None else round(season_k*100,1),"Split K%":None if split_k is None else round(split_k*100,1),

                     "Rolling 14d K%":None if r14 is None else round(r14*100,1),"Rolling 30d K%":None if r30 is None else round(r30*100,1),

                     "Split PA/AB":split_pa,"Used K%":None if used_k is None else round(used_k*100,1),"K Source":f"FantasyPros projected + {used_source}",

                     "SO":season_so,"PA/AB":season_pa,"Raw_K_Rate":used_k,"Lineup Source":"FANTASYPROS_PROJECTED_LINEUP"})

    return rows[:9] if len([r for r in rows if r.get("Raw_K_Rate") is not None])>=5 else []



# =========================

# FANGRAPHS ROSTERRESOURCE PROJECTED LINEUP LAYER (LINEUP ONLY)

# =========================

# Purpose:

# - Use FanGraphs/RosterResource projected batters BEFORE MLB confirmed lineups post.

# - Once MLB official/boxscore lineup is available, confirmed MLB lineup stays the top source.

# - This layer only affects batter lineup / matchup K% logic. It does NOT touch Underdog lines,

#   PrizePicks, sportsbook odds, or any market line pulls.

# =========================

FANGRAPHS_ROSTER_LINEUPS_ENABLED = True

FANGRAPHS_LINEUP_MIN_VALID_HITTERS = 5

FANGRAPHS_BASE_URL = "https://www.fangraphs.com/roster-resource"



