def render_kpis(picks, bankroll):

    valid = [p for p in picks if p.get("ev") is not None]

    best = sorted(valid, key=lambda x: x.get("ev", -999), reverse=True)[0] if valid else None

    real_line_count = len([p for p in picks if p.get("line") is not None])

    strong_count = len([p for p in picks if p.get("signal_type") == "good"])

    no_line_count = len([p for p in picks if p.get("line") is None])

    statcast_count = len([p for p in picks if p.get("statcast_available")])

    pitch_type_count = len([p for p in picks if p.get("pitch_type_matchup_available")])

    st.markdown(f"""

    <div class="kpi-strip">

      <div class="kpi-box"><div class="kpi-label">Board Rows</div><div class="kpi-value">{len(picks)}</div><div class="kpi-sub">Current screen</div></div>

      <div class="kpi-box"><div class="kpi-label">Real Lines</div><div class="kpi-value green">{real_line_count}</div><div class="kpi-sub">No fake prop lines</div></div>

      <div class="kpi-box"><div class="kpi-label">No Line</div><div class="kpi-value orange">{no_line_count}</div><div class="kpi-sub">Projection only</div></div>

      <div class="kpi-box"><div class="kpi-label">Strong Signals</div><div class="kpi-value green">{strong_count}</div><div class="kpi-sub">Strict gates</div></div>

      <div class="kpi-box"><div class="kpi-label">Statcast</div><div class="kpi-value">{statcast_count}/{len(picks)}</div><div class="kpi-sub">Pitch-type {pitch_type_count}</div></div>

      <div class="kpi-box"><div class="kpi-label">Bankroll</div><div class="kpi-value green">${bankroll:,.0f}</div><div class="kpi-sub">{california_now().strftime('%I:%M %p PT')}</div></div>

    </div>

    """, unsafe_allow_html=True)

    if best:

        st.markdown(f"""

        <div class="green-card">

          <div class="small-muted">Best EV Play On Current Board</div>

          <div class="big-number green">{best.get('signal')}</div>

          <div>{best.get('pitcher')} — {best.get('pick_side')} {best.get('line')} Ks | EV {round((best.get('ev') or 0)*100,2)}% | Data {best.get('data_score')}/100</div>

        </div>

        """, unsafe_allow_html=True)





_OFFICIAL_CARD_ROW_GUARD = False



def official_card_k_row(p):

    """Build one final K row with exception-safe re-entry protection."""

    global _OFFICIAL_CARD_ROW_GUARD

    if _OFFICIAL_CARD_ROW_GUARD:

        return {}



    _OFFICIAL_CARD_ROW_GUARD = True

    try:

        df = build_kproj_table([p])

        if df is None or df.empty:

            return {}

        row = df.iloc[0].to_dict()

        if "_owp_overlay_full_board_pitcher_k_rank" in globals():

            row = _owp_overlay_full_board_pitcher_k_rank(row)

        return row

    except Exception:

        return {}

    finally:

        _OFFICIAL_CARD_ROW_GUARD = False



def official_card_k_projection(p):

    """Official card projection synced to the board K PROJ.



    The card must show the same stabilized number as the table's K PROJ:

    - Soriano should show 6.41

    - Misiorowski should show 9.55

    - Gausman should show 6.16, not 4.93



    This is display-only and does not change the projection engine.

    """

    try:

        row = official_card_k_row(p)

        # FINAL CARD LOCK: the player card must display the LAST/FULLY FINAL output.

        # APP97 is the final current-data K source of truth. Legacy layers remain audit-only.

        for c in ["APP97 True K Projection", "K PROJ", "Official K PROJ", "Final K Projection", "Matchup Intelligence Final K Projection", "Line-Aware Smart Final K Projection", "WRS Final K Projection", "TPS Final K Projection"]:

            if row and row.get(c) not in (None, "", "—"):

                v = safe_float(row.get(c), None)

                if v is not None:

                    return round(float(v), 2), "APP97 Current K" if c == "APP97 True K Projection" else "Matchup Intel Final" if c == "Matchup Intelligence Final K Projection" else "Line-Aware Smart Final" if c == "Line-Aware Smart Final K Projection" else "Official K PROJ"



        # Fallback if one-row table cannot be built.

        for c in ["Matchup Intelligence Final K Projection", "Line-Aware Smart Final K Projection", "K PROJ", "WRS Final K Projection", "TPS Final K Projection", "projection"]:

            if isinstance(p, dict) and p.get(c) not in (None, "", "—"):

                v = safe_float(p.get(c), None)

                if v is not None:

                    return round(float(v), 2), "APP97 Current K" if c == "APP97 True K Projection" else "Matchup Intel Final" if c == "Matchup Intelligence Final K Projection" else "Line-Aware Smart Final" if c == "Line-Aware Smart Final K Projection" else "Official K PROJ"



        return ("—", "Unavailable")

    except Exception:

        return (p.get("projection", "—") if isinstance(p, dict) else "—", "Fallback")





def render_pick_card(p):

    prob = p.get("fair_probability")

    prob_pct = int(round(prob * 100)) if prob is not None else 0

    progress_width = max(3, min(100, prob_pct))

    risk = p.get("risk_label", "")

    signal_type = p.get("signal_type", "pass")

    if "85" in risk or signal_type == "good":

        color_class, progress_class, badge = "green", "progress-green", "good-badge"

    elif "PASS" in risk or "NO" in risk:

        color_class, progress_class, badge = "red", "progress-red", "red-badge"

    else:

        color_class, progress_class, badge = "orange", "progress-orange", "yellow-badge"

    line_display = f"{safe_float(p.get('line')):.1f}" if p.get('line') is not None else "NO REAL LINE"

    edge_display = p.get("edge_ks") if p.get("edge_ks") is not None else "—"

    ev_display = f"{(p.get('ev') or 0)*100:.2f}%" if p.get("ev") is not None else "—"

    prob_display = f"{prob_pct}%" if prob is not None else "—"

    card_k_projection, card_k_projection_source = official_card_k_projection(p)

    # Render-safe Last 10 K bars.

    # NOTE: this avoids standalone raw HTML ever being printed by Streamlit/tunnel caching.

    # The full card below is still rendered with unsafe_allow_html=True.

    bars = "<span class='small-muted'>No recent K log</span>"

    last_ks = p.get("last_10_ks", []) or []

    if last_ks:

        max_k = max(max([safe_int(x, 0) or 0 for x in last_ks]), 1)

        bar_parts = []

        for k_raw in last_ks[:10]:

            k = safe_int(k_raw, 0) or 0

            h = int(20 + (k / max_k) * 42)

            bar_parts.append(

                f"<span class='mini-k-bar-wrap'>"

                f"<span class='mini-k-bar' style='height:{h}px;'></span>"

                f"<span class='mini-k-label'>{k}</span>"

                f"</span>"

            )

        bars = "<div class='mini-k-bars'>" + "".join(bar_parts) + "</div>"

    statcast_txt = "YES" if p.get("statcast_available") else "NO"

    pitch_type_txt = "YES" if p.get("pitch_type_matchup_available") else "NO"

    def _card_pct(v):

        x = safe_float(v, None)

        if x is None:

            return "—"

        if abs(x) <= 1:

            x *= 100.0

        return f"{x:.1f}%"

    p = _sync_market_with_card_decision(p, d) if '_sync_market_with_card_decision' in globals() else p

    market_o_display = p.get('market_over_odds', '—')

    market_u_display = p.get('market_under_odds', '—')

    fair_o_display = _card_pct(p.get('market_over_implied'))

    fair_u_display = _card_pct(p.get('market_under_implied'))

    no_vig_o_display = _card_pct(p.get('market_over_no_vig'))

    no_vig_u_display = _card_pct(p.get('market_under_no_vig'))

    slate_q = st.session_state.get('slate_quality_info') or compute_slate_quality_score([p])

    slate_badge_text = f"{slate_q.get('emoji','⚪')} {slate_q.get('label','NO BOARD')} {slate_q.get('score',0)}/100"



    st.markdown(f"""

    <div class="pick-card">

      <div style="display:grid;grid-template-columns:1.3fr .8fr .9fr 1fr 1fr;gap:18px;align-items:center;">

        <div>

          <div class="player-name">{p.get('pitcher')}</div>

          <div class="small-muted">{p.get('matchup')} | {p.get('hand')}HP</div>

          <div class="small-muted">{p.get('team')} vs {p.get('opponent')}</div>

          <span class="badge {badge}">{p.get('risk_label')}</span>

          <span class="badge">{p.get('line_source')}</span>

          <span class="badge good-badge">{p.get('projection_source')}</span>

          <span class="badge">Lineup: {p.get('lineup_status')}</span>

          <span class="badge">Slate: {slate_badge_text}</span>

        </div>

        <div><div class="small-muted">Final K Projection</div><div class="big-number {color_class}">{card_k_projection}</div><div class="small-muted">{card_k_projection_source} | BF {p.get('expected_bf')} | PPB {p.get('ppb')}</div></div>

        <div><div class="small-muted">Line</div><div class="big-number">{line_display}</div><div class="small-muted">Edge: {edge_display} K</div></div>

        <div>

          <div class="small-muted">Model Side</div><div class="big-number {color_class}">{p.get('pick_side')}</div>

          <div class="small-muted">Final Action</div><div class="{color_class}" style="font-size:22px;font-weight:950;">{p.get('bet_action', '🚫 PASS')}</div>

          <div class="small-muted">Fair Prob</div><div class="{color_class}" style="font-size:26px;font-weight:900;">{prob_display}</div>

          <div class="progress-wrap"><div class="{progress_class}" style="width:{progress_width}%;"></div></div>

        </div>

        <div>

          <div class="small-muted">Signal</div><div class="{color_class}" style="font-size:20px;font-weight:950;">{p.get('signal')}</div>

          <div class="small-muted" style="margin-top:8px;">EV</div><div style="font-size:22px;font-weight:900;">{ev_display}</div>

          <div class="small-muted">Price Source</div><div style="font-size:12px;font-weight:800;">{p.get('price_source')}</div>

          <div class="small-muted">Bet Size</div><div style="font-size:22px;font-weight:900;">${p.get('bet_size')}</div>

        </div>

      </div>

      <div class="hr-soft"></div>

      <div class="mobile-decision-grid">

        <div class="mobile-info-card"><div class="small-muted">Official Filter</div><div class="kpi-value" style="font-size:17px;">{p.get('official_play_filter', '—')}</div><div class="kpi-sub">{p.get('official_filter_note', '')}</div></div>

        <div class="mobile-info-card"><div class="small-muted">Reliability</div><div class="kpi-value">{p.get('reliability_score', '—')}</div><div class="kpi-sub">{p.get('reliability_label', '')}</div></div>

        <div class="mobile-info-card"><div class="small-muted">Integrity</div><div class="kpi-value">{p.get('decision_integrity_score', '—')}</div><div class="kpi-sub">{p.get('decision_integrity_label', '')}</div></div>

        <div class="mobile-info-card"><div class="small-muted">Market / No-Vig</div><div class="kpi-value" style="font-size:16px;">{p.get('market_lean', 'NO_MARKET')}</div><div class="kpi-sub">O {market_o_display} | U {market_u_display}<br>Fair O {fair_o_display} | U {fair_u_display}<br>No-Vig O {no_vig_o_display} | U {no_vig_u_display}</div></div>

        <div class="mobile-info-card"><div class="small-muted">Sharp / Line</div><div class="kpi-value" style="font-size:16px;">{p.get('sharp_warning', 'NONE')}</div><div class="kpi-sub">{p.get('line_history_grade', '—')} | L10 {p.get('line_l10_avg', '—')}</div></div>

        <div class="mobile-info-card"><div class="small-muted">Umpire Zone</div><div class="kpi-value" style="font-size:16px;">{p.get('umpire_strike_zone_score', '—')}</div><div class="kpi-sub">K nudge {p.get('umpire_k_nudge', 0)} | {p.get('umpire', 'Unknown')}</div></div>

      </div>

      <div style="display:grid;grid-template-columns:.7fr .7fr .7fr .7fr .7fr .7fr 2.2fr;gap:14px;align-items:end;">

        <div><div class="small-muted">Data Score</div><div style="font-size:22px;font-weight:900;">{p.get('data_score')}/100</div></div>

        <div><div class="small-muted">Pitcher K%</div><div style="font-size:22px;font-weight:900;">{p.get('pitcher_k')}</div></div>

        <div><div class="small-muted">Opp K%</div><div style="font-size:22px;font-weight:900;">{p.get('opp_k')}</div></div>

        <div><div class="small-muted">Statcast</div><div style="font-size:22px;font-weight:900;">{statcast_txt}</div></div>

        <div><div class="small-muted">Pitch-Type</div><div style="font-size:22px;font-weight:900;">{pitch_type_txt}</div></div>

        <div><div class="small-muted">CLV Δ</div><div style="font-size:22px;font-weight:900;">{p.get('line_delta')}</div></div>

        <div><div class="small-muted">Last 10 Ks</div>{bars}</div>

      </div>

      <div class="small-muted" style="margin-top:12px;">Final Decision: {p.get('final_decision_note', '')} | Elite Upside: {p.get('elite_upside_score')} | Over Needs: {p.get('over_needed')}+</div>

      <div class="small-muted" style="margin-top:12px;">Risk Notes: {p.get('risk_notes')}</div>

      <div class="small-muted">Statcast: {p.get('statcast_note')} | Pitch Type: {p.get('pitch_type_note')} | Calibration: {p.get('calibration_note')}</div>

      <div class="small-muted">Trap-Line: {p.get('trap_line_label', 'CLEAR')} ({p.get('trap_line_score', 0)}/100) | {p.get('trap_line_note', '')}</div>

      <div class="small-muted">Projection Source: {p.get('projection_source')} | Lineup Status: {p.get('lineup_status')} | Lineup Note: {p.get('lineup_note')}</div>

      <div class="small-muted">Repeat Matchup: {p.get("repeat_matchup_note", "Neutral")}\nBullpen Fatigue: {p.get('bullpen_status')} | factor {p.get('bullpen_bf_factor')} | {p.get('bullpen_recent_pitches')} pitches / {p.get('bullpen_recent_ip')} IP | {p.get('bullpen_note')}</div>

      <div class="small-muted">Weather: {p.get('weather_note')} | Umpire: {p.get('umpire_note')}</div>

      <div class="small-muted">Advanced Sim: {p.get('bayesian_markov_note')} | XGBoost: {p.get('xgboost_note')}</div>

    </div>

    """, unsafe_allow_html=True)





# =========================

# DRIFT / TRAP / CALIBRATION UI HELPERS

# moved above APP so Streamlit button callbacks can call them safely

# =========================

def projection_drift_label(opening_projection, final_projection, actual=None):

    """Classify movement from the saved opening projection to the final projection and optional actual result."""

    op = safe_float(opening_projection)

    fp = safe_float(final_projection)

    ac = safe_float(actual)

    if op is None or fp is None:

        return "NO_DRIFT_DATA"

    drift = fp - op

    if abs(drift) < 0.15:

        base = "STABLE_PROJECTION"

    elif drift >= 0.75:

        base = "MAJOR_UPWARD_DRIFT"

    elif drift >= 0.35:

        base = "UPWARD_DRIFT"

    elif drift <= -0.75:

        base = "MAJOR_DOWNWARD_DRIFT"

    elif drift <= -0.35:

        base = "DOWNWARD_DRIFT"

    else:

        base = "LIGHT_DRIFT"

    if ac is not None:

        err = ac - fp

        if abs(err) <= 0.75:

            return base + " / GOOD_CLOSE"

        if err >= 1.25:

            return base + " / UNDER_PROJECTED"

        if err <= -1.25:

            return base + " / OVER_PROJECTED"

    return base





def build_projection_drift_row(p):

    """Return a row-ready drift audit dictionary from a saved/graded official pick."""

    opening = safe_float(p.get("opening_projection", p.get("pre_calibration_projection", p.get("projection"))))

    final = safe_float(p.get("final_projection", p.get("projection")))

    actual = safe_float(p.get("actual"))

    line = safe_float(p.get("line"))

    drift = None if opening is None or final is None else round(final - opening, 2)

    final_error = None if actual is None or final is None else round(actual - final, 2)

    opening_error = None if actual is None or opening is None else round(actual - opening, 2)

    return {

        "Saved At": p.get("official_snapshot_saved_at") or p.get("created_at"),

        "Graded At": p.get("graded_at"),

        "Date": p.get("date"),

        "Pitcher": p.get("pitcher"),

        "Matchup": p.get("matchup"),

        "Side": p.get("pick_side"),

        "Line": line,

        "Opening Projection": opening,

        "Final Projection": final,

        "Projection Drift": drift,

        "Actual Ks": actual,

        "Final Error": final_error,

        "Opening Error": opening_error,

        "Result": p.get("graded_result"),

        "Drift Label": projection_drift_label(opening, final, actual),

        "Trap Score": p.get("trap_line_score"),

        "Trap Label": p.get("trap_line_label"),

        "Trap Action": p.get("trap_line_action"),

        "Trap Factors": p.get("trap_line_factors"),

    }





def evaluate_trap_line_detection(p):

    """True Trap-Line Detection 2.0.



    This does not change K projection math. It evaluates whether the current line/play has hidden risk

    and returns a score + action so the official play layer can downgrade risky bets.

    """

    proj = safe_float(p.get("projection"))

    line = safe_float(p.get("line"))

    side = str(p.get("pick_side") or "").upper()

    fair = safe_float(p.get("fair_probability"), 0.0) or 0.0

    data_score = safe_float(p.get("data_score"), 0.0) or 0.0

    p10 = safe_float(p.get("p10"))

    p90 = safe_float(p.get("p90"))

    line_delta = safe_float(p.get("true_line_delta", p.get("line_delta")), 0.0) or 0.0

    spread = safe_float(p.get("consensus_spread"), 0.0) or 0.0

    pc_score = safe_float(p.get("pitch_count_score"), 72.0) or 72.0

    edge = abs(proj - line) if proj is not None and line is not None else 0.0

    sim_range = (p90 - p10) if p10 is not None and p90 is not None else None



    score = 0.0

    factors = []



    if proj is None or line is None:

        return {"score": 0, "label": "NO_LINE_DATA", "action": "IGNORE", "note": "No projection/line pair for trap check", "factors": ""}



    # Line movement against the selected side makes the required outcome harder.

    if side == "OVER" and line_delta >= 0.5:

        score += 22

        factors.append(f"Line moved up against OVER by {line_delta:+.1f}")

    elif side == "UNDER" and line_delta <= -0.5:

        score += 22

        factors.append(f"Line moved down against UNDER by {line_delta:+.1f}")

    elif abs(line_delta) >= 1.0:

        score += 10

        factors.append(f"Large line move {line_delta:+.1f}")



    # Big projection edge but mediocre probability is a classic trap shape.

    if edge >= 1.25 and fair < 0.60:

        score += 22

        factors.append("Projection edge is large but sim/fair probability is weak")

    elif edge >= 0.85 and fair < 0.57:

        score += 14

        factors.append("Projection edge not confirmed by probability")



    # Tight line without enough edge.

    if edge < 0.55:

        score += 12

        factors.append("Edge under 0.55 K")



    # Volatility / wide distribution.

    if sim_range is not None and sim_range >= 4.75:

        score += 16

        factors.append(f"Wide K distribution range {sim_range:.1f}")

    elif sim_range is not None and sim_range >= 4.10:

        score += 9

        factors.append(f"Moderate volatility range {sim_range:.1f}")



    # Volume problems kill K overs and can also make unders fragile if projection is artificially low.

    if pc_score < 62:

        score += 18

        factors.append(f"Pitch count score weak ({pc_score:.0f})")

    elif pc_score < 72:

        score += 8

        factors.append(f"Pitch count score monitor ({pc_score:.0f})")



    if data_score and data_score < 84:

        score += 10

        factors.append(f"Data score below strong-play level ({data_score:.0f})")



    if not bool(p.get("lineup_locked")):

        score += 8

        factors.append("Lineup not confirmed")



    risk_text = " ".join(str(p.get(k, "")) for k in [

        "risk_label", "leash_risk", "manager_hook_status", "manager_hook_note", "bullpen_status",

        "pitch_count_label", "pitch_count_note", "weather_note", "umpire_note", "game_script_note"

    ]).upper()

    danger_words = ["SHORT", "HOOK", "VOLATILE", "DANGER", "RISK", "MONITOR", "LIMIT", "UNKNOWN"]

    danger_hits = [w for w in danger_words if w in risk_text]

    if len(danger_hits) >= 2:

        score += 12

        factors.append("Multiple hidden-risk flags: " + ", ".join(danger_hits[:4]))

    elif danger_hits:

        score += 6

        factors.append("Hidden-risk flag: " + danger_hits[0])



    if spread >= 1.0:

        score += 10

        factors.append(f"Book/line consensus spread wide ({spread:.1f})")



    src = str(p.get("line_source") or "").upper()

    if any(x in src for x in ["MANUAL", "EST", "FALLBACK", "NO"]):

        score += 8

        factors.append("Line source is not clean live market")



    score = int(round(clamp(score, 0, 100)))

    if score >= 78:

        label = "HIGH_TRAP"

        action = "FORCE_PASS"

    elif score >= 62:

        label = "TRAP_CHECK"

        action = "DOWNGRADE_TO_LEAN"

    elif score >= 42:

        label = "WATCH"

        action = "WATCH_ONLY"

    else:

        label = "CLEAR"

        action = "ALLOW"

    note = f"Trap-Line 2.0 {label}: score {score}/100" + (" — " + "; ".join(factors[:5]) if factors else "")

    return {"score": score, "label": label, "action": action, "note": note, "factors": "; ".join(factors)}





def apply_trap_line_to_projection_row(p):

    """Attach trap-line fields and downgrade official action if needed."""

    out = dict(p)

    trap = evaluate_trap_line_detection(out)

    out["trap_line_score"] = trap.get("score")

    out["trap_line_label"] = trap.get("label")

    out["trap_line_action"] = trap.get("action")

    out["trap_line_note"] = trap.get("note")

    out["trap_line_factors"] = trap.get("factors")



    reasons = list(out.get("no_bet_reasons") or [])

    action_tier = str(out.get("action_tier") or "PASS").upper()

    if trap.get("action") == "FORCE_PASS":

        out["bettable"] = False

        out["action_tier"] = "PASS"

        out["bet_action"] = "🚫 PASS — TRAP LINE"

        out["bet_size"] = 0.0

        if "Trap-Line 2.0 high-risk pass" not in reasons:

            reasons.append("Trap-Line 2.0 high-risk pass")

    elif trap.get("action") == "DOWNGRADE_TO_LEAN" and action_tier == "BET":

        out["bettable"] = False

        out["action_tier"] = "LEAN"

        out["bet_action"] = "⚠️ LEAN — TRAP CHECK"

        out["bet_size"] = 0.0

        if "Trap-Line 2.0 downgraded official bet to lean" not in reasons:

            reasons.append("Trap-Line 2.0 downgraded official bet to lean")

    out["no_bet_reasons"] = reasons

    if trap.get("label") in ["HIGH_TRAP", "TRAP_CHECK"]:

        base_risk = str(out.get("risk_label") or "")

        out["risk_label"] = (base_risk + " | " if base_risk else "") + trap.get("label")

        rn = str(out.get("risk_notes") or "")

        out["risk_notes"] = (rn + "; " if rn else "") + trap.get("note", "")

    return out



def render_calibration_audit_tab():

    st.markdown('<div class="section-title-pro">Calibration Audit</div>', unsafe_allow_html=True)

    st.caption("Tracks projected Ks vs actual Ks and shows whether the model is biased to overs, unders, or specific buckets.")

    results = load_json(RESULT_LOG, [])

    if not results:

        st.info("No graded history yet. Save official snapshots before games, then grade after games finish.")

        return



    finished = []

    for r in results:

        if r.get("actual") is None or r.get("projection") is None:

            continue

        rr = dict(r)

        actual = safe_float(rr.get("actual"))

        proj = safe_float(rr.get("projection"))

        line = safe_float(rr.get("line"))

        rr["Miss By"] = None if actual is None or proj is None else round(actual - proj, 2)

        rr["Abs Miss"] = None if rr["Miss By"] is None else round(abs(rr["Miss By"]), 2)

        rr["Projected Side"] = rr.get("pick_side") or ("OVER" if line is not None and proj is not None and proj > line else "UNDER" if line is not None and proj is not None else "—")

        rr["Hit/Miss"] = rr.get("graded_result") or ("WIN" if rr.get("win") is True else "LOSS" if rr.get("win") is False else "—")

        rr["Pitch Count Score"] = rr.get("pitch_count_score")

        rr["Pitch Count Label"] = rr.get("pitch_count_label")

        finished.append(rr)



    if not finished:

        st.info("No completed graded rows with actual Ks yet.")

        return



    df = pd.DataFrame(finished)

    miss = pd.to_numeric(df.get("Miss By"), errors="coerce")

    abs_miss = pd.to_numeric(df.get("Abs Miss"), errors="coerce")

    wins = df.get("Hit/Miss", pd.Series(dtype=str)).astype(str).str.upper().eq("WIN")

    c1, c2, c3, c4, c5 = st.columns(5)

    c1.metric("Graded Rows", len(df))

    c2.metric("Win Rate", f"{wins.mean()*100:.1f}%" if len(df) else "N/A")

    c3.metric("Model Bias", f"{miss.mean():+.2f} K" if not miss.dropna().empty else "N/A")

    c4.metric("Avg Miss", f"{abs_miss.mean():.2f} K" if not abs_miss.dropna().empty else "N/A")

    c5.metric("Last 50 WR", f"{wins.tail(50).mean()*100:.1f}%" if len(df.tail(50)) else "N/A")



    net_gain = build_merge_net_gain_audit_v25(finished)

    st.subheader("PO Protection Audit")

    ng1, ng2, ng3, ng4 = st.columns(4)

    ng1.metric("Disagreements", net_gain.get("disagreements", 0))

    ng2.metric("Merge Wins Added", net_gain.get("merge_only_wins_added", 0))

    ng3.metric("PO Wins Surrendered", net_gain.get("po_winners_surrendered", 0))

    ng4.metric("Net Gain", f"{net_gain.get('net_gain', 0):+d}")

    shared_loss_buckets = net_gain.get("shared_loss_buckets") or {}

    if shared_loss_buckets:

        loss_bucket_df = pd.DataFrame([

            {"Shared Loss Type": bucket, "Count": count}

            for bucket, count in sorted(

                shared_loss_buckets.items(), key=lambda item: (-item[1], item[0])

            )

        ])

        st.caption("Shared PO + Merge losses by pregame diagnostic category")

        st.dataframe(loss_bucket_df, use_container_width=True, hide_index=True)



    profile, bucket_df = build_true_calibration_dashboard(results)

    st.subheader("Calibration Profile")

    cp1, cp2, cp3, cp4 = st.columns(4)

    cp1.metric("Quality", f"{profile.get('quality_score', 0)}/100")

    cp2.metric("Samples", profile.get("samples", 0))

    cp3.metric("Global Bias", f"{safe_float(profile.get('bias'), 0):+.2f} K")

    cp4.metric("MAE", f"{safe_float(profile.get('mae'), 0):.2f} K")



    st.subheader("Recent Projection Drift")

    preferred = [c for c in [

        "graded_at", "date", "pitcher", "matchup", "Projected Side", "line", "opening_projection", "final_projection", "projection", "actual",

        "projection_drift", "projection_drift_label", "final_projection_error", "opening_projection_error",

        "Miss By", "Abs Miss", "Hit/Miss", "trap_line_score", "trap_line_label", "expected_bf", "actual_bf", "Pitch Count Score",

        "Pitch Count Label", "lineup_status", "manager_hook_status", "risk_label", "fair_probability", "ev"

    ] if c in df.columns]

    st.dataframe(df[preferred].tail(200), use_container_width=True, hide_index=True)



    st.subheader("Projection Drift Tracker")

    drift_rows = [build_projection_drift_row(r) for r in finished]

    drift_df = pd.DataFrame(drift_rows)

    if not drift_df.empty:

        dc1, dc2, dc3, dc4 = st.columns(4)

        drift_vals = pd.to_numeric(drift_df.get("Projection Drift"), errors="coerce")

        final_err = pd.to_numeric(drift_df.get("Final Error"), errors="coerce")

        high_trap = drift_df.get("Trap Label", pd.Series(dtype=str)).astype(str).isin(["HIGH_TRAP", "TRAP_CHECK"])

        dc1.metric("Avg Projection Drift", f"{drift_vals.mean():+.2f} K" if not drift_vals.dropna().empty else "N/A")

        dc2.metric("Avg Final Error", f"{final_err.mean():+.2f} K" if not final_err.dropna().empty else "N/A")

        dc3.metric("Trap-Flagged Rows", int(high_trap.sum()))

        dc4.metric("Stable Rows", int(drift_df.get("Drift Label", pd.Series(dtype=str)).astype(str).str.contains("STABLE", na=False).sum()))

        st.dataframe(drift_df.tail(250), use_container_width=True, hide_index=True)

    else:

        st.info("Projection drift tracker will populate after official snapshots are saved and graded.")



    st.subheader("Bucket Audit")

    if bucket_df is not None and not bucket_df.empty:

        st.dataframe(bucket_df, use_container_width=True, hide_index=True)

    else:

        st.info("Bucket audit will populate after more graded rows.")









# =========================

# MERGE V2.5.4 LIVE RELIABILITY / FROZEN-SLATE SUPPORT

# =========================

_V254_OUTCOME_KEYS = {

    "actual", "actual_k", "actual_ip", "final_result", "win_loss",

    "hit/miss", "graded_result", "result", "outcome", "postgame",

}





def _v254_parse_timestamp(value):

    if not value:

        return None

    try:

        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).replace(tzinfo=None)

    except Exception:

        return None





def _v254_age_minutes(value, now_value=None):

    stamp = _v254_parse_timestamp(value)

    if stamp is None:

        return None

    now_dt = now_value if isinstance(now_value, datetime) else datetime.now()

    try:

        return max(0.0, (now_dt.replace(tzinfo=None) - stamp).total_seconds() / 60.0)

    except Exception:

        return None





def evaluate_data_quality_v254(p, now_value=None):

    """Evaluate pregame source sufficiency without changing projection math."""

    p = p if isinstance(p, dict) else {}

    hard_reasons = []

    cautions = []

    hand = str(p.get("hand") or "").upper().strip()

    lineup_count = safe_int(p.get("expected_lineup_batter_count"), 0) or 0

    underdog_count = safe_int(p.get("underdog_player_count"), 0) or 0

    resolved_hitter_count = max(lineup_count, underdog_count)

    data_score = safe_float(p.get("data_score"), None)

    lineup_locked = bool(p.get("lineup_locked") or p.get("official_lineup_available"))

    refresh_stamp = p.get("lineup_last_refresh") or p.get("projection_generated_at") or p.get("created_at")

    lineup_age = _v254_age_minutes(refresh_stamp, now_value=now_value)



    if hand not in {"L", "R", "LHP", "RHP"}:

        hard_reasons.append("pitcher handedness unresolved")

    if data_score is not None and data_score < MERGE_V254_MIN_DATA_SCORE:

        hard_reasons.append(f"data score {data_score:.0f} below {MERGE_V254_MIN_DATA_SCORE}")

    if resolved_hitter_count < MERGE_V254_MIN_RESOLVED_HITTERS:

        hard_reasons.append(

            f"only {resolved_hitter_count} hitter K profiles resolved; need {MERGE_V254_MIN_RESOLVED_HITTERS}"

        )

    elif resolved_hitter_count < MERGE_V254_TARGET_RESOLVED_HITTERS:

        cautions.append(

            f"{resolved_hitter_count}/{MERGE_V254_TARGET_RESOLVED_HITTERS} target hitter profiles resolved"

        )

    if not bool(p.get("pitcher_confirmed")):

        cautions.append("probable starter not yet confirmed")

    if not lineup_locked:

        cautions.append("official batting order not posted")

    if lineup_age is None:

        cautions.append("lineup refresh timestamp unavailable")

    elif not lineup_locked and lineup_age > MERGE_V254_HARD_STALE_LINEUP_AGE_MIN:

        hard_reasons.append(f"expected lineup is {lineup_age:.0f} minutes old")

    elif not lineup_locked and lineup_age > MERGE_V254_MAX_EXPECTED_LINEUP_AGE_MIN:

        cautions.append(f"expected lineup is {lineup_age:.0f} minutes old")

    if not bool(p.get("statcast_available")):

        cautions.append("Savant pitcher profile unavailable")

    if not bool(p.get("pitch_type_matchup_available")):

        cautions.append("automatic pitch-type matchup unavailable")

    ud_status = str(p.get("underdog_lineup_status") or "UNDERDOG_NOT_CHECKED")

    if "SUPPORTED" not in ud_status and "OVERRIDES" not in ud_status:

        cautions.append("Underdog names-only pool unavailable or partial")



    status = "PASS_DATA_QUALITY" if hard_reasons else ("CAUTION" if cautions else "READY")

    score = 100

    score -= 35 * len(hard_reasons)

    score -= min(40, 7 * len(cautions))

    return {

        "status": status,

        "score": int(max(0, score)),

        "hard_reasons": hard_reasons,

        "cautions": cautions,

        "resolved_hitter_count": int(resolved_hitter_count),

        "lineup_age_minutes": None if lineup_age is None else round(lineup_age, 1),

        "lineup_freshness": (

            "CONFIRMED" if lineup_locked else

            "STALE" if lineup_age is not None and lineup_age > MERGE_V254_MAX_EXPECTED_LINEUP_AGE_MIN else

            "EXPECTED_FRESH"

        ),

    }





def apply_data_quality_gate_v254(p, now_value=None):

    out = dict(p or {})

    quality = evaluate_data_quality_v254(out, now_value=now_value)

    out["data_quality_gate_status"] = quality["status"]

    out["data_quality_gate_score"] = quality["score"]

    out["data_quality_hard_reasons"] = quality["hard_reasons"]

    out["data_quality_cautions"] = quality["cautions"]

    out["resolved_hitter_count"] = quality["resolved_hitter_count"]

    out["lineup_age_minutes"] = quality["lineup_age_minutes"]

    out["lineup_freshness_status"] = quality["lineup_freshness"]

    if MERGE_V254_ENABLE_DATA_QUALITY_GATE and quality["status"] == "PASS_DATA_QUALITY":

        out["pre_data_quality_action_tier"] = out.get("action_tier")

        out["pre_data_quality_bet_action"] = out.get("bet_action")

        out["action_tier"] = "PASS"

        out["bet_action"] = "PASS — DATA QUALITY"

    return out





def official_lineup_transition_v254(picks, force=False):

    """Detect newly posted MLB batting orders; called at most once per interval."""

    if not MERGE_V254_ENABLE_AUTO_LINEUP_REFRESH:

        return {"refresh": False, "games": [], "status": "DISABLED"}

    now_epoch = datetime.now().timestamp()

    last_epoch = safe_float(st.session_state.get("v254_last_lineup_check_epoch"), 0.0) or 0.0

    if not force and now_epoch - last_epoch < MERGE_V254_OFFICIAL_LINEUP_CHECK_INTERVAL_SEC:

        return {"refresh": False, "games": [], "status": "THROTTLED"}

    st.session_state.v254_last_lineup_check_epoch = now_epoch

    game_pks = sorted({str(p.get("game_pk")) for p in (picks or []) if p.get("game_pk") and not p.get("lineup_locked")})

    transitioned = []

    for game_pk in game_pks:

        try:

            box = safe_get_json(f"{MLB_BASE}/game/{game_pk}/boxscore", timeout=12) or {}

            teams = box.get("teams") or {}

            counts = {}

            for side in ("away", "home"):

                players = ((teams.get(side) or {}).get("players") or {}).values()

                counts[side] = sum(1 for player in players if player.get("battingOrder"))

            if max(counts.values() or [0]) >= 8:

                transitioned.append({"game_pk": game_pk, "away_hitters": counts.get("away", 0), "home_hitters": counts.get("home", 0)})

        except Exception:

            continue

    return {"refresh": bool(transitioned), "games": transitioned, "status": "OFFICIAL_LINEUP_FOUND" if transitioned else "NO_TRANSITION"}





def _v254_pregame_value(value):

    if isinstance(value, dict):

        return {

            str(key): _v254_pregame_value(item)

            for key, item in value.items()

            if str(key).lower() not in _V254_OUTCOME_KEYS

        }

    if isinstance(value, (list, tuple)):

        return [_v254_pregame_value(item) for item in value]

    if isinstance(value, np.ndarray):

        return value.tolist()

    if isinstance(value, (np.integer, np.floating)):

        return value.item()

    if isinstance(value, (datetime, pd.Timestamp)):

        return value.isoformat()

    if pd.isna(value) if not isinstance(value, (str, bytes)) else False:

        return None

    return value





def save_frozen_pregame_snapshot_v254(picks, base_dir=None):

    """Write a pregame-only JSON fixture and flat CSV; outcome keys are removed."""

    if not MERGE_V254_ENABLE_PREGAME_FIXTURES:

        return {"status": "DISABLED", "count": 0}

    root = Path(base_dir or "validation/pregame_live")

    root.mkdir(parents=True, exist_ok=True)

    stamp = datetime.now().strftime("%Y%m%dT%H%M%S")

    clean_rows = [_v254_pregame_value(dict(p)) for p in (picks or []) if isinstance(p, dict)]

    settings = {

        "po_protection": True,

        "workload_repair": MERGE_V252_ENABLE_WORKLOAD_REPAIR,

        "elite_escape": MERGE_V252_ENABLE_ELITE_ESCAPE,

        "exact_line_guard": MERGE_V252_ENABLE_EXACT_LINE_GUARD,

        "early_k_projection": MERGE_V252_ENABLE_EARLY_K_PROJECTION,

        "umpire_projection": MERGE_V252_ENABLE_UMPIRE_PROJECTION,

        "underdog_projection": MERGE_V252_ENABLE_UNDERDOG_LINEUP_PROJECTION,

        "data_quality_gate": MERGE_V254_ENABLE_DATA_QUALITY_GATE,

        "lineup_resolver_v256": bool(globals().get("MERGE_V256_ENABLE_LINEUP_RESOLVER", True)),

        "skill_matchup_diagnostics_v256": bool(globals().get("MERGE_V256_ENABLE_SKILL_MATCHUP_DIAGNOSTICS", True)),

        "skill_matchup_projection_v256": bool(globals().get("MERGE_V256_ENABLE_SKILL_MATCHUP_PROJECTION", False)),

        "k_history_diagnostics_v256": bool(globals().get("MERGE_V256_ENABLE_K_HISTORY_DIAGNOSTICS", True)),

        "k_history_projection_v256": bool(globals().get("MERGE_V256_ENABLE_K_HISTORY_PROJECTION", False)),

    }

    payload = {

        "schema": "MERGE_V254_PREGAME_ONLY",

        "snapshot_timestamp": now_iso(),

        "app_version": APP_VERSION,

        "settings": settings,

        "rows": clean_rows,

    }

    json_path = root / f"merge_v254_pregame_{stamp}.json"

    csv_path = root / f"merge_v254_pregame_{stamp}.csv"

    json_path.write_text(json.dumps(payload, indent=2, ensure_ascii=True), encoding="utf-8")

    flat_rows = []

    for row in clean_rows:

        flat_rows.append({key: json.dumps(value, ensure_ascii=True) if isinstance(value, (dict, list)) else value for key, value in row.items()})

    pd.DataFrame(flat_rows).to_csv(csv_path, index=False)

    return {"status": "SAVED", "count": len(clean_rows), "json_path": str(json_path), "csv_path": str(csv_path)}





def build_live_source_health_v254(picks):

    rows = []

    for p in picks or []:

        if not isinstance(p, dict):

            continue

        quality = evaluate_data_quality_v254(p)

        pitch_rows = [row for row in (p.get("pitch_type_rows") or []) if isinstance(row, dict)]

        rows.append({

            "Pitcher": p.get("pitcher"),

            "Hand": p.get("hand"),

            "Starter": "CONFIRMED" if p.get("pitcher_confirmed") else "PROBABLE",

            "Lineup": "OFFICIAL" if p.get("lineup_locked") else "EXPECTED",

            "Hitters": quality["resolved_hitter_count"],

            "Lineup Age Min": quality["lineup_age_minutes"],

            "Underdog": p.get("underdog_lineup_status"),

            "UD Hitters": safe_int(p.get("underdog_player_count"), 0),

            "UD K%": p.get("underdog_expected_lineup_k_pct"),

            "Savant": "READY" if p.get("statcast_available") else "MISSING",

            "Arsenal Rows": len(pitch_rows),

            "Pitch Matchup": "READY" if p.get("pitch_type_matchup_available") else "FALLBACK",

            "Data Gate": quality["status"],

            "Gate Score": quality["score"],

            "Reason": "; ".join(quality["hard_reasons"] or quality["cautions"][:2]),

        })

    return pd.DataFrame(rows)





def _v254_side_won(side, actual_k, line):

    side = str(side or "").upper()

    actual = safe_float(actual_k, None)

    threshold = safe_float(line, None)

    if actual is None or threshold is None or actual == threshold or side not in {"OVER", "UNDER"}:

        return None

    return actual > threshold if side == "OVER" else actual < threshold





def build_module_grading_v254(results=None):

    """Observed model comparison plus module usage; no fabricated counterfactuals."""

    graded = [row for row in (results if results is not None else load_json(RESULT_LOG, [])) if isinstance(row, dict)]

    model_specs = [

        ("CURRENT_PO", ["current_po_side", "PO Side", "po_direction"], ["current_po_projection", "PO Projection", "po_projection"]),

        ("MERGE_RAW", ["merge_raw_side", "Merge Raw Side", "merge_direction"], ["hybrid_consensus_projection", "Merge Raw Projection", "merge_projection"]),

        ("FINAL_PROTECTED", ["pick_side", "Final Resolved Side", "final_side"], ["decision_projection", "projection", "Final Resolved Projection"]),

    ]

    metrics = []

    normalized = []

    for row in graded:

        actual = next((safe_float(row.get(key), None) for key in ("actual", "actual_k", "Actual K", "strikeouts") if safe_float(row.get(key), None) is not None), None)

        line = next((safe_float(row.get(key), None) for key in ("line", "UD/Line", "Line") if safe_float(row.get(key), None) is not None), None)

        if actual is None or line is None:

            continue

        normalized.append((row, actual, line))

    for name, side_keys, projection_keys in model_specs:

        wins = losses = 0

        errors = []

        for row, actual, line in normalized:

            side = next((row.get(key) for key in side_keys if str(row.get(key) or "").upper() in {"OVER", "UNDER"}), None)

            won = _v254_side_won(side, actual, line)

            if won is True:

                wins += 1

            elif won is False:

                losses += 1

            projection = next((safe_float(row.get(key), None) for key in projection_keys if safe_float(row.get(key), None) is not None), None)

            if projection is not None:

                errors.append(abs(projection - actual))

        plays = wins + losses

        metrics.append({

            "Model": name,

            "Wins": wins,

            "Losses": losses,

            "Win Rate": None if not plays else round(wins / plays * 100.0, 1),

            "Projection MAE": None if not errors else round(float(np.mean(errors)), 3),

            "Graded Plays": plays,

        })

    rescued = surrendered = comparable = 0

    for row, actual, line in normalized:

        po_side = str(row.get("current_po_side") or row.get("PO Side") or "").upper()

        final_side = str(row.get("pick_side") or row.get("Final Resolved Side") or "").upper()

        if po_side not in {"OVER", "UNDER"} or final_side not in {"OVER", "UNDER"} or po_side == final_side:

            continue

        comparable += 1

        po_win = _v254_side_won(po_side, actual, line)

        final_win = _v254_side_won(final_side, actual, line)

        rescued += int(po_win is False and final_win is True)

        surrendered += int(po_win is True and final_win is False)

    module_rows = []

    module_specs = [

        ("PO protection", True, "resolver_decision", "PRESERVE_PO"),

        ("Workload V2", MERGE_V252_ENABLE_WORKLOAD_REPAIR, "workload_repair_v252_applied", True),

        ("Suppression escape", MERGE_V252_ENABLE_ELITE_ESCAPE, "elite_escape_v252_applied", True),

        ("Exact-line guard", MERGE_V252_ENABLE_EXACT_LINE_GUARD, "exact_line_v252_force_pass", True),

        ("Early-K projection", MERGE_V252_ENABLE_EARLY_K_PROJECTION, "early_k_projection_enabled", True),

        ("Umpire projection", MERGE_V252_ENABLE_UMPIRE_PROJECTION, "umpire_projection_enabled", True),

        ("Underdog lineup projection", MERGE_V252_ENABLE_UNDERDOG_LINEUP_PROJECTION, "underdog_lineup_projection_enabled", True),

        ("Data-quality gate", MERGE_V254_ENABLE_DATA_QUALITY_GATE, "data_quality_gate_status", "PASS_DATA_QUALITY"),

        ("V2.6 lineup resolver", bool(globals().get("MERGE_V256_ENABLE_LINEUP_RESOLVER", True)), "lineup_resolver_active_v256", True),

        ("V2.6 skill/matchup projection", bool(globals().get("MERGE_V256_ENABLE_SKILL_MATCHUP_PROJECTION", False)), "skill_matchup_projection_applied", True),

        ("V2.6 K-history projection", bool(globals().get("MERGE_V256_ENABLE_K_HISTORY_PROJECTION", False)), "k_history_projection_applied", True),

    ]

    for module, enabled, field, active_value in module_specs:

        active = sum(1 for row, _actual, _line in normalized if row.get(field) == active_value)

        module_rows.append({"Module": module, "Projection Enabled": bool(enabled), "Observed Activations": active, "Evaluation": "OBSERVED ONLY — use frozen replay for causal A/B"})

    return {

        "metrics": pd.DataFrame(metrics),

        "modules": pd.DataFrame(module_rows),

        "net_gain": {"rescued_po_losses": rescued, "surrendered_po_wins": surrendered, "net": rescued - surrendered, "flip_attempts": comparable},

        "graded_rows": len(normalized),

    }





