# K UPSIDE TESTER LAYER — K MODEL ONLY

# Adds evaluation/ranking metrics for the K PROJ / UPSIDE tab only.

# Does NOT touch Pitching Outs, Pitcher FS, Moneyline, grading, learning,

# saved boards, GitHub backup, or any non-K module.

# ============================================================

K_UPSIDE_TESTER_VERSION = "K_UPSIDE_TESTER_V71_BF_AUTHORITY_VOL_CONFIDENCE"



def _kut_num(x, default=None):

    try:

        if x is None or str(x).strip() in ["", "—", "None", "nan"]:

            return default

        v = float(str(x).replace("%", "").replace(",", "").strip())

        if pd.isna(v):

            return default

        return v

    except Exception:

        return default



def _kut_rate(x, default=None):

    v = _kut_num(x, None)

    if v is None:

        return default

    if abs(v) > 1.0:

        v = v / 100.0

    return float(clamp(v, 0.0, 1.0))



def _kut_first_rate(p, keys, default=None):

    for k in keys:

        v = _kut_rate((p or {}).get(k), None)

        if v is not None:

            return v

    return default



def _kut_lineup_contact_context(p):

    """Return lineup K/contact context from batter rows when available.



    A higher contact risk lowers OVER confidence. This only feeds K tester scores.

    """

    rows = (p or {}).get("lineup_rows") or []

    vals = []

    for r in rows[:9] if isinstance(rows, list) else []:

        if not isinstance(r, dict):

            continue

        k_val = None

        for key in ["Used K%", "K%", "Raw_K_Rate", "K Rate", "K_Pct", "SO%"]:

            if r.get(key) is not None:

                k_val = _kut_rate(r.get(key), None)

                break

        if k_val is not None:

            vals.append(k_val)

    if vals:

        avg_k = float(np.mean(vals))

        low_k_bats = int(sum(1 for v in vals if v <= 0.17))

        high_k_bats = int(sum(1 for v in vals if v >= 0.255))

        return {"available": True, "avg_k": avg_k, "low_k_bats": low_k_bats, "high_k_bats": high_k_bats, "sample": len(vals)}

    ok = _kut_rate((p or {}).get("opp_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    return {"available": False, "avg_k": ok, "low_k_bats": None, "high_k_bats": None, "sample": 0}



def k_upside_strikeout_conversion_score(p):

    """0-100 score: are projected batters likely to convert into strikeouts?"""

    p = p or {}

    pk = _kut_rate(p.get("pitcher_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    ok = _kut_rate(p.get("opp_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    csw = _kut_first_rate(p, ["statcast_csw", "csw_pct", "CSW%", "CSW"], None)

    whiff = _kut_first_rate(p, ["statcast_whiff", "whiff_pct", "putaway_whiff", "Putaway/Whiff", "whiff"], None)

    putaway = _kut_first_rate(p, ["putaway_pct", "putaway", "putaway_rate"], None)

    lineup = _kut_lineup_contact_context(p)

    lineup_k = lineup.get("avg_k") or ok



    score = 50.0

    # Pitcher true K ability.

    score += clamp((pk - 0.215) * 170.0, -18, 22)

    # Opponent / lineup strikeout tendency.

    score += clamp((lineup_k - 0.215) * 145.0, -18, 20)

    # Quality of strike generation and finish ability.

    if csw is not None:

        score += clamp((csw - 0.285) * 130.0, -10, 14)

    if whiff is not None:

        score += clamp((whiff - 0.255) * 115.0, -10, 14)

    if putaway is not None:

        score += clamp((putaway - 0.205) * 80.0, -6, 8)

    # Contact-heavy lineups make raw K projection less trustworthy.

    if lineup.get("low_k_bats") is not None:

        score -= min(10, max(0, lineup.get("low_k_bats", 0) - 2) * 2.0)

        score += min(8, max(0, lineup.get("high_k_bats", 0) - 2) * 1.5)

    label = "ELITE" if score >= 85 else "GOOD" if score >= 72 else "AVG" if score >= 58 else "WEAK"

    note = f"pk {pk*100:.1f}% | opp/lineup {lineup_k*100:.1f}%"

    if csw is not None:

        note += f" | CSW {csw*100:.1f}%"

    if whiff is not None:

        note += f" | whiff {whiff*100:.1f}%"

    return {"score": int(clamp(round(score), 0, 100)), "label": label, "note": note}



def k_upside_contact_suppression_rating(p):

    """0-100 score where higher = better for K overs; label describes contact risk."""

    p = p or {}

    ok = _kut_rate(p.get("opp_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    lineup = _kut_lineup_contact_context(p)

    lineup_k = lineup.get("avg_k") or ok

    # Direct contact fields if available. Higher contact = worse for K overs.

    zone_contact = _kut_first_rate(p, ["opp_zone_contact", "zone_contact", "Zone Contact%", "zone_contact_pct"], None)

    contact = _kut_first_rate(p, ["opp_contact", "contact_rate", "Contact%", "contact_pct"], None)

    foul = _kut_first_rate(p, ["foul_rate", "opp_foul_rate", "Foul%"], None)



    score = 65.0 + clamp((lineup_k - 0.215) * 180.0, -30, 25)

    if zone_contact is not None:

        score -= clamp((zone_contact - 0.835) * 95.0, -8, 14)

    if contact is not None:

        score -= clamp((contact - 0.765) * 90.0, -8, 14)

    if foul is not None:

        score -= clamp((foul - 0.270) * 45.0, -4, 7)

    if lineup.get("low_k_bats") is not None:

        score -= min(14, max(0, lineup.get("low_k_bats", 0) - 2) * 2.8)

    risk = "LOW" if score >= 75 else "MEDIUM" if score >= 58 else "HIGH"

    note = f"contact risk {risk} | lineup K {lineup_k*100:.1f}%"

    if lineup.get("sample"):

        note += f" | low-K bats {lineup.get('low_k_bats')}"

    return {"score": int(clamp(round(score), 0, 100)), "risk": risk, "note": note}



def k_upside_volatility_tax(p, dist=None):

    """Penalty points. Higher = less trust in K official status."""

    p = p or {}

    if dist is None:

        dist = {}

    vol = _kut_num(dist.get("volatility"), _kut_num(p.get("volatility"), 1.2)) or 1.2

    role_score, _, _ = kproj_role_stability_score(p)

    starter_score, _ = kproj_starter_confirmation_score(p)

    ip_floor = kproj_probable_innings_floor(p)

    exp_label = str(p.get("pitcher_experience_label") or p.get("experience_label") or "").upper()

    tax = 0.0

    tax += clamp((vol - 1.25) * 8.0, 0, 12)

    tax += clamp((64 - role_score) * 0.18, 0, 9)

    tax += clamp((62 - starter_score) * 0.15, 0, 7)

    if ip_floor is not None and ip_floor < 4.3:

        tax += clamp((4.3 - ip_floor) * 4.2, 0, 10)

    # v71 stronger volatility tax for uncertain MLB roles / small samples.

    role_text = " ".join(str(p.get(k) or "") for k in ["role", "pitcher_role", "probable_role", "starter_status", "Beta Flags", "leash_risk"]).upper()

    if any(x in exp_label for x in ["ROOKIE", "UNKNOWN", "LOW SAMPLE"]):

        tax += 6.0

    if any(x in role_text for x in ["OPENER", "BULK", "PITCH_LIMIT", "RECENT_HOOK", "LOW_SAMPLE", "SHORT"]):

        tax += 5.0

    recent_n = len([x for x in (p.get("last_10_ks") or []) if safe_float(x, None) is not None])

    if recent_n and recent_n < 4:

        tax += 3.0

    rd = str(p.get("run_damage_risk_level") or "").upper()

    if rd == "EXTREME":

        tax += 6.0

    elif rd == "HIGH":

        tax += 3.0

    label = "LOW" if tax < 6 else "MEDIUM" if tax < 14 else "HIGH"

    return {"tax": round(float(clamp(tax, 0, 30)), 1), "label": label, "note": f"vol {vol:.2f} | role {role_score} | starter {starter_score} | IP floor {ip_floor}"}



def k_upside_bf_ip_ceiling_check(p, line=None, proj=None):

    """Checks if BF/IP opportunity realistically supports the K line/projection."""

    p = p or {}

    bf = _kut_num(p.get("expected_bf"), DEFAULT_BF) or DEFAULT_BF

    ip_floor = kproj_probable_innings_floor(p)

    pk = _kut_rate(p.get("pitcher_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    ok = _kut_rate(p.get("opp_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    line = _kut_num(line, None)

    proj = _kut_num(proj, None)

    needed = required_ks_for_over(line) if line is not None else None

    # Realistic upper conversion for a normal starter slate. Elite arms can stretch it a little.

    ceiling_rate = clamp((pk * 0.62) + (ok * 0.28) + 0.035, 0.22, 0.42)

    max_supported_k = bf * ceiling_rate

    score = 82.0

    if needed is not None:

        margin = max_supported_k - needed

        score += clamp(margin * 10.0, -32, 18)

    if proj is not None:

        score += clamp((max_supported_k - proj) * 5.0, -18, 8)

    if bf < 20:

        score -= 12

    elif bf >= 24:

        score += 6

    if ip_floor is not None and ip_floor < 4.0:

        score -= 10

    status = "PASS" if score >= 68 else "CAUTION" if score >= 52 else "FAIL"

    return {"score": int(clamp(round(score), 0, 100)), "status": status, "max_supported_k": round(float(max_supported_k), 2), "note": f"BF {bf:.1f} | IP floor {ip_floor} | max supported {max_supported_k:.1f} K"}



def k_upside_line_difficulty(line):

    """Historical line difficulty caution. Higher score = easier/cleaner line."""

    line = _kut_num(line, None)

    if line is None:

        return {"score": 50, "label": "NO LINE", "tax": 8.0, "note": "No real line"}

    if line <= 3.5:

        score, tax, label = 88, 0.0, "EASY"

    elif line <= 4.5:

        score, tax, label = 78, 1.5, "NORMAL"

    elif line <= 5.5:

        score, tax, label = 68, 3.0, "MODERATE"

    elif line <= 6.5:

        score, tax, label = 56, 6.0, "HARD"

    else:

        score, tax, label = 46, 9.0, "VERY HARD"

    return {"score": score, "label": label, "tax": tax, "note": f"Line {line:.1f} = {label} clearance difficulty"}



def k_upside_tester_profile(p, decision=None):

    """Full K Upside Tester profile. Uses K data only; no Pitching Outs changes."""

    p = p or {}

    if decision is None:

        decision = kproj_decision(p)

    proj = _kut_num(decision.get("projection"), _kut_num(p.get("projection"), None))

    line = _kut_num(decision.get("line"), _kut_num(p.get("line") or p.get("underdog_line"), None))

    dist = kproj_distribution_profile(proj, line, p) if proj is not None else {}

    conversion = k_upside_strikeout_conversion_score(p)

    contact = k_upside_contact_suppression_rating(p)

    volatility = k_upside_volatility_tax(p, dist)

    ceiling = k_upside_bf_ip_ceiling_check(p, line=line, proj=proj)

    line_diff = k_upside_line_difficulty(line)

    role_score, _, _ = kproj_role_stability_score(p)

    # Learning confidence proxy from reliability/data/lineup. This is a trust score, not a projection boost.

    learning_conf = _kut_num(p.get("reliability_score"), None)

    if learning_conf is None:

        learning_conf = _kut_num(p.get("data_score"), 75.0)

    learning_conf = float(clamp(learning_conf or 75.0, 0, 100))

    edge = 0.0 if proj is None or line is None else float(proj - line)

    abs_edge_score = clamp(abs(edge) / 1.75 * 100.0, 0, 100)

    bf = _kut_num(p.get("expected_bf"), DEFAULT_BF) or DEFAULT_BF

    bf_score = clamp((bf - 17.0) / 9.0 * 100.0, 0, 100)

    # V63 conservative calibration: keep the original K projection as the anchor.

    # The tester should rank/filter borderline plays, not become a second aggressive model.

    # Higher contact score = lower contact suppression risk. Higher conversion = more likely Ks convert.

    learning_strength = clamp((learning_conf - 50.0) / 50.0, 0.25, 1.0)

    tester_weight = 0.35 + (0.25 * learning_strength)  # v71: tester filters/ranks more than it overrides



    raw = (

        0.55 * abs_edge_score +      # anchor to original projection edge

        0.16 * bf_score +

        0.10 * conversion["score"] +

        0.07 * contact["score"] +

        0.08 * role_score +

        0.04 * learning_conf

    )



    # Reduced penalty strength versus the first tester. Volatility/contact now mostly changes confidence.

    ceiling_penalty = 0 if ceiling["status"] == "PASS" else 4 if ceiling["status"] == "CAUTION" else 10

    penalty = (volatility["tax"] * 0.85) + (line_diff["tax"] * 0.55) + ceiling_penalty

    sos = int(clamp(round((raw - penalty) * tester_weight + abs_edge_score * (1.0 - tester_weight)), 0, 100))



    model_side = str(decision.get("lean_side") or ("OVER" if edge >= 0 else "UNDER")).upper()

    abs_edge = abs(edge)

    negative_cluster = 0

    negative_cluster += 1 if conversion["score"] < 58 else 0

    negative_cluster += 1 if contact["risk"] == "HIGH" else 0

    negative_cluster += 1 if volatility["label"] == "HIGH" else 0

    negative_cluster += 1 if ceiling["status"] == "FAIL" else 0

    negative_cluster += 1 if line_diff["label"] in ["HARD", "VERY HARD"] else 0



    # Conservative recommendation gates:

    # - no official-style tester play on tiny gaps

    # - elite/strong requires real projection separation

    # - large base edges are protected from one warning signal

    if line is None:

        rec = "🚫 NO LINE"

    elif abs_edge < 0.35:

        rec = f"🚫 PASS — THIN {model_side}"

    elif abs_edge < 0.60 and sos < 82:

        rec = f"🚫 PASS — BORDERLINE {model_side}"

    elif negative_cluster >= 3 and abs_edge < 1.15:

        rec = f"⚠️ LEAN {model_side} — RISK CHECK"

    elif sos >= 91 and abs_edge >= 1.10 and conversion["score"] >= 72 and contact["score"] >= 58 and ceiling["status"] == "PASS" and volatility["label"] != "HIGH":

        rec = f"🔥 ELITE {model_side}"

    elif sos >= 84 and abs_edge >= 0.85 and ceiling["status"] != "FAIL" and negative_cluster <= 2:

        rec = f"✅ STRONG {model_side}"

    elif sos >= 72 and abs_edge >= 0.60:

        rec = f"⚠️ LEAN {model_side}"

    else:

        rec = f"🚫 PASS — {model_side}"



    note = " | ".join([

        f"SOS {sos}/100",

        f"edge {edge:+.2f}",

        f"tester wt {tester_weight:.2f}",

        f"conv {conversion['score']} {conversion['label']}",

        f"contact risk {contact['risk']}",

        f"vol {volatility['label']} -{volatility['tax']}",

        f"BF ceiling {ceiling['status']}",

        f"line diff {line_diff['label']}",

        f"risk flags {negative_cluster}",

    ])

    return {

        "version": K_UPSIDE_TESTER_VERSION,

        "sos_score": sos,

        "recommendation": rec,

        "strikeout_conversion_score": conversion["score"],

        "strikeout_conversion_label": conversion["label"],

        "strikeout_conversion_note": conversion["note"],

        "contact_suppression_score": contact["score"],

        "contact_suppression_risk": contact["risk"],

        "contact_suppression_note": contact["note"],

        "volatility_tax": volatility["tax"],

        "volatility_label": volatility["label"],

        "volatility_note": volatility["note"],

        "bf_ip_ceiling_score": ceiling["score"],

        "bf_ip_ceiling_status": ceiling["status"],

        "bf_ip_max_supported_k": ceiling["max_supported_k"],

        "bf_ip_ceiling_note": ceiling["note"],

        "line_difficulty_score": line_diff["score"],

        "line_difficulty_label": line_diff["label"],

        "line_difficulty_note": line_diff["note"],

        "learning_confidence": round(learning_conf, 1),

        "tester_weight": round(float(tester_weight), 2),

        "negative_cluster": int(negative_cluster),

        "note": note,

    }



def build_k_upside_tester_table(board):

    rows = []

    for p in board or []:

        d = kproj_decision(p)

        t = k_upside_tester_profile(p, d)

        rows.append({

            "Pitcher": p.get("pitcher") or p.get("Pitcher"),

            "Matchup": p.get("matchup") or p.get("Matchup"),

            "Line": d.get("line"),

            "K PROJ": d.get("projection"),

            "Model Decision": d.get("decision"),

            "Tester Recommendation": t.get("recommendation"),

            "SOS Score": t.get("sos_score"),

            "Strikeout Conversion": t.get("strikeout_conversion_score"),

            "Contact Score": t.get("contact_suppression_score"),

            "Contact Risk": t.get("contact_suppression_risk"),

            "Volatility Tax": t.get("volatility_tax"),

            "Volatility": t.get("volatility_label"),

            "BF/IP Ceiling": t.get("bf_ip_ceiling_status"),

            "Max Supported K": t.get("bf_ip_max_supported_k"),

            "Line Difficulty": t.get("line_difficulty_label"),

            "Learning Conf": t.get("learning_confidence"),

            "Tester Weight": t.get("tester_weight"),

            "Risk Flags": t.get("negative_cluster"),

            "Tester Note": t.get("note"),

        })

    df = pd.DataFrame(rows)

    if not df.empty:

        df = df.sort_values(["SOS Score", "K PROJ"], ascending=[False, False])

    return df



def kproj_confidence_tier(conf, hit_rate, gap, role_score):

    conf = safe_float(conf, 0.50) or 0.50

    hit_rate = safe_float(hit_rate, 0.50) or 0.50

    gap = abs(safe_float(gap, 0) or 0)



    if conf >= 0.66 and hit_rate >= 0.64 and gap >= 1.25 and role_score >= 72:

        return "A"

    if conf >= 0.62 and hit_rate >= 0.60 and gap >= 0.90 and role_score >= 62:

        return "B"

    if hit_rate >= 0.56 and gap >= 0.55:

        return "C"

    return "PASS"





def _impl_kproj_decision_01(p):

    """

    Projection-first decision logic for the K PROJ / Upside tab.



    Philosophy:

    1) Build the true K projection first.

    2) Use sim probability second.

    3) PASS only when data/role is bad or edge is truly too thin.

    4) Always keep directional output: PASS — OVER / PASS — UNDER.

    """

    line, line_source = kproj_line_for_display(p)

    proj = kproj_upside_projection(p)



    if line is None:

        return {

            "line": None, "line_source": line_source, "projection": proj,

            "side": "NO LINE", "lean_side": "NO LINE", "lean_gap": None,

            "confidence": None, "decision": "🚫 NO UD LINE", "over_needed": None,

            "under_max": None, "line_edge": None, "edge_display": "—", "edge_class": "yellow-badge",

            "hit_rate": None, "tier": "NO LINE", "role_score": None, "starter_score": None,

            "ip_floor": None, "edge_gap": None,

            "note": "No Underdog/active real line found"

        }



    over_needed = required_ks_for_over(line)

    under_max = max_ks_for_under(line)



    # True line edge: this drives model direction. Cash-number logic is still displayed.

    line_edge = round(float(proj - line), 2)

    abs_edge = abs(line_edge)

    model_side = "OVER" if proj >= line else "UNDER"



    # Cash-number edge: useful for explaining half-point lines.

    diff_to_over_cash = proj - over_needed

    diff_to_under_cash = under_max - proj

    pass_direction_gap = line_edge if model_side == "OVER" else -line_edge



    upside = safe_float(p.get("elite_upside_score"), 0.0) or 0.0

    pk = safe_float(p.get("pitcher_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    ok = safe_float(p.get("opp_k"), LEAGUE_AVG_K) or LEAGUE_AVG_K



    role_score, role_note, _ = kproj_role_stability_score(p)

    starter_score, starter_note = kproj_starter_confirmation_score(p)

    ip_floor = kproj_probable_innings_floor(p)

    ceiling_risk, ceiling_note = kproj_ceiling_risk_score(p)

    true_floor, true_floor_note = kproj_true_projection_floor(p)



    # Sim probability comes after projection direction.

    hit_rate = kproj_sim_hit_rate(proj, line, model_side, p)

    hit_rate_val = safe_float(hit_rate, 0.50) or 0.50



    # PASS should mean data/role problem or no meaningful edge, not fear of a good projection.

    bad_data = False

    bad_data_reasons = []

    if role_score < 45:

        bad_data = True; bad_data_reasons.append(f"bad role score {role_score}/100")

    if starter_score < 45:

        bad_data = True; bad_data_reasons.append(f"bad starter score {starter_score}/100")

    if ip_floor is not None and ip_floor < 2.6:

        bad_data = True; bad_data_reasons.append(f"bad IP floor {ip_floor}")



    side = "PASS"

    conf = hit_rate_val

    gap = abs_edge

    reasons = []



    # v71 K-only confidence helpers. These affect K decisions/confidence only.

    try:

        _conv = k_upside_strikeout_conversion_score(p)

        _contact = k_upside_contact_suppression_rating(p)

        _vol = k_upside_volatility_tax(p, kproj_distribution_profile(proj, line, p))

        _ceil = k_upside_bf_ip_ceiling_check(p, line=line, proj=proj)

        _line_diff = k_upside_line_difficulty(line)

    except Exception:

        _conv = {"score": 65}; _contact = {"risk": "MEDIUM", "score": 60}; _vol = {"label": "MEDIUM", "tax": 8}; _ceil = {"status": "CAUTION"}; _line_diff = {"label": "MODERATE"}



    over_risk_flags = 0

    over_risk_flags += 1 if _conv.get("score", 65) < 66 else 0

    over_risk_flags += 1 if _contact.get("risk") == "HIGH" else 0

    over_risk_flags += 1 if _vol.get("label") == "HIGH" else 0

    over_risk_flags += 1 if _ceil.get("status") != "PASS" else 0

    over_risk_flags += 1 if _line_diff.get("label") in ["HARD", "VERY HARD"] else 0



    under_danger_flags = 0

    under_danger_flags += 1 if ceiling_risk >= KPROJ_CEILING_RISK_WARN_UNDER else 0

    under_danger_flags += 1 if upside >= 55 else 0

    under_danger_flags += 1 if pk >= 0.255 and ok >= 0.220 else 0

    under_danger_flags += 1 if _conv.get("score", 65) >= 70 else 0

    under_danger_flags += 1 if _ceil.get("status") == "PASS" and safe_float(p.get("expected_bf"), DEFAULT_BF) >= 22 else 0



    # v73: cap recent hit-rate influence. Recent clears/misses cannot force a side.

    _recent_guard = kproj_recent_hit_rate_guard(p, model_side=model_side, line=line, proj=proj)

    over_risk_flags += int(_recent_guard.get("over_risk", 0) or 0)

    under_danger_flags += int(_recent_guard.get("under_danger", 0) or 0)



    # confidence is now reduced by risk; projection remains the anchor.

    conf = clamp(hit_rate_val + (safe_float(_recent_guard.get("conf_adj"), 0.0) or 0.0) - ((_vol.get("tax", 0) or 0) * 0.003) - (over_risk_flags * 0.010 if model_side == "OVER" else under_danger_flags * 0.008), 0.01, 0.99)



    if bad_data:

        side = "PASS"

        reasons.extend(bad_data_reasons)

    else:

        if model_side == "OVER":

            # v71: fewer false overs. Borderline overs need conversion + BF/IP support.

            if abs_edge < 0.45:

                side = "PASS"; reasons.append("v71 pass: over edge below 0.45 K")

            elif abs_edge < 0.80 and (over_risk_flags >= 2 or hit_rate_val < 0.58):

                side = "PASS"; reasons.append(f"v71 pass: borderline over with {over_risk_flags} risk flags")

            elif abs_edge >= 1.00 and hit_rate_val >= 0.61 and over_risk_flags <= 3:

                side = "OVER"

            elif abs_edge >= 0.70 and hit_rate_val >= 0.58 and over_risk_flags <= 2:

                side = "OVER"

            elif abs_edge >= 0.45 and hit_rate_val >= 0.54:

                side = "OVER LEAN"

            else:

                side = "PASS"; reasons.append("thin over edge / low sim probability")



            if side == "OVER" and (_vol.get("label") == "HIGH" or role_score < 58 or starter_score < 58 or (ip_floor is not None and ip_floor < 3.9)):

                side = "OVER LEAN"

                reasons.append("v71 downgrade: volatility or role/IP risk")



        else:

            # v71: under gate is conservative vs real K-ceiling arms.

            dangerous_under = under_danger_flags >= 2

            if dangerous_under and abs_edge < 2.25:

                side = "PASS"

                reasons.append(f"v71 blocked under: {under_danger_flags} K-upside danger flags")

            elif abs_edge >= 1.75 and hit_rate_val >= 0.62 and role_score >= 58 and under_danger_flags <= 2:

                side = "UNDER"

            elif abs_edge >= 1.00 and hit_rate_val >= 0.56 and under_danger_flags <= 2:

                side = "UNDER LEAN"

            elif abs_edge >= 0.65 and hit_rate_val >= 0.55 and under_danger_flags == 0:

                side = "UNDER LEAN"

            else:

                side = "PASS"

                reasons.append("v71 pass: thin under edge or K-upside danger")



    # Tier is informational. It should not override a valid projection+sim pick.

    tier = kproj_confidence_tier(conf, hit_rate, gap, role_score)

    if side in ["OVER", "UNDER"] and tier == "PASS":

        tier = "C"



    if side == "OVER":

        decision = "🔥 OVER" if hit_rate_val >= 0.64 and abs_edge >= 1.00 else "✅ OVER"

    elif side == "UNDER":

        decision = "🔥 UNDER" if hit_rate_val >= 0.65 and abs_edge >= 1.50 else "✅ UNDER"

    elif side == "OVER LEAN":

        decision = "⚠️ OVER LEAN"

    elif side == "UNDER LEAN":

        decision = "⚠️ UNDER LEAN"

    else:

        decision = f"🚫 PASS — {model_side}"



    edge_display = f"{line_edge:+.2f} K"

    if line_edge >= 1.5 or line_edge <= -1.25:

        edge_class = "good-badge"

    elif abs(line_edge) >= 0.75:

        edge_class = "yellow-badge"

    else:

        edge_class = "red-badge"



    note_parts = [

        f"Projection-first decision",

        f"Over needs {over_needed}+",

        f"Under wins {under_max} or fewer",

        f"line edge={line_edge:+.2f}",

        f"model lean={model_side}",

        f"hit={round(hit_rate_val * 100, 1)}%",

        f"tier={tier}",

        f"role={role_score}/100",

        f"starter={starter_score}/100",

        f"IP floor={ip_floor}",

        f"ceiling risk={ceiling_risk}/100",

        f"v71 conv={_conv.get('score', '—')} contact={_contact.get('risk', '—')} vol={_vol.get('label', '—')} BF/IP={_ceil.get('status', '—')}",

        f"v73 recent-hit cap={_recent_guard.get('label', '—')}: {_recent_guard.get('note', '')}",

        f"cash over edge={round(diff_to_over_cash, 2)}",

        f"cash under edge={round(diff_to_under_cash, 2)}",

    ]

    if ceiling_note:

        note_parts.append(ceiling_note)

    if true_floor_note:

        note_parts.append(true_floor_note)

    if role_note:

        note_parts.append(role_note)

    if starter_note:

        note_parts.append(starter_note)

    if reasons:

        note_parts.extend(reasons)



    return {

        "line": line, "line_source": line_source, "projection": proj,

        "side": side, "lean_side": model_side, "lean_gap": round(pass_direction_gap, 2),

        "confidence": round(conf, 3), "decision": decision,

        "over_needed": over_needed, "under_max": under_max,

        "line_edge": line_edge, "edge_display": edge_display, "edge_class": edge_class,

        "hit_rate": hit_rate, "tier": tier, "role_score": role_score,

        "starter_score": starter_score, "ip_floor": ip_floor, "edge_gap": round(gap, 2),

        "note": " | ".join(str(x) for x in note_parts if x)

    }



def kproj_bar_html(vals):

    vals = [safe_int(x, 0) or 0 for x in (vals or [])[:10]]

    if not vals:

        return "<span class='small-muted'>No recent starts</span>"

    mx = max(max(vals), 1)

    parts = []

    for v in vals:

        h = int(20 + (v / mx) * 42)

        color = "#31e84f" if v >= 6 else "#a92b2b" if v <= 3 else "#ffbe3c"

        parts.append(f"<span class='mini-k-bar-wrap'><span class='mini-k-bar' style='height:{h}px;background:{color};'></span><span class='mini-k-label'>{v}</span></span>")

    return "<div class='mini-k-bars'>" + "".join(parts) + "</div>"







def _k_context_reason_chips(p, d=None):

    """Mobile-friendly explanation chips for K cards.

    UI-only: reads existing model fields and does not change projections or decisions.

    """

    d = d or {}

    reasons = []

    risks = []

    try:

        proj = safe_float(d.get("projection"), safe_float(p.get("projection"), None))

        line = safe_float(d.get("line"), safe_float(p.get("line"), None))

        if proj is not None and line is not None:

            edge = proj - line

            if edge >= 1.0:

                reasons.append(f"Projection edge +{edge:.2f} K")

            elif edge <= -1.0:

                risks.append(f"Projection edge {edge:.2f} K")

            else:

                risks.append(f"Tight edge {edge:+.2f} K")

    except Exception:

        pass

    lineup_status = str(p.get("lineup_status") or "").upper()

    if p.get("lineup_locked") or "CONFIRMED" in lineup_status:

        reasons.append("Confirmed lineup read")

    else:

        risks.append("Pre-lineup estimate")

    opp_k = safe_float(p.get("opp_k"), None)

    if opp_k is not None:

        if opp_k >= 0.245:

            reasons.append(f"High lineup K pressure {opp_k*100:.1f}%")

        elif opp_k <= 0.185:

            risks.append(f"Contact lineup {opp_k*100:.1f}%")

    whiff = safe_float(p.get("whiff_pct"), safe_float(p.get("putaway_whiff"), None))

    csw = safe_float(p.get("csw_pct"), None)

    if whiff is not None:

        w = whiff if whiff <= 1 else whiff/100

        if w >= 0.30:

            reasons.append(f"Whiff/stuff boost {w*100:.1f}%")

        elif w <= 0.20:

            risks.append(f"Low whiff/stuff {w*100:.1f}%")

    if csw is not None:

        c = csw if csw <= 1 else csw/100

        if c >= 0.31:

            reasons.append(f"CSW strength {c*100:.1f}%")

        elif c <= 0.26:

            risks.append(f"CSW below ideal {c*100:.1f}%")

    leash = str(p.get("early_pull_label") or p.get("leash_label") or "").upper()

    if any(x in leash for x in ["SHORT", "EARLY", "HOOK", "LIMIT"]):

        risks.append("Early-pull/leash risk")

    elif any(x in leash for x in ["NORMAL", "WORKHORSE", "LONG"]):

        reasons.append("Normal workload support")

    market = str(p.get("market_lean") or "").upper()

    if market and "NO_MARKET" not in market:

        reasons.append(f"Market: {market.replace('_',' ')}")

    # Deduplicate while preserving order and keep mobile concise.

    def uniq(xs):

        out=[]

        for x in xs:

            if x and x not in out:

                out.append(x)

        return out[:4]

    reasons = uniq(reasons)

    risks = uniq(risks)

    reason_html = "".join([f"<span class='badge good-badge' style='margin:3px 4px 3px 0;'>{html.escape(x)}</span>" for x in reasons]) or "<span class='small-muted'>No major green signal</span>"

    risk_html = "".join([f"<span class='badge yellow-badge' style='margin:3px 4px 3px 0;'>{html.escape(x)}</span>" for x in risks]) or "<span class='small-muted'>No major risk flag</span>"

    summary = " / ".join(reasons[:2] + risks[:1]) if (reasons or risks) else "Context neutral"

    return summary, reason_html, risk_html







def _lineup_pressure_summary(lineup_rows, expected_bf=DEFAULT_BF):

    """UI summary using the displayed hitters, slot probabilities, and the pitcher's real expected BF."""

    rows = lineup_rows or []

    if not rows:

        return "No batter-by-batter lineup available yet."

    vals = []

    for r in rows[:9]:

        name = r.get("Batter") or r.get("Name") or r.get("Player") or r.get("player") or ""

        k = r.get("Used K%")

        if k is None:

            k = r.get("K%") if r.get("K%") is not None else r.get("Raw_K_Rate")

        kv = safe_float(k, None)

        if kv is None:

            continue

        if abs(kv) <= 1.0:

            kv *= 100.0

        vals.append((name, kv))

    if not vals:

        return "Lineup available, but hitter K% data is still filling in."

    high = [n for n, k in vals if k >= 25]

    low = [n for n, k in vals if k <= 15]

    exposure_k = _weighted_lineup_k_from_rows(rows, expected_bf=expected_bf)

    avg = (exposure_k * 100.0) if exposure_k is not None else sum(k for _, k in vals) / len(vals)

    order_conf = safe_float((rows[0] or {}).get("Expected Order Confidence Overall"), None)

    conf_txt = f" • Order confidence {order_conf:.0f}%" if order_conf is not None else ""

    return f"Expected exposure K {avg:.1f}%{conf_txt} • High-K bats {len(high)} • Low-K contact bats {len(low)}"







