def _display_pct_value(v):

    """Return a readable percentage string for K-rate values.

    Handles either decimal rates (0.2383) or already-percent values (23.83).

    """

    try:

        if v is None or (isinstance(v, float) and np.isnan(v)):

            return "—"

        x = float(v)

        if abs(x) <= 1.0:

            x *= 100.0

        return f"{x:.1f}%"

    except Exception:

        return "—"



def _short_lineup_source(row):

    src = str((row or {}).get("Lineup Source") or (row or {}).get("Source") or "").upper()

    ksrc = str((row or {}).get("K Source") or "")

    if "UNDERDOG_SUPPORTED_EXPECTED" in src:

        return "Underdog-supported expected"

    if "CONSENSUS_EXPECTED" in src:

        return "Consensus expected"

    if "FANGRAPHS" in src or "FanGraphs" in ksrc:

        return "FanGraphs roster"

    if "ROTOWIRE_CONFIRMED" in src:

        return "Rotowire confirmed"

    if "ROTOWIRE" in src or "Rotowire" in ksrc:

        return "Rotowire expected"

    if "CONFIRMED" in src:

        return "MLB confirmed"

    if "PROJECTED" in src or "MLB projected" in ksrc:

        return "MLB projected"

    if src:

        return src.replace("_", " ").title()

    return "—"





def normalize_official_kproj_columns(df):

    """Display/export normalization only.



    Keeps the official table projection aligned to the latest stabilized value.

    Does not rebuild the model; it only prevents confusing intermediate columns.

    """

    try:

        if not isinstance(df, pd.DataFrame) or df.empty:

            return df

        d = df.copy()

        official_cols = [

            "Line-Aware Smart Final K Projection",

            "WRS Final K Projection",

            "TPS Final K Projection",

            "K PROJ",

            "TPC True K Projection",

        ]

        def pick_official(row):

            for c in official_cols:

                if c in row.index:

                    v = safe_float(row.get(c), None)

                    if v is not None:

                        return round(float(v), 2)

            v = safe_float(row.get("Final K Projection"), None)

            return round(float(v), 2) if v is not None else row.get("K PROJ")

        if "K PROJ" in d.columns:

            d["Official K PROJ"] = d.apply(pick_official, axis=1)

            d["K PROJ"] = d["Official K PROJ"]

            if "UD/Line" in d.columns:

                d["Official K Edge"] = d.apply(

                    lambda r: None if safe_float(r.get("UD/Line"), None) is None or safe_float(r.get("K PROJ"), None) is None

                    else round(float(safe_float(r.get("K PROJ"), 0)) - float(safe_float(r.get("UD/Line"), 0)), 2),

                    axis=1

                )

        return d

    except Exception:

        return df





