# =============================================================================

# APP95 SHARED FINAL-LAYER UTILITIES

#

# Legacy helpers remain for backward compatibility, but every new/canonical

# path below uses this single implementation.

# =============================================================================

def _safe_num(value, default=float("nan")):

    try:

        result = float(value)

        return result if np.isfinite(result) else default

    except (TypeError, ValueError):

        return default



def _safe_pct(value, default=float("nan")):

    result = _safe_num(value, default)

    if not np.isfinite(result):

        return default

    return result / 100.0 if result > 1.0 else result



def _safe_clip(value, low, high):

    result = _safe_num(value, 0.0)

    return max(float(low), min(float(high), result))



# =============================================================================

# APP89 — COPY/PASTE SLATE USES THE TRUE ACTIVE FINAL K PROJECTION

#

# Fixes a display-only mismatch:

# The old copy/paste builder still read "Line-Aware Smart Final K Projection",

# which could show stale pre-App88 numbers and stale Over/Under directions.

#

# This override uses:

#   APP88 Final K Projection

#   APP88 Final Side

#   current Underdog line

# and falls back safely only when an App88 field is unavailable.

#

# Projection math and Pitching Outs are untouched.

# =============================================================================



def _impl_build_copy_paste_k_slate_02(df, show_pass_notes=False, force_all_players_ou=False):

    try:

        if not isinstance(df, pd.DataFrame) or df.empty:

            return ""



        d = df.copy()



        # Underdog only.

        if "Line Source" in d.columns:

            d = d[d["Line Source"].astype(str).str.upper().eq("UNDERDOG")].copy()



        # Normalize the active line column.

        if "UD/Line" not in d.columns:

            d["UD/Line"] = d.get("Line")

        d = d[~d["UD/Line"].astype(str).str.upper().isin(

            ["NO LINE", "NO_UD_LINE", "", "NAN", "NONE"]

        )].copy()



        # One current/primary row per pitcher.

        d = _owp_one_final_row_per_pitcher(d)



        lines = []

        for matchup, g in d.groupby("Matchup", sort=False):

            block = []



            for _, r in g.iterrows():

                line = safe_float(r.get("UD/Line"), None)



                # TRUE active projection priority.

                proj = safe_float(r.get("APP88 Final K Projection"), None)

                if proj is None:

                    proj = safe_float(r.get("K PROJ"), None)

                if proj is None:

                    proj = safe_float(r.get("Final K Projection"), None)

                if proj is None:

                    proj = safe_float(r.get("Line-Aware Smart Final K Projection"), None)



                # TRUE active side priority.

                side = str(r.get("APP88 Final Side") or "").upper().strip()

                if side not in {"OVER", "UNDER"} and proj is not None and line is not None:

                    side = "OVER" if proj > line else "UNDER"



                if side not in {"OVER", "UNDER"}:

                    if not show_pass_notes:

                        continue

                    symbol = "PASS"

                    edge = None

                else:

                    edge = None if proj is None or line is None else proj - line

                    abs_edge = abs(edge) if edge is not None else 0.0



                    # Match the user's clean slate style.

                    prefix = "O" if side == "OVER" else "U"

                    if abs_edge >= 1.00:

                        symbol = f"🔥 {prefix}"

                    elif abs_edge < 0.65:

                        symbol = f"⚠️ {prefix}"

                    else:

                        symbol = prefix



                ip = safe_float(r.get("IP Floor"), None)

                if ip is None:

                    ip = safe_float(r.get("IP PROJ"), None)

                if ip is None:

                    ip = safe_float(r.get("Projected IP"), None)



                line_txt = "NO LINE" if line is None else f"{line:.1f}"

                proj_txt = "—" if proj is None else f"{proj:.2f}"

                ip_txt = "—" if ip is None else f"{ip:.2f}"



                block.append(

                    f"• {r.get('Pitcher')} — {symbol} {line_txt} — {proj_txt} K — IP {ip_txt}"

                )



            if block:

                lines.append(str(matchup))

                lines.extend(block)

                lines.append("")



        return "\n".join(lines).strip()



    except Exception as e:

        return f"Slate builder unavailable: {e}"





# =============================================================================

# APP95 CANONICAL PUBLIC PIPELINE

#

# The historical wrapper chain is preserved internally for output parity.

# All UI/export consumers below this point use this one public entry point.

# RAW BASE_K is immutable and never reconstructed from a mid-pipeline field.

# Strikeout-line and Pitching-Outs line parsers are not modified here.

# =============================================================================

_APP95_COMPATIBILITY_K_PIPELINE = _k_checkpoint_factory(24)



def _k_stage_25_app95_compatibility_k(df, board):

    """Explicit K enrichment stage 25. Receives the prior DataFrame and returns the enriched DataFrame.



Legacy note: Canonical public K table.



    Runs the existing compatibility pipeline once, then normalizes the final

    output while preserving the immutable RAW BASE_K snapshot."""

    if not isinstance(df, pd.DataFrame) or df.empty:

        return df

    out = df.copy()

    if 'RAW BASE_K' not in out.columns:

        for candidate in ['Pre-App70 K PROJ', 'Original K PROJ', 'K PROJ']:

            if candidate in out.columns:

                out['RAW BASE_K'] = pd.to_numeric(out[candidate], errors='coerce')

                break

    final_col = next((c for c in ['APP88 Final K Projection', 'Line-Aware Smart Final K Projection', 'WRS Final K Projection', 'TPS Final K Projection', 'K PROJ'] if c in out.columns), None)

    if final_col is not None:

        final_values = pd.to_numeric(out[final_col], errors='coerce')

        out['K PROJ'] = final_values

        out['Final K Projection'] = final_values

        out['Official K PROJ'] = final_values

    if 'UD/Line' in out.columns and 'K PROJ' in out.columns:

        live_line = pd.to_numeric(out['UD/Line'], errors='coerce')

        final_k = pd.to_numeric(out['K PROJ'], errors='coerce')

        out['Official K Edge'] = (final_k - live_line).round(2)

    out['Active K Pipeline'] = 'APP95_CANONICAL'

    return out





# One final formatter only. It does not alter K lines, Outs lines, or projections.

def _impl_build_copy_paste_k_slate_03(df, show_pass_notes=False, force_all_players_ou=False):

    try:

        if not isinstance(df, pd.DataFrame) or df.empty:

            return ""



        d = df.copy()

        if "Line Source" in d.columns:

            d = d[d["Line Source"].astype(str).str.upper().eq("UNDERDOG")].copy()



        if "UD/Line" not in d.columns:

            d["UD/Line"] = d.get("Line")

        d["UD/Line"] = pd.to_numeric(d["UD/Line"], errors="coerce")

        d = d[d["UD/Line"].notna()].copy()

        d = _owp_one_final_row_per_pitcher(d)



        projection_col = next(

            (

                c for c in [

                    "APP88 Final K Projection",

                    "K PROJ",

                    "Final K Projection",

                    "Line-Aware Smart Final K Projection",

                ]

                if c in d.columns

            ),

            None,

        )

        if projection_col is None:

            return ""



        output = []

        for matchup, group in d.groupby("Matchup", sort=False):

            block = []

            for _, row in group.iterrows():

                line = _safe_num(row.get("UD/Line"))

                proj = _safe_num(row.get(projection_col))

                if not np.isfinite(line) or not np.isfinite(proj):

                    continue



                side = str(row.get("APP88 Final Side") or "").upper().strip()

                if side not in {"OVER", "UNDER"}:

                    side = "OVER" if proj > line else "UNDER"



                edge = abs(proj - line)

                prefix = "O" if side == "OVER" else "U"

                symbol = (

                    f"🔥 {prefix}"

                    if edge >= 1.00

                    else (f"⚠️ {prefix}" if edge < 0.65 else prefix)

                )



                ip = float("nan")

                for column in ["IP Floor", "IP PROJ", "Projected IP"]:

                    if column in row.index:

                        candidate = _safe_num(row.get(column))

                        if np.isfinite(candidate):

                            ip = candidate

                            break



                ip_text = "—" if not np.isfinite(ip) else f"{ip:.2f}"

                block.append(

                    f"• {row.get('Pitcher')} — {symbol} {line:.1f} — "

                    f"{proj:.2f} K — IP {ip_text}"

                )



            if block:

                output.append(str(matchup))

                output.extend(block)

                output.append("")



        return "\n".join(output).strip()

    except Exception as exc:

        return f"Slate builder unavailable: {exc}"





