                stt = splits[-1].get("stat") or {}

                so = _app97_num(stt.get("strikeOuts"), None)

                bb = _app97_num(stt.get("baseOnBalls"), None)

                hr = _app97_num(stt.get("homeRuns"), None)

                er = _app97_num(stt.get("earnedRuns"), None)

