def _kclean_copy_paste_slate(df, include_thin=False, force_all_players_ou=False):

    try:

        if df is None or not isinstance(df, pd.DataFrame) or df.empty:

            return ""

        d = df.copy()

        # Best-picks keeps the strict Underdog-source gate. The ALL-projections
        # tracker keeps every row with a real numeric UD/Line even when the Beta
        # overlay did not preserve the Line Source label.
        if "Line Source" in d.columns and not force_all_players_ou:

            d = d[d["Line Source"].astype(str).str.upper().eq("UNDERDOG")].copy()

        if d.empty:

            return ""

        if "UD/Line" not in d.columns:

            d["UD/Line"] = d.get("Line")

        d["UD/Line"] = pd.to_numeric(d["UD/Line"], errors="coerce")

        d = d[d["UD/Line"].notna()].copy()

        if "_owp_one_final_row_per_pitcher" in globals():

            d = _owp_one_final_row_per_pitcher(d)



        lines = []

        for matchup, group in d.groupby("Matchup", sort=False):

            block = []

            for _, rr in group.iterrows():

                row = rr.to_dict()

                proj, line = _kclean_final_proj_line(row)

                if not np.isfinite(line) or not np.isfinite(proj):

                    continue

                edge = _kclean_final_edge(row, np.nan)

                if not np.isfinite(edge):

                    edge = proj - line

                side = _kclean_side_label(row)

                if side not in {"OVER", "UNDER"}:

                    continue

                ip = _kclean_num(_kclean_pick(row, ["IP Floor", "IP PROJ", "Projected IP", "IP Projection"], ""), np.nan)

                ip_text = "—" if not np.isfinite(ip) else f"{ip:.2f}"

                probability_key = "P(OVER Today's Line)" if side == "OVER" else "P(UNDER Today's Line)"

                prob = _kclean_num(_kclean_pick(row, [probability_key, "Final Decision Confidence %", "K Sim Current Side Prob %"], np.nan), np.nan)

                if np.isfinite(prob) and prob <= 1:

                    prob *= 100.0

                if not include_thin:

                    probability_ok = np.isfinite(prob) and prob >= float(MERGE_V265_CONFIG.get("play_probability", 0.59)) * 100.0

                    edge_ok = abs(float(edge)) >= float(MERGE_V265_CONFIG.get("track_edge_k", 0.60))

                    if not (probability_ok and edge_ok):

                        continue

                prob_text = "" if not np.isfinite(prob) else f" — {prob:.0f}%"

                block.append(f"• {row.get('Pitcher')} — {side} {line:.1f} — {proj:.2f} K{prob_text} — IP {ip_text}")

            if block:

                lines.append(str(matchup))

                lines.extend(block)

                lines.append("")

        return "\n".join(lines).strip()

    except Exception as e:

        return f"Slate builder unavailable: {e}"





def _kclean_card_decision(row):

    proj, line = _kclean_final_proj_line(row)

    authoritative = str(_kclean_pick(row, ["UB Final Decision", "Final Authoritative Decision"], "") or "").upper()

    side = authoritative if authoritative in {"OVER", "UNDER", "PASS"} else _kclean_side_label(row)

    edge = round(float(proj - line), 2) if np.isfinite(proj) and np.isfinite(line) else _kclean_final_edge(row, np.nan)

    probability_key = "P(OVER Today's Line)" if side == "OVER" else "P(UNDER Today's Line)"

    prob = _kclean_num(_kclean_pick(row, ["UB Final Probability %", probability_key, "Final Decision Confidence %", "K Sim Current Side Prob %", "K Sim True Prob %", "Sim Side %"], ""), np.nan)

    if np.isfinite(prob) and prob <= 1:

        prob *= 100.0

    if side == "PASS":

        tier = "PASS"

    elif side not in {"OVER", "UNDER"}:

        tier = "NO LINE"

    elif np.isfinite(prob) and prob >= 70.0:

        tier = "HIGH"

    elif np.isfinite(prob) and prob >= 60.0:

        tier = "GOOD"

    elif np.isfinite(prob) and prob >= 54.0:

        tier = "LEAN"

    else:

        tier = "CAUTION"

    return side if side in {"OVER", "UNDER", "PASS"} else "NO LINE", edge, prob, tier





def _kcard_split_matchup(matchup):

    try:

        text = str(matchup or "").upper().replace(" VS ", " @ ")

        if "@" in text:

            a, h = [x.strip() for x in text.split("@", 1)]

            return _rw_norm_team_abbr(a), _rw_norm_team_abbr(h)

    except Exception:

        pass

    return "", ""





def _kcard_board_lookup(board):

    lookup = {}

    for p in board or []:

        try:

            nm = str(p.get("pitcher") or p.get("Pitcher") or "").strip()

            if nm:

                lookup[normalize_name(nm)] = p

        except Exception:

            continue

    return lookup





def _kcard_team_logo(abbr):

    try:

        if "_ml_ui_logo" in globals():

            url = _ml_ui_logo(abbr)

            if url:

                return url

        if "ml_team_logo_url" in globals():

            url = ml_team_logo_url(abbr)

            if url:

                return url

    except Exception:

        pass

    tid = _ML_TEAM_IDS.get(str(abbr or "").upper().strip()) if "_ML_TEAM_IDS" in globals() else None

    return f"https://www.mlbstatic.com/team-logos/{tid}.svg" if tid else ""





def _kcard_pitcher_team(row, p):

    for src in [p or {}, row or {}]:

        for key in ["team", "Team", "Pitcher Team", "pitcher_team"]:

            val = str(src.get(key) or "").upper().strip()

            if val:

                return _rw_norm_team_abbr(val)

    away, home = _kcard_split_matchup((row or {}).get("Matchup") or (p or {}).get("matchup"))

    return away





def _kcard_opp_team(row, p):

    for src in [p or {}, row or {}]:

        for key in ["opponent", "Opponent", "Opp", "Opp Team", "opp_team"]:

            val = str(src.get(key) or "").upper().strip()

            if val:

                return _rw_norm_team_abbr(val)

    away, home = _kcard_split_matchup((row or {}).get("Matchup") or (p or {}).get("matchup"))

    team = _kcard_pitcher_team(row, p)

    if away and home and team:

        return home if team == away else away if team == home else home

    return home or away





def _kcard_lineup_rows(row, p):

    rows = []

    try:

        rows = [r for r in ((p or {}).get("lineup_rows") or []) if isinstance(r, dict)]

    except Exception:

        rows = []

    if len(rows) >= 5:

        return rows[:9], str((p or {}).get("lineup_source_detail") or (p or {}).get("lineup_note") or "Saved matchup lineup")



    opp_id = None

    try:

        opp_id = (p or {}).get("opp_team_id") or (row or {}).get("opp_team_id") or (row or {}).get("Opponent Team ID")

        opp_id = int(float(opp_id)) if opp_id not in (None, "", "nan") else None

    except Exception:

        opp_id = None

    opp_abbr = _kcard_opp_team(row, p)

    if not opp_id and "_ML_TEAM_IDS" in globals():

        opp_id = _ML_TEAM_IDS.get(str(opp_abbr or "").upper())

    hand = str(_kclean_pick(row or {}, ["Pitcher Hand", "Hand", "Throws"], (p or {}).get("hand", "")) or "").upper()

    if opp_id and "build_mlb_projected_lineup_rows" in globals():

        try:

            built = build_mlb_projected_lineup_rows(opp_id, pitcher_hand=hand, before_date=None) or []

            if len(built) >= 5:

                return built[:9], f"MLB projected recent lineup ({opp_abbr})"

        except Exception:

            pass

    return [], "Lineup rows not loaded yet"





def _kcard_pct_val(row, keys, default="—"):

    val = _kclean_pick(row, keys, "")

    text = str(_kclean_pct_display(val, blank="")).strip()

    return text if text else str(default)





def _kcard_name_key(value):

    raw = str(value or "").strip()

    if "," in raw:

        last, first = [x.strip() for x in raw.split(",", 1)]

        raw = f"{first} {last}".strip()

    try:

        return normalize_name(raw)

    except Exception:

        return re.sub(r"[^a-z0-9]+", "", raw.lower())





def _kcard_pitch_name_short(value):

    txt = str(value or "").strip()

    aliases = {

        "4-seam fastball": "Four-seam FB",

        "four-seam fastball": "Four-seam FB",

        "sinker": "Sinker",

        "slider": "Slider",

        "sweeper": "Sweeper",

        "cutter": "Cutter",

        "curveball": "Curveball",

        "knuckle curve": "Knuckle Curve",

        "changeup": "Changeup",

        "split-finger": "Splitter",

        "splitter": "Splitter",

    }

    return aliases.get(txt.lower(), txt or "Pitch")





def _kcard_pitch_key(value):

    txt = str(value or "").strip().lower()

    txt = re.sub(r"[^a-z0-9]+", " ", txt).strip()

    aliases = {

        "ff": "four seam fastball",

        "fa": "four seam fastball",

        "fastball": "four seam fastball",

        "4 seam fastball": "four seam fastball",

        "four seamer": "four seam fastball",

        "four seam fb": "four seam fastball",

        "si": "sinker",

        "sink": "sinker",

        "sl": "slider",

        "st": "sweeper",

        "sweeper": "sweeper",

        "fc": "cutter",

        "ct": "cutter",

        "fs": "splitter",

        "split finger": "splitter",

        "splitter": "splitter",

        "ch": "changeup",

        "change": "changeup",

        "cu": "curveball",

        "kc": "knuckle curve",

        "knuckle curve": "knuckle curve",

        "curve": "curveball",

    }

    return aliases.get(txt, txt)





def _kcard_pitch_mix_feed():

    frames = []

    for name in ["pitch_mix_matchups.csv", "pitch-arsenal-stats.csv"]:

        try:

            df, _path = _hadb_read_csv(name) if "_hadb_read_csv" in globals() else (pd.DataFrame(), "")

            if isinstance(df, pd.DataFrame) and not df.empty:

                frames.append(df.copy())

        except Exception:

            pass

    if not frames:

        return pd.DataFrame()

    df = pd.concat(frames, ignore_index=True, sort=False)

    pcol = next((c for c in ["Pitcher", "pitcher", "Player", "player_name", "last_name, first_name", "Name"] if c in df.columns), None)

    if not pcol:

        return pd.DataFrame()

    df["_kc_mix_name"] = df[pcol].map(_kcard_name_key)

    return df





def _kcard_csv_arsenal_rows(key):

    rows = []

    df = _kcard_pitch_mix_feed()

    if isinstance(df, pd.DataFrame) and not df.empty and key:

        d = df[df["_kc_mix_name"].eq(key)].copy()

        if not d.empty:

            def _alias(rr, names, default=np.nan):

                for name in names:

                    if name in rr.index:

                        val = rr.get(name)

                        if val not in (None, "", "—", "-", "nan", "NaN"):

                            return val

                return default

            for _, rr in d.iterrows():

                rows.append({

                    "Pitch": _kcard_pitch_name_short(_alias(rr, ["pitch_name", "pitch_type", "Pitch", "Pitch Type", "pitch"])),

                    "Use": _kclean_num(_alias(rr, ["pitch_usage", "Pitch Usage", "Pitcher Usage %", "Usage %", "use", "Use", "pitch_percent", "usage_percent"]), np.nan),

                    "K%": _kclean_num(_alias(rr, ["k_percent", "K%", "Pitch K%", "K Rate", "strikeout_percent", "strikeouts_percent"]), np.nan),

                    "Whiff%": _kclean_num(_alias(rr, ["whiff_percent", "Whiff%", "Whiff Rate", "Pitcher Whiff%", "Avg Batter Whiff%", "swing_miss_percent"]), np.nan),

                    "Putaway": _kclean_num(_alias(rr, ["put_away", "putaway", "put_away_percent", "PutAway%", "Putaway%", "Putaway", "PutAway"]), np.nan),

                    "Damage": _kclean_num(_alias(rr, ["est_woba", "estimated_woba_using_speedangle", "xwoba", "woba", "SLG", "est_slg", "Hard Hit%", "hard_hit_percent"]), np.nan),

                    "HardHit": _kclean_num(_alias(rr, ["hard_hit_percent", "Hard Hit%", "hard_hit_rate"]), np.nan),

                })

    return rows





def _kcard_arsenal_profile(row, p):

    raw_pitcher = str((row or {}).get("Pitcher") or (p or {}).get("pitcher") or "").strip()

    key = _kcard_name_key(raw_pitcher)

    pitch_rows = [r for r in ((p or {}).get("pitch_type_rows") or []) if isinstance(r, dict)]

    csv_rows = _kcard_csv_arsenal_rows(key)

    rows_by_pitch = {}



    def _merge_pitch_row(src):

        pitch = _kcard_pitch_name_short(src.get("Pitch") or src.get("Pitch Type") or src.get("pitch_name") or src.get("pitch_type"))

        pk = _kcard_pitch_key(pitch)

        if not pk:

            return

        item = rows_by_pitch.setdefault(pk, {"Pitch": pitch})

        if pitch and pitch != "Pitch":

            item["Pitch"] = pitch

        for dst, keys in {

            "Use": ["Use", "Pitcher Usage %", "Usage %", "pitch_usage", "pitch_percent", "usage_percent"],

            "K%": ["K%", "Pitch K%", "K Rate", "k_percent", "strikeout_percent"],

            "Whiff%": ["Whiff%", "Pitcher Whiff%", "Avg Batter Whiff%", "whiff_percent", "Whiff Rate"],

            "Putaway": ["Putaway", "PutAway", "put_away", "putaway", "put_away_percent"],

            "Damage": ["Damage", "SLG", "est_slg", "Hard Hit%", "hard_hit_percent", "xwoba", "est_woba"],

            "HardHit": ["HardHit", "hard_hit_percent", "Hard Hit%", "hard_hit_rate"],

        }.items():

            cur = _kclean_num(item.get(dst), np.nan)

            if np.isfinite(cur):

                continue

            for k in keys:

                val = src.get(k) if isinstance(src, dict) else None

                num = _kclean_num(val, np.nan)

                if np.isfinite(num):

                    item[dst] = num

                    break



    if pitch_rows:

        for r in pitch_rows:

            _merge_pitch_row({

                "Pitch": _kcard_pitch_name_short(r.get("Pitch Type") or r.get("pitch_name") or r.get("pitch_type")),

                "Use": _kclean_num(r.get("Pitcher Usage %") or r.get("Usage %") or r.get("pitch_usage") or r.get("pitch_percent") or r.get("usage_percent"), np.nan),

                "K%": _kclean_num(r.get("Pitch K%") or r.get("K%") or r.get("K Rate") or r.get("k_percent") or r.get("strikeout_percent"), np.nan),

                "Whiff%": _kclean_num(r.get("Pitcher Whiff%") or r.get("Avg Batter Whiff%") or r.get("Whiff%") or r.get("whiff_percent") or r.get("Whiff Rate"), np.nan),

                "Putaway": _kclean_num(r.get("Putaway") or r.get("PutAway") or r.get("put_away") or r.get("putaway") or r.get("put_away_percent"), np.nan),

                "Damage": _kclean_num(r.get("SLG") or r.get("est_slg") or r.get("Hard Hit%") or r.get("hard_hit_percent") or r.get("xwoba") or r.get("est_woba"), np.nan),

            })

    # Overlay richer uploaded CSV stats, but do not let a partial CSV hide

    # lower-usage pitches already present in the board pitch mix.

    for r in csv_rows:

        _merge_pitch_row(r)

    rows = list(rows_by_pitch.values())

    clean = []

    for r in rows:

        use = _kclean_num(r.get("Use"), np.nan)

        if np.isfinite(use) and use <= 1:

            use *= 100.0

        if not np.isfinite(use) or use <= 0:

            continue

        item = dict(r)

        item["Use"] = use

        clean.append(item)

    clean = sorted(clean, key=lambda x: _kclean_num(x.get("Use"), 0), reverse=True)[:6]



    summary_match_k = _kclean_num(_kclean_pick(row or {}, [

        "Match K%", "APP100 Match K%", "Pitch Mix Match K%", "Lineup Match K%",

        "Opponent K% vs Pitcher Hand", "APP88 Batter Lineup K%"

    ], np.nan), np.nan)

    summary_putaway = _kclean_num(_kclean_pick(row or {}, [

        "Putaway/Whiff", "PutAway%", "Putaway %", "Putaway", "APP85 PutAway Rate"

    ], np.nan), np.nan)

    if np.isfinite(summary_match_k) and abs(summary_match_k) <= 1:

        summary_match_k *= 100.0

    if np.isfinite(summary_putaway) and abs(summary_putaway) <= 1:

        summary_putaway *= 100.0

    for item in clean:

        if not np.isfinite(_kclean_num(item.get("K%"), np.nan)) and np.isfinite(summary_match_k):

            item["K% Display"] = summary_match_k

            item["K% Display Source"] = "matchup"

        if not np.isfinite(_kclean_num(item.get("Putaway"), np.nan)) and np.isfinite(summary_putaway):

            item["Putaway Display"] = summary_putaway

            item["Putaway Display Source"] = "pitcher"



    top = clean[0] if clean else {}

    weights = [max(0.0, _kclean_num(r.get("Use"), 0.0)) for r in clean]

    wsum = sum(weights) or 1.0

    wk = sum((_kclean_num(r.get("K%"), np.nan) if np.isfinite(_kclean_num(r.get("K%"), np.nan)) else 22.0) * w for r, w in zip(clean, weights)) / wsum if clean else np.nan

    ww = sum((_kclean_num(r.get("Whiff%"), np.nan) if np.isfinite(_kclean_num(r.get("Whiff%"), np.nan)) else 24.0) * w for r, w in zip(clean, weights)) / wsum if clean else np.nan

    damage_vals = [_kclean_num(r.get("Damage"), np.nan) for r in clean]

    damage_vals = [v for v in damage_vals if np.isfinite(v)]

    damage = float(np.mean(damage_vals)) if damage_vals else np.nan

    score = _kclean_num(_kclean_pick(row or {}, ["APP100 Arsenal Score", "APP88 Arsenal Matchup Score", "Pitch Mix Matchup Score"], np.nan), np.nan)

    if np.isfinite(score) and score <= 0 and clean:

        score = np.nan

    if not np.isfinite(score) and clean:

        score = 50.0

        if np.isfinite(wk):

            score += (wk - 22.0) * 1.05

        if np.isfinite(ww):

            score += (ww - 24.0) * 1.15

        if np.isfinite(damage):

            score -= (damage - 0.330) * 45.0 if damage < 2 else (damage - 38.0) * 0.25

        top_use = _kclean_num(top.get("Use"), np.nan)

        if np.isfinite(top_use) and top_use >= 45 and np.isfinite(ww) and ww >= 30:

            score += 6.0

        score = max(1.0, min(99.0, score))

    if not np.isfinite(score):

        grade = "—"

        signal = "Arsenal not loaded"

    elif score >= 78:

        grade, signal = "A+", "Elite K Arsenal"

    elif score >= 66:

        grade, signal = "A", "Positive Arsenal"

    elif score >= 54:

        grade, signal = "B", "Balanced Arsenal"

    elif score >= 44:

        grade, signal = "C", "Mixed Arsenal"

    else:

        grade, signal = "D", "Arsenal Risk"

    return {

        "rows": clean,

        "top_pitch": top.get("Pitch") or _kclean_pick(row or {}, ["APP100 Top Pitch", "Pitch Arsenal Top Pitch Used", "Top Pitch"], ""),

        "top_usage": _kclean_num(top.get("Use"), _kclean_num(_kclean_pick(row or {}, ["APP100 Top Pitch Usage", "Pitch Arsenal Top Usage Used", "Top Pitch Usage"], np.nan), np.nan)),

        "weighted_k": wk,

        "weighted_whiff": ww,

        "score": score,

        "grade": grade,

        "signal": signal,

    }





def _kcard_arsenal_html(profile):

    rows = profile.get("rows") or []

    if not rows:

        return '<div class="kc-empty">Automatic Savant arsenal data did not resolve. The projection uses its neutral fallback and the data gate records the missing source.</div>'

    def _pct(value, digits=0):

        v = _kclean_num(value, np.nan)

        if not np.isfinite(v):

            return "—"

        return f"{v:.{digits}f}%"

    trs = []

    for r in rows[:5]:

        pitch = html.escape(str(r.get("Pitch") or "Pitch"))

        use = _pct(r.get("Use"), 0)

        k_val = r.get("K%") if np.isfinite(_kclean_num(r.get("K%"), np.nan)) else r.get("K% Display")

        put_val = r.get("Putaway") if np.isfinite(_kclean_num(r.get("Putaway"), np.nan)) else r.get("Putaway Display")

        k = _pct(k_val, 0)

        whiff = _pct(r.get("Whiff%"), 0)

        put = _pct(put_val, 0)

        cls = "hi" if _kclean_num(r.get("Whiff%"), 0) >= 30 or _kclean_num(k_val, 0) >= 30 else "lo" if _kclean_num(r.get("Whiff%"), 99) <= 18 else ""

        trs.append(f"<tr><td>{pitch}</td><td>{use}</td><td class='{cls}'>K:{k}</td><td class='{cls}'>W:{whiff}</td><td>{put}</td></tr>")

    return "<table class='kc-arsenal'><thead><tr><th>Pitch</th><th>Use</th><th>K%</th><th>Whiff</th><th>Put</th></tr></thead><tbody>" + "".join(trs) + "</tbody></table>"





def _kcard_batter_pitch_value(rr, names, default=np.nan):

    for name in names:

        try:

            val = (rr or {}).get(name)

        except Exception:

            val = None

        if val not in (None, "", "—", "-", "nan", "NaN"):

            return val

    return default





def _kcard_opponent_pitch_arsenal_profile(row, p, arsenal):

    """Opponent hitters vs the pitcher's actual pitch mix.



    Uses true per-batter pitch-profile rows when the scraper/feed has them.

    If those rows are not present yet, it falls back to the installed Savant

    pitcher pitch-mix rows so the card still has real arsenal context.

    """

    top_pitch = str((arsenal or {}).get("top_pitch") or _kclean_pick(row or {}, ["Pitch Arsenal Top Pitch Used", "Top Pitch", "APP100 Top Pitch"], "") or "")

    top_key = _kcard_pitch_key(top_pitch)

    pitch_weights = {}

    for ar in (arsenal or {}).get("rows", []) or []:

        pk = _kcard_pitch_key(ar.get("Pitch"))

        use = _kclean_num(ar.get("Use"), np.nan)

        if np.isfinite(use) and use > 0:

            pitch_weights[pk] = use



    raw_rows = [r for r in ((p or {}).get("batter_pitch_profile_rows") or []) if isinstance(r, dict)]

    matched = []

    for rr in raw_rows:

        pitch = _kcard_batter_pitch_value(rr, ["Pitch", "Pitch Type", "pitch_name", "pitch_type", "type"], "")

        pk = _kcard_pitch_key(pitch)

        if top_key and pk and pk != top_key:

            continue

        batter = _kcard_batter_pitch_value(rr, ["Batter", "Player", "Name", "batter_name", "player_name"], "")

        pa = _kclean_num(_kcard_batter_pitch_value(rr, ["PA", "pa", "BF", "Pitches", "PC", "pitches"], np.nan), np.nan)

        kval = _kclean_num(_kcard_batter_pitch_value(rr, ["K%", "k_percent", "K Rate", "strikeout_percent", "vs_pitch_k", "K% vs Pitch"], np.nan), np.nan)

        whiff = _kclean_num(_kcard_batter_pitch_value(rr, ["Whiff%", "whiff_percent", "Whiff Rate", "swing_miss_percent", "vs_pitch_whiff"], np.nan), np.nan)

        woba = _kclean_num(_kcard_batter_pitch_value(rr, ["wOBA", "woba", "xwOBA", "xwoba", "est_woba"], np.nan), np.nan)

        if np.isfinite(kval) and abs(kval) <= 1:

            kval *= 100.0

        if np.isfinite(whiff) and abs(whiff) <= 1:

            whiff *= 100.0

        matched.append({

            "Batter": str(batter or ""),

            "Pitch": _kcard_pitch_name_short(pitch or top_pitch),

            "PA": pa,

            "K%": kval,

            "Whiff%": whiff,

            "wOBA": woba,

        })



    if matched:

        vals_k = [_kclean_num(r.get("K%"), np.nan) for r in matched]

        vals_w = [_kclean_num(r.get("Whiff%"), np.nan) for r in matched]

        weights = np.array([max(1.0, _kclean_num(r.get("PA"), 1.0)) for r in matched], dtype=float)

        k_vals = np.array([v for v in vals_k], dtype=float)

        w_vals = np.array([v for v in vals_w], dtype=float)

        k_mask = np.isfinite(k_vals)

        w_mask = np.isfinite(w_vals)

        opp_k = float(np.average(k_vals[k_mask], weights=weights[k_mask])) if k_mask.any() else np.nan

        opp_whiff = float(np.average(w_vals[w_mask], weights=weights[w_mask])) if w_mask.any() else np.nan

        source = "BATTER_VS_TOP_PITCH"

    else:

        # Real pitcher-level Savant pitch-mix fallback. It is not batter-level,

        # but prevents fake dashes and keeps the support read honest.

        rows = (arsenal or {}).get("rows", []) or []

        opp_k = _kclean_num((arsenal or {}).get("weighted_k"), np.nan)

        opp_whiff = _kclean_num((arsenal or {}).get("weighted_whiff"), np.nan)

        matched = [{

            "Batter": "Pitch-mix baseline",

            "Pitch": r.get("Pitch"),

            "PA": _kclean_num(r.get("Use"), np.nan),

            "K%": _kclean_num(r.get("K%"), np.nan),

            "Whiff%": _kclean_num(r.get("Whiff%"), np.nan),

            "wOBA": _kclean_num(r.get("Damage"), np.nan),

        } for r in rows[:5]]

        source = "PITCHER_ARSENAL_BASELINE"



    top_usage = _kclean_num((arsenal or {}).get("top_usage"), np.nan)

    score = 0.0

    if np.isfinite(opp_k):

        score += (opp_k - 22.0) * 1.15

    if np.isfinite(opp_whiff):

        score += (opp_whiff - 24.0) * 1.25

    if np.isfinite(top_usage) and top_usage >= 40:

        score *= 1.15

    if not np.isfinite(opp_k) and not np.isfinite(opp_whiff):

        read = "PITCH_ARSENAL_DATA_GAP"

        adj = 0.0

    elif score >= 9:

        read = "TOP_PITCH_UPSIDE"

        adj = 0.12

    elif score >= 4:

        read = "PITCH_MIX_SUPPORT"

        adj = 0.06

    elif score <= -8:

        read = "TOP_PITCH_SUPPRESSION"

        adj = -0.12

    elif score <= -4:

        read = "PITCH_MIX_RISK"

        adj = -0.06

    else:

        read = "PITCH_MIX_NEUTRAL"

        adj = 0.0

    return {

        "rows": matched[:9],

        "source": source,

        "top_pitch": top_pitch,

        "top_usage": top_usage,

        "opp_k": opp_k,

        "opp_whiff": opp_whiff,

        "score": score,

        "read": read,

        "adj": adj,

    }





def _kcard_opponent_pitch_arsenal_html(profile):

    rows = (profile or {}).get("rows") or []

    if not rows:

        return '<div class="kc-empty">Opponent-vs-pitch rows did not resolve automatically. No manual upload is required; the matchup stays neutral until Savant data is available.</div>'

    def _fmt(value, digits=0, suffix="%"):

        v = _kclean_num(value, np.nan)

        if not np.isfinite(v):

            return "—"

        return f"{v:.{digits}f}{suffix}"

    trs = []

    for idx, r in enumerate(rows[:9], start=1):

        batter = html.escape(str(r.get("Batter") or "Pitch-mix baseline"))

        pitch = html.escape(str(r.get("Pitch") or (profile or {}).get("top_pitch") or "Pitch"))

        k = _fmt(r.get("K%"), 0)

        whiff = _fmt(r.get("Whiff%"), 0)

        pa = _fmt(r.get("PA"), 0, "")

        woba_val = _kclean_num(r.get("wOBA"), np.nan)

        woba = "—" if not np.isfinite(woba_val) else f"{woba_val:.3f}" if abs(woba_val) < 2 else f"{woba_val:.0f}%"

        cls = "hi" if _kclean_num(r.get("Whiff%"), 0) >= 30 or _kclean_num(r.get("K%"), 0) >= 28 else "lo" if _kclean_num(r.get("Whiff%"), 99) <= 18 else ""

        trs.append(f"<tr><td>{idx}</td><td>{batter}</td><td>{pitch}</td><td>{pa}</td><td class='{cls}'>K:{k}</td><td class='{cls}'>W:{whiff}</td><td>{woba}</td></tr>")

    return "<table class='kc-lineup'><thead><tr><th>#</th><th>Batter/Profile</th><th>Pitch</th><th>PA/Use</th><th>K%</th><th>Whiff</th><th>wOBA</th></tr></thead><tbody>" + "".join(trs) + "</tbody></table>"





def _kcard_ceiling_value(row, line=np.nan, proj=np.nan, arsenal=None):

    """Display-only K ceiling.



    Prefer the Monte Carlo P90 because it is generated from the same final K mean,

    line, role/volume risk, damage risk, and data-completeness volatility used by

    the probability table. If P90 is missing, use a bounded context fallback from

    workload, whiff, pitch arsenal, and recent K logs.

    """

    raw = _kclean_pick(row or {}, ["K Sim P90", "APP100 K P90", "Ceiling", "Atlas Ceiling K", "K Ceiling", "P90", "80th Percentile K"], np.nan)

    val = _kclean_num(raw, np.nan)

    if np.isfinite(val):

        return val

    txt = str(_kclean_pick(row or {}, ["K Ceiling Read", "Ceiling Read"], "") or "")

    m = re.search(r"(-?\d+(?:\.\d+)?)\s*K?", txt, flags=re.I)

    if m:

        val = _kclean_num(m.group(1), np.nan)

        if np.isfinite(val):

            return val

    proj_v = _kclean_num(proj, np.nan)

    if not np.isfinite(proj_v):

        return np.nan

    line_v = _kclean_num(line, np.nan)

    score = _kclean_num((arsenal or {}).get("score"), np.nan)

    whiff = _kclean_num((arsenal or {}).get("weighted_whiff"), np.nan)

    if not np.isfinite(whiff):

        whiff = _kclean_num(_kclean_pick(row or {}, ["Whiff%", "Official Whiff%", "Savant Custom Whiff%", "APP100 Whiff%"], np.nan), np.nan)

    if np.isfinite(whiff) and whiff <= 1:

        whiff *= 100.0

    bf = _kclean_num(_kclean_pick(row or {}, ["APP100 Projected BF", "APP97 Reconciled Expected BF", "Exp BF", "Projected BF", "BF"], np.nan), np.nan)

    kbf = proj_v / bf if np.isfinite(bf) and bf > 0 else np.nan

    last10 = []

    try:

        last10 = _kcard_last10_values(row or {}, {}) if "_kcard_last10_values" in globals() else []

    except Exception:

        last10 = []

    last10_p80 = float(np.percentile(last10, 80)) if len(last10) >= 5 else np.nan

    bump = 1.10

    if np.isfinite(line_v) and line_v >= 6.5:

        bump += 0.40

    if np.isfinite(score) and score >= 66:

        bump += 0.35

    if np.isfinite(whiff) and whiff >= 30:

        bump += 0.30

    if np.isfinite(kbf) and kbf >= 0.25:

        bump += 0.25

    if np.isfinite(bf) and bf >= 23:

        bump += 0.20

    fallback = proj_v + max(0.9, min(2.6, bump))

    if np.isfinite(last10_p80):

        fallback = max(fallback, min(proj_v + 2.8, last10_p80))

    return fallback





def _kcard_last10_values(row, p):

    candidates = []

    for src in [row or {}, p or {}]:

        for key in ["Last 10 Ks", "Last 10 K Results", "Last 10", "recent_ks", "k_log", "Recent Ks"]:

            v = src.get(key) if isinstance(src, dict) else None

            if isinstance(v, (list, tuple)):

                candidates.extend(v)

            elif v not in (None, "", "—"):

                candidates.extend(re.findall(r"\d+(?:\.\d+)?", str(v)))

        if candidates:

            break

    vals = []

    for x in candidates[:10]:

        try:

            vals.append(float(x))

        except Exception:

            pass

    return vals[:10]





def _kcard_last10_html(row, p, line):

    vals = _kcard_last10_values(row, p)

    if not vals:

        return ""

    ln = _kclean_num(line, np.nan)

    avg = float(np.mean(vals)) if vals else np.nan

    bars = []

    maxv = max(max(vals), ln if np.isfinite(ln) else 0, 1)

    for v in vals:

        good = np.isfinite(ln) and v > ln

        h = max(14, min(74, 16 + (v / maxv) * 58))

        bars.append(f"<div class='kc-barcol {'hit' if good else 'miss'}' style='height:{h:.0f}px'><span>{v:g}</span></div>")

    avg_txt = "—" if not np.isfinite(avg) else f"{avg:.1f} avg"

    return f"<div class='kc-section'><div class='kc-section-title'><span>Last 10 starts</span><span class='kc-chip'>{avg_txt} · line {html.escape(str(line))}</span></div><div class='kc-bars'>{''.join(bars)}</div></div>"





def _v265_json_obj(value):

    if isinstance(value, dict):

        return value

    if isinstance(value, str) and value.strip():

        try:

            parsed = json.loads(value)

            return parsed if isinstance(parsed, dict) else {}

        except Exception:

            return {}

    return {}





def _v265_pct_text(value):

    value = _canonical_k_num(value, None)

    if value is None:

        return "—"

    if value <= 1.0:

        value *= 100.0

    return f"{value:.0f}%"





