def _lta_num(value, default=np.nan):

    try:

        if "_kclean_num" in globals():

            return _kclean_num(value, default)

        out = pd.to_numeric(value, errors="coerce")

        return float(out) if np.isfinite(out) else default

    except Exception:

        return default





def _lta_text(value, default=""):

    try:

        if value in (None, "", "—", "-", "nan", "NaN"):

            return default

        return str(value)

    except Exception:

        return default





def _lta_pick(row, keys, default=""):

    try:

        if "_kclean_pick" in globals():

            return _kclean_pick(row or {}, keys, default)

    except Exception:

        pass

    try:

        for key in keys:

            val = (row or {}).get(key)

            if val not in (None, "", "—", "-", "nan", "NaN"):

                return val

    except Exception:

        pass

    return default





def _lta_board_lookup(board):

    out = {}

    try:

        for p in board or []:

            name = str((p or {}).get("pitcher") or (p or {}).get("Pitcher") or "").strip()

            if name:

                out[normalize_name(name)] = p

    except Exception:

        pass

    return out





def _lta_lineup_rows(row, p):

    try:

        rows = _kcard_lineup_rows(row, p) if "_kcard_lineup_rows" in globals() else []

        if rows:

            return rows

    except Exception:

        pass

    for src in [p or {}, row or {}]:

        for key in ["lineup_rows", "Lineup Rows", "confirmed_lineup_rows", "projected_lineup_rows"]:

            val = src.get(key) if isinstance(src, dict) else None

            if isinstance(val, list) and val:

                return val

    return []





def _lta_row_dict(row):

    try:

        if isinstance(row, pd.Series):

            return row.to_dict()

        if isinstance(row, dict):

            return row

        if hasattr(row, "to_dict"):

            d = row.to_dict()

            return d if isinstance(d, dict) else {}

    except Exception:

        pass

    return {}





def _lta_batter_k(row):

    row = _lta_row_dict(row)

    for key in ["Used K%", "K% Used", "Split K%", "K% vs Hand", "K% vs RHP", "K% vs LHP", "Season K%", "K%"]:

        val = _lta_num(row.get(key), np.nan)

        if np.isfinite(val):

            return val * 100.0 if abs(val) <= 1.0 else val

    return np.nan







def _lta_order_weights(n):

    counts = np.array(_expected_pa_counts_by_slot(DEFAULT_BF)[: max(0, min(9, int(n or 0)))], dtype=float)

    if counts.size == 0:

        return counts

    return counts / (counts.mean() or 1.0)





def _lta_lineup_profile(rows):

    vals = []

    hands = []

    sources = []

    hitters = []

    for r in rows[:9]:

        rd = _lta_row_dict(r)

        k = _lta_batter_k(r)

        if np.isfinite(k):

            vals.append(float(k))

        hands.append(_lta_text(rd.get("Hand") or rd.get("Bats"), ""))

        sources.append(_lta_text(rd.get("Lineup Source") or rd.get("K Source"), ""))

        hitters.append(_lta_text(rd.get("Batter") or rd.get("Player") or rd.get("Name"), ""))

    weights = _lta_order_weights(len(vals))

    weighted = float(np.average(vals, weights=weights[:len(vals)])) if vals and weights.size else np.nan

    top4 = float(np.mean(vals[:4])) if len(vals) >= 4 else (float(np.mean(vals)) if vals else np.nan)

    return {

        "count": len(rows[:9]),

        "valid_k": len(vals),

        "avg_k": float(np.mean(vals)) if vals else np.nan,

        "weighted_k": weighted,

        "top4_k": top4,

        "high_k": int(sum(v >= 25.0 for v in vals)),

        "low_k": int(sum(v <= 16.0 for v in vals)),

        "top4_high_k": int(sum(v >= 25.0 for v in vals[:4])),

        "hands": "/".join([h for h in hands[:9] if h]),

        "sources": " | ".join([s for s in sources[:3] if s])[:180],

        "hitters": " | ".join([h for h in hitters[:9] if h])[:500],

    }





def _lta_lineup_stage(row, p, profile):

    text = " ".join([

        _lta_text(_lta_pick(row, ["Lineup Status", "APP97 Lineup Status", "Projection Source", "Lineup Source"], "")),

        _lta_text((p or {}).get("lineup_status") if isinstance(p, dict) else ""),

        _lta_text(profile.get("sources"), ""),

    ]).upper()

    if "OFFICIAL" in text or "CONFIRMED" in text or "MLB_OFFICIAL" in text:

        return "CONFIRMED"

    if "ROTOWIRE" in text:

        return "ROTOWIRE_EXPECTED"

    if "PROJECTED" in text or "EXPECTED" in text:

        return "EXPECTED"

    return "FALLBACK"





def _lta_projection_trace(row, profile):

    proj = _lta_num(_lta_pick(row, ["K PROJ", "Projection", "Final K Projection", "Winning File K Projection"], np.nan))

    line = _lta_num(_lta_pick(row, ["UD/Line", "Line", "Strikeout Line"], np.nan))

    bf = _lta_num(_lta_pick(row, ["APP100 Projected BF", "APP97 Reconciled Expected BF", "Exp BF", "Projected BF", "BF"], np.nan))

    ip = _lta_num(_lta_pick(row, ["APP100 Projected IP", "IP", "IP PROJ", "Projected IP"], np.nan))

    ceiling = _lta_num(_lta_pick(row, ["K Sim P90", "APP100 K P90", "Ceiling", "K Ceiling", "P90"], np.nan))

    if not np.isfinite(ceiling):

        try:

            ceiling = _kcard_ceiling_value(row, line, proj, None) if "_kcard_ceiling_value" in globals() else np.nan

        except Exception:

            ceiling = np.nan

    opp_k = _lta_num(_lta_pick(row, [

        "Opponent K% vs Pitcher Hand", "Opp K%", "APP100 Opp K%", "APP97 Opponent K Environment",

        "APP88 Batter Lineup K%", "Confirmed Lineup K%"

    ], np.nan))

    if np.isfinite(opp_k) and abs(opp_k) <= 1.0:

        opp_k *= 100.0

    weighted_k = _lta_num(profile.get("weighted_k"), np.nan)

    delta = opp_k - weighted_k if np.isfinite(opp_k) and np.isfinite(weighted_k) else np.nan

    edge = proj - line if np.isfinite(proj) and np.isfinite(line) else np.nan

    kbf = proj / bf if np.isfinite(proj) and np.isfinite(bf) and bf > 0 else np.nan

    whiff = _lta_num(_lta_pick(row, ["Whiff%", "Official Whiff%", "statcast_whiff"], np.nan))

    if np.isfinite(whiff) and abs(whiff) <= 1.0:

        whiff *= 100.0

    if not np.isfinite(delta):

        materiality = "NO_LINEUP_K_TRACE"

    elif abs(delta) >= 2.0:

        materiality = "MATERIAL_K_ENV_GAP"

    elif abs(delta) >= 1.0:

        materiality = "SMALL_K_ENV_GAP"

    else:

        materiality = "K_ENV_ALIGNED"

    if not np.isfinite(edge):

        thin_gate = "NO_LINE"

    elif abs(edge) < 0.35:

        thin_gate = "PASS_THIN_EDGE"

    elif abs(edge) < 0.55:

        thin_gate = "TRACK_THIN_EDGE"

    else:

        thin_gate = "EDGE_CLEAR"

    ceiling_gap = ceiling - proj if np.isfinite(ceiling) and np.isfinite(proj) else np.nan

    if np.isfinite(ceiling_gap) and ceiling_gap >= 2.0 and np.isfinite(weighted_k) and weighted_k >= 22.0 and np.isfinite(bf) and bf >= 21.5 and np.isfinite(whiff) and whiff >= 24.0:

        upside = "UPSIDE_READY_TRACK"

    elif np.isfinite(ceiling_gap) and ceiling_gap >= 2.0:

        upside = "CEILING_DISPLAY_ONLY"

    else:

        upside = "CENTER_RANGE"

    return {

        "proj": proj,

        "line": line,

        "bf": bf,

        "ip": ip,

        "bf_low": round(bf * 0.84, 1) if np.isfinite(bf) else np.nan,

        "bf_high": round(bf * 1.12, 1) if np.isfinite(bf) else np.nan,

        "ip_low": round(ip * 0.84, 2) if np.isfinite(ip) else np.nan,

        "ip_high": round(ip * 1.12, 2) if np.isfinite(ip) else np.nan,

        "opp_k": opp_k,

        "delta": delta,

        "edge": edge,

        "kbf": kbf,

        "ceiling": ceiling,

        "ceiling_gap": ceiling_gap,

        "materiality": materiality,

        "thin_gate": thin_gate,

        "upside": upside,

        "formula": f"K={proj:.2f} = BF {bf:.1f} x K/BF {kbf:.3f}" if np.isfinite(proj) and np.isfinite(bf) and np.isfinite(kbf) else "K=BF x K/BF needs BF/proj",

    }





def _lta_pitch_arsenal_matchup(row, p):

    try:

        arsenal = _kcard_arsenal_profile(row or {}, p or {}) if "_kcard_arsenal_profile" in globals() else {}

        prof = _kcard_opponent_pitch_arsenal_profile(row or {}, p or {}, arsenal) if "_kcard_opponent_pitch_arsenal_profile" in globals() else {}

        return {

            "Pitch Arsenal Matchup Read": _lta_text(prof.get("read"), "PITCH_MIX_NEUTRAL"),

            "Pitch Arsenal Support Adj": round(_lta_num(prof.get("adj"), 0.0), 2),

            "Pitch Arsenal Top Pitch": _lta_text(prof.get("top_pitch"), _lta_pick(row or {}, ["APP100 Top Pitch", "Pitch Arsenal Top Pitch Used", "Top Pitch"], "")),

            "Pitch Arsenal Top Usage": round(_lta_num(prof.get("top_usage"), np.nan), 1) if np.isfinite(_lta_num(prof.get("top_usage"), np.nan)) else np.nan,

            "Pitch Arsenal Opp K%": round(_lta_num(prof.get("opp_k"), np.nan), 1) if np.isfinite(_lta_num(prof.get("opp_k"), np.nan)) else np.nan,

            "Pitch Arsenal Opp Whiff%": round(_lta_num(prof.get("opp_whiff"), np.nan), 1) if np.isfinite(_lta_num(prof.get("opp_whiff"), np.nan)) else np.nan,

            "Pitch Arsenal Matchup Source": _lta_text(prof.get("source"), ""),

        }

    except Exception:

        return {

            "Pitch Arsenal Matchup Read": "PITCH_MIX_TRACE_ERROR",

            "Pitch Arsenal Support Adj": 0.0,

            "Pitch Arsenal Top Pitch": _lta_pick(row or {}, ["APP100 Top Pitch", "Pitch Arsenal Top Pitch Used", "Top Pitch"], ""),

            "Pitch Arsenal Top Usage": np.nan,

            "Pitch Arsenal Opp K%": np.nan,

            "Pitch Arsenal Opp Whiff%": np.nan,

            "Pitch Arsenal Matchup Source": "",

        }





def _tka_quality_adjustments(row, trace):

    """Support-only center calibration. This never rewrites K PROJ.



    The adjustment is intentionally small and bounded because the existing board

    has winning pockets. It only answers: if we were auditing a true center,

    which component is likely pulling low/high?

    """

    proj = _lta_num(trace.get("proj"), np.nan)

    line = _lta_num(trace.get("line"), np.nan)

    bf = _lta_num(trace.get("bf"), np.nan)

    kbf = _lta_num(trace.get("kbf"), np.nan)

    weighted_k = _lta_num(row.get("Lineup Trace Weighted K%") if isinstance(row, dict) else np.nan, np.nan)

    opp_k = _lta_num(trace.get("opp_k"), np.nan)

    whiff = _lta_num(_lta_pick(row, ["Whiff%", "Official Whiff%", "Savant Custom Whiff%", "APP100 Whiff%"], np.nan), np.nan)

    if np.isfinite(whiff) and whiff <= 1:

        whiff *= 100.0

    pitch_k = _lta_num(_lta_pick(row, ["APP100 Pitcher K%", "Pitcher K%", "Official Pitcher K%", "Savant Custom K%"], np.nan), np.nan)

    if np.isfinite(pitch_k) and pitch_k <= 1:

        pitch_k *= 100.0

    match_k = _lta_num(_lta_pick(row, ["Match K%", "APP100 Match K%", "Pitch Mix Match K%", "Lineup Match K%"], np.nan), np.nan)

    if np.isfinite(match_k) and match_k <= 1:

        match_k *= 100.0

    recent = str(_lta_pick(row, ["APP100 Recent Skill", "Recent Skill", "Skill"], "") or "").upper()

    workload = str(_lta_pick(row, ["APP100 BF Coverage", "BF Gate", "Workload Gate"], "") or "").upper()

    stage = str(row.get("Lineup Trace Stage") or "").upper() if isinstance(row, dict) else ""

    ceiling_gap = _lta_num(trace.get("ceiling_gap"), np.nan)

    edge = _lta_num(trace.get("edge"), np.nan)

    adj = 0.0

    notes = []



    if stage == "CONFIRMED" and np.isfinite(weighted_k) and np.isfinite(opp_k):

        gap = weighted_k - opp_k

        if abs(gap) >= 1.0 and np.isfinite(bf):

            # 1 percentage point of lineup K environment over 22 BF is about 0.22 K;

            # only let a minority of that move the support read until backtested.

            move = max(-0.22, min(0.22, gap * bf / 100.0 * 0.38))

            adj += move

            notes.append(f"confirmed weighted lineup gap {gap:+.1f}% -> {move:+.2f}K")



    if "CAUTION" in recent and np.isfinite(match_k) and np.isfinite(pitch_k) and np.isfinite(weighted_k):

        if match_k >= pitch_k + 2.0 and weighted_k >= 21.5:

            adj += 0.12

            notes.append("recent-skill caution softened by matchup support +0.12K")

        elif match_k <= pitch_k - 2.0 and weighted_k <= 20.0:

            adj -= 0.10

            notes.append("recent-skill caution reinforced by weak matchup -0.10K")



    if np.isfinite(ceiling_gap) and ceiling_gap >= 2.0:

        upside_ready = (

            np.isfinite(weighted_k) and weighted_k >= 22.0

            and np.isfinite(whiff) and whiff >= 24.0

            and np.isfinite(bf) and bf >= 20.5

            and "LOW" not in workload

        )

        if upside_ready:

            adj += 0.15

            notes.append("conditional ceiling bridge +0.15K")

        else:

            notes.append("ceiling gap display-only")



    if np.isfinite(edge) and abs(edge) < 0.35:

        notes.append("thin edge: decision should stay pass/track")

    if "LOW" in workload:

        adj -= 0.08

        notes.append("low-BF workload drag -0.08K")

    pa_adj = _lta_num(row.get("Pitch Arsenal Support Adj") if isinstance(row, dict) else np.nan, np.nan)

    pa_read = str(row.get("Pitch Arsenal Matchup Read") or "") if isinstance(row, dict) else ""

    if np.isfinite(pa_adj) and abs(pa_adj) > 0:

        adj += pa_adj

        notes.append(f"{pa_read.lower()} {pa_adj:+.2f}K")



    adj = max(-0.35, min(0.35, adj))

    advisory = proj + adj if np.isfinite(proj) else np.nan

    if not notes:

        notes.append("no support-only center adjustment")

    return {

        "True K Advisor Projection": round(advisory, 2) if np.isfinite(advisory) else np.nan,

        "True K Advisor Adj": round(adj, 2),

        "True K Advisor Read": "; ".join(notes),

        "True K Advisor Version": TRUE_K_ADVISOR_VERSION,

    }





def _lineup_trace_apply(df, board=None):

    if not isinstance(df, pd.DataFrame) or df.empty:

        return df

    out = df.copy()

    lookup = _lta_board_lookup(board)

    rows_out = []

    for _, sr in out.iterrows():

        r = sr.to_dict()

        name = _lta_text(_lta_pick(r, ["Pitcher", "pitcher"], ""))

        p = lookup.get(normalize_name(name), {})

        lineup_rows = _lta_lineup_rows(r, p)

        prof = _lta_lineup_profile(lineup_rows)

        stage = _lta_lineup_stage(r, p, prof)

        trace = _lta_projection_trace(r, prof)

        stale = ""

        src_u = str(prof.get("sources") or "").upper()

        if stage == "CONFIRMED" and ("PROJECTED" in src_u or "EXPECTED" in src_u) and "OFFICIAL" not in src_u and "CONFIRMED" not in src_u:

            stale = "STALE_EXPECTED_CHECK"

        trace_row = {

            "Lineup Trace Stage": stage,

            "Lineup Trace Count": prof.get("count", 0),

            "Lineup Trace Valid K": prof.get("valid_k", 0),

            "Lineup Trace Avg K%": round(prof.get("avg_k"), 1) if np.isfinite(_lta_num(prof.get("avg_k"), np.nan)) else np.nan,

            "Lineup Trace Weighted K%": round(prof.get("weighted_k"), 1) if np.isfinite(_lta_num(prof.get("weighted_k"), np.nan)) else np.nan,

            "Lineup Trace Top4 K%": round(prof.get("top4_k"), 1) if np.isfinite(_lta_num(prof.get("top4_k"), np.nan)) else np.nan,

            "Lineup Trace High-K": prof.get("high_k", 0),

            "Lineup Trace Low-K": prof.get("low_k", 0),

            "Lineup Trace Top4 High-K": prof.get("top4_high_k", 0),

            "Lineup Trace Opp K%": round(trace.get("opp_k"), 1) if np.isfinite(_lta_num(trace.get("opp_k"), np.nan)) else np.nan,

            "Lineup Trace Opp-vs-Weighted Delta": round(trace.get("delta"), 2) if np.isfinite(_lta_num(trace.get("delta"), np.nan)) else np.nan,

            "Lineup Trace Materiality": trace.get("materiality", ""),

            "Lineup Trace Stale Expected Flag": stale,

            "Lineup Trace Thin Edge Gate": trace.get("thin_gate", ""),

            "Lineup Trace K/BF": round(trace.get("kbf"), 3) if np.isfinite(_lta_num(trace.get("kbf"), np.nan)) else np.nan,

            "Lineup Trace Projected BF": round(trace.get("bf"), 1) if np.isfinite(_lta_num(trace.get("bf"), np.nan)) else np.nan,

            "Lineup Trace BF Low": trace.get("bf_low", np.nan),

            "Lineup Trace BF High": trace.get("bf_high", np.nan),

            "Lineup Trace IP Low": trace.get("ip_low", np.nan),

            "Lineup Trace IP High": trace.get("ip_high", np.nan),

            "Lineup Trace Ceiling": round(trace.get("ceiling"), 1) if np.isfinite(_lta_num(trace.get("ceiling"), np.nan)) else np.nan,

            "Lineup Trace Ceiling Gap": round(trace.get("ceiling_gap"), 2) if np.isfinite(_lta_num(trace.get("ceiling_gap"), np.nan)) else np.nan,

            "Lineup Trace Upside Watch": trace.get("upside", ""),

            "Lineup Trace Formula": trace.get("formula", ""),

            "Lineup Trace Hitters": prof.get("hitters", ""),

            "Lineup Trace Version": LINEUP_TRACE_AUDIT_VERSION,

        }

        trace_row.update(_lta_pitch_arsenal_matchup(r, p))

        advisor_input = dict(r)

        advisor_input.update(trace_row)

        trace_row.update(_tka_quality_adjustments(advisor_input, trace))

        rows_out.append(trace_row)

    trace_df = pd.DataFrame(rows_out, index=out.index)

    for col in trace_df.columns:

        out[col] = trace_df[col]

    return out





_LINEUP_TRACE_PREV_BUILD_KPROJ_TABLE = _k_checkpoint_factory(45)





def _k_stage_46_lineup_trace(df, board):

    """Explicit K enrichment stage 46. Receives the prior DataFrame and returns the enriched DataFrame."""

    base = df if True else pd.DataFrame()

    return _lineup_trace_apply(base, board)





# =============================================================================

# ELITE ACE CLEAR-LINE GATE

#

# Runs after the support/trace layers. This is intentionally strict: it only lets

# the center projection clear a very high line when the pitcher skill, opponent

# split, whiff profile, workload, ceiling, and slip brain all agree. It protects

# normal unders by requiring multiple independent upside signals.

# =============================================================================

ELITE_ACE_CLEAR_LINE_VERSION = "ELITE_ACE_CLEAR_LINE_GATE_2026_07_29_CAP38"





def _eacl_num(row, keys, default=np.nan):

    for key in keys:

        if key in row:

            raw = row.get(key)

            val = pd.to_numeric(pd.Series([raw]), errors="coerce").iloc[0]

            if not np.isfinite(val) and raw is not None and not pd.isna(raw):

                txt = str(raw).strip().upper().replace("%", "").replace("K", "")

                cleaned = "".join(ch if (ch.isdigit() or ch in ".-") else " " for ch in txt).split()

                if cleaned:

                    val = pd.to_numeric(pd.Series([cleaned[0]]), errors="coerce").iloc[0]

            if np.isfinite(val):

                return float(val)

    return default





def _eacl_text(row, keys, default=""):

    for key in keys:

        val = row.get(key)

        if val is not None and not pd.isna(val):

            txt = str(val).strip()

            if txt:

                return txt

    return default





def _eacl_decision(proj, line):

    if not np.isfinite(proj) or not np.isfinite(line):

        return "PASS"

    edge = proj - line

    if abs(edge) < 0.15:

        return "PASS"

    side = "OVER" if edge > 0 else "UNDER"

    if abs(edge) >= 1.00:

        return f"🔥 {side}"

    if abs(edge) >= 0.55:

        return f"⚠️ {side} LEAN"

    return f"TRACK {side}"





def _eacl_apply(df):

    if df is None or not isinstance(df, pd.DataFrame) or df.empty:

        return df

    out = df.copy()

    final_cols = [

        "K PROJ", "Final K Projection", "Official K PROJ",

        "Matchup Intelligence Final K Projection", "Line-Aware Smart Final K Projection",

        "Winning File K Projection", "APP97 True K Projection", "APP100 Projected Strikeouts",

    ]

    edge_cols = [

        "Edge", "Edge Gap", "Official K Edge", "Final K Edge", "Line-Aware Smart Edge",

        "Winning File K Edge",

    ]

    for idx, sr in out.iterrows():

        row = sr.to_dict()

        proj = _eacl_num(row, [

            "K PROJ", "Matchup Intelligence Final K Projection", "Winning File K Projection",

            "Final K Projection", "Official K PROJ", "APP97 True K Projection",

        ])

        line = _eacl_num(row, ["UD/Line", "Line", "Strikeout Line"])

        pitcher_k = _eacl_num(row, [

            "APP97 Live Pitcher K%", "APP100 Pitcher K%", "Official Savant K%",

            "APP97 Raw MLB Season Pitcher K%", "Pitcher K%",

        ])

        opp_k = _eacl_num(row, [

            "Opponent K% vs Pitcher Hand", "Lineup Trace Opp K%", "Opp K% vs Pitcher Hand",

            "Opp K%", "Opponent K%",

        ])

        whiff = _eacl_num(row, [

            "Whiff%", "Official Savant Whiff%", "Savant Custom Whiff%", "APP100 Whiff%",

        ])

        bf = _eacl_num(row, [

            "Lineup Trace Projected BF", "APP97 Reconciled Expected BF", "APP100 Projected BF",

            "Exp BF", "Projected BF", "BF",

        ])

        ceiling = _eacl_num(row, ["K Ceiling Read", "Lineup Trace Ceiling", "Ceiling", "K Ceiling"])

        app98 = _eacl_num(row, ["APP98 Loss Target Projection"])

        slip_score = _eacl_num(row, ["K Slip Brain Score"])

        bf_gate = _eacl_text(row, ["APP100 BF Coverage", "BF Gate", "Projection Data Gate"]).upper()

        skill = _eacl_text(row, ["APP100 Recent Skill", "Skill", "Projection Data Cautions"]).upper()



        reason = "NO_CLEAR_LINE"

        move = 0.0

        new_proj = proj

        role_limited = any(token in (bf_gate + " " + skill) for token in ["LOW_BF", "ROLE_LIMIT", "OPENER", "BULK", "LIMIT"])

        elite_clear = bool(

            np.isfinite(proj) and np.isfinite(line) and line >= 7.5 and proj < line

            and np.isfinite(pitcher_k) and pitcher_k >= 30.0

            and np.isfinite(opp_k) and opp_k >= 24.0

            and np.isfinite(whiff) and whiff >= 30.0

            and np.isfinite(bf) and bf >= 22.0

            and np.isfinite(ceiling) and ceiling >= line + 2.25

            and np.isfinite(slip_score) and slip_score >= 92.0

            and not role_limited

        )

        if elite_clear:

            # Use the existing ceiling only as an upside distribution clue. Cap the

            # final clear just above the line so this does not become a blind ceiling chase.

            ceiling_bridge = proj + ((ceiling - proj) * 0.38)

            support_bridge = max(app98 if np.isfinite(app98) else proj, ceiling_bridge)

            clear_target = min(line + 0.38, support_bridge)

            if clear_target > proj + 0.10:

                new_proj = round(clear_target, 2)

                move = new_proj - proj

                reason = (

                    f"ELITE_CLEAR_LINE +{move:.2f}; pitcherK {pitcher_k:.1f}, oppK {opp_k:.1f}, "

                    f"whiff {whiff:.1f}, BF {bf:.1f}, ceiling {ceiling:.1f}, slip {slip_score:.0f}"

                )



        out.at[idx, "Elite Ace Clear-Line Pre Projection"] = round(proj, 2) if np.isfinite(proj) else np.nan

        out.at[idx, "Elite Ace Clear-Line Projection"] = round(new_proj, 2) if np.isfinite(new_proj) else np.nan

        out.at[idx, "Elite Ace Clear-Line Move"] = round(move, 3)

        out.at[idx, "Elite Ace Clear-Line Reason"] = reason

        out.at[idx, "Elite Ace Clear-Line Version"] = ELITE_ACE_CLEAR_LINE_VERSION

        if np.isfinite(new_proj) and np.isfinite(proj) and abs(new_proj - proj) >= 0.005:

            for col in final_cols:

                if col in out.columns:

                    out.at[idx, col] = new_proj

            if np.isfinite(line):

                edge = round(new_proj - line, 2)

                out.at[idx, "Elite Ace Clear-Line Edge"] = edge

                for col in edge_cols:

                    if col in out.columns:

                        out.at[idx, col] = edge

                decision = _eacl_decision(new_proj, line)

                side = "OVER" if edge > 0 else "UNDER" if edge < 0 else "PUSH"

                for col in [

                    "Decision", "Final Decision", "Model Lean", "Main Engine Action",

                    "Line-Aware Smart Decision", "Winning File K Decision",

                    "APP98 Loss Target Decision",

                ]:

                    if col in out.columns:

                        out.at[idx, col] = decision

                for col in [

                    "Elite Ace Clear-Line Side", "Winning File K Side", "APP97 Final Side",

                    "APP88 Final Side", "APP98 Loss Target Side", "Slip Side",

                    "Model Side", "Side", "Pick Side",

                ]:

                    if col in out.columns or col == "Elite Ace Clear-Line Side":

                        out.at[idx, col] = side

                out.at[idx, "Elite Ace Clear-Line Decision"] = decision

    return out





_EACL_PREV_BUILD_KPROJ_TABLE = _k_checkpoint_factory(46)





def _k_stage_47_eacl(df, board):

    """Explicit K enrichment stage 47. Receives the prior DataFrame and returns the enriched DataFrame."""

    base = df if True else pd.DataFrame()

    return _eacl_apply(base)





# ============================================================

# MATCHUP INTELLIGENCE FINAL SYNC 38

# Late projection/side sync. Older helper layers can still build

# support columns, but this owns the final displayed K side.

# ============================================================

def _mifs_num(v, default=np.nan):

    try:

        if v is None:

            return default

        if isinstance(v, (int, float, np.integer, np.floating)):

            val = float(v)

            return val if np.isfinite(val) else default

        s = str(v).strip().replace("−", "-").replace("–", "-").replace("—", "-")

        s = s.replace("%", "").replace("K", "").replace("k", "").replace(",", "")

        if s in ("", "-", "None", "nan", "NaN"):

            return default

        try:

            val = float(s)

            return val if np.isfinite(val) else default

        except Exception:

            import re as _mifs_re

            m = _mifs_re.search(r"-?\d+(?:\.\d+)?", s)

            if m:

                val = float(m.group(0))

                return val if np.isfinite(val) else default

    except Exception:

        pass

    return default





def _mifs_pick(row, keys, default=np.nan):

    try:

        if row is None:

            return default

        if hasattr(row, "index"):

            cmap = {str(c).strip().lower(): c for c in row.index}

            for key in keys:

                col = cmap.get(str(key).strip().lower())

                if col is not None:

                    val = row.get(col, default)

                    if val is not None and str(val).strip() not in ("", "-", "—", "nan", "None"):

                        return val

        elif isinstance(row, dict):

            cmap = {str(c).strip().lower(): c for c in row.keys()}

            for key in keys:

                col = cmap.get(str(key).strip().lower())

                if col is not None:

                    val = row.get(col, default)

                    if val is not None and str(val).strip() not in ("", "-", "—", "nan", "None"):

                        return val

    except Exception:

        pass

    return default





def _mifs_cols(df, candidates):

    lower = {str(c).strip().lower(): c for c in getattr(df, "columns", [])}

    out = []

    for key in candidates:

        col = lower.get(str(key).strip().lower())

        if col is not None and col not in out:

            out.append(col)

    return out





def _mifs_first_num(row, keys, default=np.nan):

    for key in keys:

        val = _mifs_num(_mifs_pick(row, [key], np.nan), np.nan)

        if np.isfinite(val):

            return val

    return default





def _mifs_text(row, keys, default=""):

    val = _mifs_pick(row, keys, default)

    if val is None:

        return default

    return str(val)





def _mifs_apply(df):

    try:

        if df is None or not isinstance(df, pd.DataFrame) or df.empty:

            return df

        out = df.copy()

        proj_keys = [

            "K PROJ", "Final K", "Final K Projection", "PROJ K", "Projected K",

            "Projection", "Matchup Intelligence Final K Projection",

            "Line-Aware Smart Final K Projection", "APP97 Current K",

            "APP100 Projected Strikeouts", "APP88 Final K",

            "APP98 Loss Target Projection", "Official K PROJ",

            "Official Projection", "Official K Projection", "Current Projection",

            "Winning File K Projection", "Legacy Projection",

        ]

        proj_write_keys = [

            "K PROJ", "Final K", "Final K Projection", "PROJ K", "Projected K",

            "Projection", "Matchup Intelligence Final K Projection",

            "Line-Aware Smart Final K Projection", "APP97 Current K",

            "APP100 Projected Strikeouts", "APP88 Final K",

            "Official K PROJ", "Official Projection", "Official K Projection",

            "Current Projection",

        ]

        line_keys = ["Line", "UD/Line", "K Line", "Strikeout Line", "Line K", "Prop Line", "Book Line"]

        side_keys = [

            "Side", "Projection Side", "Model Side", "Pick Side", "Slip Side",

            "APP97 Final Side", "APP88 Final Side", "APP98 Loss Target Side",

            "Elite Ace Clear-Line Side", "K Side", "K Pick Side", "Final K Side",

            "Official Side", "Official K Side", "Line-Aware Smart Side",

            "Matchup Intelligence Side", "K Model Side", "Model K Side",

            "Projected Side",

        ]

        decision_keys = [

            "Decision", "Final Decision", "Model Lean", "Main Engine Action",

            "Line-Aware Smart Decision", "APP98 Loss Target Decision",

            "K Decision", "Official Decision", "Model Pick", "Pick",

            "Elite Ace Clear-Line Decision", "K Pick", "K Model Pick",

            "Selector", "Official Selector", "Final Pick", "Final K Pick",

            "Slate Pick", "Play", "Action", "Projection Decision",

            "Model Decision",

        ]

        edge_keys = ["Edge", "K Edge", "Model Edge", "Projection Edge", "Final Edge", "Matchup Intelligence Edge"]



        if "K PROJ" not in out.columns:

            out["K PROJ"] = np.nan

        if "Side" not in out.columns:

            out["Side"] = ""

        if "Decision" not in out.columns:

            out["Decision"] = ""

        if "Edge" not in out.columns:

            out["Edge"] = np.nan



        proj_write_cols = _mifs_cols(out, proj_write_keys) or ["K PROJ"]

        side_cols = _mifs_cols(out, side_keys) or ["Side"]

        decision_cols = _mifs_cols(out, decision_keys) or ["Decision"]

        edge_cols = _mifs_cols(out, edge_keys) or ["Edge"]



        for idx, row in out.iterrows():

            line = _mifs_first_num(row, line_keys)

            proj = _mifs_first_num(row, proj_keys)

            if not np.isfinite(line) or not np.isfinite(proj):

                continue



            pitch_k = _mifs_first_num(row, ["Pitcher K%", "Pitch K%", "APP97 Raw MLB Season Pitcher K%", "APP97 Live Pitcher K%", "Savant Custom K%", "Pitcher K% Used", "Official Savant K%", "K%"])

            opp_k = _mifs_first_num(row, ["OPP K%", "Opp K%", "Opponent K% vs Pitcher Hand", "APP97 Opponent K Environment", "APP88 Batter Lineup K%", "Lineup K%"])

            whiff = _mifs_first_num(row, ["Whiff%", "WHIFF", "Savant Custom Whiff%", "Official Savant Whiff%", "Pitcher Whiff%", "APP100 Whiff%"])

            match_k = _mifs_first_num(row, ["Match K%", "Arsenal Match K%", "Pitch Mix Match K%", "APP100 Match K%", "Pitch Arsenal Match K%"])

            opp_whiff = _mifs_first_num(row, ["Opp Whiff%", "Opponent Whiff%", "APP100 Opp Whiff%", "Arsenal Opp Whiff%"])

            put = _mifs_first_num(row, ["PutAway%", "Putaway%", "Putaway Rate", "APP85 PutAway Rate", "PUT"])

            bf = _mifs_first_num(row, ["BF", "Exp BF", "Projected BF", "APP97 Reconciled Expected BF"])

            ip = _mifs_first_num(row, ["IP", "IP PROJ", "Projected IP", "IP Projection"])

            ceiling = _mifs_first_num(row, ["Ceiling", "Ceiling K", "K Ceiling", "APP100 Ceiling", "K Ceiling Projection"])

            quality = _mifs_first_num(row, ["APP100 Projection Quality Score", "Quality", "APP100 Projection Quality"])

            bf_gate = _mifs_text(row, ["APP100 BF Coverage", "BF Gate", "BF GATE"], "").upper()

            skill = _mifs_text(row, ["APP100 Recent Skill", "Skill", "Recent Skill"], "").upper()

            gate = _mifs_text(row, ["Projection Data Gate", "Data Gate", "APP99 Right Wins Gate"], "").upper()

            role = _mifs_text(row, ["Role", "Starter Role", "Pitcher Role", "APP100 Role"], "").upper()



            support = 0

            risk = 0

            if np.isfinite(pitch_k):

                if pitch_k >= 28:

                    support += 2

                elif pitch_k >= 25:

                    support += 1

                elif pitch_k < 18:

                    risk += 2

            if np.isfinite(opp_k):

                if opp_k >= 24.5:

                    support += 2

                elif opp_k >= 22.5:

                    support += 1

                elif opp_k < 20:

                    risk += 1

            if np.isfinite(match_k):

                if match_k >= 27:

                    support += 2

                elif match_k >= 23:

                    support += 1

            if np.isfinite(whiff):

                if whiff >= 30:

                    support += 1

                elif whiff < 18:

                    risk += 1

            if np.isfinite(opp_whiff) and opp_whiff >= 28:

                support += 1

            if np.isfinite(put) and put >= 27:

                support += 1

            if np.isfinite(ceiling) and ceiling - line >= 2:

                support += 1

            if np.isfinite(quality) and quality >= 80:

                support += 1

            if "RECENT_SKILL_SUPPORT" in skill:

                support += 1

            if any(token in gate for token in ("SUCCESS", "GREEN", "PLAYABLE")):

                support += 1



            if (np.isfinite(bf) and bf < 18) or (np.isfinite(ip) and ip < 3.5):

                risk += 4

            elif (np.isfinite(bf) and bf < 21) or (np.isfinite(ip) and ip < 4.5):

                risk += 2

            if any(token in bf_gate for token in ("LOW_BF", "THIN_BF", "SHORT", "OPEN", "BULK")):

                risk += 3

            if any(token in role for token in ("OPEN", "BULK", "RELIEF", "TANDEM")):

                risk += 3

            if "RECENT_SKILL_CAUTION" in skill:

                risk += 1

            if "RED" in gate:

                risk += 3



            final = float(proj)

            cap = 0.38

            edge = final - float(line)

            workload_ok = (not np.isfinite(bf) or bf >= 21) and (not np.isfinite(ip) or ip >= 4.5)

            full_workload_ok = (not np.isfinite(bf) or bf >= 22) and (not np.isfinite(ip) or ip >= 4.8)



            if risk < 5 and support >= 8 and edge < 0 and workload_ok:

                target = float(line) + (0.12 if support >= 10 and full_workload_ok else 0.03)

                final += min(cap, max(0.0, target - final))

            elif risk <= 3 and support >= 6 and -0.70 <= edge < 0 and workload_ok:

                target = float(line) + 0.01

                final += min(0.30, max(0.0, target - final))

            elif risk <= 2 and support >= 9 and edge >= 0 and full_workload_ok:

                final += min(0.18, cap / 2.0)



            edge = final - float(line)

            if 0 < edge <= 0.10 and risk >= 3:

                final = float(line) - 0.02

            elif 0 < edge <= 0.25 and risk >= 5:

                final = float(line) - 0.05



            final = round(float(final), 2)

            edge = round(final - float(line), 2)

            side = "OVER" if edge > 0 else "UNDER" if edge < 0 else "PASS"

            abs_edge = abs(edge)

            if side == "PASS":

                decision = "PASS"

            elif abs_edge >= 0.75 and support >= 6 and risk <= 3:

                decision = f"🔥 {side}"

            elif abs_edge >= 0.30 and risk <= 4:

                decision = side

            else:

                decision = f"⚠️ {side}"



            for col in proj_write_cols:

                if col in out.columns:

                    out.at[idx, col] = final

            for col in edge_cols:

                if col in out.columns:

                    out.at[idx, col] = edge

            for col in side_cols:

                if col in out.columns:

                    out.at[idx, col] = side

            for col in decision_cols:

                if col in out.columns:

                    out.at[idx, col] = decision



            out.at[idx, "Matchup Intelligence Base K"] = round(float(proj), 2)

            out.at[idx, "Matchup Intelligence Final K Projection"] = final

            out.at[idx, "Matchup Intelligence Edge"] = edge

            out.at[idx, "Matchup Intelligence Side"] = side

            out.at[idx, "Matchup Intelligence Decision"] = decision

            out.at[idx, "Matchup Intelligence Support Score"] = support

            out.at[idx, "Matchup Intelligence Risk Score"] = risk

            out.at[idx, "Matchup Intelligence Cap"] = cap

        return out

    except Exception:

        return df





