# =============================================================================

# UNDEFEATED BETA V1.8 — TARGETED LOSS RESCUE

# V1.7 is preserved as the benchmark file. V1.8 changes biological projections only

# through current pregame baseball evidence: workload, confirmed-lineup shape, and a

# small finishing-conversion interaction. No player/team/outcome hardcoding.

# =============================================================================

_ub_workload_distribution_v17_active = _ub_workload_distribution

_ub_lineup_profile_v17_active = _ub_lineup_profile

_ub_component_blend_profile_v17_active = _ub_component_blend_profile

_ub_under_ceiling_risk_v17_active = _ub_under_ceiling_risk

_ub_build_row_v17_active = _ub_build_row





def _ub_workload_distribution(p, row=None):

    """V1.8: verified normal full-start usage becomes the independent workload center.



    The downstream component blend remains the ONLY regularization back toward Merge.

    This avoids the old double-anchor problem while protecting short-role/openers.

    """

    p = p or {}; row = row or {}

    base = dict(_ub_workload_distribution_v17_active(p, row) or {})

    if not base:

        return base

    role = str(base.get("role") or "").upper()

    role_authority = str(base.get("role_authority") or "")

    confirmed_short = role in {"OPENER", "RELIEVER", "LIMITED_STARTER"} and role_authority == "CURRENT_CONFIRMED_ROLE"

    games = _ub_history_games(p)

    full = []

    for g in games[:8]:

        if not isinstance(g, dict):

            continue

        bf = _ub_num(g.get("BF"), None)

        ip = _ub_num(g.get("IP_float"), None)

        pc = _ub_num(g.get("Pitches") if g.get("Pitches") is not None else g.get("pitch_count"), None)

        if bf is None or ip is None:

            continue

        if bf >= float(UB_CONFIG["recent_starter_min_bf"]) and ip >= float(UB_CONFIG["recent_starter_min_ip"]):

            full.append({"bf": float(bf), "ip": float(ip), "pc": pc})



    base["v18_full_starter_sample"] = len(full)

    base["v18_full_starter_available"] = False

    base["v18_full_starter_bf"] = None

    base["v18_full_starter_ip"] = None

    base["v18_full_starter_source"] = "NO_VERIFIED_FULL_STARTS"

    if confirmed_short or not full:

        return base



    if len(full) >= 3:

        recent3_bf = float(np.median([g["bf"] for g in full[:3]]))

        recent5_bf = float(np.median([g["bf"] for g in full[:5]]))

        center = 0.70 * recent3_bf + 0.30 * recent5_bf

        authority = float(UB_CONFIG["v18_full_starter_authority_event3"])

        source = "V18_VERIFIED_FULL_STARTS_3PLUS"

    elif len(full) == 2:

        center = float(np.mean([g["bf"] for g in full[:2]]))

        authority = float(UB_CONFIG["v18_full_starter_authority_event2"])

        source = "V18_VERIFIED_FULL_STARTS_2"

    else:

        center = float(full[0]["bf"])

        authority = float(UB_CONFIG["v18_full_starter_authority_event1"])

        source = "V18_VERIFIED_FULL_START_1"



    # Pitch-count capacity is corroboration inside workload, never a second K family.

    cap_bf = _ub_num(base.get("pitch_capacity_bf"), None)

    if cap_bf is not None and cap_bf > 0 and abs(cap_bf - center) <= 4.5:

        center = 0.85 * center + 0.15 * float(cap_bf)

        source += "+PITCH_CAPACITY_CORROBORATION"



    ratios = [g["ip"] / g["bf"] for g in full if g.get("bf") and g.get("ip")]

    ip_per_bf = float(np.median(ratios)) if ratios else float(_ub_num(base.get("ip_per_bf"), 0.245) or 0.245)

    ip_per_bf = float(clamp(ip_per_bf, 0.16, 0.33))

    merge_bf = float(_ub_num(base.get("merge_bf"), DEFAULT_BF) or DEFAULT_BF)

    gap = float(center - merge_bf)

    min_gap = float(UB_CONFIG["v18_full_starter_min_gap_bf"])



    if abs(gap) >= min_gap:

        vals = [g["bf"] for g in full[:6]]

        spread = float(np.std(vals, ddof=1)) if len(vals) >= 2 else 2.5

        spread = float(clamp(spread, 1.6, float(UB_CONFIG["v18_full_starter_max_spread_bf"])))

        p10 = center - max(3.0, 1.28 * spread)

        p25 = center - max(1.5, 0.67 * spread)

        p75 = center + max(1.5, 0.67 * spread)

        p90 = center + max(3.0, 1.28 * spread)

        base.update({

            "bf_p10": round(float(clamp(p10, 4.0, 31.0)), 2),

            "bf_p25": round(float(clamp(p25, 4.0, 31.0)), 2),

            "bf_p50": round(float(clamp(center, 4.0, 31.0)), 2),

            "bf_p75": round(float(clamp(max(center, p75), center, 32.0)), 2),

            "bf_p90": round(float(clamp(max(p75, p90), p75, 33.0)), 2),

        })

        for bf_key, ip_key in (("bf_p10","ip_p10"),("bf_p25","ip_p25"),("bf_p50","ip_p50"),("bf_p75","ip_p75"),("bf_p90","ip_p90")):

            base[ip_key] = round(float(base[bf_key]) * ip_per_bf, 2)

        base["ip_per_bf"] = round(ip_per_bf, 4)

        base["confidence"] = "HIGH" if len(full) >= 3 else "MEDIUM"

        base["recent_starter_authority"] = True

        mismatch = max(float(_ub_num(base.get("workload_mismatch_score"), 0.0) or 0.0), float(clamp(30.0 + abs(gap) * 15.0, 0.0, 100.0)))

        escape = max(float(_ub_num(base.get("workload_escape_score"), 0.0) or 0.0), float(clamp(45.0 + abs(gap) * 11.0, 0.0, 100.0)))

        base["workload_mismatch_score"] = round(mismatch, 1)

        base["workload_escape_score"] = round(escape, 1)

        reasons = list(base.get("workload_mismatch_reasons") or [])

        reasons.append(f"V1.8 verified full-start BF {center:.1f} vs Merge {merge_bf:.1f}")

        base["workload_mismatch_reasons"] = list(dict.fromkeys(reasons))



        # Backward-compatible authority fields are intentionally updated because the existing

        # coherent component blend reads them. This is not a second blend.

        base["v17_independent_source"] = source

        base["v17_authority_hint"] = authority

        base["v17_independent_available"] = True

        base["v17_gap_bf"] = round(gap, 2)



    base["v18_full_starter_available"] = True

    base["v18_full_starter_bf"] = round(center, 2)

    base["v18_full_starter_ip"] = round(center * ip_per_bf, 2)

    base["v18_full_starter_source"] = source

    base["v18_full_starter_authority"] = round(authority, 3)

    base["note"] = str(base.get("note") or "") + f"; V1.8 full-starter {center:.1f} BF/{center*ip_per_bf:.2f} IP ({source})"

    return base





def _ub_lineup_profile(p, row, expected_bf):

    """V1.8 opponent-K shape: preserve V1.7 batter rates, add order concentration once."""

    out = dict(_ub_lineup_profile_v17_active(p, row, expected_bf) or {})

    rows = list(out.get("rows") or [])

    if not rows:

        out.update({"top3_rate": None, "top5_rate": None, "high_k_25": 0, "high_k_30": 0, "concentration_modifier": 0.0})

        return out

    rates = [float(_ub_num(r.get("rate"), LEAGUE_AVG_K) or LEAGUE_AVG_K) for r in rows[:9]]

    simple = float(np.mean(rates)) if rates else LEAGUE_AVG_K

    top3 = float(np.mean(rates[:3])) if rates[:3] else simple

    top5 = float(np.mean(rates[:5])) if rates[:5] else simple

    high25 = sum(1 for rate in rates if rate >= 0.25)

    high30 = sum(1 for rate in rates if rate >= 0.30)

    low17 = sum(1 for rate in rates if rate <= 0.17)

    weighted_top = 0.60 * top3 + 0.40 * top5

    modifier = (weighted_top - simple) * float(UB_CONFIG["v18_lineup_concentration_shape_weight"])

    # Counts corroborate a real order-shape difference; they do not independently add team K twice.

    if high30 >= 4 and weighted_top >= simple + 0.012:

        modifier += 0.002

    if low17 >= 4 and weighted_top <= simple - 0.012:

        modifier -= 0.002

    cap = float(UB_CONFIG["v18_lineup_concentration_cap_k_rate"])

    modifier = float(clamp(modifier, -cap, cap))



    seq = list(out.get("sequence") or [])

    if seq and abs(modifier) > 1e-12:

        seq = [float(clamp(float(rate) + modifier, 0.04, 0.55)) for rate in seq]

        out["sequence"] = seq

        out["exposure_rate"] = float(np.mean(seq))

    out.update({

        "top3_rate": top3, "top5_rate": top5, "high_k_25": high25, "high_k_30": high30, "low_k_17": low17,

        "concentration_modifier": modifier, "concentration_weighted_top": weighted_top,

    })

    return out





def _ub_v18_conversion_interaction(fixed, workload):

    """Small matchup finishing interaction; all ingredients must agree before it can move K/BF."""

    fixed = fixed or {}; workload = workload or {}

    current = fixed.get("current_state") or {}

    lineup = fixed.get("lineup") or {}

    whiff = _ub_num(current.get("whiff"), None)

    csw = _ub_num(current.get("csw"), None)

    putaway = _ub_num(current.get("putaway"), None)

    exposure = _ub_num(lineup.get("exposure_rate"), LEAGUE_AVG_K) or LEAGUE_AVG_K

    high25 = int(lineup.get("high_k_25") or lineup.get("high_k") or 0)

    bf50 = float(_ub_num(workload.get("bf_p50"), DEFAULT_BF) or DEFAULT_BF)

    swing_strong = bool((whiff is not None and whiff >= 0.285) or (csw is not None and csw >= 0.290))

    put_strong = bool(putaway is not None and putaway >= 0.235)

    lineup_pressure = bool(exposure >= 0.235 and high25 >= 4)

    workload_ok = bool(bf50 >= 19.0)

    value = 0.0; status = "INACTIVE"; reasons = []

    if swing_strong and put_strong and lineup_pressure and workload_ok:

        value = float(UB_CONFIG["v18_conversion_interaction_strong_kbf"])

        status = "STRONG"

        reasons = ["SWING_MISS", "PUTAWAY", "LINEUP_K_PRESSURE", "WORKLOAD"]

        elite = bool(putaway is not None and putaway >= 0.270 and whiff is not None and whiff >= 0.310 and exposure >= 0.245)

        if elite:

            value = float(UB_CONFIG["v18_conversion_interaction_elite_kbf"])

            status = "ELITE"

    value = float(clamp(value, 0.0, float(UB_CONFIG["v18_conversion_interaction_max_kbf"])))

    return {"kbf": value, "status": status, "reasons": reasons}





def _ub_component_blend_profile(merge_projection, fixed, workload, recent, regime, data_quality):

    """V1.8 preserves V1.7 coherent BF/KBF blend and adds one separately-attributed conversion interaction."""

    fixed = dict(fixed or {})

    interaction = _ub_v18_conversion_interaction(fixed, workload)

    bump = float(interaction.get("kbf") or 0.0)

    fixed_for_blend = dict(fixed)

    if bump:

        base_matchup = float(fixed_for_blend.get("matchup_kbf") or fixed_for_blend.get("skill_kbf") or LEAGUE_AVG_K)

        fixed_for_blend["matchup_kbf"] = float(clamp(base_matchup + bump, 0.08, 0.45))

        fixed_for_blend["projection"] = float(fixed_for_blend["matchup_kbf"] * float(workload.get("bf_p50") or DEFAULT_BF))

    comp = dict(_ub_component_blend_profile_v17_active(merge_projection, fixed_for_blend, workload, recent, regime, data_quality) or {})

    kbf_auth = float(comp.get("kbf_authority") or 0.0)

    merge_bf = float(comp.get("merge_bf") or workload.get("merge_bf") or DEFAULT_BF)

    interaction_delta = merge_bf * kbf_auth * bump

    # V1.7 called every post-trend matchup delta "suppression". Reclassify this known V1.8

    # interaction so the attribution ledger still sums exactly.

    if bump and "suppression_delta" in comp:

        comp["suppression_delta"] = float(comp.get("suppression_delta") or 0.0) - interaction_delta

    comp["conversion_interaction_kbf"] = bump

    comp["conversion_interaction_delta"] = interaction_delta

    comp["conversion_interaction_status"] = interaction.get("status")

    comp["conversion_interaction_reasons"] = interaction.get("reasons") or []

    total = sum(float(comp.get(k) or 0.0) for k in [

        "skill_matchup_delta", "pitch_trend_delta", "suppression_delta", "conversion_interaction_delta", "workload_delta", "guard_adjustment"

    ])

    comp["attribution_residual"] = float(comp.get("projection") or merge_projection) - float(merge_projection) - total

    comp["math_status"] = "PASS" if abs(float(comp["attribution_residual"])) <= 1e-6 else "FAIL"

    return comp





def _ub_under_ceiling_risk(line, side, fixed, recent, workload, regime):

    """V1.8 adds a normal-full-starter escape path to the existing P75/P90 guard."""

    out = dict(_ub_under_ceiling_risk_v17_active(line, side, fixed, recent, workload, regime) or {})

    if line is None or str(side).upper() != "UNDER":

        out["full_starter_k"] = None

        return out

    bf_full = _ub_num(workload.get("v18_full_starter_bf"), None)

    if bf_full is None:

        out["full_starter_k"] = None

        return out

    interaction = _ub_v18_conversion_interaction(fixed, workload)

    kbf = float(fixed.get("matchup_kbf") or fixed.get("skill_kbf") or LEAGUE_AVG_K) + float(interaction.get("kbf") or 0.0)

    full_k = float(bf_full) * kbf

    needed = int(math.floor(float(line)) + 1)

    score = float(out.get("score") or 0.0)

    reasons = list(out.get("reasons") or [])

    if full_k >= needed + 0.35:

        score += 24.0; reasons.append(f"verified full-starter path {full_k:.1f} K vs {needed} needed")

    elif full_k >= needed:

        score += 16.0; reasons.append(f"verified full-starter path clears threshold ({full_k:.1f} K)")

    elif full_k >= needed - 0.30:

        score += 8.0; reasons.append(f"verified full-starter path near threshold ({full_k:.1f} K)")

    score = float(clamp(score, 0.0, 100.0))

    support = int(out.get("support_families") or 0)

    status = "VETO" if score >= float(UB_CONFIG["under_ceiling_veto_score"]) and support >= 2 else "WATCH" if score >= float(UB_CONFIG["under_ceiling_watch_score"]) else "CLEAR"

    out.update({"score": round(score,1), "status": status, "reasons": list(dict.fromkeys(reasons)), "full_starter_k": round(full_k,2), "full_starter_bf": round(float(bf_full),2)})

    return out





def _ub_v18_flip_evidence(out):

    """Classify side changes. Never changes the biological projection or side."""

    out = out or {}

    merge_side = str(out.get("Merge Control Side") or "").upper()

    side = str(out.get("Undefeated Beta Side") or "").upper()

    if merge_side not in {"OVER","UNDER"} or side not in {"OVER","UNDER"} or merge_side == side:

        return {"status":"NO_FLIP", "count":0, "reasons":[]}

    direction = 1.0 if side == "OVER" else -1.0

    reasons = []

    merge_kbf = _ub_num(out.get("UB Merge Implied K/BF"), None)

    indep_kbf = _ub_num(out.get("UB Independent Matchup K/BF"), None)

    if merge_kbf is not None and indep_kbf is not None and direction * (indep_kbf - merge_kbf) >= 0.010:

        reasons.append("KBF")

    workload_delta = float(_ub_num(out.get("UB Workload Delta"), 0.0) or 0.0)

    if direction * workload_delta >= 0.18:

        reasons.append("WORKLOAD")

    pitch_delta = float(_ub_num(out.get("UB Pitch Trend Delta"), 0.0) or 0.0)

    if direction * pitch_delta >= 0.10:

        reasons.append("PITCH_TREND")

    line_mod = float(_ub_num(out.get("UB Lineup Concentration Modifier"), 0.0) or 0.0)

    if direction * line_mod >= 0.0025:

        reasons.append("LINEUP_SHAPE")

    interaction = float(_ub_num(out.get("UB Conversion Interaction K/BF"), 0.0) or 0.0)

    if side == "OVER" and interaction >= 0.003:

        reasons.append("FINISHING_INTERACTION")

    if side == "UNDER" and str(out.get("UB Current State") or "") == "DECLINING_CURRENT":

        reasons.append("DECLINING_CURRENT")

    reasons = list(dict.fromkeys(reasons))

    status = "CONFIRMED_FLIP" if len(reasons) >= 3 else "SUPPORTED_FLIP" if len(reasons) >= 2 else "THIN_FLIP"

    return {"status": status, "count": len(reasons), "reasons": reasons}





def _ub_build_row(row, p):

    """V1.8 row wrapper: diagnostics + thin-flip trust guard; raw projection remains formula-driven."""

    out = _ub_build_row_v17_active(row, p)

    if not out:

        return out

    # Recreate only lightweight diagnostics; all biological math was already computed by the wrapped functions.

    workload = _ub_workload_distribution(p or {}, row or {})

    lineup = _ub_lineup_profile(p or {}, row or {}, workload.get("bf_p50") or DEFAULT_BF)

    current = {

        "whiff": _ub_num(out.get("UB Whiff% Used"), None),

        "csw": _ub_num(out.get("UB CSW% Used"), None),

        "putaway": _ub_num(out.get("UB PutAway% Used"), None),

    }

    # Output percentages may be stored as percent values; normalize for interaction diagnostics.

    for key in ("whiff","csw","putaway"):

        if current[key] is not None and current[key] > 1.0:

            current[key] /= 100.0

    interaction = _ub_v18_conversion_interaction({"current_state": current, "lineup": lineup}, workload)

    exact_interaction = _ub_num(out.get("UB Conversion Interaction K/BF"), None)

    if exact_interaction is not None:

        interaction["kbf"] = float(exact_interaction)

        interaction["status"] = out.get("UB Conversion Interaction Status") or interaction.get("status")

    out.update({

        "UB V1.8 Full Starter BF": workload.get("v18_full_starter_bf"),

        "UB V1.8 Full Starter IP": workload.get("v18_full_starter_ip"),

        "UB V1.8 Full Starter Sample": workload.get("v18_full_starter_sample"),

        "UB V1.8 Full Starter Source": workload.get("v18_full_starter_source"),

        "UB V1.8 Full Starter Authority": workload.get("v18_full_starter_authority"),

        "UB Lineup Top3 K%": None if lineup.get("top3_rate") is None else round(float(lineup.get("top3_rate"))*100.0,2),

        "UB Lineup Top5 K%": None if lineup.get("top5_rate") is None else round(float(lineup.get("top5_rate"))*100.0,2),

        "UB Lineup High-K 25% Count": int(lineup.get("high_k_25") or 0),

        "UB Lineup High-K 30% Count": int(lineup.get("high_k_30") or 0),

        "UB Lineup Concentration Modifier": round(float(lineup.get("concentration_modifier") or 0.0),5),

        "UB Conversion Interaction K/BF": round(float(interaction.get("kbf") or 0.0),5),

        "UB Conversion Interaction Status": out.get("UB Conversion Interaction Status") or interaction.get("status"),

        "UB Conversion Interaction Reasons": out.get("UB Conversion Interaction Reasons") or ("; ".join(interaction.get("reasons") or []) or "NONE"),

        "UB Confidence Sync Check": True,

    })

    flip = _ub_v18_flip_evidence(out)

    out["UB Flip Evidence Status"] = flip["status"]

    out["UB Flip Evidence Count"] = flip["count"]

    out["UB Flip Evidence Reasons"] = "; ".join(flip["reasons"]) or "NONE"

    edge = abs(float(_ub_num(out.get("Undefeated Beta Edge"), 0.0) or 0.0))

    if flip["status"] == "THIN_FLIP" and edge < float(UB_CONFIG["v18_flip_confirm_edge_k"]):

        old_play = str(out.get("Undefeated Beta Playability") or "TRACK")

        downgrade = {"OFFICIAL_PLAY":"LEAN", "LEAN":"TRACK", "TRACK":"PASS", "PASS":"PASS"}

        new_play = downgrade.get(old_play, "PASS")

        out["Undefeated Beta Playability"] = new_play

        out["Undefeated Beta Decision State"] = f"{new_play}_{out.get('Undefeated Beta Side')}"

        reason = str(out.get("Undefeated Beta Decision Reason") or "")

        out["Undefeated Beta Decision Reason"] = (reason + "; V1.8_THIN_FLIP_CONFIRMATION_GUARD").strip("; ")

        if out.get("Best Play Score") is not None:

            out["Best Play Score"] = max(0.0, float(_ub_num(out.get("Best Play Score"), 0.0) or 0.0) - 8.0)

        if new_play == "PASS":

            out["Best Play Tier"] = "PASS"

    return out







# =============================================================================

# UNDEFEATED BETA V1.9 — TARGETED COMPONENT ADD-ONS

# Adds only the strongest still-missing ideas from the component-engine audit:

#   1) explicit projected-pitch-count / pitches-per-BF workload cross-check,

#   2) contact / two-strike finishability resistance (small, multi-signal only),

#   3) actual TTO-rate weighting by expected BF exposure,

#   4) separate positive leash support vs negative early-hook risk used ONLY to

#      modulate workload authority, never as another free-standing K bonus.

# Umpire projection remains OFF. Moneyline Phase 2.1 is intentionally unchanged.

# =============================================================================

_ub_workload_distribution_v18_active = _ub_workload_distribution

_ub_fixed_core_v18_active = _ub_fixed_core

_ub_component_blend_profile_v18_active = _ub_component_blend_profile

_ub_build_row_v18_active = _ub_build_row

_ub_v18_flip_evidence_active = _ub_v18_flip_evidence





def _ub_v19_script_authority_profile(p, row, workload):

    """Separate helpful leash context from early-hook risk without double-counting BF.



    This profile never adds BF directly. It only changes how much authority an explicit

    pitch-budget BF estimate is allowed to receive.

    """

    p = p or {}; row = row or {}; workload = workload or {}

    bullpen = str(_ub_first([p, row], ["bullpen_status", "Bullpen Status", "PO Bullpen Leash Signal"], "") or "").upper()

    damage = str(_ub_first([p, row], ["run_damage_risk_level", "K Damage Risk Label", "Damage Risk Label"], "") or "").upper()

    hook = str(_ub_first([p, row], ["manager_hook_status", "early_pull_label", "leash_risk", "Manager Hook"], "") or "").upper()

    manager = str(workload.get("manager_leash_state") or "NEUTRAL").upper()



    positive = []

    negative = []

    if any(token in bullpen for token in ("TIRED", "TAXED", "HEAVY", "EXTEND")):

        positive.append("TIRED_BULLPEN")

    if manager == "DEEP" or any(token in hook for token in ("LOW_HOOK", "LOW HOOK", "LONG LEASH", "DEEP")):

        positive.append("DEEP_LEASH")

    if manager == "SHORT" or any(token in hook for token in ("QUICK_HOOK", "QUICK HOOK", "EARLY_PULL", "EARLY PULL", "PITCH_LIMIT", "PITCH LIMIT", "LIMITED")):

        negative.append("SHORT_LEASH")

    if any(token in damage for token in ("HIGH", "EXTREME", "RED", "SEVERE")):

        negative.append("EARLY_DAMAGE_RISK")



    return {

        "positive": bool(positive), "negative": bool(negative),

        "positive_reasons": positive, "negative_reasons": negative,

        "label": "NEGATIVE_HOOK_RISK" if negative else "POSITIVE_LEASH_SUPPORT" if positive else "NEUTRAL",

    }





def _ub_v19_pitch_budget_profile(p, row, workload):

    """Independent BF cross-check: projected pitch budget / expected pitches per BF.



    Only an explicit/current projected pitch count is allowed to move BF here. Recent

    pitch counts already participate elsewhere and are not counted again as a second

    independent source.

    """

    p = p or {}; row = row or {}; workload = workload or {}

    pitches = _ub_num(_ub_first([p, row], [

        "projected_pitches", "Projected Pitches", "Projected Pitch Count", "Expected Pitch Count",

        "APP97 Projected Pitches", "Pitch Count Projection",

    ], workload.get("projected_pitches_input")), None)

    ppb3 = _ub_num(workload.get("recent_ppb_l3"), None)

    ppb5 = _ub_num(workload.get("recent_ppb_l5"), None)

    raw_ppb = _ub_num(_ub_first([p, row], ["pitches_per_bf", "Pitches Per BF", "PPB", "pitches_per_batter"], None), None)

    ppb_parts = []

    if ppb3 is not None and 2.8 <= ppb3 <= 5.2: ppb_parts.append((ppb3, 0.60))

    if ppb5 is not None and 2.8 <= ppb5 <= 5.2: ppb_parts.append((ppb5, 0.30))

    if raw_ppb is not None and 2.8 <= raw_ppb <= 5.2: ppb_parts.append((raw_ppb, 0.10))

    if pitches is None or not (45.0 <= float(pitches) <= 125.0) or not ppb_parts:

        return {"available": False, "bf": None, "expected_ppb": None, "pitches": pitches, "reason": "NO_EXPLICIT_PITCH_BUDGET_OR_PPB"}

    denom = sum(w for _, w in ppb_parts) or 1.0

    expected_ppb = sum(v*w for v,w in ppb_parts) / denom

    expected_ppb = float(clamp(expected_ppb, 3.05, 4.65))

    bf = float(clamp(float(pitches) / expected_ppb, 8.0, 31.5))

    return {

        "available": True, "bf": bf, "expected_ppb": expected_ppb, "pitches": float(pitches),

        "reason": f"{float(pitches):.0f} projected pitches / {expected_ppb:.2f} pitches per BF",

    }





def _ub_workload_distribution(p, row=None):

    """V1.9 workload: V1.8 full-starter center + one explicit pitch-budget cross-check."""

    p = p or {}; row = row or {}

    base = dict(_ub_workload_distribution_v18_active(p, row) or {})

    if not base:

        return base

    pitch_budget = _ub_v19_pitch_budget_profile(p, row, base)

    script = _ub_v19_script_authority_profile(p, row, base)

    base.update({

        "v19_pitch_budget_available": bool(pitch_budget.get("available")),

        "v19_pitch_budget_bf": None if pitch_budget.get("bf") is None else round(float(pitch_budget["bf"]), 2),

        "v19_pitch_budget_pitches": None if pitch_budget.get("pitches") is None else round(float(pitch_budget["pitches"]), 1),

        "v19_pitch_budget_expected_ppb": None if pitch_budget.get("expected_ppb") is None else round(float(pitch_budget["expected_ppb"]), 3),

        "v19_pitch_budget_reason": pitch_budget.get("reason"),

        "v19_positive_leash_support": bool(script.get("positive")),

        "v19_negative_hook_risk": bool(script.get("negative")),

        "v19_script_label": script.get("label"),

        "v19_positive_leash_reasons": script.get("positive_reasons") or [],

        "v19_negative_hook_reasons": script.get("negative_reasons") or [],

        "v19_pitch_budget_move_bf": 0.0,

        "v19_pitch_budget_authority": 0.0,

    })

    if not pitch_budget.get("available"):

        return base

    if str(base.get("role") or "").upper() in {"OPENER", "RELIEVER", "LIMITED_STARTER"} and str(base.get("role_authority") or "") == "CURRENT_CONFIRMED_ROLE":

        base["v19_pitch_budget_reason"] = str(base.get("v19_pitch_budget_reason") or "") + "; confirmed short role blocks pitch-budget promotion"

        return base



    center = float(_ub_num(base.get("bf_p50"), DEFAULT_BF) or DEFAULT_BF)

    budget_bf = float(pitch_budget["bf"])

    gap = budget_bf - center

    if abs(gap) < float(UB_CONFIG["v19_pitch_budget_min_gap_bf"]):

        return base



    # Require pitch budget to agree reasonably with an independent recent/full-start workload source.

    corroborators = []

    for value in (base.get("v18_full_starter_bf"), base.get("recent_bf_median"), base.get("live_workload_center")):

        value = _ub_num(value, None)

        if value is not None:

            corroborators.append(float(value))

    corroborated = any(abs(budget_bf - x) <= float(UB_CONFIG["v19_pitch_budget_corroboration_gap_bf"]) for x in corroborators)

    if not corroborated and int(base.get("sample") or 0) < 3:

        base["v19_pitch_budget_reason"] = str(base.get("v19_pitch_budget_reason") or "") + "; insufficient workload corroboration"

        return base



    authority = float(UB_CONFIG["v19_pitch_budget_base_authority"])

    if script.get("positive") and gap > 0:

        authority += 0.07

    if script.get("negative") and gap > 0:

        authority -= 0.10

    if script.get("negative") and gap < 0:

        authority += 0.05

    authority = float(clamp(authority, 0.08, float(UB_CONFIG["v19_pitch_budget_max_authority"])))

    move = float(clamp(gap * authority, -float(UB_CONFIG["v19_pitch_budget_max_move_bf"]), float(UB_CONFIG["v19_pitch_budget_max_move_bf"])))

    if abs(move) < 0.05:

        return base



    # Add the same BF shift to every percentile so distribution width is preserved.

    previous = {}

    for key in ("bf_p10", "bf_p25", "bf_p50", "bf_p75", "bf_p90"):

        val = _ub_num(base.get(key), None)

        if val is not None:

            previous[key] = float(val)

            base[key] = round(float(clamp(float(val) + move, 4.0, 33.0)), 2)

    # Reassert monotonic distribution after clipping.

    ordered = ["bf_p10", "bf_p25", "bf_p50", "bf_p75", "bf_p90"]

    last = 4.0

    for key in ordered:

        if base.get(key) is not None:

            base[key] = round(max(last, float(base[key])), 2)

            last = float(base[key])

    ip_per_bf = float(_ub_num(base.get("ip_per_bf"), 0.245) or 0.245)

    for bf_key, ip_key in (("bf_p10","ip_p10"),("bf_p25","ip_p25"),("bf_p50","ip_p50"),("bf_p75","ip_p75"),("bf_p90","ip_p90")):

        if base.get(bf_key) is not None:

            base[ip_key] = round(float(base[bf_key]) * ip_per_bf, 2)

    base["v19_pitch_budget_move_bf"] = round(move, 3)

    base["v19_pitch_budget_authority"] = round(authority, 3)

    if abs(move) >= 0.35:

        base["workload_mismatch_score"] = round(max(float(_ub_num(base.get("workload_mismatch_score"), 0.0) or 0.0), min(100.0, 35.0 + abs(move)*25.0)), 1)

        reasons = list(base.get("workload_mismatch_reasons") or [])

        reasons.append(f"V1.9 pitch-budget cross-check moved BF {move:+.2f} ({budget_bf:.1f} budget BF vs {center:.1f} prior center)")

        base["workload_mismatch_reasons"] = list(dict.fromkeys(reasons))

    base["note"] = str(base.get("note") or "") + f"; V1.9 pitch-budget {budget_bf:.1f} BF, authority {authority:.2f}, move {move:+.2f}"

    return base





def _ub_v19_contact_finishability_profile(p, row):

    """Small multi-signal K/BF modifier for hitters extending/fouling off two-strike PAs.



    This intentionally excludes lineup K% so opponent strikeout tendency is not counted twice.

    """

    p = p or {}; row = row or {}

    zone_contact = _ub_rate(_ub_first([p, row], ["statcast_zone_contact", "Zone Contact%", "Statcast Zone Contact%"], None), None)

    foul = _ub_rate(_ub_first([p, row], ["foul_extension_rate", "Foul Extension Rate", "Foul%", "PO Foul Workload %"], None), None)

    two_reach = _ub_rate(_ub_first([p, row], ["two_strike_reach_rate", "Two Strike Reach Rate"], None), None)

    two_put = _ub_rate(_ub_first([p, row], ["two_strike_putaway_rate", "Two Strike PutAway Rate"], None), None)



    support, resist = [], []

    if zone_contact is not None:

        if zone_contact <= 0.79: support.append("LOW_ZONE_CONTACT")

        elif zone_contact >= 0.88: resist.append("HIGH_ZONE_CONTACT")

    if foul is not None:

        if foul <= 0.14: support.append("LOW_FOUL_EXTENSION")

        elif foul >= 0.23: resist.append("HIGH_FOUL_EXTENSION")

    if two_reach is not None:

        if two_reach <= 0.18: support.append("LOW_TWO_STRIKE_SURVIVAL")

        elif two_reach >= 0.30: resist.append("HIGH_TWO_STRIKE_SURVIVAL")

    if two_put is not None:

        if two_put >= 0.27: support.append("STRONG_TWO_STRIKE_FINISH")

        elif two_put <= 0.15: resist.append("WEAK_TWO_STRIKE_FINISH")



    min_fams = int(UB_CONFIG["v19_contact_finish_min_families"])

    raw = 0.0

    status = "NEUTRAL"

    if len(support) >= min_fams and len(support) > len(resist):

        raw = min(float(UB_CONFIG["v19_contact_finish_max_kbf"]), 0.0015 * len(support))

        status = "EASIER_TO_FINISH"

    elif len(resist) >= min_fams and len(resist) > len(support):

        raw = -min(float(UB_CONFIG["v19_contact_finish_max_kbf"]), 0.0015 * len(resist))

        status = "CONTACT_RESISTANT"

    return {

        "kbf_modifier": float(raw), "status": status, "support": support, "resistance": resist,

        "zone_contact": zone_contact, "foul_extension": foul, "two_strike_reach": two_reach, "two_strike_putaway": two_put,

        "evidence_families": len(support) + len(resist),

    }





def _ub_v19_tto_rate_profile(p, row, workload, skill_kbf):

    """Weight actual TTO K rates by the BF the pitcher is expected to reach.



    The resulting adjustment is deliberately only 25-35% of the gap to true-talent K/BF

    and capped to +/-0.45 percentage points so TTO cannot overpower core skill/matchup.

    """

    p = p or {}; row = row or {}; workload = workload or {}

    t1 = _ub_rate(_ub_first([p, row], ["TTO1_K_pct", "tto1_k_pct"], None), None)

    t2 = _ub_rate(_ub_first([p, row], ["TTO2_K_pct", "tto2_k_pct"], None), None)

    t3 = _ub_rate(_ub_first([p, row], ["TTO3_K_pct", "tto3_k_pct"], None), None)

    starts = len(_ub_history_games(p))

    if starts < int(UB_CONFIG["v19_tto_min_starts"]) or t1 is None or t2 is None:

        return {"available": False, "kbf_modifier": 0.0, "weighted_kbf": None, "starts": starts, "reason": "INSUFFICIENT_TTO_SAMPLE"}

    bf = float(_ub_num(workload.get("bf_p50"), DEFAULT_BF) or DEFAULT_BF)

    if bf < 12.0:

        return {"available": False, "kbf_modifier": 0.0, "weighted_kbf": None, "starts": starts, "reason": "LOW_TTO_ACCESS"}

    n1 = min(bf, 9.0)

    n2 = min(max(bf - 9.0, 0.0), 9.0)

    n3 = max(bf - 18.0, 0.0)

    if t3 is None:

        t3 = t2

    denom = max(1e-9, n1+n2+n3)

    weighted = (n1*t1 + n2*t2 + n3*t3) / denom

    authority = float(UB_CONFIG["v19_tto_strong_authority"] if starts >= 8 else UB_CONFIG["v19_tto_base_authority"])

    modifier = float(clamp((weighted - float(skill_kbf)) * authority, -float(UB_CONFIG["v19_tto_max_kbf"]), float(UB_CONFIG["v19_tto_max_kbf"])))

    return {

        "available": True, "kbf_modifier": modifier, "weighted_kbf": weighted, "starts": starts,

        "authority": authority, "bf1": n1, "bf2": n2, "bf3": n3,

        "tto1": t1, "tto2": t2, "tto3": t3,

        "reason": f"TTO-weighted {weighted*100:.1f}% across {bf:.1f} BF vs skill {float(skill_kbf)*100:.1f}%",

    }





def _ub_fixed_core(p, row, workload, recent, regime):

    """V1.9 keeps V1.8 core and applies only capped contact/TTO K/BF modifiers."""

    base = dict(_ub_fixed_core_v18_active(p, row, workload, recent, regime) or {})

    if not base:

        return base

    pre = float(base.get("matchup_kbf") or base.get("skill_kbf") or LEAGUE_AVG_K)

    contact = _ub_v19_contact_finishability_profile(p, row)

    tto = _ub_v19_tto_rate_profile(p, row, workload, float(base.get("skill_kbf") or LEAGUE_AVG_K))

    contact_mod = float(contact.get("kbf_modifier") or 0.0)

    tto_mod = float(tto.get("kbf_modifier") or 0.0)

    net = float(clamp(contact_mod + tto_mod, -0.0070, 0.0070))

    post = float(clamp(pre + net, 0.08, 0.45))

    base["v19_pre_modifier_matchup_kbf"] = pre

    base["v19_contact_finishability"] = contact

    base["v19_tto_rate"] = tto

    base["v19_contact_kbf_modifier"] = contact_mod

    base["v19_tto_kbf_modifier"] = tto_mod

    base["v19_net_kbf_modifier"] = post - pre

    base["matchup_kbf"] = post

    base["projection"] = post * float(_ub_num(workload.get("bf_p50"), DEFAULT_BF) or DEFAULT_BF)

    return base





def _ub_component_blend_profile(merge_projection, fixed, workload, recent, regime, data_quality):

    """V1.9 reclassifies contact/TTO effects in the additive attribution ledger."""

    comp = dict(_ub_component_blend_profile_v18_active(merge_projection, fixed, workload, recent, regime, data_quality) or {})

    if not comp:

        return comp

    merge_bf = float(comp.get("merge_bf") or workload.get("merge_bf") or DEFAULT_BF)

    auth = float(comp.get("kbf_authority") or UB_CONFIG["component_kbf_authority_normal"])

    contact_kbf = float((fixed or {}).get("v19_contact_kbf_modifier") or 0.0)

    tto_kbf = float((fixed or {}).get("v19_tto_kbf_modifier") or 0.0)

    contact_delta = merge_bf * auth * contact_kbf

    tto_delta = merge_bf * auth * tto_kbf

    # V1.8 sees these as part of post-trend/suppression because they are injected after

    # the base core is built. Reclassify, do not add them twice.

    if "suppression_delta" in comp:

        comp["suppression_delta"] = float(comp.get("suppression_delta") or 0.0) - contact_delta - tto_delta

    comp["contact_finishability_kbf"] = contact_kbf

    comp["contact_finishability_delta"] = contact_delta

    comp["tto_rate_kbf"] = tto_kbf

    comp["tto_rate_delta"] = tto_delta

    total = sum(float(comp.get(k) or 0.0) for k in [

        "skill_matchup_delta", "pitch_trend_delta", "suppression_delta", "conversion_interaction_delta",

        "contact_finishability_delta", "tto_rate_delta", "workload_delta", "guard_adjustment"

    ])

    comp["attribution_residual"] = float(comp.get("projection") or merge_projection) - float(merge_projection) - total

    comp["math_status"] = "PASS" if abs(float(comp["attribution_residual"])) <= 1e-6 else "FAIL"

    fams = list(comp.get("signal_families") or [])

    if abs(contact_kbf) >= 0.0015: fams.append("CONTACT_FINISHABILITY")

    if abs(tto_kbf) >= 0.0015: fams.append("TTO_RATE")

    comp["signal_families"] = sorted(set(fams))

    return comp





def _ub_v19_flip_evidence(out):

    base = dict(_ub_v18_flip_evidence_active(out) or {})

    if base.get("status") == "NO_FLIP":

        return base

    side = str((out or {}).get("Undefeated Beta Side") or "").upper()

    direction = 1.0 if side == "OVER" else -1.0

    reasons = list(base.get("reasons") or [])

    contact = float(_ub_num((out or {}).get("UB Contact Finishability K/BF"), 0.0) or 0.0)

    tto = float(_ub_num((out or {}).get("UB TTO Rate K/BF Modifier"), 0.0) or 0.0)

    pitch_move = float(_ub_num((out or {}).get("UB Pitch Budget Move BF"), 0.0) or 0.0)

    if direction * contact >= 0.0015: reasons.append("CONTACT_FINISHABILITY")

    if direction * tto >= 0.0015: reasons.append("TTO_RATE")

    if direction * pitch_move >= 0.35: reasons.append("PITCH_BUDGET")

    reasons = list(dict.fromkeys(reasons))

    status = "CONFIRMED_FLIP" if len(reasons) >= 3 else "SUPPORTED_FLIP" if len(reasons) >= 2 else "THIN_FLIP"

    return {"status": status, "count": len(reasons), "reasons": reasons}





def _ub_build_row(row, p):

    """V1.9 diagnostics wrapper; biological math is already handled by global overrides."""

    out = _ub_build_row_v18_active(row, p)

    if not out:

        return out

    workload = _ub_workload_distribution(p or {}, row or {})

    # Rebuild only the small V1.9 profiles for transparent output.

    contact = _ub_v19_contact_finishability_profile(p or {}, row or {})

    skill = float(_ub_num(out.get("UB Skill K/BF"), LEAGUE_AVG_K) or LEAGUE_AVG_K)

    tto = _ub_v19_tto_rate_profile(p or {}, row or {}, workload, skill)

    out.update({

        "UB V1.9 Pitch Budget BF": workload.get("v19_pitch_budget_bf"),

        "UB V1.9 Pitch Budget Pitches": workload.get("v19_pitch_budget_pitches"),

        "UB V1.9 Pitch Budget Expected PPB": workload.get("v19_pitch_budget_expected_ppb"),

        "UB Pitch Budget Move BF": workload.get("v19_pitch_budget_move_bf"),

        "UB Pitch Budget Authority": workload.get("v19_pitch_budget_authority"),

        "UB Pitch Budget Reason": workload.get("v19_pitch_budget_reason"),

        "UB Positive Leash Support": bool(workload.get("v19_positive_leash_support")),

        "UB Negative Hook Risk": bool(workload.get("v19_negative_hook_risk")),

        "UB Script Authority Label": workload.get("v19_script_label"),

        "UB Script Positive Reasons": "; ".join(workload.get("v19_positive_leash_reasons") or []) or "NONE",

        "UB Script Negative Reasons": "; ".join(workload.get("v19_negative_hook_reasons") or []) or "NONE",

        "UB Contact Finishability Status": contact.get("status"),

        "UB Contact Finishability K/BF": round(float(contact.get("kbf_modifier") or 0.0), 5),

        "UB Contact Finishability Support": "; ".join(contact.get("support") or []) or "NONE",

        "UB Contact Finishability Resistance": "; ".join(contact.get("resistance") or []) or "NONE",

        "UB Contact Zone Contact%": None if contact.get("zone_contact") is None else round(float(contact.get("zone_contact"))*100.0, 2),

        "UB Contact Foul Extension%": None if contact.get("foul_extension") is None else round(float(contact.get("foul_extension"))*100.0, 2),

        "UB Contact Two-Strike Reach%": None if contact.get("two_strike_reach") is None else round(float(contact.get("two_strike_reach"))*100.0, 2),

        "UB TTO Rate Available": bool(tto.get("available")),

        "UB TTO Weighted K%": None if tto.get("weighted_kbf") is None else round(float(tto.get("weighted_kbf"))*100.0, 2),

        "UB TTO Rate K/BF Modifier": round(float(tto.get("kbf_modifier") or 0.0), 5),

        "UB TTO Rate Starts": int(tto.get("starts") or 0),

        "UB TTO Rate Reason": tto.get("reason"),

    })

    # The exact component math values were produced during the wrapped build.

    # Preserve existing reconciliation flag and expose new attribution components when available.

    merge_bf = float(_ub_num(out.get("UB Merge BF Component"), DEFAULT_BF) or DEFAULT_BF)

    kbf_auth = float(_ub_num(out.get("UB KBF Authority"), UB_CONFIG["component_kbf_authority_normal"]) or UB_CONFIG["component_kbf_authority_normal"])

    out["UB Contact Finishability Delta"] = round(merge_bf * kbf_auth * float(contact.get("kbf_modifier") or 0.0), 3)

    out["UB TTO Rate Delta"] = round(merge_bf * kbf_auth * float(tto.get("kbf_modifier") or 0.0), 3)

    flip = _ub_v19_flip_evidence(out)

    out["UB Flip Evidence Status"] = flip["status"]

    out["UB Flip Evidence Count"] = flip["count"]

    out["UB Flip Evidence Reasons"] = "; ".join(flip["reasons"]) or "NONE"

    edge = abs(float(_ub_num(out.get("Undefeated Beta Edge"), 0.0) or 0.0))

    # V1.8 already applies the thin-flip trust downgrade once inside the wrapped row builder.

    # V1.9 enriches the evidence classification only; it never double-penalizes the same flip.

    out["UB Pregame Feature Persistence"] = "COMPLETE_V1_9_TARGETED_COMPONENTS"

    return out







# =============================================================================

# UNDEFEATED BETA V1.10 — PRESERVE-WINS / THRESHOLD-LOSS PROTECTION

# The biological challenger remains independent. V1.10 adds:

#   1) current-role K/BF reconciliation (small, line-independent raw adjustment),

#   2) P25/P40 OVER workload-floor survival,

#   3) exact-line fragility around the one-K threshold zone,

#   4) low-line (2.5/3.5) historical threshold shadow,

#   5) PO/Merge disagreement diagnostics,

#   6) a narrowly-scoped final resolver for unsupported thin flips.

# No pitcher/team/outcome names are hard-coded. Moneyline Phase 2.1 is untouched.

# =============================================================================

_ub_fixed_core_v19_active = _ub_fixed_core

_ub_component_blend_profile_v19_active = _ub_component_blend_profile

_ub_build_row_v19_active = _ub_build_row





def _ub_v110_all_history_games(p):

    """Return recent MLB game-log rows without discarding relief/opener appearances.



    Older Beta helpers intentionally preferred starter rows. This companion view is

    used only for CURRENT-ROLE conversion/role-volatility reconciliation so a recent

    role change cannot be hidden by older starts.

    """

    p = p or {}

    history = p.get("k_history_context_v256") if isinstance(p.get("k_history_context_v256"), dict) else {}

    raw = history.get("game_log") if isinstance(history.get("game_log"), list) else []

    clean, seen = [], set()

    for game in raw:

        if not isinstance(game, dict):

            continue

        date = str(game.get("date") or game.get("Date") or "")

        game_pk = str(game.get("game_pk") or game.get("GamePk") or "")

        key = game_pk or f"{date}|{game.get('opponent')}|{game.get('Ks')}|{game.get('IP')}"

        if key in seen:

            continue

        seen.add(key)

        role = str(game.get("role") or game.get("Role") or "UNKNOWN").upper()

        bf = _ub_num(_ub_first([game], ["BF", "TBF", "batters_faced", "Batters Faced"], None), None)

        ks = _ub_num(game.get("Ks"), None)

        clean.append({

            "Date": date, "GamePk": game_pk, "Role": role,

            "BF": bf, "Ks": ks, "IP_float": baseball_ip_to_float(game.get("IP")),

            "Pitches": _ub_num(_ub_first([game], ["pitch_count", "Pitches", "pitches", "PC"], None), None),

        })

    clean.sort(key=lambda g: str(g.get("Date") or ""), reverse=True)

    return clean





def _ub_v110_role_conversion_profile(p, row, base_core):

    """Small line-independent current-role K/BF reconciliation.



    Uses the latest raw game-log rows, including opener/relief work, because the

    existing starter-only recent profile can legitimately miss a current role shift.

    The modifier is aggressively shrunk and capped to avoid double-counting form.

    """

    games = _ub_v110_all_history_games(p)

    usable = [g for g in games[:10] if g.get("BF") and g.get("Ks") is not None]

    min_games = int(UB_CONFIG["v110_current_role_kbf_min_games"])

    total_bf = sum(float(g["BF"]) for g in usable[:6])

    if len(usable) < min_games or total_bf < float(UB_CONFIG["v110_current_role_kbf_min_bf"]):

        return {"available": False, "modifier": 0.0, "reason": "INSUFFICIENT_CURRENT_ROLE_KBF", "games": len(usable), "bf": total_bf}



    def pooled(sub):

        bf = sum(float(g["BF"]) for g in sub if g.get("BF"))

        ks = sum(float(g["Ks"]) for g in sub if g.get("Ks") is not None)

        return None if bf <= 0 else ks / bf, bf



    l3, bf3 = pooled(usable[:3])

    l6, bf6 = pooled(usable[:6])

    if l3 is None or l6 is None:

        return {"available": False, "modifier": 0.0, "reason": "NO_POOLED_CURRENT_ROLE_KBF", "games": len(usable), "bf": total_bf}

    consensus = 0.62 * l3 + 0.38 * l6

    reference = float(base_core.get("matchup_kbf") or base_core.get("skill_kbf") or LEAGUE_AVG_K)

    gap = consensus - reference

    if abs(gap) < float(UB_CONFIG["v110_current_role_kbf_gap"]):

        return {"available": True, "modifier": 0.0, "reason": "CURRENT_ROLE_KBF_WITHIN_DEADBAND", "games": len(usable), "bf": bf6, "l3": l3, "l6": l6, "consensus": consensus, "gap": gap}



    recent_roles = [str(g.get("Role") or "UNKNOWN").upper() for g in usable[:5]]

    starter_like = sum(1 for r in recent_roles if "START" in r)

    relief_like = sum(1 for r in recent_roles if any(tok in r for tok in ("RELIEF", "RELIEVER", "OPENER", "BULK", "FOLLOW")))

    mixed = bool(starter_like and relief_like) or bool(relief_like >= 3)

    authority = float(UB_CONFIG["v110_current_role_kbf_mixed_authority"] if mixed else UB_CONFIG["v110_current_role_kbf_authority"])

    modifier = float(clamp(gap * authority, -float(UB_CONFIG["v110_current_role_kbf_max_move"]), float(UB_CONFIG["v110_current_role_kbf_max_move"])))

    return {

        "available": True, "modifier": modifier, "reason": "CURRENT_ROLE_KBF_RECONCILIATION",

        "games": len(usable), "bf": bf6, "l3": l3, "l6": l6, "consensus": consensus,

        "gap": gap, "authority": authority, "mixed_role": mixed,

        "recent_roles": recent_roles,

    }





def _ub_fixed_core(p, row, workload, recent, regime):

    """V1.10 biological core: V1.9 plus one small current-role K/BF reconciliation."""

    base = dict(_ub_fixed_core_v19_active(p, row, workload, recent, regime) or {})

    if not base:

        return base

    prof = _ub_v110_role_conversion_profile(p or {}, row or {}, base)

    mod = float(prof.get("modifier") or 0.0)

    pre = float(base.get("matchup_kbf") or base.get("skill_kbf") or LEAGUE_AVG_K)

    post = float(clamp(pre + mod, 0.08, 0.45))

    base["v110_pre_role_reconcile_kbf"] = pre

    base["v110_role_conversion_profile"] = prof

    base["v110_role_kbf_modifier"] = post - pre

    base["matchup_kbf"] = post

    base["projection"] = post * float(_ub_num(workload.get("bf_p50"), DEFAULT_BF) or DEFAULT_BF)

    return base





def _ub_component_blend_profile(merge_projection, fixed, workload, recent, regime, data_quality):

    """V1.10 attribution: reclassify current-role K/BF from the generic suppression bucket."""

    comp = dict(_ub_component_blend_profile_v19_active(merge_projection, fixed, workload, recent, regime, data_quality) or {})

    if not comp:

        return comp

    role_kbf = float((fixed or {}).get("v110_role_kbf_modifier") or 0.0)

    merge_bf = float(comp.get("merge_bf") or (workload or {}).get("merge_bf") or DEFAULT_BF)

    auth = float(comp.get("kbf_authority") or UB_CONFIG["component_kbf_authority_normal"])

    role_delta = merge_bf * auth * role_kbf

    if "suppression_delta" in comp:

        comp["suppression_delta"] = float(comp.get("suppression_delta") or 0.0) - role_delta

    comp["current_role_kbf"] = role_kbf

    comp["current_role_conversion_delta"] = role_delta

    total = sum(float(comp.get(k) or 0.0) for k in [

        "skill_matchup_delta", "pitch_trend_delta", "suppression_delta", "conversion_interaction_delta",

        "contact_finishability_delta", "tto_rate_delta", "current_role_conversion_delta", "workload_delta", "guard_adjustment"

    ])

    comp["attribution_residual"] = float(comp.get("projection") or merge_projection) - float(merge_projection) - total

    comp["math_status"] = "PASS" if abs(float(comp["attribution_residual"])) <= 1e-6 else "FAIL"

    fams = list(comp.get("signal_families") or [])

    if abs(role_kbf) >= 0.0015:

        fams.append("CURRENT_ROLE_KBF")

    comp["signal_families"] = sorted(set(fams))

    return comp





def _ub_v110_normal_cdf(x):

    return 0.5 * (1.0 + math.erf(float(x) / math.sqrt(2.0)))





def _ub_v110_exact_k_probability(mean, sigma, k):

    if sigma is None or sigma <= 0:

        return 0.0

    lo = (float(k) - 0.5 - float(mean)) / float(sigma)

    hi = (float(k) + 0.5 - float(mean)) / float(sigma)

    return float(clamp(_ub_v110_normal_cdf(hi) - _ub_v110_normal_cdf(lo), 0.0, 1.0))





def _ub_v110_fragility_profile(out):

    line = _ub_num((out or {}).get("Line"), None)

    projection = _ub_num((out or {}).get("UB Biological Projection"), _ub_num((out or {}).get("Undefeated Beta Projection"), None))

    if line is None or projection is None:

        return {"status": "NO_LINE", "mass": 0.0}

    # Recreate the same exact-line sigma used by the canonical distribution.

    sigma = math.sqrt(max(0.35, float(projection)))

    sigma = float(clamp(sigma, 1.05, 3.25))

    lower = int(math.floor(float(line)))

    upper = lower + 1

    p_lower = _ub_v110_exact_k_probability(projection, sigma, lower)

    p_upper = _ub_v110_exact_k_probability(projection, sigma, upper)

    mass = float(clamp(p_lower + p_upper, 0.0, 1.0))

    status = "HIGH" if mass >= float(UB_CONFIG["v110_fragility_high_mass"]) else "WATCH" if mass >= float(UB_CONFIG["v110_fragility_watch_mass"]) else "STABLE"

    return {"status": status, "mass": mass, "lower_k": lower, "upper_k": upper, "p_lower": p_lower, "p_upper": p_upper}





def _ub_v110_over_floor_profile(out, p=None):

    side = str((out or {}).get("UB Biological Side") or (out or {}).get("Undefeated Beta Side") or "").upper()

    line = _ub_num((out or {}).get("Line"), None)

    proj = _ub_num((out or {}).get("UB Biological Projection"), _ub_num((out or {}).get("Undefeated Beta Projection"), None))

    bf25 = _ub_num((out or {}).get("UB BF P25"), None)

    bf50 = _ub_num((out or {}).get("UB BF P50"), None)

    if side != "OVER" or line is None or proj is None or not bf25 or not bf50:

        return {"status": "NOT_OVER", "p25_k": None, "p40_k": None, "reason": "NOT_APPLICABLE"}

    rate = float(proj) / max(1e-9, float(bf50))

    bf40 = float(bf25) + 0.60 * max(0.0, float(bf50) - float(bf25))

    p25_k = float(bf25) * rate

    p40_k = bf40 * rate

    margin = p40_k - float(line)

    negative_hook = bool((out or {}).get("UB Negative Hook Risk"))

    recent_games = _ub_history_games(p or {})

    recent_ip = [float(g.get("IP_float")) for g in recent_games[:5] if g.get("IP_float") is not None]

    last_ip = recent_ip[0] if recent_ip else None

    short_rate = (sum(1 for ip in recent_ip if ip < 4.5) / len(recent_ip)) if recent_ip else 0.0

    recent_short_warning = bool((last_ip is not None and last_ip < 4.0) or short_rate >= 0.40)

    if margin <= float(UB_CONFIG["v110_over_floor_veto_margin_k"]) or (negative_hook and p40_k < float(line)):

        status = "VETO"

    elif margin < float(UB_CONFIG["v110_over_floor_watch_margin_k"]) or p25_k < float(line) or (recent_short_warning and margin < 0.75):

        status = "WATCH"

    else:

        status = "CLEAR"

    return {

        "status": status, "p25_k": p25_k, "p40_k": p40_k, "p40_bf": bf40,

        "rate": rate, "margin": margin, "last_start_ip": last_ip, "recent_short_start_rate": short_rate,

        "reason": f"P25 {p25_k:.2f} K; P40 {p40_k:.2f} K vs {float(line):.1f}; negative hook={negative_hook}; last IP={last_ip}; short-start rate={short_rate:.0%}",

    }





def _ub_v110_low_line_profile(p, out):

    line = _ub_num((out or {}).get("Line"), None)

    side = str((out or {}).get("UB Biological Side") or (out or {}).get("Undefeated Beta Side") or "").upper()

    proj = _ub_num((out or {}).get("UB Biological Projection"), _ub_num((out or {}).get("Undefeated Beta Projection"), None))

    if line is None or proj is None or float(line) > float(UB_CONFIG["v110_low_line_max"]):

        return {"status": "NOT_LOW_LINE", "strong_over": False}

    games = [g for g in _ub_history_games(p or {}) if g.get("Ks") is not None]

    if len(games) < int(UB_CONFIG["v110_low_line_min_starts"]):

        return {"status": "INSUFFICIENT_HISTORY", "strong_over": False, "starts": len(games)}

    l5 = [float(g["Ks"]) for g in games[:5]]

    l10 = [float(g["Ks"]) for g in games[:10]]

    over5 = sum(1 for k in l5 if k > float(line)) / max(1, len(l5))

    over10 = sum(1 for k in l10 if k > float(line)) / max(1, len(l10))

    avg5 = float(np.mean(l5)) if l5 else 0.0

    avg10 = float(np.mean(l10)) if l10 else 0.0

    bf50 = float(_ub_num((out or {}).get("UB BF P50"), 0.0) or 0.0)

    opp_k = _ub_rate((out or {}).get("UB Lineup Exposure K%"), None)

    strong = bool(

        side == "UNDER"

        and abs(float(proj) - float(line)) <= float(UB_CONFIG["v110_low_line_projection_band_k"])

        and over10 >= float(UB_CONFIG["v110_low_line_l10_over_rate"])

        and over5 >= float(UB_CONFIG["v110_low_line_l5_over_rate"])

        and avg5 >= float(line) + float(UB_CONFIG["v110_low_line_avg_buffer_k"])

        and bf50 >= 18.0

        and (opp_k is None or opp_k >= 0.19)

    )

    status = "STRONG_OVER_THRESHOLD" if strong else "UNDER_BREAKOUT_WATCH" if side == "UNDER" and over10 >= 0.60 else "NEUTRAL"

    return {

        "status": status, "strong_over": strong, "starts": len(games),

        "l5_over_rate": over5, "l10_over_rate": over10, "l5_avg": avg5, "l10_avg": avg10,

        "bf50": bf50, "opp_k": opp_k,

        "reason": f"L5 {over5*100:.0f}% over / {avg5:.2f} avg; L10 {over10*100:.0f}% over / {avg10:.2f} avg",

    }





def _ub_v110_model_disagreement_profile(out):

    ub_side = str((out or {}).get("UB Biological Side") or (out or {}).get("Undefeated Beta Side") or "").upper()

    merge_side = str((out or {}).get("Merge Control Side") or "").upper()

    po_side = str((out or {}).get("PO Side Same-Line") or "").upper()

    po_same = bool((out or {}).get("PO Same Line")) and po_side in {"OVER", "UNDER"}

    ub_proj = _ub_num((out or {}).get("UB Biological Projection"), _ub_num((out or {}).get("Undefeated Beta Projection"), None))

    po_proj = _ub_num((out or {}).get("PO Projection"), None)

    gap = None if ub_proj is None or po_proj is None else abs(float(ub_proj) - float(po_proj))

    opposite = bool(po_same and ub_side in {"OVER", "UNDER"} and po_side != ub_side)

    control_consensus = bool(opposite and merge_side in {"OVER", "UNDER"} and po_side == merge_side)

    if opposite and gap is not None and gap >= float(UB_CONFIG["v110_model_disagreement_gap_k"]):

        status = "STRONG_DISAGREEMENT"

    elif opposite and gap is not None and gap >= float(UB_CONFIG["v110_model_disagreement_watch_gap_k"]):

        status = "WATCH_DISAGREEMENT"

    elif opposite:

        status = "SIDE_DISAGREEMENT"

    else:

        status = "AGREE_OR_UNAVAILABLE"

    return {"status": status, "opposite": opposite, "control_consensus": control_consensus, "gap_k": gap, "po_side": po_side, "merge_side": merge_side}





def _ub_v110_probability_for_projection(projection, line, side, history_std=None):

    if projection is None or line is None or side not in {"OVER", "UNDER"}:

        return 0.5

    dist = _v265_exact_line_distribution(float(projection), float(line), history_std=history_std)

    p_over = _ub_num(dist.get("over_probability"), 0.5)

    return float(p_over if side == "OVER" else 1.0 - p_over)





def _ub_build_row(row, p):

    """V1.10 final wrapper: preserve raw biology, then apply tightly-scoped decision protection."""

    out = _ub_build_row_v19_active(row, p)

    if not out:

        return out



    # Preserve untouched biological output before any sportsbook-line decision resolver.

    biological_projection = float(_ub_num(out.get("Undefeated Beta Projection"), out.get("Merge Control Projection")) or out.get("Merge Control Projection") or 0.0)

    line = _ub_num(out.get("Line"), None)

    biological_side = str(out.get("Undefeated Beta Side") or "").upper()

    merge_projection = float(_ub_num(out.get("Merge Control Projection"), biological_projection) or biological_projection)

    merge_side = str(out.get("Merge Control Side") or "").upper()

    biological_prob = float(_ub_num(out.get("UB Calibrated Clear Probability %"), 50.0) or 50.0) / 100.0

    out["UB Biological Projection"] = round(biological_projection, 2)

    out["UB Biological Side"] = biological_side

    out["UB Biological Edge"] = None if line is None else round(biological_projection - float(line), 2)

    out["UB Biological Clear Probability %"] = round(biological_prob * 100.0, 1)



    role_prof = (out.get("UB Signal Ledger JSON") or "")

    role_reconcile = _ub_v110_role_conversion_profile(p or {}, row or {}, {

        "matchup_kbf": _ub_num(out.get("UB Matchup K/BF"), LEAGUE_AVG_K),

        "skill_kbf": _ub_num(out.get("UB Skill K/BF"), LEAGUE_AVG_K),

    })

    out["UB Current Role K/BF Available"] = bool(role_reconcile.get("available"))

    out["UB Current Role K/BF L3"] = None if role_reconcile.get("l3") is None else round(float(role_reconcile.get("l3"))*100.0, 2)

    out["UB Current Role K/BF L6"] = None if role_reconcile.get("l6") is None else round(float(role_reconcile.get("l6"))*100.0, 2)

    out["UB Current Role K/BF Consensus"] = None if role_reconcile.get("consensus") is None else round(float(role_reconcile.get("consensus"))*100.0, 2)

    out["UB Current Role K/BF Modifier"] = round(float(role_reconcile.get("modifier") or 0.0), 5)

    _v110_merge_bf = float(_ub_num(out.get("UB Merge BF Component"), DEFAULT_BF) or DEFAULT_BF)

    _v110_kbf_auth = float(_ub_num(out.get("UB KBF Authority"), UB_CONFIG["component_kbf_authority_normal"]) or UB_CONFIG["component_kbf_authority_normal"])

    out["UB Current Role K/BF Delta"] = round(_v110_merge_bf * _v110_kbf_auth * float(role_reconcile.get("modifier") or 0.0), 3)

    out["UB Current Role Mixed"] = bool(role_reconcile.get("mixed_role"))

    out["UB Current Role K/BF Reason"] = role_reconcile.get("reason")



    fragility = _ub_v110_fragility_profile(out)

    over_floor = _ub_v110_over_floor_profile(out, p or {})

    low_line = _ub_v110_low_line_profile(p or {}, out)

    disagree = _ub_v110_model_disagreement_profile(out)

    out.update({

        "UB Exact Line Fragility": fragility.get("status"),

        "UB Exact Line One-K Zone Mass %": round(float(fragility.get("mass") or 0.0)*100.0, 1),

        "UB Exact Line Lower K": fragility.get("lower_k"),

        "UB Exact Line Upper K": fragility.get("upper_k"),

        "UB OVER Floor Survival": over_floor.get("status"),

        "UB OVER P25 K": None if over_floor.get("p25_k") is None else round(float(over_floor.get("p25_k")), 2),

        "UB OVER P40 K": None if over_floor.get("p40_k") is None else round(float(over_floor.get("p40_k")), 2),

        "UB OVER Floor Margin K": None if over_floor.get("margin") is None else round(float(over_floor.get("margin")), 2),

        "UB OVER Last Start IP": over_floor.get("last_start_ip"),

        "UB OVER Recent Short-Start %": round(float(over_floor.get("recent_short_start_rate") or 0.0)*100.0, 1),

        "UB OVER Floor Reason": over_floor.get("reason"),

        "UB Low-Line Threshold Status": low_line.get("status"),

        "UB Low-Line L5 Over %": None if low_line.get("l5_over_rate") is None else round(float(low_line.get("l5_over_rate"))*100.0, 1),

        "UB Low-Line L10 Over %": None if low_line.get("l10_over_rate") is None else round(float(low_line.get("l10_over_rate"))*100.0, 1),

        "UB Low-Line L5 Avg K": None if low_line.get("l5_avg") is None else round(float(low_line.get("l5_avg")), 2),

        "UB Low-Line L10 Avg K": None if low_line.get("l10_avg") is None else round(float(low_line.get("l10_avg")), 2),

        "UB Low-Line Threshold Reason": low_line.get("reason"),

        "UB Model Disagreement Status": disagree.get("status"),

        "UB vs PO Projection Gap K": None if disagree.get("gap_k") is None else round(float(disagree.get("gap_k")), 2),

        "UB PO+Merge Control Consensus": bool(disagree.get("control_consensus")),

    })



    final_projection = biological_projection

    final_side = biological_side

    resolver_reasons = []

    resolver_adjustment = 0.0

    flip = _ub_v19_flip_evidence(out)

    flip_count = int(flip.get("count") or 0)

    raw_edge_abs = abs(biological_projection - float(line)) if line is not None else 0.0

    lineup_stage = str(out.get("UB Lineup Stage") or "EXPECTED").upper()

    order_conf = _ub_num(_ub_first([p or {}, row or {}], ["order_confidence_pct", "batting_order_confidence", "Order Confidence", "Expected Order Confidence"], None), None)

    lineup_weak = bool(lineup_stage != "CONFIRMED" or (order_conf is not None and float(order_conf) < 65.0))



    # (A) Strong low-line threshold evidence can rescue a thin 2.5/3.5 UNDER.

    # It moves only the FINAL resolver projection; biological K remains logged unchanged.

    if line is not None and bool(low_line.get("strong_over")) and biological_side == "UNDER":

        hist_anchor = 0.60 * float(low_line.get("l5_avg") or biological_projection) + 0.40 * float(low_line.get("l10_avg") or biological_projection)

        desired = max(biological_projection, 0.70 * biological_projection + 0.30 * hist_anchor)

        move = min(float(UB_CONFIG["v110_low_line_resolver_max_move_k"]), max(0.0, desired - biological_projection))

        if move > 0.01:

            final_projection = biological_projection + move

            resolver_adjustment += move

            resolver_reasons.append("LOW_LINE_HISTORICAL_THRESHOLD_RESCUE")



    # (B) Unsupported thin flips get shrunk toward the protected Merge control.

    # Trigger requires a thin probability/edge PLUS weak evidence/data or PO+Merge consensus.

    if line is not None and merge_side in {"OVER", "UNDER"} and biological_side in {"OVER", "UNDER"} and biological_side != merge_side:

        thin = bool(raw_edge_abs <= float(UB_CONFIG["v110_thin_flip_edge_k"]) or biological_prob <= float(UB_CONFIG["v110_thin_flip_probability"]))

        weak_support = bool(flip_count < int(UB_CONFIG["v110_thin_flip_min_evidence"]))

        trust_warning = bool(lineup_weak or disagree.get("control_consensus") or out.get("UB Negative Hook Risk"))

        if thin and weak_support and trust_warning:

            target = (1.0 - float(UB_CONFIG["v110_thin_flip_merge_weight"])) * biological_projection + float(UB_CONFIG["v110_thin_flip_merge_weight"]) * merge_projection

            delta = float(clamp(target - final_projection, -float(UB_CONFIG["v110_thin_flip_resolver_max_move_k"]), float(UB_CONFIG["v110_thin_flip_resolver_max_move_k"])))

            if abs(delta) > 0.01:

                final_projection += delta

                resolver_adjustment += delta

                resolver_reasons.append("THIN_FLIP_PRESERVE_CONTROL")



    if line is not None:

        final_side = "OVER" if final_projection > float(line) else "UNDER" if final_projection < float(line) else "PUSH"

    final_projection = round(float(final_projection), 2)

    out["Undefeated Beta Projection"] = final_projection

    out["Undefeated Beta Side"] = final_side

    out["Undefeated Beta Edge"] = None if line is None else round(final_projection - float(line), 2)

    out["UB Decision Resolver Adjustment K"] = round(float(final_projection - biological_projection), 3)

    out["UB Decision Resolver Applied"] = bool(abs(final_projection - biological_projection) >= 0.01)

    out["UB Decision Resolver Reasons"] = "; ".join(resolver_reasons) or "NONE"

    out["UB Side Flip vs Merge"] = bool(line is not None and merge_side in {"OVER","UNDER"} and final_side in {"OVER","UNDER"} and final_side != merge_side)

    out["UB Side Math Check"] = bool(line is None or final_side == ("OVER" if final_projection > float(line) else "UNDER" if final_projection < float(line) else "PUSH"))

    out["UB Edge Math Check"] = bool(line is None or abs((final_projection - float(line)) - float(out.get("Undefeated Beta Edge") or 0.0)) <= 1e-9)



    # Recompute final line probability for the resolved projection. Preserve original

    # biological probability separately; the resolver probability is intentionally capped.

    history = (p or {}).get("k_history_context_v256") if isinstance((p or {}).get("k_history_context_v256"), dict) else {}

    hist_std = _ub_num(history.get("k_standard_deviation"), None)

    final_prob = biological_prob if abs(final_projection - biological_projection) < 0.005 else _ub_v110_probability_for_projection(final_projection, line, final_side, hist_std)

    cap_reasons = []

    if fragility.get("status") in {"WATCH", "HIGH"}:

        final_prob = min(final_prob, float(UB_CONFIG["v110_fragility_prob_cap"]))

        cap_reasons.append("EXACT_LINE_FRAGILITY")

    if final_side == "OVER" and over_floor.get("status") == "WATCH":

        final_prob = min(final_prob, float(UB_CONFIG["v110_over_floor_watch_prob_cap"]))

        cap_reasons.append("OVER_WORKLOAD_FLOOR_WATCH")

    if final_side == "OVER" and over_floor.get("status") == "VETO":

        final_prob = min(final_prob, float(UB_CONFIG["v110_over_floor_veto_prob_cap"]))

        cap_reasons.append("OVER_WORKLOAD_FLOOR_VETO")

    if disagree.get("status") == "STRONG_DISAGREEMENT" and raw_edge_abs < 0.60:

        final_prob = min(final_prob, 0.61)

        cap_reasons.append("STRONG_MODEL_DISAGREEMENT")

    if resolver_reasons:

        final_prob = min(final_prob, 0.60)

        cap_reasons.append("DECISION_RESOLVER_CAP")

    out["UB Calibrated Clear Probability %"] = round(float(clamp(final_prob, 0.01, 0.99))*100.0, 1)

    prior_caps = str(out.get("UB Confidence Cap Reason") or "NONE")

    all_caps = [x for x in prior_caps.split("; ") if x and x != "NONE"] + cap_reasons

    out["UB Confidence Cap Reason"] = "; ".join(dict.fromkeys(all_caps)) or "NONE"



    # Decision/playability downgrades for fragile or workload-dependent OVERs and strong disagreement.

    old_play = str(out.get("Undefeated Beta Playability") or "TRACK")

    severity = 0

    decision_reasons = []

    if final_side == "OVER" and over_floor.get("status") == "VETO":

        severity = max(severity, 2); decision_reasons.append("V1.10_OVER_WORKLOAD_FLOOR_VETO")

    elif final_side == "OVER" and over_floor.get("status") == "WATCH":

        severity = max(severity, 1); decision_reasons.append("V1.10_OVER_WORKLOAD_FLOOR_WATCH")

    if fragility.get("status") == "HIGH" and abs(float(out.get("Undefeated Beta Edge") or 0.0)) < 0.60:

        severity = max(severity, 1); decision_reasons.append("V1.10_EXACT_LINE_FRAGILITY")

    if disagree.get("status") == "STRONG_DISAGREEMENT" and abs(float(out.get("Undefeated Beta Edge") or 0.0)) < 0.60:

        severity = max(severity, 1); decision_reasons.append("V1.10_MODEL_DISAGREEMENT")

    if resolver_reasons:

        severity = max(severity, 1); decision_reasons.extend(resolver_reasons)

    downgrade_once = {"OFFICIAL_PLAY":"LEAN", "LEAN":"TRACK", "TRACK":"PASS", "PASS":"PASS", "NO_LINE":"NO_LINE"}

    new_play = old_play

    for _ in range(severity):

        new_play = downgrade_once.get(new_play, "PASS")

    if new_play != old_play:

        out["Undefeated Beta Playability"] = new_play

        out["Undefeated Beta Decision State"] = f"{new_play}_{final_side}"

        reason = str(out.get("Undefeated Beta Decision Reason") or "")

        out["Undefeated Beta Decision Reason"] = (reason + "; " + "; ".join(decision_reasons)).strip("; ")

        if out.get("Best Play Score") is not None:

            out["Best Play Score"] = max(0.0, float(_ub_num(out.get("Best Play Score"), 0.0) or 0.0) - 6.0*severity)

        if new_play == "PASS":

            out["Best Play Tier"] = "PASS"



    out["UB Biological No Sportsbook Leakage"] = True

    out["UB Final Resolver Uses Sportsbook Line"] = bool(resolver_reasons)

    out["UB No Sportsbook Leakage"] = bool(not resolver_reasons)

    _v110_raw_residual = float(_ub_num(out.get("UB Attribution Residual"), 0.0) or 0.0)

    _v110_final_residual = _v110_raw_residual + (float(final_projection) - float(biological_projection)) - float(out.get("UB Decision Resolver Adjustment K") or 0.0)

    out["UB Final Attribution Residual"] = round(_v110_final_residual, 6)

    out["UB Final Attribution Reconciles"] = bool(abs(_v110_final_residual) <= 1e-6)

    out["UB V1.10 Formula Check"] = bool(out.get("UB Side Math Check") and out.get("UB Edge Math Check") and out.get("UB Final Attribution Reconciles"))

    out["UB Pregame Feature Persistence"] = "COMPLETE_V1_10_THRESHOLD_PROTECTION"

    return out







# ---------------------------------------------------------------------------

# V1.11 FALSE-UNDER THRESHOLD GUARD + CONTROL-WIN PRESERVATION

# ---------------------------------------------------------------------------

# Why this exists:

# - V1.10 had a strong OVER workload-floor guard, but no symmetric P50 foundation

#   resolver for UNDERs outside the special 2.5/3.5 historical rule.

# - That allowed the final center to sit below the prop even when independent

#   pitcher-K x opponent-exposure x BF math already sat above the line.

# - V1.11 adds a line-aware DECISION guard only. It never rewrites biological K,

#   never hard-codes pitcher/team names, and logs every adjustment.



_ub_build_row_v110_active = _ub_build_row





def _ub_v111_false_under_profile(out):

    """Independent threshold-floor audit for a final UNDER.



    Uses three pregame baseball paths:

      1) neutral Log5 pitcher K/BF x lineup exposure x BF50,

      2) pitcher skill K/BF x BF50,

      3) Beta matchup K/BF x BF50.



    The sportsbook line is used only to classify decision risk; it does not feed

    the biological projection.

    """

    out = out or {}

    line = _ub_num(out.get("Line"), None)

    side = str(out.get("Undefeated Beta Side") or "").upper()

    if line is None or side != "UNDER":

        return {"status":"NOT_APPLICABLE", "score":0.0, "support_count":0}



    bf50 = float(_ub_num(out.get("UB BF P50"), DEFAULT_BF) or DEFAULT_BF)

    bf25 = float(_ub_num(out.get("UB BF P25"), bf50) or bf50)

    skill = _ub_rate(out.get("UB Pitcher K% Used"), None)

    if skill is None:

        skill = _ub_num(out.get("UB Skill K/BF"), LEAGUE_AVG_K)

    exposure = _ub_rate(out.get("UB Lineup Exposure K%"), None)

    matchup = _ub_num(out.get("UB Matchup K/BF"), None)

    if matchup is None:

        matchup = _ub_num(out.get("UB Independent Matchup K/BF"), skill)



    neutral = None

    if skill is not None and exposure is not None:

        try:

            neutral = float(calculate_log5_k_rate(float(skill), float(exposure)))

        except Exception:

            neutral = None



    neutral_k50 = None if neutral is None else neutral * bf50

    neutral_k25 = None if neutral is None else neutral * bf25

    skill_k50 = None if skill is None else float(skill) * bf50

    matchup_k50 = None if matchup is None else float(matchup) * bf50



    foundation_margin = float(UB_CONFIG["v111_false_under_foundation_margin_k"])

    skill_margin = float(UB_CONFIG["v111_false_under_skill_margin_k"])

    matchup_margin = float(UB_CONFIG["v111_false_under_matchup_margin_k"])

    score = 0.0

    support = []

    reasons = []



    if neutral_k50 is not None:

        if neutral_k50 >= float(line) + foundation_margin:

            score += 34.0; support.append("NEUTRAL_LOG5_P50")

            reasons.append(f"neutral Log5/BF50 {neutral_k50:.2f} K > line {float(line):.1f}")

        elif neutral_k50 >= float(line) - 0.15:

            score += 16.0

            reasons.append(f"neutral Log5/BF50 near line ({neutral_k50:.2f} K)")



    if skill_k50 is not None:

        if skill_k50 >= float(line) + skill_margin:

            score += 20.0; support.append("PITCHER_SKILL_P50")

            reasons.append(f"pitcher K/BF x BF50 {skill_k50:.2f} K")

        elif skill_k50 >= float(line) - 0.05:

            score += 8.0



    if matchup_k50 is not None:

        if matchup_k50 >= float(line) + matchup_margin:

            score += 20.0; support.append("MATCHUP_P50")

            reasons.append(f"matchup K/BF x BF50 {matchup_k50:.2f} K")

        elif matchup_k50 >= float(line) - 0.10:

            score += 8.0



    prior_under = str(out.get("UB Under Ceiling Status") or "").upper()

    if prior_under == "VETO":

        score += 18.0; support.append("P75_P90_CEILING")

        reasons.append("existing P75/P90 under-ceiling guard is VETO")

    elif prior_under == "WATCH":

        score += 9.0

        reasons.append("existing P75/P90 under-ceiling guard is WATCH")



    recent_accel = float(_ub_num(out.get("UB Recent K Acceleration"), 50.0) or 50.0)

    if recent_accel >= 70.0:

        score += 9.0; support.append("RECENT_K_ACCEL")

        reasons.append(f"recent K acceleration {recent_accel:.0f}/100")



    # High volume matters most when the rate-based foundation is already near/above line.

    if bf50 >= 24.0 and ((neutral_k50 is not None and neutral_k50 >= float(line)-0.15) or (matchup_k50 is not None and matchup_k50 >= float(line)-0.15)):

        score += 8.0; support.append("HIGH_BF50")

        reasons.append(f"BF50 {bf50:.1f} creates threshold exposure")



    score = float(clamp(score, 0.0, 100.0))

    independent_floor_support = len({x for x in support if x in {"NEUTRAL_LOG5_P50","PITCHER_SKILL_P50","MATCHUP_P50"}})

    # A VETO that can actually change side requires at least two independent P50

    # paths. P75/P90 tails alone can only create WATCH, which protects high-line

    # unders from being over-flipped on one ceiling scenario.

    if score >= float(UB_CONFIG["v111_false_under_veto_score"]) and independent_floor_support >= 2:

        status = "VETO"

    elif score >= float(UB_CONFIG["v111_false_under_watch_score"]):

        status = "WATCH"

    else:

        status = "CLEAR"



    anchors = [x for x in (neutral_k50, skill_k50, matchup_k50) if x is not None]

    # Median is robust to one over-aggressive component and makes this a true

    # consensus threshold guard rather than a max-path cherry-pick.

    anchor = float(np.median(anchors)) if anchors else None

    return {

        "status": status, "score": round(score,1), "support_count": independent_floor_support,

        "support": support, "reasons": reasons, "bf50": bf50, "bf25": bf25,

        "skill_kbf": skill, "exposure_kbf": exposure, "neutral_kbf": neutral, "matchup_kbf": matchup,

        "neutral_k50": neutral_k50, "neutral_k25": neutral_k25,

        "skill_k50": skill_k50, "matchup_k50": matchup_k50, "anchor_k50": anchor,

    }





def _ub_v111_preserve_control_under_profile(out):

    """Protect a Merge UNDER from a fragile, large-jump, barely-OVER Beta flip.



    This is the Skenes-type structural pattern, not a player rule: challenger moves

    a long way from control, crosses the line by only a few tenths, and its own

    lower-workload OVER survival test is not CLEAR. Stronger/more decisive OVER

    flips remain untouched.

    """

    out = out or {}

    line = _ub_num(out.get("Line"), None)

    final_proj = _ub_num(out.get("Undefeated Beta Projection"), None)

    final_side = str(out.get("Undefeated Beta Side") or "").upper()

    merge_proj = _ub_num(out.get("Merge Control Projection"), None)

    merge_side = str(out.get("Merge Control Side") or "").upper()

    floor_state = str(out.get("UB OVER Floor Survival") or "").upper()

    if None in (line, final_proj, merge_proj) or final_side != "OVER" or merge_side != "UNDER":

        return {"active":False, "reason":"NOT_APPLICABLE"}

    edge = float(final_proj) - float(line)

    jump = float(final_proj) - float(merge_proj)

    active = bool(

        edge <= float(UB_CONFIG["v111_control_preserve_thin_over_edge_k"])

        and jump >= float(UB_CONFIG["v111_control_preserve_min_delta_k"])

        and floor_state in {"WATCH","VETO"}

    )

    return {

        "active": active, "edge": edge, "jump": jump, "floor_state": floor_state,

        "reason": f"thin OVER edge {edge:.2f}; +{jump:.2f} K vs Merge; OVER floor {floor_state}",

    }





def _ub_v111_probability(projection, line, side, p):

    hist = (p or {}).get("k_history_context_v256") if isinstance((p or {}).get("k_history_context_v256"), dict) else {}

    hist_std = _ub_num(hist.get("k_standard_deviation"), None)

    return _ub_v110_probability_for_projection(projection, line, side, hist_std)





def _ub_build_row(row, p):

    """V1.11 final wrapper: false-UNDER floor + fragile-flip control preservation."""

    out = _ub_build_row_v110_active(row, p)

    if not out:

        return out



    line = _ub_num(out.get("Line"), None)

    if line is None:

        out["UB V1.11 Formula Check"] = bool(out.get("UB V1.10 Formula Check", True))

        out["UB Pregame Feature Persistence"] = "COMPLETE_V1_11_FALSE_UNDER_GUARD"

        return out



    before_proj = float(_ub_num(out.get("Undefeated Beta Projection"), 0.0) or 0.0)

    before_side = str(out.get("Undefeated Beta Side") or "").upper()

    final_proj = before_proj

    reasons = []



    false_under = _ub_v111_false_under_profile(out)

    preserve = _ub_v111_preserve_control_under_profile(out)



    # (C) Symmetric false-UNDER resolver. Only a consensus VETO can cross the line.

    # Preserve successful challenger rescues: when Merge said OVER and Beta independently

    # moved UNDER, V1.11 may warn/cap that UNDER but will not mechanically flip it back.

    merge_side_now = str(out.get("Merge Control Side") or "").upper()

    beta_rescue_protected = bool(before_side == "UNDER" and merge_side_now == "OVER")

    if before_side == "UNDER" and false_under.get("status") == "VETO" and not beta_rescue_protected:

        anchor = _ub_num(false_under.get("anchor_k50"), None)

        if anchor is not None and float(anchor) > float(line):

            cross_buffer = float(UB_CONFIG["v111_false_under_cross_buffer_k"])

            # Do not manufacture a large OVER edge. Cross only far enough to reflect

            # the independent P50 consensus, capped by both the anchor and max move.

            desired = min(float(anchor), float(line) + max(cross_buffer, min(0.18, (float(anchor)-float(line))*0.45)))

            move = min(float(UB_CONFIG["v111_false_under_max_move_k"]), max(0.0, desired-final_proj))

            if move > 0.01:

                final_proj += move

                reasons.append("FALSE_UNDER_P50_FOUNDATION_RESCUE")



    # (D) Preserve a control UNDER when Beta made a large jump but only barely

    # crossed the line and its own workload-floor test says the OVER is fragile.

    if preserve.get("active"):

        merge_proj = float(_ub_num(out.get("Merge Control Projection"), final_proj) or final_proj)

        target = ((1.0-float(UB_CONFIG["v111_control_preserve_merge_weight"]))*final_proj

                  + float(UB_CONFIG["v111_control_preserve_merge_weight"])*merge_proj)

        delta = float(clamp(target-final_proj,

                            -float(UB_CONFIG["v111_control_preserve_max_move_k"]),

                            float(UB_CONFIG["v111_control_preserve_max_move_k"])))

        # Only apply when the capped move actually restores the protected side.

        candidate = final_proj + delta

        if candidate < float(line) and delta < -0.01:

            final_proj = candidate

            reasons.append("FRAGILE_THIN_OVER_PRESERVE_MERGE_UNDER")



    final_side = "OVER" if final_proj > float(line) else "UNDER" if final_proj < float(line) else "PUSH"

    final_proj = round(float(final_proj), 2)



    out.update({

        "UB False Under Status": false_under.get("status"),

        "UB False Under Score": false_under.get("score"),

        "UB False Under Independent P50 Supports": false_under.get("support_count"),

        "UB False Under Neutral Log5 K/BF %": None if false_under.get("neutral_kbf") is None else round(float(false_under.get("neutral_kbf"))*100.0,2),

        "UB False Under Neutral P50 K": None if false_under.get("neutral_k50") is None else round(float(false_under.get("neutral_k50")),2),

        "UB False Under Skill P50 K": None if false_under.get("skill_k50") is None else round(float(false_under.get("skill_k50")),2),

        "UB False Under Matchup P50 K": None if false_under.get("matchup_k50") is None else round(float(false_under.get("matchup_k50")),2),

        "UB False Under Consensus Anchor K": None if false_under.get("anchor_k50") is None else round(float(false_under.get("anchor_k50")),2),

        "UB False Under Reasons": "; ".join(false_under.get("reasons") or []) or "NONE",

        "UB V1.11 Control Preserve Watch": bool(preserve.get("active")),

        "UB V1.11 Control Preserve Reason": preserve.get("reason"),

        "UB V1.11 Beta Rescue Protected": bool(beta_rescue_protected),

    })



    if reasons:

        out["Undefeated Beta Projection"] = final_proj

        out["Undefeated Beta Side"] = final_side

        out["Undefeated Beta Edge"] = round(final_proj-float(line),2)

        prior_adj = float(_ub_num(out.get("UB Decision Resolver Adjustment K"), 0.0) or 0.0)

        v111_adj = float(final_proj-before_proj)

        out["UB V1.11 Resolver Adjustment K"] = round(v111_adj,3)

        out["UB Decision Resolver Adjustment K"] = round(prior_adj+v111_adj,3)

        prior_reason = str(out.get("UB Decision Resolver Reasons") or "NONE")

        joined = [x for x in ([prior_reason] if prior_reason != "NONE" else []) + reasons if x]

        out["UB Decision Resolver Reasons"] = "; ".join(dict.fromkeys(joined)) or "NONE"

        out["UB Decision Resolver Applied"] = True

        out["UB Final Resolver Uses Sportsbook Line"] = True

        out["UB No Sportsbook Leakage"] = False

        out["UB Side Flip vs Merge"] = bool(str(out.get("Merge Control Side") or "").upper() in {"OVER","UNDER"} and final_side != str(out.get("Merge Control Side") or "").upper())

        out["UB Side Math Check"] = bool(final_side == ("OVER" if final_proj > float(line) else "UNDER" if final_proj < float(line) else "PUSH"))

        out["UB Edge Math Check"] = bool(abs((final_proj-float(line))-float(out.get("Undefeated Beta Edge") or 0.0)) <= 1e-9)



        prob = _ub_v111_probability(final_proj, line, final_side, p or {})

        caps = [x for x in str(out.get("UB Confidence Cap Reason") or "NONE").split("; ") if x and x != "NONE"]

        if "FALSE_UNDER_P50_FOUNDATION_RESCUE" in reasons:

            prob = min(prob, float(UB_CONFIG["v111_false_under_prob_cap"]))

            caps.append("V1.11_FALSE_UNDER_RESOLVER")

        if "FRAGILE_THIN_OVER_PRESERVE_MERGE_UNDER" in reasons:

            prob = min(prob, float(UB_CONFIG["v111_control_preserve_prob_cap"]))

            caps.append("V1.11_CONTROL_WIN_PRESERVE")

        out["UB Calibrated Clear Probability %"] = round(float(clamp(prob,0.01,0.99))*100.0,1)

        out["UB Confidence Cap Reason"] = "; ".join(dict.fromkeys(caps)) or "NONE"



        # Any line resolver should reduce staking confidence at least one tier.

        old_play = str(out.get("Undefeated Beta Playability") or "TRACK")

        downgrade = {"OFFICIAL_PLAY":"LEAN", "LEAN":"TRACK", "TRACK":"PASS", "PASS":"PASS", "NO_LINE":"NO_LINE"}

        new_play = downgrade.get(old_play,"PASS")

        out["Undefeated Beta Playability"] = new_play

        out["Undefeated Beta Decision State"] = f"{new_play}_{final_side}"

        d_reason = str(out.get("Undefeated Beta Decision Reason") or "")

        out["Undefeated Beta Decision Reason"] = (d_reason + "; " + "; ".join(reasons)).strip("; ")

        if out.get("Best Play Score") is not None:

            out["Best Play Score"] = max(0.0, float(_ub_num(out.get("Best Play Score"),0.0) or 0.0)-6.0)

        if new_play == "PASS":

            out["Best Play Tier"] = "PASS"

    else:

        out["UB V1.11 Resolver Adjustment K"] = 0.0

        # Even if side does not flip, a WATCH false-under should trim confidence.

        if before_side == "UNDER" and (false_under.get("status") == "WATCH" or beta_rescue_protected and false_under.get("status") == "VETO"):

            prob = float(_ub_num(out.get("UB Calibrated Clear Probability %"),50.0) or 50.0)/100.0

            if prob > float(UB_CONFIG["v111_false_under_watch_prob_cap"]):

                out["UB Calibrated Clear Probability %"] = round(float(UB_CONFIG["v111_false_under_watch_prob_cap"])*100.0,1)

                caps = [x for x in str(out.get("UB Confidence Cap Reason") or "NONE").split("; ") if x and x != "NONE"]

                caps.append("V1.11_FALSE_UNDER_WATCH")

                out["UB Confidence Cap Reason"] = "; ".join(dict.fromkeys(caps))



    # Final attribution math: biological remains untouched; all V1.11 movement is

    # explicitly part of the decision resolver ledger.

    bio = float(_ub_num(out.get("UB Biological Projection"), final_proj) or final_proj)

    total_resolver = float(out.get("Undefeated Beta Projection") or final_proj) - bio

    out["UB Decision Resolver Adjustment K"] = round(total_resolver,3)

    raw_residual = float(_ub_num(out.get("UB Attribution Residual"),0.0) or 0.0)

    out["UB Final Attribution Residual"] = round(raw_residual + total_resolver - float(out.get("UB Decision Resolver Adjustment K") or 0.0),6)

    out["UB Final Attribution Reconciles"] = bool(abs(float(out["UB Final Attribution Residual"])) <= 1e-6)

    out["UB V1.11 Formula Check"] = bool(out.get("UB Side Math Check") and out.get("UB Edge Math Check") and out.get("UB Final Attribution Reconciles"))

    out["UB Pregame Feature Persistence"] = "COMPLETE_V1_11_FALSE_UNDER_GUARD"

    return out





# ---------------------------------------------------------------------------

# V1.12 LOSS-ONLY REPAIR: thin-cross preserve + 3.5 tail + final-decision sync

# ---------------------------------------------------------------------------

_ub_build_row_v111_active = _ub_build_row





def _ub_v112_structural_role_exception(out):

    """Allow a large, well-supported role/workload correction to beat control.



    This is the Seymour-type *structure*, not a player rule. The exception requires

    a decisive edge/delta plus starter authority; a tiny line crossing never qualifies.

    """

    out = out or {}

    line = _ub_num(out.get("Line"), None)

    proj = _ub_num(out.get("Undefeated Beta Projection"), None)

    merge = _ub_num(out.get("Merge Control Projection"), None)

    if None in (line, proj, merge):

        return False

    edge = abs(float(proj) - float(line))

    delta = abs(float(proj) - float(merge))

    role = str(out.get("UB Role") or "").upper()

    starter_auth = bool(out.get("UB Recent Starter Authority")) or role in {"FULL_STARTER", "NORMAL_STARTER", "BULK"}

    return bool(

        edge >= float(UB_CONFIG["v112_structural_role_edge_k"])

        and delta >= float(UB_CONFIG["v112_structural_role_delta_k"])

        and starter_auth

    )





def _ub_v112_control_preserve_profile(out):

    """Preserve a strong Merge UNDER when Challenger only barely crosses OVER."""

    out = out or {}

    line = _ub_num(out.get("Line"), None)

    proj = _ub_num(out.get("Undefeated Beta Projection"), None)

    merge = _ub_num(out.get("Merge Control Projection"), None)

    side = str(out.get("Undefeated Beta Side") or "").upper()

    merge_side = str(out.get("Merge Control Side") or "").upper()

    if None in (line, proj, merge) or side != "OVER" or merge_side != "UNDER":

        return {"active": False, "reason": "NOT_APPLICABLE"}

    edge = float(proj) - float(line)

    control_margin = float(line) - float(merge)

    structural = _ub_v112_structural_role_exception(out)

    active = bool(

        not structural

        and 0.0 < edge <= float(UB_CONFIG["v112_thin_cross_edge_k"])

        and control_margin >= float(UB_CONFIG["v112_control_under_margin_k"])

    )

    return {

        "active": active,

        "edge": edge,

        "control_margin": control_margin,

        "structural_exception": structural,

        "reason": f"thin cross +{edge:.2f} K; Merge UNDER cushion {control_margin:.2f} K; structural exception={structural}",

    }





def _ub_v112_low35_profile(out, p=None):

    """Dedicated 3.5-line 4+ K tail audit.



    The mean alone cannot certify a 3.5 UNDER: four strikeouts beat it. This combines

    exact-line tail probability with existing historical breakout, workload, ceiling,

    pitcher-skill and recent-threshold evidence. No player names/outcomes are encoded.

    """

    out = out or {}; p = p or {}

    line = _ub_num(out.get("Line"), None)

    proj = _ub_num(out.get("Undefeated Beta Projection"), None)

    side = str(out.get("Undefeated Beta Side") or "").upper()

    if line is None or proj is None or abs(float(line) - 3.5) > 1e-9 or side != "UNDER":

        return {"status": "NOT_APPLICABLE", "score": 0, "p4plus": None, "reasons": []}



    hist = p.get("k_history_context_v256") if isinstance(p.get("k_history_context_v256"), dict) else {}

    hist_std = _ub_num(hist.get("k_standard_deviation"), None)

    p4plus = _ub_v110_probability_for_projection(float(proj), 3.5, "OVER", hist_std)

    l5 = float(_ub_num(out.get("UB Low-Line L5 Over %"), 0.0) or 0.0) / 100.0

    l10 = float(_ub_num(out.get("UB Low-Line L10 Over %"), 0.0) or 0.0) / 100.0

    skill = float(_ub_num(out.get("UB Skill K/BF"), LEAGUE_AVG_K) or LEAGUE_AVG_K)

    matchup = float(_ub_num(out.get("UB Matchup K/BF"), LEAGUE_AVG_K) or LEAGUE_AVG_K)

    bf50 = float(_ub_num(out.get("UB BF P50"), 0.0) or 0.0)

    under_ceiling = str(out.get("UB Under Ceiling Status") or "CLEAR").upper()

    workload_escape = float(_ub_num(out.get("UB Workload Escape Score"), 0.0) or 0.0)

    hist_breakout = bool(out.get("UB Hist 3.5 Breakout Under Risk"))

    recent_avg = max(float(_ub_num(out.get("UB Low-Line L5 Avg K"), 0.0) or 0.0), float(_ub_num(out.get("UB Low-Line L10 Avg K"), 0.0) or 0.0))



    score = 0; reasons = []

    if hist_breakout:

        score += 2; reasons.append("HIST_3_5_BREAKOUT_RISK")

    if p4plus >= 0.30:

        score += 1; reasons.append(f"P4PLUS_{p4plus:.0%}")

    if max(l5, l10) >= 0.50:

        score += 1; reasons.append("RECENT_4PLUS_RATE")

    if recent_avg >= 3.5:

        score += 1; reasons.append("RECENT_K_CENTER_AT_LINE")

    if under_ceiling in {"WATCH", "VETO"}:

        score += 1; reasons.append("UNDER_CEILING_RISK")

    if workload_escape >= 55:

        score += 1; reasons.append("WORKLOAD_ESCAPE")

    if skill >= 0.20:

        score += 1; reasons.append("PITCHER_SKILL_FLOOR")

    if matchup >= 0.20:

        score += 1; reasons.append("MATCHUP_K_FLOOR")

    if bf50 >= 19.0:

        score += 1; reasons.append("ENOUGH_BF_FOR_4K")



    anchors = [skill * bf50, matchup * bf50]

    if recent_avg > 0:

        anchors.append(recent_avg)

    anchor = float(np.median([x for x in anchors if np.isfinite(x)])) if anchors else float(proj)

    veto = bool(score >= int(UB_CONFIG["v112_low35_veto_score"]) and p4plus >= float(UB_CONFIG["v112_low35_min_over_tail"]))

    watch = bool(score >= int(UB_CONFIG["v112_low35_watch_score"]))

    status = "VETO_UNDER" if veto else "WATCH_UNDER" if watch else "CLEAR_UNDER"

    return {"status": status, "score": score, "p4plus": p4plus, "anchor": anchor, "reasons": reasons}





def _ub_v112_recompute_side_probability(out, p=None):

    out = out or {}; p = p or {}

    line = _ub_num(out.get("Line"), None)

    proj = _ub_num(out.get("Undefeated Beta Projection"), None)

    if line is None or proj is None:

        return out

    side = "OVER" if float(proj) > float(line) else "UNDER" if float(proj) < float(line) else "UNDER"

    hist = p.get("k_history_context_v256") if isinstance(p.get("k_history_context_v256"), dict) else {}

    hist_std = _ub_num(hist.get("k_standard_deviation"), None)

    prob = _ub_v110_probability_for_projection(float(proj), float(line), side, hist_std)

    out["Undefeated Beta Side"] = side

    out["Undefeated Beta Edge"] = round(float(proj) - float(line), 2)

    out["UB Calibrated Clear Probability %"] = round(float(clamp(prob, 0.01, 0.99)) * 100.0, 1)

    out["UB Side Math Check"] = True

    out["UB Edge Math Check"] = True

    return out





def _ub_v112_k_distribution_profile(out, p=None):

    """Decision-layer K distribution around the final Challenger center.



    This does not alter biological K. It exposes sportsbook-threshold probabilities

    and K quantiles so thin lines are judged by the distribution, not only the mean.

    """

    out = out or {}; p = p or {}

    line = _ub_num(out.get("Line"), None)

    proj = _ub_num(out.get("Undefeated Beta Projection"), None)

    if line is None or proj is None:

        return out

    hist = p.get("k_history_context_v256") if isinstance(p.get("k_history_context_v256"), dict) else {}

    hist_std = _ub_num(hist.get("k_standard_deviation"), None)

    dist = _v265_exact_line_distribution(float(proj), float(line), history_std=hist_std)

    sigma = float(_ub_num(dist.get("sigma"), max(1.05, math.sqrt(max(0.35, float(proj))))) or 1.05)

    # Standard-normal quantiles for 25/40/50/60/75%.

    z = {25:-0.67448975, 40:-0.25334710, 50:0.0, 60:0.25334710, 75:0.67448975}

    for q, zv in z.items():

        out[f"UB K P{q}"] = round(max(0.0, float(proj) + zv * sigma), 2)

    po = _ub_num(dist.get("over_probability"), None)

    pu = _ub_num(dist.get("under_probability"), None)

    out["UB P(Over Line) %"] = None if po is None else round(float(po) * 100.0, 1)

    out["UB P(Under Line) %"] = None if pu is None else round(float(pu) * 100.0, 1)

    required = int(math.floor(float(line)) + 1)

    ladder = dist.get("ladder") if isinstance(dist.get("ladder"), dict) else {}

    req_prob = _ub_num(ladder.get(f"P({required}+ K)"), po)

    out["UB Required Over K"] = required

    out["UB P(Required+ K) %"] = None if req_prob is None else round(float(req_prob) * 100.0, 1)

    out["UB Distribution Sigma"] = round(sigma, 3)

    out["UB Distribution Status"] = str(dist.get("status") or "READY")

    return out





def _ub_v112_final_decision(out, p=None, row=None):

    """Create one authoritative OVER / UNDER / PASS used by UI/export/grading."""

    out = out or {}; p = p or {}; row = row or {}

    side = str(out.get("Undefeated Beta Side") or "").upper()

    line = _ub_num(out.get("Line"), None)

    prob = float(_ub_num(out.get("UB Calibrated Clear Probability %"), 50.0) or 50.0)

    edge = abs(float(_ub_num(out.get("Undefeated Beta Edge"), 0.0) or 0.0))

    data_q = float(_ub_num(out.get("UB Data Quality"), 60.0) or 60.0)

    brain_score = float(_ub_num(out.get("Sports Brain Score"), 50.0) or 50.0)

    workload_conf = str(out.get("UB Workload Confidence") or "UNKNOWN").upper()

    role = str(out.get("UB Role") or "UNKNOWN").upper()

    hard = []



    if line is None or side not in {"OVER", "UNDER"}:

        hard.append("NO_VALID_LINE_OR_SIDE")

    if data_q < float(UB_CONFIG["v112_final_hard_data_floor"]):

        hard.append("DATA_QUALITY_TOO_LOW")

    if prob < float(UB_CONFIG["v112_final_min_side_prob"]) * 100.0:

        hard.append("SIDE_CONFIDENCE_MISMATCH")

    if role in {"UNKNOWN", "ROLE_UNCERTAIN"} and workload_conf == "LOW" and prob < 60.0:

        hard.append("ROLE_WORKLOAD_UNRESOLVED")

    if str(out.get("UB Model Disagreement Status") or "") == "STRONG_DISAGREEMENT" and prob < float(UB_CONFIG["v112_final_pass_prob"]) * 100.0:

        hard.append("STRONG_MODEL_DISAGREEMENT")

    if side == "OVER" and str(out.get("UB OVER Floor Survival") or "") == "VETO" and edge < 0.60 and prob < 62.0:

        hard.append("OVER_WORKLOAD_FLOOR_VETO")

    p75k = _ub_num(out.get("UB Under Ceiling P75 K"), None)

    if side == "UNDER" and str(out.get("UB Under Ceiling Status") or "") == "VETO" and p75k is not None and line is not None and float(p75k) > float(line) and prob < 62.0:

        hard.append("DEEP_START_UNDER_RISK")

    # Brain score is a strength score, not an automatic PASS switch. Only a weak

    # brain + weak probability pair can create a genuine support PASS.

    if brain_score < 46.0 and prob < 54.0:

        hard.append("INSUFFICIENT_INDEPENDENT_SUPPORT")



    final = "PASS" if hard else side

    support = "PASS" if final == "PASS" else "SUPPORTED" if (prob >= 55.0 and brain_score >= 55.0) else "LEAN_SUPPORTED"

    coherence = bool(final == "PASS" or (side == final and prob >= 50.0))

    reason = "; ".join(hard) if hard else f"{side} supported by final projection/probability; Brain strength {brain_score:.0f}/100"



    out["UB Final Decision"] = final

    out["UB Final Side"] = final if final in {"OVER", "UNDER"} else side

    out["UB Final Probability %"] = round(prob, 1)

    out["UB Final Support State"] = support

    out["UB Final Decision Reason"] = reason

    out["UB Side Confidence Coherence"] = coherence

    out["UB Side Confidence Mismatch"] = bool(not coherence)

    out["Sports Brain Direction"] = side if side in {"OVER", "UNDER"} else "PASS"

    out["Sports Brain Decision"] = final



    old_play = str(out.get("Undefeated Beta Playability") or "TRACK")

    if final == "PASS":

        out["Undefeated Beta Playability"] = "PASS"

        out["Undefeated Beta Decision State"] = "PASS"

        out["Best Play Tier"] = "PASS"

        out["Sports Brain Side"] = "PASS"

        out["Sports Brain Verdict"] = "PASS"

    else:

        # A previous PASS caused only by ranking/tier mechanics must not hide an

        # otherwise coherent side. Promote display state to TRACK/LEAN, not a bet.

        if old_play == "PASS":

            out["Undefeated Beta Playability"] = "LEAN" if (prob >= 55.0 and brain_score >= 55.0) else "TRACK"

        out["Undefeated Beta Decision State"] = f"{out.get('Undefeated Beta Playability')}_{final}"

        out["Sports Brain Side"] = final

        out["Sports Brain Verdict"] = "SUPPORTED" if brain_score >= 55.0 else "MIXED SUPPORT"

        if str(out.get("Best Play Tier") or "PASS") == "PASS" and brain_score >= 55.0 and prob >= 55.0:

            out["Best Play Tier"] = "B"

    return out





def _ub_build_row(row, p):

    """V1.12 final wrapper. Keeps V1.11 biology and targets loss patterns only."""

    out = _ub_build_row_v111_active(row, p)

    if not out:

        return out

    line = _ub_num(out.get("Line"), None)

    if line is None:

        out["UB Final Decision"] = "PASS"

        out["UB Final Decision Reason"] = "NO_VALID_LINE"

        out["Undefeated Beta Version"] = UNDEFEATED_BETA_VERSION

        return out



    before = float(_ub_num(out.get("Undefeated Beta Projection"), 0.0) or 0.0)

    reasons = []



    # 1) Preserve proven control UNDERs when the Challenger crossing is tiny.

    preserve = _ub_v112_control_preserve_profile(out)

    if preserve.get("active"):

        merge = float(_ub_num(out.get("Merge Control Projection"), before) or before)

        restore = min(float(line) - float(UB_CONFIG["v112_control_restore_buffer_k"]), (0.70 * before + 0.30 * merge))

        if restore < float(line):

            out["Undefeated Beta Projection"] = round(float(restore), 2)

            reasons.append("V1.12_THIN_LINE_CROSS_CONTROL_UNDER_PRESERVED")



    _ub_v112_recompute_side_probability(out, p)



    # 2) Dedicated 3.5 UNDER tail engine. This is evaluated after preserve so a

    # genuinely dangerous 4+ K tail can still override a control UNDER.

    low35 = _ub_v112_low35_profile(out, p)

    out["UB 3.5 Tail Status"] = low35.get("status")

    out["UB 3.5 Tail Score"] = low35.get("score")

    out["UB 3.5 P(4+ K) %"] = None if low35.get("p4plus") is None else round(float(low35.get("p4plus")) * 100.0, 1)

    out["UB 3.5 Tail Reasons"] = "; ".join(low35.get("reasons") or []) or "NONE"

    if low35.get("status") == "VETO_UNDER":

        current = float(_ub_num(out.get("Undefeated Beta Projection"), before) or before)

        anchor = float(_ub_num(low35.get("anchor"), current) or current)

        target = max(current, min(anchor, float(line) + 0.18))

        target = max(target, float(line) + float(UB_CONFIG["v112_low35_cross_buffer_k"]))

        move = min(float(UB_CONFIG["v112_low35_max_move_k"]), max(0.0, target - current))

        if move > 0.01:

            out["Undefeated Beta Projection"] = round(current + move, 2)

            reasons.append("V1.12_3_5_FOUR_PLUS_TAIL_RESCUE")

            _ub_v112_recompute_side_probability(out, p)

            # Tail rescue is evidence-driven but still line-aware, so cap staking confidence.

            out["UB Calibrated Clear Probability %"] = min(float(_ub_num(out.get("UB Calibrated Clear Probability %"), 50.0) or 50.0), float(UB_CONFIG["v112_low35_prob_cap"]) * 100.0)



    # Record decision-only movement separately from biological projection.

    final_proj = float(_ub_num(out.get("Undefeated Beta Projection"), before) or before)

    if reasons:

        prior = [x for x in str(out.get("UB Decision Resolver Reasons") or "NONE").split("; ") if x and x != "NONE"]

        out["UB Decision Resolver Reasons"] = "; ".join(dict.fromkeys(prior + reasons))

        out["UB Decision Resolver Applied"] = True

        out["UB Final Resolver Uses Sportsbook Line"] = True

        out["UB No Sportsbook Leakage"] = False

        out["UB V1.12 Resolver Adjustment K"] = round(final_proj - before, 3)

        bio = float(_ub_num(out.get("UB Biological Projection"), final_proj) or final_proj)

        out["UB Decision Resolver Adjustment K"] = round(final_proj - bio, 3)

        caps = [x for x in str(out.get("UB Confidence Cap Reason") or "NONE").split("; ") if x and x != "NONE"]

        if "V1.12_THIN_LINE_CROSS_CONTROL_UNDER_PRESERVED" in reasons:

            caps.append("V1.12_CONTROL_WIN_PRESERVE")

            out["UB Calibrated Clear Probability %"] = min(float(out.get("UB Calibrated Clear Probability %") or 50.0), float(UB_CONFIG["v112_control_preserve_prob_cap"]) * 100.0)

        if "V1.12_3_5_FOUR_PLUS_TAIL_RESCUE" in reasons:

            caps.append("V1.12_3_5_TAIL_RESCUE")

        out["UB Confidence Cap Reason"] = "; ".join(dict.fromkeys(caps)) or "NONE"

    else:

        out["UB V1.12 Resolver Adjustment K"] = 0.0



    out["UB V1.12 Control Preserve Active"] = bool(preserve.get("active"))

    out["UB V1.12 Control Preserve Reason"] = preserve.get("reason")

    out["UB V1.12 Structural Role Exception"] = bool(preserve.get("structural_exception"))



    # Rebuild Sports Brain from the final V1.12 side, then create one authoritative

    # final decision used everywhere else.

    try:

        out.update(_brain_profile(p or {}, row or {}, out))

    except Exception:

        pass

    out = _ub_v112_k_distribution_profile(out, p=p)

    out = _ub_v112_final_decision(out, p=p, row=row)

    out["Undefeated Beta Version"] = UNDEFEATED_BETA_VERSION

    out["Sports Brain Version"] = SPORTS_ANALYSIS_BRAIN_VERSION

    out["UB Pregame Feature Persistence"] = "COMPLETE_V1_12_LOSS_ONLY_UI_SAVANT"

    return out





