def _ub_apply_slate_imbalance_guard(frame):

    """Decision/ranking sanity check only; raw projections and sides remain unchanged."""

    if frame is None or frame.empty or "Undefeated Beta Side" not in frame.columns:

        return frame

    out = frame.copy()

    valid = out[out["Undefeated Beta Side"].isin(["OVER", "UNDER"])]

    n = len(valid)

    if n < int(UB_CONFIG["slate_imbalance_min_rows"]):

        out["UB Slate Imbalance Flag"] = False

        out["UB Slate Dominant Side"] = "NONE"

        out["UB Slate Dominant Share %"] = 0.0

        out["UB Slate Guard Applied"] = False

        return out

    counts = valid["Undefeated Beta Side"].value_counts()

    dominant = str(counts.index[0])

    share = float(counts.iloc[0] / n)

    active = bool(share >= float(UB_CONFIG["slate_imbalance_share"]))

    out["UB Slate Imbalance Flag"] = active

    out["UB Slate Dominant Side"] = dominant if active else "NONE"

    out["UB Slate Dominant Share %"] = round(share * 100.0, 1)

    out["UB Slate Guard Applied"] = False

    if not active:

        return out

    for idx, r in out.iterrows():

        if str(r.get("Undefeated Beta Side")) != dominant:

            continue

        conflict = False

        if dominant == "UNDER":

            conflict = str(r.get("UB Under Ceiling Status")) in {"WATCH", "VETO"} or str(r.get("Sports Brain Side")) == "OVER"

        else:

            conflict = str(r.get("UB False Over Status")) in {"WATCH", "VETO"} or str(r.get("Sports Brain Side")) == "UNDER"

        if not conflict:

            continue

        out.at[idx, "UB Slate Guard Applied"] = True

        old_play = str(r.get("Undefeated Beta Playability") or "TRACK")

        if old_play == "OFFICIAL_PLAY": new_play = "LEAN"

        elif old_play == "LEAN": new_play = "TRACK"

        else: new_play = "PASS"

        out.at[idx, "Undefeated Beta Playability"] = new_play

        out.at[idx, "Undefeated Beta Decision State"] = f"{new_play}_{dominant}"

        reason = str(r.get("Undefeated Beta Decision Reason") or "")

        out.at[idx, "Undefeated Beta Decision Reason"] = (reason + "; SLATE_SIDE_IMBALANCE_CONFLICT").strip("; ")

        if "Best Play Score" in out.columns:

            out.at[idx, "Best Play Score"] = max(0.0, float(_ub_num(r.get("Best Play Score"), 0.0)) - 8.0)

        if "Best Play Tier" in out.columns and new_play == "PASS": out.at[idx, "Best Play Tier"] = "PASS"

    return out





def _ub_beta_signal_signature(board):

    """Cache fingerprint for every pregame input that can move Beta.



    V1.6 reused the canonical K signature, which did not include recent game-log K/BF,

    pitch counts, APP97 live workload summaries, or current stuff fields. That could

    return a stale challenger even after the underlying Beta evidence changed.

    """

    rows = []

    for p in board or []:

        if not isinstance(p, dict):

            continue

        history = p.get("k_history_context_v256") if isinstance(p.get("k_history_context_v256"), dict) else {}

        game_sig = []

        for g in (history.get("game_log") or [])[:10]:

            if isinstance(g, dict):

                game_sig.append((

                    str(g.get("date") or g.get("Date") or ""),

                    _ub_num(g.get("Ks"), None), _ub_num(g.get("BF"), None), str(g.get("IP") or ""),

                    _ub_num(g.get("pitch_count") if g.get("pitch_count") is not None else g.get("Pitches"), None),

                    str(g.get("role") or g.get("Role") or ""),

                ))

        summary_sig = []

        for key in ("L3", "L5", "L10"):

            s = history.get(key) if isinstance(history.get(key), dict) else {}

            summary_sig.append((key, _ub_num(s.get("k_pct"), None), _ub_num(s.get("bf_avg"), None), _ub_num(s.get("ip_avg"), None), _ub_num(s.get("pitch_avg"), None)))

        rows.append((

            normalize_name(p.get("pitcher") or p.get("Pitcher") or ""), str(p.get("matchup") or p.get("Matchup") or ""),

            _ub_num(_ub_first([p], ["baseball_projection", "projection"], None), None),

            _ub_num(_ub_first([p], ["line", "underdog_line"], None), None),

            _ub_num(_ub_first([p], ["expected_bf", "APP97 Reconciled Expected BF", "Exp BF"], None), None),

            _ub_num(_ub_first([p], ["projected_ip", "IP PROJ", "Projected IP", "IP Projection"], None), None),

            _ub_num(_ub_first([p], ["APP97 Live L5 BF Median", "Live L5 BF Median"], None), None),

            _ub_num(_ub_first([p], ["APP97 Live L10 BF Median", "Live L10 BF Median"], None), None),

            _ub_num(_ub_first([p], ["APP97 Live L5 IP Avg", "Live L5 IP Avg"], None), None),

            _ub_num(_ub_first([p], ["APP97 Live L5 Pitch Median", "Live L5 Pitch Median", "projected_pitches"], None), None),

            _ub_num(_ub_first([p], ["savant_k_pct", "pitcher_k", "Pitcher K%"], None), None),

            _ub_num(_ub_first([p], ["statcast_whiff", "Savant Custom Whiff%", "Whiff%"], None), None),

            _ub_num(_ub_first([p], ["statcast_csw", "Savant Custom CSW%", "CSW%"], None), None),

            _ub_num(_ub_first([p], ["putaway_pct", "PutAway%"], None), None),

            _ub_num(_ub_first([p], ["projected_pitches", "Projected Pitch Count", "Expected Pitch Count", "Pitch Count Projection"], None), None),

            _ub_num(_ub_first([p], ["pitches_per_bf", "Pitches Per BF", "PPB", "pitches_per_batter"], None), None),

            _ub_num(_ub_first([p], ["statcast_zone_contact", "Zone Contact%", "Statcast Zone Contact%"], None), None),

            _ub_num(_ub_first([p], ["foul_extension_rate", "Foul Extension Rate", "Foul%", "PO Foul Workload %"], None), None),

            _ub_num(_ub_first([p], ["two_strike_reach_rate", "Two Strike Reach Rate"], None), None),

            _ub_num(_ub_first([p], ["two_strike_putaway_rate", "Two Strike PutAway Rate"], None), None),

            _ub_num(_ub_first([p], ["TTO1_K_pct", "tto1_k_pct"], None), None),

            _ub_num(_ub_first([p], ["TTO2_K_pct", "tto2_k_pct"], None), None),

            _ub_num(_ub_first([p], ["TTO3_K_pct", "tto3_k_pct"], None), None),

            str(p.get("bullpen_status") or ""), str(p.get("run_damage_risk_level") or ""), str(p.get("manager_hook_status") or ""),

            str(p.get("probable_role") or p.get("pitcher_role") or p.get("role") or ""),

            tuple(game_sig), tuple(summary_sig),

        ))

    # V1.12: include the active/last-good Savant file timestamps in the cache key.

    # A successful online refresh therefore invalidates stale Challenger rows.

    savant_sig = []

    try:

        root = Path(__file__).resolve().parent / "learning_data"

        for name in (

            f"savant_batter_platoon_{datetime.now().year}.csv",

            f"savant_batter_platoon_{datetime.now().year}.last_good.csv",

            "savant_batter_profiles.csv", "savant_pitcher_stats.csv", "pitch_mix_matchups.csv",

        ):

            path = root / name

            savant_sig.append((name, round(path.stat().st_mtime, 3), path.stat().st_size) if path.exists() else (name, 0.0, 0))

    except Exception:

        savant_sig = []

    return tuple(rows) + (("__SAVANT_FINGERPRINT__", tuple(savant_sig)),)









def build_undefeated_beta_table(board):

    try:

        _ub_atomic_write_json(UB_CONFIG_FILE, {

            "version": UNDEFEATED_BETA_VERSION,

            "sports_brain_version": SPORTS_ANALYSIS_BRAIN_VERSION,

            "mode": UNDEFEATED_BETA_MODE,

            "protected_merge_baseline_sha256": UNDEFEATED_BETA_BASELINE_SHA256,

            "config": UB_CONFIG,

            "updated_at": now_iso(),

        })

    except Exception:

        pass

    canonical = build_k_projection_pipeline(board)

    if canonical is None or not isinstance(canonical, pd.DataFrame) or canonical.empty:

        return pd.DataFrame()

    signature = _ub_beta_signal_signature(board) if "_ub_beta_signal_signature" in globals() else _canonical_k_board_signature(board)

    cache_key = _ub_hash_payload({"signature": str(signature), "version": UNDEFEATED_BETA_VERSION})

    cached = UB_RUNTIME_CACHE.get(cache_key)

    if isinstance(cached, pd.DataFrame):

        return cached.copy()

    lookup = _ub_board_lookup(board)

    rows = []

    for _, sr in canonical.iterrows():

        row = sr.to_dict()

        name = normalize_name(row.get("Pitcher") or row.get("pitcher") or "")

        p = lookup.get(name, {})

        built = _ub_build_row(row, p)

        if built:

            rows.append(built)

    out = pd.DataFrame(rows)

    if not out.empty:

        out = _ub_apply_slate_imbalance_guard(out)

        out = out.sort_values(["Best Play Score", "UB Calibrated Clear Probability %"], ascending=[False, False]).reset_index(drop=True)

        out["Undefeated Beta Rank"] = np.arange(1, len(out) + 1)

    UB_RUNTIME_CACHE.clear()

    UB_RUNTIME_CACHE[cache_key] = out.copy()

    return out





def _ub_apply_beta_to_k_frame(base_df, beta_df):

    """Overlay Undefeated Beta on an existing K Upside DataFrame.



    This preserves every existing K Upside enrichment/card field and changes only

    the visible projection/decision/workload fields needed for the Beta challenger

    presentation. Merge V2 remains a separate protected control model.

    """

    if base_df is None or not isinstance(base_df, pd.DataFrame) or base_df.empty:

        return pd.DataFrame()

    if beta_df is None or not isinstance(beta_df, pd.DataFrame) or beta_df.empty:

        return base_df.copy()

    beta_map = {normalize_name(r.get("Pitcher")): r for r in beta_df.to_dict("records")}

    out = base_df.copy()



    # V1.9.1 UI-only dtype hotfix retained in V1.10:

    # pandas StringDtype columns reject numeric Beta values (for example 57.1).

    # The overlay is a presentation frame, so safely promote only the specific

    # destination column to object if an assignment encounters a dtype conflict.

    # This does NOT alter any biological projection, probability, workload, or ML math.

    def _ub_overlay_set(row_idx, col, value):

        if col not in out.columns:

            out[col] = pd.Series([None] * len(out), index=out.index, dtype="object")

        try:

            out.at[row_idx, col] = value

        except (TypeError, ValueError):

            out[col] = out[col].astype("object")

            out.at[row_idx, col] = value



    for idx, sr in out.iterrows():

        name = normalize_name(sr.get("Pitcher") or sr.get("pitcher") or "")

        ub = beta_map.get(name)

        if not ub:

            continue

        proj = ub.get("Undefeated Beta Projection")

        line = ub.get("Line")

        raw_side = ub.get("Undefeated Beta Side")

        final_decision = str(ub.get("UB Final Decision") or raw_side or "PASS").upper()

        # V1.14 decision sync: the canonical card/export side must respect an
        # authoritative PASS. Keep the underlying model lean in a separate field.
        side = final_decision if final_decision in {"OVER", "UNDER", "PASS"} else "PASS"

        play = ub.get("Undefeated Beta Playability")

        prob = ub.get("UB Final Probability %") if ub.get("UB Final Probability %") is not None else ub.get("UB Calibrated Clear Probability %")

        state = f"PLAY_{side}" if final_decision in {"OVER", "UNDER"} and play == "OFFICIAL_PLAY" else f"TRACK_{side}" if final_decision in {"OVER", "UNDER"} else "PASS"

        for col in ["Canonical Final K Projection", "K PROJ", "Official K PROJ", "Final K Projection"]:

            _ub_overlay_set(idx, col, proj)

        _ub_overlay_set(idx, "Canonical Line", line)

        _ub_overlay_set(idx, "Canonical Side", side)

        _ub_overlay_set(idx, "UB Raw Lean Side", raw_side)

        _ub_overlay_set(idx, "Final Decision State", state)

        _ub_overlay_set(idx, "Canonical Decision", state)

        _ub_overlay_set(idx, "Canonical Edge", None if line is None else round(proj - line, 2))

        _ub_overlay_set(idx, "K Sim Current Side Prob %", prob)

        _ub_overlay_set(idx, "Current Side Prob %", prob)

        _ub_overlay_set(idx, "Confidence %", prob)

        # V1.7: visible workload is the same blended runtime workload used by final K math.

        final_bf = ub.get("UB Blended BF") if ub.get("UB Blended BF") is not None else ub.get("UB BF P50")

        final_ip = ub.get("UB Blended IP") if ub.get("UB Blended IP") is not None else ub.get("UB IP P50")

        _ub_overlay_set(idx, "APP97 Reconciled Expected BF", final_bf)

        _ub_overlay_set(idx, "Exp BF", final_bf)

        _ub_overlay_set(idx, "Projected BF", final_bf)

        _ub_overlay_set(idx, "IP Floor", final_ip)

        _ub_overlay_set(idx, "IP PROJ", final_ip)

        _ub_overlay_set(idx, "Projected IP", final_ip)

        _ub_overlay_set(idx, "Winning File K Source", "CHALLENGER V1.12")

        for key, value in ub.items():

            _ub_overlay_set(idx, key, value)

    return out





def _ub_beta_card_frame(board, beta_df=None):

    canonical = build_k_projection_pipeline(board)

    beta_df = build_undefeated_beta_table(board) if beta_df is None else beta_df

    return _ub_apply_beta_to_k_frame(canonical, beta_df)





def _ub_escape_csv_text(value):

    return "" if value is None else str(value)





def build_undefeated_beta_copy_paste(beta_df, best_only=False):

    if beta_df is None or not isinstance(beta_df, pd.DataFrame) or beta_df.empty:

        return ""

    d = beta_df.copy()

    if best_only:

        d = d[d["Best Play Tier"].isin(["S", "A"])]

        d = d[d["Undefeated Beta Playability"].isin(["OFFICIAL_PLAY", "LEAN"])]

    lines = []

    for matchup, group in d.groupby("Matchup", sort=False):

        lines.append(str(matchup))

        for _, row in group.sort_values("Best Play Score", ascending=False).iterrows():

            side = row.get("UB Final Decision") or row.get("Undefeated Beta Side")

            line = row.get("Line")

            proj = row.get("Undefeated Beta Projection")

            prob = row.get("UB Final Probability %") if row.get("UB Final Probability %") is not None else row.get("UB Calibrated Clear Probability %")

            tier = row.get("Best Play Tier")

            play = row.get("Undefeated Beta Playability")

            lines.append(f"• {row.get('Pitcher')} — {side} {line} — {proj:.2f} K — {prob:.0f}% — {tier} TIER — {play}")

        lines.append("")

    return "\n".join(lines).strip()





def _ub_atomic_write_csv(path, df):

    path_obj = Path(path)

    path_obj.parent.mkdir(parents=True, exist_ok=True)

    tmp = path_obj.with_suffix(path_obj.suffix + ".tmp")

    df.to_csv(tmp, index=False)

    os.replace(tmp, path_obj)





def _ub_atomic_write_json(path, payload):

    path_obj = Path(path)

    path_obj.parent.mkdir(parents=True, exist_ok=True)

    tmp = path_obj.with_suffix(path_obj.suffix + ".tmp")

    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True, default=str))

    os.replace(tmp, path_obj)





def _ub_append_csv(path, new_df, dedupe_cols=None):

    if new_df is None or not isinstance(new_df, pd.DataFrame) or new_df.empty:

        return 0

    path_obj = Path(path)

    try:

        old = pd.read_csv(path_obj) if path_obj.exists() else pd.DataFrame()

    except Exception:

        old = pd.DataFrame()

    merged = pd.concat([old, new_df], ignore_index=True, sort=False)

    if dedupe_cols:

        subset = [c for c in dedupe_cols if c in merged.columns]

        if subset:

            merged = merged.drop_duplicates(subset=subset, keep="last")

    before = len(old)

    _ub_atomic_write_csv(path, merged)

    return max(0, len(merged) - before)





def save_undefeated_beta_snapshot(board, stage_override=None):

    df = build_undefeated_beta_table(board)

    if df.empty:

        return {"saved": 0, "message": "No Undefeated Beta rows available."}

    snap = df.copy()

    timestamp = now_iso()

    snap["Snapshot Timestamp"] = timestamp

    if stage_override and str(stage_override).upper() not in {"", "AUTO"}:

        snap["Snapshot Stage"] = str(stage_override).upper()

    else:

        snap["Snapshot Stage"] = snap["UB Lineup Stage"].map({

            "CONFIRMED": "CONFIRMED_LINEUP",

            "CACHED": "CACHED_LINEUP",

            "EXPECTED": "EXPECTED_LINEUP",

        }).fillna("EXPECTED_LINEUP")

    snap["Snapshot Biological Input Hash"] = [

        _ub_hash_payload({

            "pitcher": row.get("Pitcher ID") or row.get("Pitcher"),

            "merge": row.get("Merge Control Projection"),

            "fixed": row.get("UB Fixed Core Projection"),

            "bf50": row.get("UB BF P50"),

            "skill": row.get("UB Skill K/BF"),

            "lineup": row.get("UB Lineup Exposure K%"),

            "stage": row.get("Snapshot Stage"),

        })[:24]

        for row in snap.to_dict("records")

    ]

    snap["Snapshot Record ID"] = [

        _ub_hash_payload({

            "base": row.get("UB Snapshot ID"),

            "timestamp": timestamp,

            "stage": row.get("Snapshot Stage"),

            "input_hash": row.get("Snapshot Biological Input Hash"),

        })[:28]

        for row in snap.to_dict("records")

    ]

    # Immutable snapshot semantics: never replace an earlier pregame record.

    saved = _ub_append_csv(UB_SNAPSHOT_FILE, snap, dedupe_cols=["Snapshot Record ID"])

    _ub_append_csv(BRAIN_SNAPSHOT_FILE, snap, dedupe_cols=["Snapshot Record ID"])

    feature_cols = [c for c in snap.columns if c.startswith("UB ") or c in [

        "Pitcher", "Matchup", "Line", "Slate Date", "Snapshot Timestamp", "Snapshot Stage",

        "Snapshot Record ID", "Snapshot Biological Input Hash", "UB Snapshot ID"

    ]]

    _ub_append_csv(UB_FEATURE_HISTORY_FILE, snap[feature_cols], dedupe_cols=["Snapshot Record ID"])

    return {

        "saved": saved, "rows": len(snap), "path": UB_SNAPSHOT_FILE,

        "stage": str(stage_override or "AUTO"),

        "message": f"Saved {saved} new immutable Undefeated Beta snapshot rows."

    }





def _ub_actual_pitcher_line(game_pk, pitcher_id):

    box = safe_get_json(f"{MLB_BASE}/game/{game_pk}/boxscore")

    if not box:

        return None

    for side in ("home", "away"):

        players = box.get("teams", {}).get(side, {}).get("players", {})

        for item in players.values():

            person = item.get("person", {})

            if str(person.get("id")) != str(pitcher_id):

                continue

            stat = item.get("stats", {}).get("pitching", {}) or {}

            return {

                "Actual K": _ub_num(stat.get("strikeOuts"), None),

                "Actual IP": baseball_ip_to_float(stat.get("inningsPitched")),

                "Actual BF": _ub_num(stat.get("battersFaced"), None),

                "Actual Pitches": _ub_num(stat.get("numberOfPitches"), None),

                "Actual ER": _ub_num(stat.get("earnedRuns"), None),

                "Actual H": _ub_num(stat.get("hits"), None),

                "Actual BB": _ub_num(stat.get("baseOnBalls"), None),

            }

    return None





def _ub_grade_side(side, line, actual_k):

    if side not in {"OVER", "UNDER"} or line is None or actual_k is None:

        return "VOID"

    if actual_k == line:

        return "PUSH"

    if side == "OVER":

        return "WIN" if actual_k > line else "LOSS"

    return "WIN" if actual_k < line else "LOSS"





def grade_saved_undefeated_beta():

    path = Path(UB_SNAPSHOT_FILE)

    if not path.exists():

        return {"graded": 0, "message": "No saved Undefeated Beta snapshots yet.", "path": UB_GRADE_FILE}

    try:

        snaps = pd.read_csv(path)

    except Exception as exc:

        return {"graded": 0, "message": f"Snapshot read failed: {exc}", "path": UB_GRADE_FILE}

    if snaps.empty:

        return {"graded": 0, "message": "Snapshot file is empty.", "path": UB_GRADE_FILE}

    try:

        old = pd.read_csv(UB_GRADE_FILE) if Path(UB_GRADE_FILE).exists() else pd.DataFrame()

    except Exception:

        old = pd.DataFrame()

    existing = set(str(x) for x in old.get("Grade Key", pd.Series(dtype=str)).dropna().astype(str).tolist()) if not old.empty else set()

    grades = []

    for _, sr in snaps.iterrows():

        row = sr.to_dict()

        game_pk = row.get("GamePk")

        pitcher_id = row.get("Pitcher ID")

        if not game_pk or not pitcher_id:

            continue

        key = _ub_hash_payload({"snapshot": row.get("Snapshot Record ID") or row.get("UB Snapshot ID"), "line": row.get("Line"), "stage": row.get("Snapshot Stage")})[:28]

        if key in existing:

            continue

        try:

            if not is_game_final(int(float(game_pk))):

                continue

        except Exception:

            continue

        actual = _ub_actual_pitcher_line(int(float(game_pk)), pitcher_id)

        if not actual or actual.get("Actual K") is None:

            continue

        line = _ub_num(row.get("Line"), None)

        beta_side = str(row.get("UB Final Decision") or row.get("Undefeated Beta Side") or "").upper()

        merge_side = str(row.get("Merge Control Side") or "").upper()

        undefeated_control_side = str(
            row.get("UB V1.14 Primary Control Side")
            or row.get("UB Biological Side")
            or ""
        ).upper()

        beta_result = _ub_grade_side(beta_side, line, actual.get("Actual K"))

        merge_result = _ub_grade_side(merge_side, line, actual.get("Actual K"))

        undefeated_control_result = _ub_grade_side(undefeated_control_side, line, actual.get("Actual K"))

        playability = str(row.get("Undefeated Beta Playability") or "")

        official_beta_result = beta_result if playability in {"OFFICIAL_PLAY", "LEAN"} else "PASS_AVOIDED" if beta_result == "LOSS" else "PASS_WOULD_WIN" if beta_result == "WIN" else beta_result

        rescue = bool(merge_result == "LOSS" and beta_result == "WIN" and playability in {"OFFICIAL_PLAY", "LEAN"})

        avoided_loss = bool(merge_result == "LOSS" and playability == "PASS")

        broken = bool(merge_result == "WIN" and beta_result == "LOSS" and playability in {"OFFICIAL_PLAY", "LEAN"})

        undefeated_rescue = bool(undefeated_control_result == "LOSS" and beta_result == "WIN" and playability in {"OFFICIAL_PLAY", "LEAN"})

        undefeated_avoided = bool(undefeated_control_result == "LOSS" and playability == "PASS")

        undefeated_broken = bool(undefeated_control_result == "WIN" and beta_result == "LOSS" and playability in {"OFFICIAL_PLAY", "LEAN"})

        actual_bf = actual.get("Actual BF")

        expected_bf = _ub_num(row.get("UB BF P50"), None)

        actual_kbf = None if not actual_bf else actual.get("Actual K") / actual_bf

        projected_kbf = _ub_num(row.get("UB Matchup K/BF"), None)

        bf_error = None if actual_bf is None or expected_bf is None else actual_bf - expected_bf

        kbf_error = None if actual_kbf is None or projected_kbf is None else actual_kbf - projected_kbf

        edge_abs = abs(_ub_num(row.get("Undefeated Beta Edge"), 0.0) or 0.0)

        low35_loss = bool(beta_result == "LOSS" and beta_side == "UNDER" and line is not None and abs(float(line) - 3.5) < 1e-9)

        bad_undefeated_flip = bool(
            beta_result == "LOSS" and undefeated_control_result == "WIN"
            and beta_side in {"OVER","UNDER"} and undefeated_control_side in {"OVER","UNDER"}
            and beta_side != undefeated_control_side
        )
        bad_merge_flip = bool(
            beta_result == "LOSS" and merge_result == "WIN"
            and beta_side in {"OVER","UNDER"} and merge_side in {"OVER","UNDER"}
            and beta_side != merge_side
        )

        if bad_undefeated_flip:

            miss_class = "BAD_UNDEFEATED_CONTROL_FLIP"

        elif bad_merge_flip:

            miss_class = "BAD_MERGE_CONTROL_FLIP"

        elif low35_loss:

            miss_class = "LOW_3_5_TAIL_MISS"

        elif bf_error is not None and abs(bf_error) >= 3.5 and kbf_error is not None and abs(kbf_error) >= 0.035:

            miss_class = "BOTH_WORKLOAD_AND_K_CONVERSION"

        elif bf_error is not None and bf_error <= -3.5:

            miss_class = "WORKLOAD_TOO_HIGH"

        elif bf_error is not None and bf_error >= 3.5:

            miss_class = "WORKLOAD_TOO_LOW"

        elif kbf_error is not None and kbf_error <= -0.035:

            miss_class = "K_RATE_TOO_HIGH"

        elif kbf_error is not None and kbf_error >= 0.035:

            miss_class = "K_RATE_TOO_LOW"

        elif edge_abs < 0.25:

            miss_class = "THIN_EDGE_OR_VARIANCE"

        else:

            miss_class = "NORMAL_VARIANCE_OR_UNCLASSIFIED"

        grade = dict(row)

        grade.update(actual)

        grade.update({

            "Grade Key": key, "Graded At": now_iso(), "Undefeated Beta Result": beta_result,

            "UB Resolved Side For Grading": beta_side,
            "Undefeated Beta Official Result": official_beta_result, "Merge Control Result": merge_result,
            "Undefeated Primary Control Side": undefeated_control_side,
            "Undefeated Primary Control Result": undefeated_control_result,

            "Merge Loss Rescued": rescue, "Merge Loss Avoided By PASS": avoided_loss, "Merge Win Broken": broken,
            "Undefeated Loss Rescued": undefeated_rescue, "Undefeated Loss Avoided By PASS": undefeated_avoided,
            "Undefeated Win Broken": undefeated_broken,

            "Net Rescue Value": int(rescue) - int(broken),
            "Net Rescue vs Undefeated": int(undefeated_rescue) - int(undefeated_broken),
            "Actual K/BF": actual_kbf, "BF Error": bf_error, "K/BF Error": kbf_error,

            "Miss Class": miss_class, "Outcome Context": "NORMAL_OR_UNKNOWN", "Clean Model Eligible": True,

        })

        grades.append(grade)

    if not grades:

        return {"graded": 0, "message": "No new final Undefeated Beta snapshots were gradeable.", "path": UB_GRADE_FILE}

    new = pd.DataFrame(grades)

    _ub_append_csv(UB_GRADE_FILE, new, dedupe_cols=["Grade Key"])

    _ub_append_csv(BRAIN_GRADE_FILE, new, dedupe_cols=["Grade Key"])

    wins = int((new["Undefeated Beta Result"] == "WIN").sum())

    losses = int((new["Undefeated Beta Result"] == "LOSS").sum())

    rescued = int(new["Merge Loss Rescued"].fillna(False).astype(bool).sum())

    avoided = int(new["Merge Loss Avoided By PASS"].fillna(False).astype(bool).sum())

    broken = int(new["Merge Win Broken"].fillna(False).astype(bool).sum())

    return {"graded": len(new), "wins": wins, "losses": losses, "rescued": rescued, "avoided_losses": avoided, "wins_broken": broken, "net_rescue": rescued - broken, "path": UB_GRADE_FILE}





def build_undefeated_beta_grade_report():

    path = Path(UB_GRADE_FILE)

    if not path.exists():

        return {"status": "NO_GRADES", "rows": 0}

    try:

        df = pd.read_csv(path)

    except Exception as exc:

        return {"status": "ERROR", "rows": 0, "error": str(exc)[:160]}

    if df.empty:

        return {"status": "NO_GRADES", "rows": 0}

    clean = df.copy()

    if "Clean Model Eligible" in clean.columns:

        clean = clean[clean["Clean Model Eligible"].fillna(True).astype(bool)]

    graded = clean[clean["Undefeated Beta Result"].isin(["WIN", "LOSS"])] if "Undefeated Beta Result" in clean.columns else pd.DataFrame()

    wins = int((graded.get("Undefeated Beta Result") == "WIN").sum()) if not graded.empty else 0

    losses = int((graded.get("Undefeated Beta Result") == "LOSS").sum()) if not graded.empty else 0

    merge_wins = int((graded.get("Merge Control Result") == "WIN").sum()) if not graded.empty and "Merge Control Result" in graded.columns else 0

    merge_losses = int((graded.get("Merge Control Result") == "LOSS").sum()) if not graded.empty and "Merge Control Result" in graded.columns else 0

    undefeated_wins = int((graded.get("Undefeated Primary Control Result") == "WIN").sum()) if not graded.empty and "Undefeated Primary Control Result" in graded.columns else 0

    undefeated_losses = int((graded.get("Undefeated Primary Control Result") == "LOSS").sum()) if not graded.empty and "Undefeated Primary Control Result" in graded.columns else 0

    rescued = int(graded.get("Merge Loss Rescued", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not graded.empty else 0

    avoided = int(graded.get("Merge Loss Avoided By PASS", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not graded.empty else 0

    broken = int(graded.get("Merge Win Broken", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not graded.empty else 0

    undefeated_rescued = int(graded.get("Undefeated Loss Rescued", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not graded.empty else 0

    undefeated_avoided = int(graded.get("Undefeated Loss Avoided By PASS", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not graded.empty else 0

    undefeated_broken = int(graded.get("Undefeated Win Broken", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not graded.empty else 0



    actual = pd.to_numeric(graded.get("Actual K"), errors="coerce") if not graded.empty and "Actual K" in graded.columns else pd.Series(dtype=float)

    beta_proj = pd.to_numeric(graded.get("Undefeated Beta Projection"), errors="coerce") if not graded.empty else pd.Series(dtype=float)

    merge_proj = pd.to_numeric(graded.get("Merge Control Projection"), errors="coerce") if not graded.empty else pd.Series(dtype=float)

    beta_err = beta_proj - actual if len(beta_proj) else pd.Series(dtype=float)

    merge_err = merge_proj - actual if len(merge_proj) else pd.Series(dtype=float)



    def record_by(col, values):

        rows = []

        if graded.empty or col not in graded.columns:

            return rows

        for value in values:

            sub = graded[graded[col].astype(str).str.upper() == str(value).upper()]

            if sub.empty:

                continue

            w = int((sub["Undefeated Beta Result"] == "WIN").sum())

            l = int((sub["Undefeated Beta Result"] == "LOSS").sum())

            rows.append({"Bucket": str(value), "W": w, "L": l, "Win %": round(100*w/max(1,w+l),1)})

        return rows



    confidence_rows = []

    if not graded.empty and "UB Calibrated Clear Probability %" in graded.columns:

        probs = pd.to_numeric(graded["UB Calibrated Clear Probability %"], errors="coerce")

        for lo, hi in [(50,54.999),(55,59.999),(60,64.999),(65,69.999),(70,74.999),(75,79.999),(80,100.001)]:

            sub = graded[(probs >= lo) & (probs <= hi)]

            if sub.empty:

                continue

            w = int((sub["Undefeated Beta Result"] == "WIN").sum())

            l = int((sub["Undefeated Beta Result"] == "LOSS").sum())

            confidence_rows.append({"Bucket": f"{lo:.0f}-{min(99,hi):.0f}%", "N": w+l, "W": w, "L": l, "Win %": round(100*w/max(1,w+l),1)})



    historical_guard_records = []

    def _flag_bool_series(frame, col):

        if col not in frame.columns:

            return pd.Series(False, index=frame.index)

        return frame[col].map(lambda x: str(x).strip().upper() in {"TRUE","1","YES","Y"} or x is True)

    for col, label in [

        ("UB Hist False Over Guard", "False-OVER guard"),

        ("UB Hist 5.5 Over Difficulty", "5.5 OVER difficulty"),

        ("UB Hist 3.5 Breakout Under Risk", "3.5 breakout-UNDER risk"),

        ("UB Hist Strong Over Exception", "Strong OVER exception"),

        ("UB Hist 4.5 Control Bucket", "4.5 control bucket"),

    ]:

        if graded.empty or col not in graded.columns:

            continue

        sub = graded[_flag_bool_series(graded, col)]

        if sub.empty:

            continue

        w = int((sub["Undefeated Beta Result"] == "WIN").sum())

        l = int((sub["Undefeated Beta Result"] == "LOSS").sum())

        rescued_n = int(sub.get("Merge Loss Rescued", pd.Series(False, index=sub.index)).fillna(False).map(lambda x: str(x).strip().upper() in {"TRUE","1","YES","Y"} or x is True).sum())

        broken_n = int(sub.get("Merge Win Broken", pd.Series(False, index=sub.index)).fillna(False).map(lambda x: str(x).strip().upper() in {"TRUE","1","YES","Y"} or x is True).sum())

        historical_guard_records.append({

            "Guard": label, "N": w+l, "W": w, "L": l,

            "Win %": round(100*w/max(1,w+l),1),

            "Rescued": rescued_n, "Broken": broken_n,

            "Net Rescue": rescued_n-broken_n,

        })



    return {

        "status": "READY", "rows": len(graded),

        "beta_record": {"wins": wins, "losses": losses, "win_rate": None if wins+losses == 0 else round(wins/(wins+losses),4)},

        "merge_same_snapshot_record": {"wins": merge_wins, "losses": merge_losses, "win_rate": None if merge_wins+merge_losses == 0 else round(merge_wins/(merge_wins+merge_losses),4)},

        "undefeated_primary_control_record": {"wins": undefeated_wins, "losses": undefeated_losses, "win_rate": None if undefeated_wins+undefeated_losses == 0 else round(undefeated_wins/(undefeated_wins+undefeated_losses),4)},

        "net_rescue": {"losses_rescued": rescued, "losses_avoided_by_pass": avoided, "wins_broken": broken, "net_rescue_value": rescued-broken},

        "net_rescue_vs_undefeated": {"losses_rescued": undefeated_rescued, "losses_avoided_by_pass": undefeated_avoided, "wins_broken": undefeated_broken, "net_rescue_value": undefeated_rescued-undefeated_broken},

        "projection": {

            "beta_mae": None if beta_err.dropna().empty else round(float(beta_err.abs().mean()),3),

            "beta_bias": None if beta_err.dropna().empty else round(float(beta_err.mean()),3),

            "merge_mae": None if merge_err.dropna().empty else round(float(merge_err.abs().mean()),3),

            "merge_bias": None if merge_err.dropna().empty else round(float(merge_err.mean()),3),

        },

        "side_records": record_by("UB Resolved Side For Grading", ["OVER","UNDER"]),

        "tier_records": record_by("Best Play Tier", ["S","A","B","PASS"]),

        "confidence_buckets": confidence_rows,

        "historical_guard_records": historical_guard_records,

        "miss_classes": graded["Miss Class"].value_counts(dropna=False).to_dict() if "Miss Class" in graded.columns else {},

    }





def _ub_summary_metrics(beta_df):

    if beta_df is None or beta_df.empty:

        return {"S": 0, "A": 0, "official": 0, "disagreements": 0}

    if "UB Final Decision" in beta_df.columns:
        resolved_side = beta_df["UB Final Decision"].fillna(beta_df["Undefeated Beta Side"]).astype(str).str.upper()
    else:
        resolved_side = beta_df["Undefeated Beta Side"].astype(str).str.upper()
    merge_side = beta_df["Merge Control Side"].astype(str).str.upper()
    comparable = resolved_side.isin(["OVER", "UNDER"]) & merge_side.isin(["OVER", "UNDER"])

    return {

        "S": int((beta_df["Best Play Tier"] == "S").sum()),

        "A": int((beta_df["Best Play Tier"] == "A").sum()),

        "official": int(beta_df["Undefeated Beta Playability"].isin(["OFFICIAL_PLAY", "LEAN"]).sum()),

        "disagreements": int((resolved_side[comparable] != merge_side[comparable]).sum()),

    }





