# -----------------------------------------------------------------------------
# MONEYLINE: data-completeness repair only.
# Existing Phase 2.1 already reconciles starter IP with recent full-start usage.
# If its normal history fields are missing, feed the same live MLB recent workload
# center into that existing capped reconciliation. This does NOT change the ML side
# protection or create a new independent scoring family.
# -----------------------------------------------------------------------------
_ML_PHASE21_RECENT_IP_PRE_V5 = _ml_phase21_recent_full_starter_ip


def _ml_phase21_recent_full_starter_ip(row):
    base = _ML_PHASE21_RECENT_IP_PRE_V5(row)
    if isinstance(base, dict) and base.get("available"):
        return base
    row = row if isinstance(row, dict) else {}
    name = str(row.get("Pitcher") or row.get("pitcher") or row.get("Starter") or row.get("Starting Pitcher") or "").strip()
    if not name:
        return base
    prof = _po_v5_workload_profile(name, None)
    if not prof or not prof.get("available"):
        return base
    center = _po_v5_valid_num(prof.get("l5_ip_avg"), 1.0, 9.0)
    if not np.isfinite(center):
        center = _po_v5_valid_num(prof.get("ip_p50"), 1.0, 9.0)
    if not np.isfinite(center):
        return base
    sample = int(_po_v5_valid_num(prof.get("sample"), 0, 100) if np.isfinite(_po_v5_valid_num(prof.get("sample"), 0, 100)) else 0)
    authority = 0.42 if sample >= 5 else 0.34 if sample >= 3 else 0.25
    # A genuinely low recent pitch-count center reduces how much the recent-IP
    # fallback can claim, but never creates a side flip by itself.
    pc = _po_v5_valid_num(prof.get("l5_pitch_median"), 20, 140)
    if np.isfinite(pc) and pc < 78:
        authority = min(authority, 0.28)
    return {
        "available": True,
        "center": round(float(center), 3),
        "authority": float(authority),
        "source": "MLB_REAL_WORKLOAD_FALLBACK",
        "sample": sample,
    }



# ===========================================================================
# CHALLENGER_RECENCY_VISIBLE_SHADOW_V2_2026_08_28
# DISPLAY/RESEARCH ONLY. Does NOT modify official Challenger K projection,
# side, confidence, BF/IP, probability, grading, PO, or FS formulas.
# Designed to be lightweight: one cached K-table snapshot per loaded board state.
# ===========================================================================
CHALLENGER_RECENCY_VISIBLE_SHADOW_VERSION = "CHALLENGER_RECENCY_VISIBLE_SHADOW_V2_2026_08_28"


def _crv_num(v, default=np.nan):
    try:
        if v in (None, "", "—", "-", "None", "nan", "NaN"):
            return default
        x = float(str(v).replace("%", "").replace(",", "").strip())
        return x if np.isfinite(x) else default
    except Exception:
        return default


def _crv_rate(v, default=np.nan):
    x = _crv_num(v, default)
    if not np.isfinite(x):
        return default
    return x / 100.0 if abs(x) > 1.5 else x


def _crv_pick(row, keys, default=None):
    try:
        for k in keys:
            if k in row:
                v=row.get(k)
                if v not in (None, "", "—", "-", "nan", "NaN"):
                    return v
    except Exception:
        pass
    return default


def _crv_first_num(row, keys, rate=False, default=np.nan):
    for k in keys:
        if k in row:
            x = _crv_rate(row.get(k), np.nan) if rate else _crv_num(row.get(k), np.nan)
            if np.isfinite(x):
                return float(x)
    return default


def _crv_board_key(board):
    try:
        parts=[]
        for p in (board or []):
            if not isinstance(p, dict):
                continue
            nm=str(_crv_pick(p,["Pitcher","Player","player_name","name"],""))
            ln=str(_crv_pick(p,["UD/Line","Line","line","stat_value"],""))
            mk=str(_crv_pick(p,["Market","market","Stat Type","stat_type"],""))
            parts.append((nm,ln,mk))
        return repr(sorted(parts))
    except Exception:
        return str(len(board or []))


def _crv_get_kdf_once(board):
    """Reuse a per-board session snapshot so Save/reruns do not repeatedly rebuild K."""
    key = _crv_board_key(board)
    skey = "_crv_shadow_cache_v2"
    try:
        cached = st.session_state.get(skey)
        if isinstance(cached, dict) and cached.get("key") == key:
            df = cached.get("df")
            if isinstance(df, pd.DataFrame):
                return df.copy()
    except Exception:
        pass
    try:
        df = build_kproj_table(board)
        if not isinstance(df, pd.DataFrame):
            df = pd.DataFrame()
        try:
            # modest column reduction keeps session memory small
            keep_tokens = (
                "Pitcher","Matchup","UD/Line","Line","K PROJ","Projection","Decision","Side",
                "L3","L5","L10","K/BF","Whiff","CSW","SwStr","Velocity","velo",
                "Pitch Count","Pitches","IP","BF","Probability","Confidence","Hit %",
                "PO ","Outs","FS ","Fantasy"
            )
            keep=[c for c in df.columns if any(t.lower() in str(c).lower() for t in keep_tokens)]
            slim=df[keep].copy() if keep else df.copy()
            st.session_state[skey] = {"key":key, "df":slim}
            return slim.copy()
        except Exception:
            return df.copy()
    except Exception:
        return pd.DataFrame()


def _crv_side(row):
    s=str(_crv_pick(row,["Line-Aware Smart Decision","Decision","Final Decision","Canonical Decision","Pick","Side"],"")).upper()
    if "UNDER" in s: return "UNDER"
    if "OVER" in s: return "OVER"
    return "PASS"


def _crv_process(row):
    votes=[]; why=[]
    pairs=[
        ("K/BF", ["UB L3 Pooled K/BF","L3 K/BF","Recent L3 K/BF"], ["UB L10 Pooled K/BF","L10 K/BF","Pitcher K/BF","Model K/BF","K/BF"], .015),
        ("Whiff", ["UB Recent Whiff L3","L3_Whiff_pct","L3 Whiff%","Recent Whiff%"], ["UB Recent Whiff L10","L10_Whiff_pct","L10 Whiff%","APP100 Whiff%","Official Savant Whiff%","Statcast Whiff%"], .015),
        ("CSW", ["UB Recent CSW L3","L3_CSW_pct","L3 CSW%","Recent CSW%"], ["UB Recent CSW L10","L10_CSW_pct","L10 CSW%","APP100 CSW%","Official Savant CSW%","Statcast CSW%"], .012),
        ("SwStr", ["UB Recent SwStr L3","L3_swinging_strike_pct","L3 SwStr%"], ["UB Recent SwStr L10","L10_swinging_strike_pct","L10 SwStr%"], .010),
    ]
    for label,short_keys,long_keys,thr in pairs:
        a=_crv_first_num(row,short_keys,rate=True); b=_crv_first_num(row,long_keys,rate=True)
        if np.isfinite(a) and np.isfinite(b):
            d=a-b
            if d>=thr: votes.append(1.0); why.append(f"{label} improving +{d*100:.1f}pp")
            elif d<=-thr: votes.append(-1.0); why.append(f"{label} cooling {d*100:.1f}pp")
    wh=_crv_first_num(row,["APP100 Whiff%","Official Savant Whiff%","Statcast Whiff%","Recent Whiff%"],rate=True)
    csw=_crv_first_num(row,["APP100 CSW%","Official Savant CSW%","Statcast CSW%","Recent CSW%"],rate=True)
    if np.isfinite(wh):
        if wh>=.285: votes.append(.5); why.append(f"Whiff healthy {wh*100:.1f}%")
        elif wh<=.205: votes.append(-.5); why.append(f"Whiff weak {wh*100:.1f}%")
    if np.isfinite(csw):
        if csw>=.295: votes.append(.5); why.append(f"CSW healthy {csw*100:.1f}%")
        elif csw<=.245: votes.append(-.5); why.append(f"CSW weak {csw*100:.1f}%")
    return float(sum(votes)) if votes else 0.0, why


def _crv_recent_k(row, label):
    keys={
        "L3":["Atlas L3 Avg K","Trend L3 Avg 2.2","L3 K Avg","Recent L3 Ks"],
        "L5":["L5 K Avg","Atlas L5 Avg K","Trend L5 Avg 2.2","Recent L5 Ks"],
        "L10":["Atlas L10 Avg K","APP97 Live L10 K Avg","L10 K Avg","Trend L10 Avg"],
    }[label]
    x=_crv_first_num(row,keys)
    if np.isfinite(x): return x
    if label=="L5":
        kbf=_crv_first_num(row,["UB L5 Pooled K/BF","Recent K/BF","L5 K/BF"],rate=True)
        bf=_crv_first_num(row,["APP97 Live L5 BF Median","APP100 L5 BF","L5 BF Median","Recent BF L5","UB Live L5 BF"])
        if np.isfinite(kbf) and np.isfinite(bf): return kbf*bf
    return np.nan


def _crv_shadow_table(board):
    df=_crv_get_kdf_once(board)
    if df.empty: return pd.DataFrame()
    rows=[]
    for _, rr in df.iterrows():
        r=rr.to_dict()
        name=str(_crv_pick(r,["Pitcher","Player"],""))
        if not name: continue
        line=_crv_first_num(r,["UD/Line","Underdog Line","Line","Current Line"])
        proj=_crv_first_num(r,["Canonical Final K Projection","APP97 True K Projection","Line-Aware Smart Final K Projection","K PROJ","Official K PROJ","Final K Projection"])
        if not np.isfinite(proj): continue
        l3=_crv_recent_k(r,"L3"); l5=_crv_recent_k(r,"L5"); l10=_crv_recent_k(r,"L10")
        pscore, reasons=_crv_process(r)
        gap=(l5-proj) if np.isfinite(l5) else np.nan
        state="INSUFFICIENT RECENCY DATA"
        market="NO RECENCY EDGE"
        if np.isfinite(gap):
            if gap<=-1.0 and pscore>=1.0:
                state="🔥 STRONG REBOUND" if gap<=-1.5 and pscore>=2 else "🔥 REBOUND WATCH"
            elif gap<=-1.0 and pscore<=-1.0:
                state="⚠️ TRUE DOWNTREND RISK"
            elif gap>=1.0 and pscore<=-1.0:
                state="🧊 STRONG SUPPRESSION" if gap>=1.5 and pscore<=-2 else "🧊 SUPPRESSION WATCH"
            elif gap>=1.0 and pscore>=1.0:
                state="✅ TRUE SURGE SUPPORT"
            else:
                state="NEUTRAL / MIXED"
        if np.isfinite(line) and np.isfinite(l5):
            if l5 <= line-1.0 and proj>line and pscore>=1.0:
                market="🔥 BUY-LOW K OVER"
            elif l5 >= line+1.0 and proj<line and pscore<=-1.0:
                market="🧊 SELL-HIGH K UNDER"
        score=0.0
        if np.isfinite(gap):
            score=min(45,abs(gap)*18)+min(30,abs(pscore)*8)
            if (gap<0<pscore) or (gap>0>pscore): score+=18
        score=float(min(100,max(0,score)))
        side=_crv_side(r)
        best="K — no shadow override"
        if "BUY-LOW" in market: best=f"K OVER {line:.1f}" if np.isfinite(line) else "K OVER"
        elif "SELL-HIGH" in market: best=f"K UNDER {line:.1f}" if np.isfinite(line) else "K UNDER"
        elif side in {"OVER","UNDER"} and np.isfinite(line): best=f"K {side} {line:.1f}"
        workload=[]
        ip5=_crv_first_num(r,["APP97 Live L5 IP Avg","Live L5 IP Avg","Recent IP L5","L5 IP Avg","UB Live L5 IP"])
        bf5=_crv_first_num(r,["APP97 Live L5 BF Median","APP100 L5 BF","Live L5 BF Median","L5 BF Median","Recent BF L5","UB Live L5 BF"])
        pc5=_crv_first_num(r,["APP97 Live L5 Pitch Median","APP100 L5 Pitch Median","Live L5 Pitch Median","Pitch Count Avg L5","L5 Pitch Median","UB Live L5 Pitch"])
        if np.isfinite(ip5): workload.append(f"L5 IP {ip5:.1f}")
        if np.isfinite(bf5): workload.append(f"BF {bf5:.0f}")
        if np.isfinite(pc5): workload.append(f"PC {pc5:.0f}")
        why=[]
        if np.isfinite(gap): why.append(f"L5 vs model {gap:+.2f}K")
        why.extend(reasons[:3]); why.extend(workload[:2])
        rows.append({
            "Pitcher":name,
            "Matchup":str(_crv_pick(r,["Matchup"],"")),
            "Line":round(line,1) if np.isfinite(line) else np.nan,
            "Challenger Proj":round(proj,2),
            "Official Side":side,
            "L3 K":round(l3,2) if np.isfinite(l3) else np.nan,
            "L5 K":round(l5,2) if np.isfinite(l5) else np.nan,
            "L10 K":round(l10,2) if np.isfinite(l10) else np.nan,
            "Process":round(pscore,1),
            "Recency State":state,
            "Trap Score":round(score,1),
            "Market Read":market,
            "Best Prop Shadow":best,
            "Why":" | ".join(why) if why else "Not enough pregame trend separation",
        })
    out=pd.DataFrame(rows)
    if not out.empty:
        out=out.sort_values(["Trap Score","Pitcher"],ascending=[False,True],kind="stable")
    return out


def render_challenger_recency_visible_shadow(board):
    with st.expander("🧠 RECENCY TRAP / BEST PROP — SHADOW", expanded=False):
        st.caption(
            "Pregame research only. This does NOT alter Challenger's official K projection, side, confidence, BF/IP, probability, or grading. "
            "It looks for recent box-score results disagreeing with K process (K/BF, Whiff, CSW, SwStr) and workload."
        )
        try:
            df=_crv_shadow_table(board)
            if df.empty:
                st.info("Load today's K board first. Shadow analysis will appear here after the board is loaded.")
                return
            strong=df[df["Trap Score"].fillna(0)>=40].copy()
            if not strong.empty:
                st.markdown("**🔥 Highest recency/process disagreements**")
                st.dataframe(strong, use_container_width=True, hide_index=True)
            else:
                st.info("No strong recency trap is detected on the current board. Full audit is still available below.")
            st.markdown("**Full shadow board**")
            st.dataframe(df, use_container_width=True, hide_index=True)
        except Exception as e:
            st.info(f"Recency Trap shadow unavailable: {e}")



