def _unified_actuals_from_k_result_log():

    """Build a simple actuals table from graded K results for PO loss learning."""

    rows = []

    try:

        for r in load_json(RESULT_LOG, []) or []:

            if not isinstance(r, dict):

                continue

            pitcher = r.get("pitcher") or r.get("Pitcher")

            actual_ip = r.get("actual_ip") or r.get("Actual IP")

            actual_k = r.get("actual") or r.get("actual_k") or r.get("Actual K")

            if not pitcher or actual_ip in (None, "", "—"):

                continue

            rows.append({

                "Pitcher": pitcher,

                "Actual K": actual_k,

                "Actual IP": actual_ip,

                "Actual Outs": _tpl_ip_to_outs(actual_ip) if "_tpl_ip_to_outs" in globals() else None,

                "Source": "K_RESULT_LOG_ACTUAL_IP",

            })

    except Exception:

        rows = []

    return pd.DataFrame(rows)





def build_projection_health_audit(board=None):

    """Audit-only checklist for what is holding K, PO, and ML projections back."""

    rows = []



    def add(area, status, holding_back, fix):

        rows.append({"Area": area, "Status": status, "Holding Back": holding_back, "Best Fix": fix})



    try:

        kdf = build_kproj_table(board) if "build_kproj_table" in globals() else pd.DataFrame()

        total = int(len(kdf)) if isinstance(kdf, pd.DataFrame) else 0

        confirmed = 0

        if total:

            src_cols = [c for c in ["Lineup Source", "Lineup Status", "APP97 Lineup Status", "Confirmed Lineup"] if c in kdf.columns]

            if src_cols:

                mask = pd.Series(False, index=kdf.index)

                for c in src_cols:

                    mask = mask | kdf[c].astype(str).str.upper().str.contains("CONFIRMED|ROTO|ACTUAL", na=False)

                confirmed = int(mask.sum())

        add("K Batter Lineups", f"{confirmed}/{total} confirmed or RotoWire-backed", "Projected/manual lineups still create wrong opponent K% spots.", "Use Auto Pull RotoWire daily, then refresh after confirmed lineups post.")



        if total and "APP100 Projection Quality Score" in kdf.columns:

            q = pd.to_numeric(kdf["APP100 Projection Quality Score"], errors="coerce")

            strong = int((q >= 86).sum())

            playable = int(((q >= 74) & (q < 86)).sum())

            track = int(((q >= 62) & (q < 74)).sum())

            verify = int((q < 62).sum())

            add("APP100 K Projection Quality", f"A {strong} | B {playable} | C {track} | D {verify}", "The K number can be mathematically fine but built from weak lineup, split, BF, pitch-mix, or recent-skill coverage.", "Prioritize A/B rows; treat C/D rows as track/pass unless price and edge are very strong.")



        if total and "APP100 Batter Split Count" in kdf.columns:

            split_avg = float(pd.to_numeric(kdf["APP100 Batter Split Count"], errors="coerce").fillna(0).mean()) if total else 0.0

            fallback_avg = float(pd.to_numeric(kdf.get("APP100 Batter Fallback Count", pd.Series(dtype=float)), errors="coerce").fillna(0).mean()) if total else 0.0

            add("Batter Split Coverage", f"Avg split bats {split_avg:.1f}/9 | fallback bats {fallback_avg:.1f}/9", "Blank vs-hand batter splits make opponent K% less precise.", "Use confirmed/projected batter rows with K% vs pitcher hand; fallback to season K% only when split sample is missing.")



        if total and "APP100 BF Coverage" in kdf.columns:

            bf_counts = kdf["APP100 BF Coverage"].astype(str).value_counts().head(5).to_dict()

            add("Batters Faced / Workload", str(bf_counts), "K props miss when projected BF/IP is wrong even if pitcher K% is right.", "Check APP100 Projected BF, L5 BF, L10 BF, pitch median, and low/thin BF labels before trusting overs.")



        if total and "APP100 Pitch Mix Coverage" in kdf.columns:

            pm_counts = kdf["APP100 Pitch Mix Coverage"].astype(str).value_counts().head(5).to_dict()

            add("Pitch Mix Matchup Coverage", str(pm_counts), "Pitch arsenal edge is weaker when only pitcher mix is known and batter pitch-type whiff/contact rows are missing.", "Trust pitch-mix boosts more when APP100 Pitch Mix Coverage says matchup ready.")



        if total and "APP100 Recent Skill" in kdf.columns:

            sk_counts = kdf["APP100 Recent Skill"].astype(str).value_counts().head(5).to_dict()

            add("Recent Skill Form", str(sk_counts), "Recent strikeout totals can lie; CSW, whiff, chase, first-strike, and velo better show if K stuff is real.", "Use APP100 Recent Skill and the Whiff/CSW/Chase columns to downgrade fading stuff.")



        warning_count = 0

        if total and "APP97 Pitcher K% Warning" in kdf.columns:

            ok_mask = kdf["APP97 Pitcher K% Warning"].astype(str).str.upper().isin(["", "OK", "NAN"])

            warning_count = int((~ok_mask).sum())

        elif total:

            warning_count = total

        add("Pitcher K% Sanity", f"{warning_count} warning rows", "Wrong pitcher K% can push overs/unders the wrong way.", "Check APP97 Pitcher K% Warning and ID Source before locking plays.")



        savant_loaded = 0

        savant_rows = 0

        if total and "Official Savant Status" in kdf.columns:

            savant_loaded = int(kdf["Official Savant Status"].astype(str).str.upper().eq("SUCCESS").sum())

        if total and "Official Savant Rows" in kdf.columns:

            savant_rows = int(pd.to_numeric(kdf["Official Savant Rows"], errors="coerce").fillna(0).sum())

        add("Official MLB/Savant Inputs", f"{savant_loaded}/{total} pitchers loaded | {savant_rows} pitch rows", "Missing official Statcast leaves K%, whiff, CSW, chase, and damage risk on weaker fallback inputs.", "Keep MLB pitcher IDs clean; trust GREEN/YELLOW more when Official Savant Status is SUCCESS.")



        custom_loaded = 0

        custom_low_min = 0

        if total and "Savant Custom Status" in kdf.columns:

            custom_loaded = int(kdf["Savant Custom Status"].astype(str).str.upper().eq("SUCCESS").sum())

        if total and "Savant Custom Min Filter" in kdf.columns:

            custom_low_min = int(kdf["Savant Custom Min Filter"].astype(str).eq("0").sum())

        add("Savant Custom Pitcher Board", f"{custom_loaded}/{total} pitchers matched | low-min fallback {custom_low_min}", "Pitcher K%, BB%, Whiff%, xwOBA, hard-hit, and barrel can be wrong when the slate misses official season leaderboards.", "Use the Savant Custom columns in Full K audit; low-min fallback is expected for rookies or unqualified pitchers.")



        winning_loaded = 0

        source_counts = {}

        if total and "Winning File K Source" in kdf.columns:

            src = kdf["Winning File K Source"].astype(str)

            winning_loaded = int(~src.str.upper().isin(["", "NO_WINNING_SOURCE", "NAN"]).sum())

            source_counts = src.value_counts().head(4).to_dict()

        add("Winning File K Projection Source", f"{winning_loaded}/{total} rows | {source_counts}", "Later current-matchup layers can drift away from the 17-11 / 15-9 slate behavior.", "Use the Winning File K Source column to confirm rows are anchored to File33/Pre-App70/App70 instead of current-only fallback.")



        hand_ok = 0

        hand_warn = 0

        if total and "Handedness Split Warning" in kdf.columns:

            hw = kdf["Handedness Split Warning"].astype(str).str.upper()

            hand_ok = int(hw.eq("OK").sum())

            hand_warn = int((~hw.eq("OK")).sum())

        add("LHP/RHP Matchup K Split", f"{hand_ok}/{total} verified | {hand_warn} fallback warnings", "Using overall opponent K% for a lefty/righty matchup can move K projections and sides the wrong way.", "Check Pitcher Hand, Opp K Source, and Handedness Split Warning on the K board before trusting plays.")



        if total and "Projection Data Gate" in kdf.columns:

            dg = kdf["Projection Data Gate"].astype(str).str.upper()

            green = int(dg.str.contains("GREEN", na=False).sum())

            yellow = int(dg.str.contains("YELLOW", na=False).sum())

            orange = int(dg.str.contains("ORANGE", na=False).sum())

            red = int(dg.str.contains("RED", na=False).sum())

        add("Projection Data Integrity", f"Green {green} | Yellow {yellow} | Orange {orange} | Red {red}", "Wrong pitcher IDs, missing hand splits, or failed official fetches create wrong projections even when the formula is good.", "Use Data Gate and Projection Data Issues; treat RED rows as verify/pass until the source is fixed.")



        external_on = bool(st.session_state.get("enable_external_k_resim", False)) if "st" in globals() else False

        external_rows = 0

        if total and "External K Override" in kdf.columns:

            external_rows = int(kdf["External K Override"].astype(str).str.upper().str.startswith("YES").sum())

        add("External K Input Re-Sim", f"{'ON' if external_on else 'OFF'} | {external_rows}/{total} rows overridden", "Outlier/manual K%, team K%, BF, or whiff corrections only help when they are explicitly applied and matched to the right pitcher.", "Use the External K Inputs editor in K tab diagnostics; save rows, turn the toggle on, then refresh.")



        app98_adjusted = 0

        if total and "APP98 Loss Target Adjustment" in kdf.columns:

            app98_adjusted = int((pd.to_numeric(kdf["APP98 Loss Target Adjustment"], errors="coerce").fillna(0).abs() > 0).sum())

        add("K Loss Targeting", f"{app98_adjusted}/{total} audit adjustments flagged", "The model was losing too many high-line/contact-suppression and thin-edge spots.", "APP98 is audit-only right now; use the flags to avoid risky plays without moving the stable public K projection.")

        if total and "APP99 Right Wins Gate" in kdf.columns:

            gates = kdf["APP99 Right Wins Gate"].astype(str).str.upper()

            green = int(gates.str.contains("GREEN", na=False).sum())

            yellow = int(gates.str.contains("YELLOW", na=False).sum())

            track = int(gates.str.contains("ORANGE|RED", na=False).sum())

            add("K Right-Wins Gate", f"Green {green} | Yellow {yellow} | Track/Pass {track}", "Wins get hurt when thin data plays are treated the same as fully covered plays.", "Prioritize GREEN/YELLOW rows; use APP99 Missing Data and Loss Risks before playing TRACK rows.")

        if total and "K Real Data Override" in kdf.columns:

            loaded = int(kdf["K Real Data Override"].astype(str).str.upper().eq("YES").sum())

            add("K/PO Real Data Overrides", f"{loaded}/{total} rows loaded", "Umpire, pitch mix, leash, injury/role, and damage flags need daily coverage.", "Use the K/PO real-data CSV panel inside K tab diagnostics when APP99 shows missing inputs.")

    except Exception as e:

        add("K Projection Audit", "ERROR", str(e)[:140], "Check K board build errors before trusting slate output.")



    try:

        po_df = _beta_projection_rows(board, "OUTS") if "_beta_projection_rows" in globals() else pd.DataFrame()

        po_rows = int(len(po_df)) if isinstance(po_df, pd.DataFrame) else 0

        low_conf = 0

        if po_rows:

            text_cols = [c for c in ["IP Confidence", "Beta Flags", "Decision Note", "Beta Lean"] if c in po_df.columns]

            if text_cols:

                combo = po_df[text_cols].astype(str).agg(" ".join, axis=1).str.upper()

                low_conf = int(combo.str.contains("LOW|HOOK|ROLE|LIMIT|PASS|VOLATILITY|TRACK", na=False).sum())

        add("Pitching Outs", f"{po_rows} rows | {low_conf} leash/risk flags", "PO is mostly an IP/leash problem, not a K problem.", "Use graded actual IP to tune hook, pitch-count, bad-game, and full-leash flags.")

    except Exception as e:

        add("Pitching Outs Audit", "ERROR", str(e)[:140], "Check beta outs board build.")



    try:

        ml_df = ml_build_board(board) if "ml_build_board" in globals() else pd.DataFrame()

        ml_rows = int(len(ml_df)) if isinstance(ml_df, pd.DataFrame) else 0

        pass_rows = 0

        if ml_rows:

            combo = ml_df.astype(str).agg(" ".join, axis=1).str.upper()

            pass_rows = int(combo.str.contains("PASS|NO BET|LOW CONF|MISSING", na=False).sum())

        add("Moneyline", f"{ml_rows} games | {pass_rows} pass/risk rows", "ML needs confirmed lineups, bullpen availability, starter confirmation, weather, and odds sanity.", "Keep ML real-data overrides fresh; grade saved ML picks with the unified button after finals.")

    except Exception as e:

        add("Moneyline Audit", "ERROR", str(e)[:140], "Check moneyline board build.")



    add("Code Structure", "Large single-file app", "Many late wrapper overrides make old UI/logic easy to reappear.", "Next cleanup should split K, PO, ML, grading, and RotoWire into separate modules.")

    return pd.DataFrame(rows)





def grade_all_markets_with_diagnostics(board=None):

    """One after-games action that grades K, Undefeated Beta, Pitching Outs, FI strikeouts, and ML."""

    diag = {

        "version": UNIFIED_ALL_MARKETS_GRADING_VERSION,

        "K": {},

        "Undefeated Beta": {},

        "Pitching Outs": {},

        "First Inning Strikeouts": {},

        "Moneyline": {},

        "Learning Refresh": {},

    }



    try:

        diag["K"] = grade_finished_games_with_diagnostics()

    except Exception as e:

        diag["K"] = {"graded": 0, "message": f"K grade failed: {e}"}



    try:

        diag["Undefeated Beta"] = grade_saved_undefeated_beta() if "grade_saved_undefeated_beta" in globals() else {"graded": 0, "message": "Undefeated Beta grader unavailable."}

    except Exception as e:

        diag["Undefeated Beta"] = {"graded": 0, "message": f"Undefeated Beta grade failed: {e}"}



    try:

        po_df = _beta_projection_rows(board, "OUTS") if "_beta_projection_rows" in globals() else pd.DataFrame()

        po_actuals = _unified_actuals_from_k_result_log()

        if "grade_pitching_outs_loss_lab" in globals() and isinstance(po_actuals, pd.DataFrame) and not po_actuals.empty:

            diag["Pitching Outs"] = grade_pitching_outs_loss_lab(po_df, po_actuals)

        else:

            diag["Pitching Outs"] = _beta_grade_saved_board(po_df, "OUTS") if "_beta_grade_saved_board" in globals() else {"graded": 0, "message": "Pitching Outs grader unavailable."}

    except Exception as e:

        diag["Pitching Outs"] = {"graded": 0, "message": f"Pitching Outs grade failed: {e}"}



    try:

        fi_df = build_first_inning_k_board(board) if "build_first_inning_k_board" in globals() else pd.DataFrame()

        diag["First Inning Strikeouts"] = _beta_grade_saved_board(fi_df, "FI_K") if "_beta_grade_saved_board" in globals() else {"graded": 0, "message": "FI K grader unavailable."}

    except Exception as e:

        diag["First Inning Strikeouts"] = {"graded": 0, "message": f"FI strikeout grade failed: {e}"}



    try:

        diag["Moneyline"] = _ow_grade_moneyline_saved() if "_ow_grade_moneyline_saved" in globals() else {"graded": 0, "reason": "moneyline_grader_unavailable"}

    except Exception as e:

        diag["Moneyline"] = {"graded": 0, "message": f"Moneyline grade failed: {e}"}



    try:

        results = load_json(RESULT_LOG, [])

        if "build_k_v72_learning_profiles" in globals():

            build_k_v72_learning_profiles(results=results, save=True)

        if "sync_graded_history_csv_from_result_log" in globals():

            sync_graded_history_csv_from_result_log()

        if "rebuild_manager_pull_learning_from_results_v11_21" in globals():

            rebuild_manager_pull_learning_from_results_v11_21(results=results, merge_existing=True)

        try:

            st.session_state["graded_history"] = _learning_lab_normalize_results_df(pd.DataFrame(results))

        except Exception:

            pass

        diag["Learning Refresh"] = {"status": "OK", "result_log_rows": len(results)}

    except Exception as e:

        diag["Learning Refresh"] = {"status": "ERROR", "message": str(e)[:160]}



    try:

        diag["Projection Health"] = build_projection_health_audit(board).to_dict("records")

    except Exception as e:

        diag["Projection Health"] = [{"Area": "Projection Health", "Status": "ERROR", "Holding Back": str(e)[:140], "Best Fix": "Open board diagnostics."}]

    return diag





def render_v2610_postgrade_validation(results):

    """Render strict audit output after grading; never feeds the live model."""

    source = pd.DataFrame(results or [])

    with st.expander("V2.6.10 Strict Post-Grade Audit", expanded=False):

        st.caption(

            "Validation only. Results are recomputed from side, line, and exact actual K; "

            "quarantined rows never enter this audit or alter production projections."

        )

        if source.empty:

            st.info("No graded rows are available for strict validation yet.")

            return

        try:

            validation = validate_graded_history(source, quarantine_result_conflicts=True)

            report_source = validation.get("accepted")

            report = build_unified_post_grade_report(report_source)

            summary = validation.get("summary") or {}

            record = report.get("record") or {}

            projection = report.get("projection") or {}

            c1, c2, c3, c4 = st.columns(4)

            c1.metric("Validated", summary.get("accepted_rows", 0))

            c2.metric("Quarantined", summary.get("quarantined_rows", 0))

            c3.metric("Record", f"{record.get('wins', 0)}-{record.get('losses', 0)}")

            c4.metric("MAE", "—" if projection.get("mae") is None else f"{projection.get('mae'):.2f} K")

            st.json({

                "record": record,

                "over_record": report.get("over_record"),

                "under_record": report.get("under_record"),

                "projection": projection,

                "confidence_buckets": report.get("confidence_buckets"),

                "workload_conversion_classes": report.get("workload_conversion_classes"),

                "model_disagreements": report.get("model_disagreements"),

                "win_preservation": report.get("win_preservation"),

            })

            quarantine = validation.get("quarantine")

            if isinstance(quarantine, pd.DataFrame) and not quarantine.empty:

                st.warning("Invalid, contradictory, or duplicate rows were quarantined.")

                st.dataframe(quarantine, use_container_width=True, hide_index=True)

                st.download_button(

                    "Download graded-history quarantine CSV",

                    quarantine.to_csv(index=False),

                    file_name="graded_history_QUARANTINE.csv",

                    mime="text/csv",

                    use_container_width=True,

                    key="v2610_download_graded_quarantine",

                )

        except Exception as exc:

            st.warning(f"Strict post-grade validation unavailable: {str(exc)[:180]}")





